    private static readonly int[] s_PanelX_00564938 = [0x5a, -20, 0x154, 0xe6];
    private static readonly int[] s_PanelX_00564948 = [0xa0, 0xa0, 0xa0, 0xa0];
    private static readonly int[] s_PanelX_00564958 = [0xb4, 0x8c, 0xb4, 0x8c];

