            case 0x0047C3A0: TickDarkness_0047C3A0(record); return;
            case 0x0047C450: TickDarknessShade_0047C450(record); return;

            // ONDE DE CHOC, ecole 0 indice 7 — la premiere poussee RADIALE : chaque victime part
