            case 0x0047C660: TickShockwave_0047C660(record); return;
            case 0x0047C830: TickShockwaveRing_0047C830(record); return;

            // FLECHES MAGIQUES, ecole 0 indice 8 — le premier projectile a tete chercheuse, et le
