            case 0x0047CE40: TickEnchant_0047CE40(record); return;
            case 0x0047CF30: TickEnchantMote_0047CF30(record); return;

            // MUR DE FLAMMES, ecole 0 indice 10 — Pieds mouilles refait en feu : meme chute, mais
