            case 0x0047DB50: TickSneeze_0047DB50(record); return;
            case 0x0047DE10: TickSneezePuff_0047DE10(record); return;

            // ASSAUT MAGIQUE, ecole 0 indice 14 — le seul sort ou le signal de fin REMONTE : ce
