            case 0x0047E260: TickLight_0047E260(record); return;
            case 0x0047E370: TickLightGlobe_0047E370(record); return;

            // ECLAIR, ecole 0 indice 16 — quatrieme sort entretenu (1 PM par DIX images), et le
