        if (RollSavingThrowB_0053A790(attacker, victim, attackerBlock, victimBlock) != 0) return 1;

        int duration = (*(short*)(attackerBlock + 0x3c) >> 3) + 0x1a;
        if (*(ushort*)(victimBlock + 0x96) < duration)
