    private static byte* NativeCopy(byte[] source, ref byte* storage)
    {
        if (storage == null)
        {
            storage = (byte*)NativeMemory.Alloc((nuint)source.Length);
            for (int i = 0; i < source.Length; i++) storage[i] = source[i];
        }

        return storage;
    }

