        0x00, 0xc0, 0x10, 0x10, 0x01, 0x02, 0x10, 0x00,   // 0x005519a0
        0x10, 0xc0, 0x10, 0x10, 0x01, 0x02, 0x10, 0x00,   // 0x005519a8
        0x20, 0xc0, 0x10, 0x10, 0x01, 0x02, 0x10, 0x00,   // 0x005519b0
    ];

