    private static readonly byte[] s_Descriptors_0054F910 =
    [
        0x90, 0xf0, 0x0f, 0x0f, 0x00, 0x00, 0x09, 0x00,   // 0x0054f910
        0x20, 0xf0, 0x0f, 0x0f, 0x01, 0x02, 0x09, 0x00,   // 0x0054f918
