        => NativeCopy(s_Descriptors_0054F970, ref s_Descriptors0054F970Storage);

    /// <summary>Ghidra: <c>0x0040fbb0</c> — le premier des trois eclats de corde.</summary>
    private static void EntityHandler_0040FBB0(byte* e)
        => TickArcChordFlash(e, Descriptors0054F758());   // Ghidra: &DAT_0054f758

    /// <summary>Ghidra: <c>0x00412d10</c> — le deuxieme.</summary>
    private static void EntityHandler_00412D10(byte* e)
        => TickArcChordFlash(e, Descriptors0054F878());

    /// <summary>Ghidra: <c>0x00416300</c> — le troisieme.</summary>
    private static void EntityHandler_00416300(byte* e)
        => TickArcChordFlash(e, Descriptors0054F970());

    /// <summary>
    /// Ghidra: <c>0x00483920</c> — <b>le plus court gestionnaire du jeu</b> : trois instructions,
    /// <c>mov eax,[esp+4] ; mov dword [eax],0 ; ret</c>. Absent de <c>Blaze.c</c>. Table
    /// <c>0x0056b2c8</c>, foret, sous-zones 5 et 9.
    ///
    /// <para>
    /// Il efface le mot de drapeaux en entier, <c>0x80000000</c> compris — l'entite ne se marque
    /// donc pas seulement comme eteinte, elle perd <b>tout</b> son etat de drapeaux d'un coup, la
    /// ou les autres corps se contentent de <c>&amp;= 0x7fffffff</c>. Rien d'autre n'est touche :
    /// ni la position, ni le compteur, ni l'atlas.
    /// </para>
    /// <para>
    /// C'est la forme minimale d'un <b>emplacement bouche</b> : une entree de table qui existe
    /// pour que l'index soit valide, et dont le seul travail est de faire disparaitre ce qui
    /// l'atteint. Il n'y a rien de plus a en tirer, et il n'y a rien qui manque.
    /// </para>
    /// </summary>
    private static void EntityHandler_00483920(byte* e) => *(uint*)e = 0;

    // =====================================================================
    // LE PANACHE QUI ENFLE ET S'ETEINT, EN DEUX EXEMPLAIRES (2026-08-30)
    //
    // 0x00415d40 et 0x004157a0 sont le meme corps, absents de Blaze.c ; releves au
    // desassembleur — Legacy/Raw/Blaze/FUN_00415D40.asm.
    //
    // Le diff normalise tient en UNE ligne, et ce n'est meme pas une adresse : 0x004157a0 ecrit
    // `mov [eax+0Bh],cl` DEUX FOIS de suite, la seconde n'ayant aucun effet. Le compilateur a emis
    // le meme magasin deux fois. C'est la premiere famille de la foret dont les membres ne
    // different par aucune donnee — un seul corps suffit pour les deux.
    // =====================================================================

    /// <summary>Ghidra: <c>0x00415d40</c> — le premier des deux panaches.</summary>
    private static void EntityHandler_00415D40(byte* e) => TickSwellingPlume(e);

    /// <summary>Ghidra: <c>0x004157a0</c> — le second, a un magasin redondant pres.</summary>
    private static void EntityHandler_004157A0(byte* e) => TickSwellingPlume(e);

    /// <summary>
    /// Le corps commun des deux panaches.
    ///
    /// <para>
    /// <b>Le champ <c>+0x14</c> choisit le modele, puis ne sert plus.</b> A la naissance il est
    /// recopie dans <c>+0x04</c> — le numero de modele — et sa valeur decide de <c>+0x0a</c> :
    /// <c>2</c> s'il valait 1, <c>9</c> sinon. Le meme <c>+0x04</c> est relu a chaque image pour
    /// choisir la vitesse d'enflure, <c>0x190</c> contre <c>0x320</c>. Un panache « 1 » est donc
    /// deux fois plus lent a grandir qu'un autre.
    /// </para>
    /// <para>
    /// <b>Il part des trois echelles a zero</b> — <c>+0x28</c>, <c>+0x2a</c> et <c>+0x2c</c>, donc
    /// invisible a sa premiere image — monte de <c>0x14000</c> d'un coup, et grandit ensuite d'un
    /// pas fixe sur les trois axes. Rien ne borne cette croissance : c'est la teinte qui met fin a
    /// l'affaire.
    /// </para>
    /// <para>
    /// <b>La teinte est le seul compteur.</b> Elle part de blanc plein (<c>0xff</c> sur les trois
    /// canaux) et perd <b>six</b> par image et par canal. Le binaire fait la soustraction sur des
    /// mots de 16 bits obtenus par <c>movzx</c>, puis teste le <b>rouge seul</b> : s'il est passe
    /// sous zero, les trois canaux sont remis a zero et l'entite s'eteint. Les trois canaux
    /// partant de la meme valeur et perdant le meme pas, tester le rouge suffit — mais c'est bien
    /// le rouge, pas un minimum.
    /// </para>
    /// <para>
    /// La vie est donc de <c>0xff / 6</c>, soit <b>quarante-trois images</b> exactement, quelle que
    /// soit la variante.
    /// </para>
    /// </summary>
    private static void TickSwellingPlume(byte* e)
    {
        if (*(short*)(e + 0x10) == 0)
        {
            byte model = e[0x14];
            bool slim = *(short*)(e + 0x14) == 1;

            *(short*)(e + 0x10) = 1;
            e[4] = model;
            e[0x0a] = (byte)(slim ? 2 : 9);
            e[0x0b] = 0;

            *(short*)(e + 0x28) = 0;
            *(short*)(e + 0x2a) = 0;
            *(short*)(e + 0x2c) = 0;
            *(short*)(e + 0x34) = 0;

            *(int*)(e + 0x20) += 0x14000;

            e[0x38] = 0xff;
            e[0x39] = 0xff;
            e[0x3a] = 0xff;
        }

        if (*(short*)(e + 0x10) != 1) return;

        short step = (short)(e[4] == 1 ? 0x190 : 0x320);

        *(short*)(e + 0x28) += step;
        *(short*)(e + 0x2a) += step;
        *(short*)(e + 0x2c) += step;

        // Ghidra: les trois canaux passent par un `movzx` 16 bits avant la soustraction, donc le
        // resultat est signe et peut descendre sous zero — c'est ce que le test suivant guette.
        short red = (short)(e[0x38] - 6);
        short green = (short)(e[0x39] - 6);
        short blue = (short)(e[0x3a] - 6);

        if (red < 0)
        {
            red = 0;
            green = 0;
            blue = 0;
            *(uint*)e &= 0x7fffffff;
        }

        e[0x38] = (byte)red;
        e[0x39] = (byte)green;
        e[0x3a] = (byte)blue;
    }

    /// <summary>
    /// Ghidra: <c>0x0040f260</c> — <b>le halo accroche a son porteur</b>. Absent de <c>Blaze.c</c> ;
    /// releve au desassembleur, 82 instructions. Table <c>0x0056b2c8</c>, foret.
    ///
    /// <para>
    /// C'est le meme halo que la phase 3 de <see cref="TickFivePhaseBurst"/> — meme tuile
    /// <c>0x3f x 0x3f</c>, meme echelle <c>0x800</c>, meme <c>+0x0a = 7</c>, meme montee de trois
    /// par canal bornee a <c>0x3c</c>, puis meme battement en sinus. Deux differences :
    /// </para>
    /// <list type="bullet">
    /// <item>il <b>suit son porteur en hauteur</b> — <c>+0x6c</c>, relu a chaque image des deux
    /// etats, et sa hauteur recopiee telle quelle ; le porteur peut etre nul, et le binaire le
    /// teste ;</item>
    /// <item>sa planche de couleurs est une <b>constante</b>, <c>8</c> ecrit en dur dans l'octet 6
    /// de l'enregistrement, la ou la gerbe y met le <c>+0x96</c> de l'entite.</item>
    /// </list>
    /// <para>
    /// <b>Il meurt au temps, pas a la teinte.</b> <c>+0x16</c> monte d'un par image sans jamais
    /// etre remis a zero ; a <c>0xc8</c> l'entite s'eteint. La vie est donc de deux cents images
    /// exactement, dont les quarante-trois premieres en montee.
    /// </para>
    /// </summary>
    private static void EntityHandler_0040F260(byte* e)
    {
        byte* carrier = *(byte**)(e + 0x6c);

        if (*(short*)(e + 0x10) == 0)
        {
            byte* atlas = Descriptors0054F7F8() + 8;     // Ghidra: &DAT_0054f800

            *(byte**)(e + 0x3c) = atlas;
            atlas[6] = 8;                                // Ghidra: DAT_0054f806 = 8

            *(short*)(e + 0x2e) = -0x1e;
            e[0x40] = 0;
            e[0x0a] = 7;
            e[0x0b] = 0;
            *(short*)(e + 0x10) = 1;
            *(short*)(e + 0x12) = 0;
            *(short*)(e + 0x28) = 0x800;
            *(short*)(e + 0x2a) = 0x800;
            e[0x38] = 0;
            e[0x39] = 0;
            e[0x3a] = 0;
        }

        if (*(short*)(e + 0x10) == 1)
        {
            if (carrier != null) *(int*)(e + 0x20) = *(int*)(carrier + 0x20);

            BrightenEntityTint_00404DE0(e, 3, 3, 3);

            if (e[0x38] >= 0x3c)
            {
                e[0x38] = 0x3c;
                e[0x39] = 0x3c;
                e[0x3a] = 0x3c;
            }

            (*(short*)(e + 0x12))++;

            if (*(short*)(e + 0x12) >= 0x2b)
            {
                *(short*)(e + 0x10) = 2;
                *(short*)(e + 0x12) = 0;
            }
        }

        if (*(short*)(e + 0x10) == 2)
        {
            if (carrier != null) *(int*)(e + 0x20) = *(int*)(carrier + 0x20);

            // Les trois canaux lisent le meme +0x12 : l'increment ne vient qu'apres les trois
            // appels, comme dans la phase 3 de la gerbe.
            byte beat = (byte)(((int)Winsys3d.GetSinTableEntry(*(short*)(e + 0x12) << 8) >> 8) + 0x3c);

            e[0x38] = beat;
            e[0x39] = beat;
            e[0x3a] = beat;

            (*(short*)(e + 0x12))++;

            if (*(short*)(e + 0x16) >= 0xc8) *(uint*)e &= 0x7fffffff;
        }

        (*(short*)(e + 0x16))++;
    }

    /// <summary>
    /// Ghidra: <c>0x00571654</c> — un <c>short</c> que le corps de
    /// <see cref="EntityHandler_00458DE0"/> compare a <c>-100</c>, et <b>que rien n'ecrit dans les
    /// sources decompilees</b>. Il n'apparait meme pas dans la liste des <c>DAT_</c> de
    /// <c>Blaze.c</c> : ses voisins connus sont <c>0x00571640</c> et <c>0x00571668</c>, il n'est
    /// donc rattachable a aucun bloc.
    ///
    /// <para>L'adresse tombe dans la queue non initialisee de <c>.data</c> : zero au chargement.
    /// Tant que rien ne l'ecrit, le test <c>&gt; -100</c> est donc toujours vrai et
    /// <see cref="EntityHandler_00458DE0"/> ne prend jamais sa seconde branche. Si un jour une
    /// fonction encore non transcrite y ecrit, ce sera visible ici.</para>
    /// </summary>
    private static short* Unknown_00571654() => (short*)ForestSceneField(0x00571654);

    /// <summary>
    /// Ghidra: <c>0x00458de0</c> — <b>le decor qui range sa pose et la reprend</b>. Absent de
    /// <c>Blaze.c</c> ; releve au desassembleur, 52 instructions. Table <c>0x0056adc8</c>, foret,
    /// sous-zones 6 a 8.
    ///
    /// <para>
    /// <b>La premiere image demenage six champs.</b> Les trois mots <c>+0x30</c>, <c>+0x32</c> et
    /// <c>+0x34</c> — que la sous-zone a remplis, et qui servent partout ailleurs d'orientation —
    /// sont recopies dans <c>+0x12</c>, <c>+0x14</c>, <c>+0x16</c>, puis <b>remis a zero</b>. Ce
    /// ne sont donc pas des angles ici mais une <b>position de rechange</b>, en unites entieres.
    /// En parallele, la position courante est rangee arrondie dans <c>+0x44</c>, <c>+0x48</c>,
    /// <c>+0x4c</c>.
    /// </para>
    /// <para>
    /// <b>Ensuite il choisit entre les deux, chaque image.</b> Si <c>0x00571654</c> depasse
    /// <c>-100</c>, la position revient de <c>+0x44</c>/<c>+0x48</c>/<c>+0x4c</c> — c'est-a-dire
    /// la position d'origine <b>arrondie a l'unite entiere</b> par l'aller-retour de decalage.
    /// Sinon elle vient de la position de rechange.
    /// </para>
    /// <para>
    /// <b>Le binaire teste <c>0x00571654</c> deux fois de suite</b> sans que rien ne l'ait modifie
    /// entre-temps. C'est la queue commune d'un <c>if/else</c> que le compilateur a repliee ; le
    /// second test rend donc toujours le meme verdict que le premier, et la branche de rechange
    /// n'est atteinte que par le premier saut. Conserve tel quel.
    /// </para>
    /// </summary>
    private static void EntityHandler_00458DE0(byte* e)
    {
        if (*(short*)(e + 0x10) == 0)
        {
            short x = *(short*)(e + 0x30);
            *(short*)(e + 0x30) = 0;
            *(short*)(e + 0x12) = x;

            short y = *(short*)(e + 0x32);
            *(short*)(e + 0x14) = y;

            short z = *(short*)(e + 0x34);
            *(short*)(e + 0x32) = 0;
            *(short*)(e + 0x34) = 0;

            *(short*)(e + 0x10) = 1;
            *(int*)(e + 0x44) = *(int*)(e + 0x1c) >> 0xc;
            *(int*)(e + 0x48) = *(int*)(e + 0x20) >> 0xc;
            *(short*)(e + 0x16) = z;
            *(int*)(e + 0x4c) = *(int*)(e + 0x24) >> 0xc;
        }

        if (*(short*)(e + 0x10) != 1) return;

        if (*Unknown_00571654() > -100)
        {
            *(int*)(e + 0x1c) = *(int*)(e + 0x44) << 0xc;
            *(int*)(e + 0x20) = *(int*)(e + 0x48) << 0xc;
            *(int*)(e + 0x24) = *(int*)(e + 0x4c) << 0xc;

            // Le second test du binaire. Rien n'a touche la globale entre les deux.
            if (*Unknown_00571654() > -100) return;
        }

        *(int*)(e + 0x1c) = (int)*(short*)(e + 0x12) << 0xc;
        *(int*)(e + 0x20) = (int)*(short*)(e + 0x14) << 0xc;
        *(int*)(e + 0x24) = (int)*(short*)(e + 0x16) << 0xc;
    }

    /// <summary>
    /// Ghidra: <c>0x00459b20</c> — <b>la dalle qui s'enfonce sous le poids</b>. Absent de
    /// <c>Blaze.c</c> ; releve au desassembleur, 73 instructions. Table <c>0x0056adc8</c>, foret,
    /// sous-zones 6 a 8.
    ///
    /// <para>
    /// <b>Trois etats, et un seul aller-retour.</b> <c>+0x12</c> retient la hauteur de repos,
    /// prise a la premiere image et arrondie a l'unite entiere. Ensuite
    /// <see cref="CountPartyMembersMatching"/> compte les membres rattaches a la dalle
    /// (<c>0x10</c> exige, <c>0x40000000</c> interdit) : s'il y en a, l'etat passe a 2 — la dalle
    /// descend de <c>+0x14</c> unites ; s'il n'y en a plus, a 3 — elle remonte d'un coup. Les deux
    /// etats se remettent eux-memes a 1 apres avoir agi, de sorte que la bascule peut se refaire a
    /// chaque image.
    /// </para>
    /// <para>
    /// <b>Elle pose un drapeau de script tant qu'on est dessus.</b> L'indice est <c>+0x16</c>, le
    /// meme decoupage que <see cref="ScriptFlagSet"/> — un octet tous les huit indices dans la
    /// banque d'etat 0 — et il est <b>borne a 32 octets</b> : un indice au-dela de 255 ne pose
    /// rien du tout, silencieusement. Le drapeau n'est jamais retire.
    /// </para>
    /// <para>
    /// <b>Le son ne part qu'une fois par appui</b> : <c>+0x98</c> le retient, et c'est l'etat 3 —
    /// la remontee — qui le remet a zero. L'identifiant vient de la sous-zone,
    /// <c>sons[0x12]</c>.
    /// </para>
    /// </summary>
    private static void EntityHandler_00459B20(byte* e)
    {
        if (*(short*)(e + 0x10) == 0)
        {
            *(short*)(e + 0x10) = 1;
            *(short*)(e + 0x12) = (short)(*(int*)(e + 0x20) >> 0xc);
            *(short*)(e + 0x98) = 0;
        }

        int riders = CountPartyMembersMatching(e, 0x10, 0x40000000);

        if (riders != 0)
        {
            if (*(short*)(e + 0x10) == 1) *(short*)(e + 0x10) = 2;
        }
        else if (*(short*)(e + 0x10) == 1)
        {
            *(short*)(e + 0x10) = 3;
        }

        if (*(short*)(e + 0x10) == 2)
        {
            if (*(short*)(e + 0x98) == 0)
            {
                TryPlaySoundNearEntity((uint*)e, SubAreaSounds()[0x12], 0x400, 0x1000, 0, 0);
                *(short*)(e + 0x98) = 1;
            }

            *(int*)(e + 0x20) = (*(short*)(e + 0x12) - *(short*)(e + 0x14)) << 0xc;
            *(short*)(e + 0x10) = 1;

            ScriptFlagRaise(*(short*)(e + 0x16));
        }

        if (*(short*)(e + 0x10) != 3) return;

        *(int*)(e + 0x20) = (int)*(short*)(e + 0x12) << 0xc;
        *(short*)(e + 0x98) = 0;
        *(short*)(e + 0x10) = 1;
    }

    /// <summary>
    /// Pose le drapeau de script <paramref name="index"/> dans la banque d'etat 0 — le pendant
    /// ecrivain de <see cref="ScriptFlagSet"/>.
    ///
    /// <para><b>Le garde a 32 octets est dans le binaire</b>, pas ajoute ici : au-dela de l'indice
    /// 255 le corps rend la main sans rien poser, et sans se plaindre. La banque fait bien
    /// <c>0x40</c> octets, donc la moitie haute reste hors d'atteinte par ce chemin.</para>
    /// </summary>
    private static void ScriptFlagRaise(short index)
    {
        int cell = DivideTowardZeroBy8(index);
        if (cell > 0x1f) return;

        int bit = (index - cell * 8) & 0x1f;
        Mem.s_StateBank0_005e96e0[cell] |= (byte)(1 << bit);
    }

    /// <summary>
    /// Ghidra: <c>0x00458e90</c> — <b>le decor qui flotte, et qui replonge quand on le lache</b>.
    /// Absent de <c>Blaze.c</c> ; releve au desassembleur, 101 instructions. Table
    /// <c>0x0056adc8</c>, foret, sous-zones 6 a 8.
    ///
    /// <para>
    /// <b>Le bit <c>0x40000000</c> partage le corps en deux moities qui ne se rencontrent
    /// jamais.</b> Pose, l'entite <b>flotte</b> ; efface, elle joue la <b>replongee</b> et se
    /// repose. Ce n'est donc pas un automate a etats mais deux comportements qu'un bit exterieur
    /// commute — c'est autre chose qui efface ce bit, pas ce corps-ci.
    /// </para>
    /// <para>
    /// <b>La flottaison.</b> La premiere image retient la hauteur de repos dans <c>+0x14</c>,
    /// arrondie a l'unite entiere, et pose la vitesse <c>+0x16</c> a <c>-1</c>. Ensuite la hauteur
    /// avance de <c>+0x16</c> unites par image, et la vitesse <b>s'inverse</b> des qu'on atteint
    /// le repos par le haut ou le repos moins vingt par le bas. Un aller-retour de quarante
    /// images, un pas d'une unite.
    /// </para>
    /// <para>
    /// <b>La replongee.</b> Elle commence par poser <c>0x10000000</c>, met <c>+0x12</c> a dix et
    /// joue <c>sons[0x18]</c>. Les dix images suivantes font <b>descendre</b> la hauteur de
    /// <c>+0x12</c> unites — donc de neuf, puis huit, puis sept : un enfoncement qui ralentit.
    /// Quand le compte est epuise, la hauteur <b>remonte</b> de <c>0x5000</c> par image jusqu'a
    /// depasser le repos, ou elle s'y colle net ; le bit <c>0x40000000</c> revient alors, la
    /// vitesse repart a <c>-1</c> et <c>+0x12</c> est charge a cent.
    /// </para>
    /// <para>
    /// <b>Deux bits differents dans la meme instruction, et ce n'est pas une faute de lecture.</b>
    /// La fin de la flottaison teste <c>0x10</c> (par <c>test al,10h</c>) et, s'il est absent,
    /// efface <c>0x10000000</c> (par <c>and eax,0efffffffh</c>). Le bit teste n'est pas celui qui
    /// est efface. Le desassemblage le confirme, et la transcription le garde tel quel.
    /// </para>
    /// </summary>
    private static void EntityHandler_00458E90(byte* e)
    {
        uint flags = *(uint*)e;

        if ((flags & 0x40000000) != 0)
        {
            if (*(short*)(e + 0x10) == 0)
            {
                *(short*)(e + 0x16) = -1;
                *(short*)(e + 0x14) = (short)(*(int*)(e + 0x20) >> 0xc);
                *(short*)(e + 0x10) = 1;
            }

            if (*(short*)(e + 0x10) == 1)
            {
                short speed = *(short*)(e + 0x16);
                int height = *(int*)(e + 0x20) + (speed << 0xc);
                *(int*)(e + 0x20) = height;

                int rest = *(short*)(e + 0x14) << 0xc;
                int floor = (*(short*)(e + 0x14) - 20) << 0xc;

                if (height >= rest || height <= floor) *(short*)(e + 0x16) = (short)-speed;
            }

            // Ghidra: `test al,10h` puis `and eax,0efffffffh`. Deux bits differents. Voir le resume.
            if ((flags & 0x10) != 0) return;
            *(uint*)e = flags & 0xefffffff;
            return;
        }

        short state = *(short*)(e + 0x10);

        if (state == 1 || state == 0)
        {
            flags |= 0x10000000;
            *(short*)(e + 0x10) = 2;
            *(short*)(e + 0x12) = 10;
            *(uint*)e = flags;

            TryPlaySoundNearEntity((uint*)e, SubAreaSounds()[0x18], 0x400, 0x1000, 0, 0);
        }

        if (*(short*)(e + 0x10) != 2) return;

        short remaining = *(short*)(e + 0x12);

        if (remaining > 0)
        {
            remaining--;
            *(short*)(e + 0x12) = remaining;
            *(int*)(e + 0x20) -= remaining << 0xc;
            return;
        }

        int rising = *(int*)(e + 0x20) + 0x5000;
        *(int*)(e + 0x20) = rising;

        int home = *(short*)(e + 0x14) << 0xc;
        if (home > rising) return;

        *(int*)(e + 0x20) = home;
        *(uint*)e |= 0x40000000;
        *(short*)(e + 0x10) = 1;
        *(short*)(e + 0x16) = -1;
        *(short*)(e + 0x12) = 100;
    }

    // =====================================================================
    // LES DEUX SCENES CINEMA DE LA FORET (2026-08-30)
    //
    // Quatre creneaux, deux corps. 0x00410820 et 0x00413c90 sont le meme corps a 286 instructions,
    // decompile dans Blaze.c ; 0x00411240 et 0x004146b0 sont deux AMORCES de dix instructions vers
    // FUN_00411270 et FUN_00414d10, elles aussi decompilees et elles aussi identiques entre elles.
    //
    // Dans les deux cas la seule difference entre les exemplaires est la BASE DU BLOC PRIVE :
    // l'enregistrement 0 (0x00571420) pour les uns, le 1 (0x00571450) pour les autres. Elles sont
    // donc parametrees par un simple indice.
    //
    // Ces quatre-la avaient ete mises de cote le 2026-08-30 pour trois raisons : le bloc prive non
    // modelise, et deux appelees « manquantes ». Aucune des trois ne tenait — FUN_00423d10 et
    // FUN_0040b0e0 sont dans Blaze.c, et font quinze et quarante lignes.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_00423d10 @ 0x00423d10 — <b>desarme les quatre emplacements</b>. Decompilee dans
    /// <c>Blaze.c</c>, quinze lignes : elle efface le bit <c>0x4000000</c> sur les quatre fiches,
    /// et rien d'autre.
    ///
    /// <para>C'est la remise a zero du compteur d'attente de <see cref="WaitForPartyToSettle"/> :
    /// tant que les quatre bits ne sont pas revenus, la scene n'avance pas.</para>
    /// </summary>
    private static void DisarmPartySlots_00423D10()
    {
        byte* slot = Inp.s_SlotFlags_005e93c0;
        for (int i = 0; i < 4; i++, slot += 0x9c) *(uint*)slot &= 0xfbffffff;
    }

    /// <summary>
    /// Ghidra: FUN_0040b0e0 @ 0x0040b0e0 — <b>attend que les quatre membres soient poses</b>.
    /// Decompilee dans <c>Blaze.c</c>. Rend <c>true</c> quand les quatre portent le bit
    /// <c>0x4000000</c>.
    ///
    /// <para>
    /// <b>Chaque membre tombe dans un des trois cas.</b> Le binaire les calcule par deux tests
    /// enchevetres que Ghidra rend avec des <c>goto</c> ; reconstruits, ils disent :
    /// </para>
    /// <list type="number">
    /// <item><b>a preparer</b> — le membre est vivant, il ne porte aucun des bits d'occupation
    /// <c>0x44000003</c> ni <c>0x50000000</c>. Il est remis en pose neutre : teinte blanche, pose
    /// et image a zero, <c>+0x0a</c> et <c>+0x96</c> effaces, le bit <c>0x40</c> retire et
    /// <c>0x1000000</c> pose. Puis il est marque pret.</item>
    /// <item><b>hors jeu</b> — mort, absent ou occupe autrement : marque pret sans etre
    /// touche.</item>
    /// <item><b>encore occupe</b> — vivant et portant un bit de <c>0x44000003</c> : rien du tout,
    /// et la scene attendra une image de plus.</item>
    /// </list>
    /// <para>
    /// <b>Le mot de drapeaux est relu apres avoir ete ecrit</b> dans le premier cas — le second
    /// masque part de la valeur fraiche, pas de celle du debut. Conserve tel quel.
    /// </para>
    /// </summary>
    private static bool WaitForPartyToSettle()
    {
        byte* slot = Inp.s_SlotFlags_005e93c0;

        for (int i = 0; i < 4; i++, slot += 0x9c)
        {
            uint flags = *(uint*)slot;
            short verdict = 0;

            if ((flags & 0x44000003) == 0 && (flags & 0x80000000) != 0) verdict = 1;

            if ((flags & 0x80000000) == 0 || (flags & 0x50000000) != 0) verdict = 2;

            if (verdict == 1)
            {
                *(uint*)slot = flags & 0xffffffbf | 0x4000000;

                slot[0x0a] = 0;
                slot[0x38] = 0xff;
                slot[0x39] = 0xff;
                slot[0x3a] = 0xff;
                *(ushort*)(slot + 0x36) &= 0xfffb;
                *(short*)(slot + 0x96) = 0;

                // Ghidra relit *puVar2 ici : le masque part de la valeur qui vient d'etre ecrite.
                *(uint*)slot = *(uint*)slot & 0xf7fffffb | 0x1000000;

                *(short*)(slot + 0x18) = 0;
                *(short*)(slot + 0x1a) = 0;
            }

            if (verdict == 2) *(uint*)slot |= 0x4000000;
        }

        short ready = 0;
        slot = Inp.s_SlotFlags_005e93c0;
        for (int i = 0; i < 4; i++, slot += 0x9c)
        {
            if ((*(uint*)slot & 0x4000000) != 0) ready++;
        }

        return ready == 4;
    }

    /// <summary>
    /// La pose de fin de scene, par classe. Les deux scenes cinema portent la <b>meme</b> table,
    /// ecrite en toutes lettres dans chacune : seize couples <c>(pose, image)</c>, choisis par les
    /// trois bits bas de l'octet d'identite <c>+0x150</c> de la fiche de personnage, le bit
    /// <c>3</c> departageant les deux moities.
    ///
    /// <para>Aucun des seize couples n'est calculable a partir de la classe : c'est une table, et
    /// elle est relevee comme telle.</para>
    /// </summary>
    private static void ApplyCutscenePose(byte* slot, byte identity)
    {
        int cls = identity & 7;

        short pose, frame;

        if ((identity & 8) == 0)
        {
            switch (cls)
            {
                case 0: pose = 5; frame = 1; break;
                case 1: pose = 6; frame = 0x12; break;
                case 2: pose = 4; frame = 5; break;
                case 3: pose = 3; frame = 3; break;
                case 4: pose = 5; frame = 8; break;
                case 5: pose = 6; frame = 9; break;
                case 6: pose = 6; frame = 0x0b; break;
                default: pose = 6; frame = 0x12; break;
            }
        }
        else
        {
            switch (cls)
            {
                case 0: pose = 6; frame = 4; break;
                case 1: pose = 6; frame = 9; break;
                case 2: pose = 3; frame = 0; break;
                case 3: pose = 6; frame = 0x12; break;
                case 4: pose = 5; frame = 8; break;
                case 5: pose = 7; frame = 5; break;
                case 6: pose = 6; frame = 4; break;
                default: pose = 6; frame = 9; break;
            }
        }

        *(short*)(slot + 0x18) = pose;
        *(short*)(slot + 0x1a) = frame;
    }

    /// <summary>Les quatre membres remis a blanc en tete de chaque image de scene : teinte pleine,
    /// <c>+0x0a</c> et <c>+0x96</c> effaces, bit 2 de <c>+0x36</c> retire. Les deux corps de scene
    /// ouvrent par cette meme boucle.</summary>
    private static void ResetPartyAppearance()
    {
        byte* slot = Inp.s_SlotFlags_005e93c0;

        for (int i = 0; i < 4; i++, slot += 0x9c)
        {
            slot[0x0a] = 0;
            slot[0x38] = 0xff;
            slot[0x39] = 0xff;
            slot[0x3a] = 0xff;
            *(ushort*)(slot + 0x36) &= 0xfffb;
            *(short*)(slot + 0x96) = 0;
        }
    }

    /// <summary>
    /// La camera privee prend la main : le bloc <paramref name="record"/> recoit la pose du membre
    /// vise, et les trois pointeurs <c>DAT_005e9ae0</c> / <c>DAT_005eca94</c> / <c>DAT_005edebc</c>
    /// y sont detournes. Les deux corps de scene font exactement cela, au bloc pres.
    ///
    /// <para><b>La cible est tiree au sort autour du membre</b> : l'azimut prend <c>+200</c> plus
    /// un tirage sur 400, l'elevation <c>+0x200</c> plus un tirage sur 200, et la distance
    /// <c>+700</c> plus un tirage sur 200. La scene ne cadre donc jamais deux fois pareil.</para>
    /// </summary>
    private static void TakeCutsceneCamera(byte* e, byte* record)
    {
        byte* slots = Inp.s_SlotFlags_005e93c0;
        int index = *(short*)(e + 0x12);
        byte* member = slots + index * 0x9c;

        *(int*)(e + 0x1c) = *(int*)(member + 0x1c);
        *(int*)(e + 0x20) = *(int*)(member + 0x20);
        *(int*)(e + 0x24) = *(int*)(member + 0x24);
        *(short*)(e + 0x30) = *(short*)(member + 0x30);
        *(short*)(e + 0x32) = *(short*)(member + 0x32);

        *(int*)(record + 0x18) = *(int*)(e + 0x1c);

        *(short*)(e + 0x34) = *(short*)(member + 0x34);
        *(short*)(e + 0x10) = 3;
        *(short*)(e + 0x16) = 0;

        *(int*)(record + 0x1c) = *(int*)(e + 0x20);
        *(int*)(record + 0x20) = *(int*)(e + 0x24);

        *(short*)(record + 0) = (short)(CrtRand() % 400 + *(short*)(e + 0x30) + 200);
        *(short*)(record + 2) = (short)(CrtRand() % 200 + *(short*)(e + 0x32) + 0x200);
        *(short*)(record + 4) = *(short*)(e + 0x34);

        int* target = *(int**)Mem.Entity(0x005eca94);
        *(int*)(record + 8) = target[0];
        *(int*)(record + 0x0c) = target[1];
        *(int*)(record + 0x10) = target[2];

        int distance = CrtRand();

        *(byte**)Mem.Entity(0x005eca94) = record + 8;
        *(byte**)Mem.Arena(0x005e9ae0) = record;
        *(byte**)Mem.Entity(0x005edebc) = record + 0x18;

        *(int*)(record + 0x10) = distance % 200 + 700;
    }

    /// <summary>La camera de marche reprend la main : les trois memes pointeurs remis sur
    /// <c>0x005de078</c>, <c>0x00564650</c> et <c>0x005de068</c>, puis le mode de camera
    /// rappele.</summary>
    private static void ReleaseCutsceneCamera()
    {
        *(byte**)Mem.Entity(0x005eca94) = (byte*)Mem.Camera(0x005de078);
        *(byte**)Mem.Arena(0x005e9ae0) = s_WorldMapCamera_00564650;
        *(byte**)Mem.Entity(0x005edebc) = (byte*)Mem.Camera(0x005de068);

        CameraModeApply_005037E0(0);                          // Ghidra: FUN_005037b0
    }

    /// <summary>Le fondu des deux voiles pendant une scene : le second monte ou descend de dix par
    /// canal, le premier de trois. C'est le meme rapport que
    /// <see cref="EntityHandler_0040EDF0"/>.</summary>
    private static void ShiftCutsceneVeils(int step)
    {
        Mem.s_Unknown_005de028 = ShiftScreenVeil(Mem.s_Unknown_005de028, 10 * step);
        Mem.s_Unknown_005de024 = ShiftScreenVeil(Mem.s_Unknown_005de024, 3 * step);
    }

    /// <summary>Ghidra: <c>0x00410820</c> — la premiere scene cinema, bloc prive 0.</summary>
    private static void EntityHandler_00410820(byte* e)
        => TickForestCutscene(e, ForestSceneRecord(0));

    /// <summary>Ghidra: <c>0x00413c90</c> — la seconde, bloc prive 1. Comparee instruction par
    /// instruction : <b>seules les onze adresses du bloc different</b>.</summary>
    private static void EntityHandler_00413C90(byte* e)
        => TickForestCutscene(e, ForestSceneRecord(1));

    /// <summary>
    /// Ghidra: FUN_00410820 @ 0x00410820 (et FUN_00413c90) — <b>la scene cinema muette de la
    /// foret</b>. Decompilee dans <c>Blaze.c</c>, 286 instructions.
    ///
    /// <para>
    /// <b>Cinq etats, puis un compte a rebours de 202 images.</b> L'etat 0 desarme les quatre
    /// emplacements et retient dans <c>+0x12</c> le membre que la memoire du bloc designe ; l'etat
    /// 1 attend que les quatre soient poses ; l'etat 2 detourne la camera ; l'etat 3 seme l'entite
    /// de sous-type <c>+0x98 + 0xc0</c> et passe a 4, ou plus rien ne se fait. Tout le reste est
    /// gouverne par <c>+0x16</c>, qui monte d'un par image sans jamais redescendre.
    /// </para>
    /// <list type="bullet">
    /// <item><b>0x82 a 0x9a</b> — les deux voiles montent, le second de dix par canal, le premier
    /// de trois : l'ecran blanchit en vingt-cinq images.</item>
    /// <item><b>0x9b</b> — la pose de fin est posee sur les quatre membres, par la table de
    /// <see cref="ApplyCutscenePose"/>. C'est l'image ou l'ecran est le plus clair, donc celle ou
    /// le changement ne se voit pas.</item>
    /// <item><b>0x9b a 0xb3</b> — les deux voiles redescendent au meme rapport.</item>
    /// <item><b>0xc8</b> — les deux voiles sont remis a zero net, canaux compris.</item>
    /// <item><b>0xca</b> — la camera de marche revient, le script 1 part sur le membre vise, et
    /// l'entite s'eteint.</item>
    /// </list>
    /// <para>
    /// <b>Le mode de camera est rappele deux fois de suite</b> a la derniere image, une fois avant
    /// le detournement des pointeurs et une fois apres. Ghidra le rend ainsi et le desassemblage le
    /// confirme.
    /// </para>
    /// </summary>
    private static void TickForestCutscene(byte* e, byte* record)
    {
        *(short*)(e + 0x98) = 0x38;
        ResetPartyAppearance();

        if (*(short*)(e + 0x10) == 0)
        {
            DisarmPartySlots_00423D10();
            *(short*)(e + 0x10) = 1;
            *(short*)(e + 0x12) = record[0x28];
        }

        if (*(short*)(e + 0x10) == 1 && WaitForPartyToSettle()) *(short*)(e + 0x10) = 2;

        if (*(short*)(e + 0x10) == 2) TakeCutsceneCamera(e, record);

        if (*(short*)(e + 0x10) == 3)
        {
            *(short*)(e + 0x10) = 4;
            *(short*)(e + 0x14) = 2;
            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), null, (byte)(*(short*)(e + 0x98) + 0xc0), 0, -1);
        }

        (*(short*)(e + 0x16))++;

        short beat = *(short*)(e + 0x16);

        if (beat > 0x81 && beat < 0x9b) ShiftCutsceneVeils(+1);

        if (beat == 0x9b)
        {
            byte* mainMem = GetMainMemPtr();
            byte* slot = Inp.s_SlotFlags_005e93c0;

            for (int i = 0; i < 4; i++, slot += 0x9c)
            {
                uint flags = *(uint*)slot;
                if ((flags & 0x80000000) == 0 || (flags & 0x50000000) != 0) continue;

                ApplyCutscenePose(slot, mainMem[(slot[8] + 0x78) * 0x2000 + 0x150]);
            }
        }

        if (beat > 0x9a && beat < 0xb4) ShiftCutsceneVeils(-1);

        if (beat == 200)
        {
            Mem.s_Unknown_005de028 = 0x01000000;
            Mem.s_Unknown_005de024 = 0x01000000;
        }

        if (beat != 0xca) return;

        CameraModeApply_005037E0(0);                          // Ghidra: FUN_005037b0, le premier
        RunEntityScript(
            s_Unknown_005e97cc, Inp.s_SlotFlags_005e93c0 + *(short*)(e + 0x12) * 0x9c, 1);

        ReleaseCutsceneCamera();                              // FUN_005037b0, le second
        *(uint*)e &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: <c>0x00411240</c> — <b>l'amorce de la scene cinema parlante</b>, bloc prive 0.
    /// Absente de <c>Blaze.c</c> ; dix instructions. Elle pose <c>+0x98 = 0x39</c> et appelle
    /// <c>FUN_00411270</c> avec trois constantes : le script <c>1</c>, la memoire d'emplacement du
    /// bloc, et <c>-1</c> pour « ne pas changer de musique ».
    /// </summary>
    private static void EntityHandler_00411240(byte* e)
    {
        byte* record = ForestSceneRecord(0);
        *(short*)(e + 0x98) = 0x39;
        TickForestCutsceneWithDialogue(e, record, 1, record[0x28], 0xffff);
    }

    /// <summary>Ghidra: <c>0x004146b0</c> — la meme amorce sur le bloc prive 1. Les deux corps
    /// appeles, <c>FUN_00411270</c> et <c>FUN_00414d10</c>, ne different eux aussi que par les
    /// adresses du bloc.</summary>
    private static void EntityHandler_004146B0(byte* e)
    {
        byte* record = ForestSceneRecord(1);
        *(short*)(e + 0x98) = 0x39;
        TickForestCutsceneWithDialogue(e, record, 1, record[0x28], 0xffff);
    }

    /// <summary>
    /// Ghidra: FUN_00411270 @ 0x00411270 (et FUN_00414d10) — <b>la scene cinema parlante de la
    /// foret</b>. Decompilee dans <c>Blaze.c</c>.
    ///
    /// <para>
    /// C'est <see cref="TickForestCutscene"/> avec quatre ajouts, et une soustraction. Le squelette
    /// est identique — desarmement, attente, camera privee, semis, puis le compte de <c>+0x16</c>
    /// avec ses deux fondus et sa pose de fin a <c>0x9b</c>.
    /// </para>
    /// <list type="bullet">
    /// <item><b>Cinq sons</b> ponctuent le debut (<c>0x0f</c>, <c>9</c>, <c>0x2f</c> aux images 0,
    /// 1 et 2) et le fondu au blanc (<c>5</c> deux fois, aux images <c>0x82</c> et <c>0x83</c>,
    /// la seconde plus aigue). La scene muette n'en joue aucun.</item>
    /// <item><b>Une boite de dialogue</b> s'ouvre a l'image 200, au moment ou les voiles retombent
    /// a zero, sur la fiche du membre vise et avec l'etiquette <c>+0x490</c> du repertoire
    /// principal.</item>
    /// <item><b>Le script part sans entite</b> : <c>RunEntityScript(repertoire, null, script)</c>,
    /// la ou la scene muette le lance sur le membre. Et il ne part que si
    /// <paramref name="script"/> vaut autre chose que <c>-1</c>.</item>
    /// <item><b>Un changement de musique optionnel</b>, si <paramref name="music"/> n'est pas
    /// <c>0xffff</c> et que la piste demandee n'est pas deja en cours : la piste demarre et chaque
    /// membre vivant recoit l'effet <c>0x59</c>. Les deux amorces connues passent <c>0xffff</c>,
    /// donc <b>ce bloc ne s'execute jamais par elles</b> — il est transcrit parce qu'il est la, pas
    /// parce qu'on l'a vu tourner.</item>
    /// </list>
    /// <para>
    /// <b>La soustraction</b> : le mode de camera n'est rappele qu'une fois a la fin, contre deux
    /// dans la scene muette.
    /// </para>
    /// <para>
    /// <b>Le meme defaut de descripteur que la gerbe.</b> Le semis de l'etat 3 passe le tampon de
    /// pile <c>local_8</c>, que rien ne remplit — voir <c>LB-014</c> dans <c>legacy-bug.md</c>. La
    /// scene muette, elle, passe proprement <c>0</c> au meme endroit.
    /// </para>
    /// </summary>
    /// <param name="script">L'indice de script lance a la derniere image, ou <c>-1</c> pour n'en
    /// lancer aucun.</param>
    /// <param name="member">Le membre du groupe que la scene cadre. Les deux amorces y passent la
    /// memoire d'emplacement du bloc.</param>
    /// <param name="music">La piste a lancer en sortant, ou <c>0xffff</c> pour n'y pas
    /// toucher.</param>
    private static void TickForestCutsceneWithDialogue(
        byte* e, byte* record, short script, short member, ushort music)
    {
        // Le tampon jamais rempli du binaire, comme dans TickFivePhaseBurst. Voir LB-014.
        byte* scratch = stackalloc byte[8];

        ResetPartyAppearance();

        if (*(short*)(e + 0x10) == 0)
        {
            DisarmPartySlots_00423D10();
            *(short*)(e + 0x10) = 1;
            *(short*)(e + 0x12) = member;
        }

        if (*(short*)(e + 0x10) == 1 && WaitForPartyToSettle()) *(short*)(e + 0x10) = 2;

        if (*(short*)(e + 0x10) == 2) TakeCutsceneCamera(e, record);

        if (*(short*)(e + 0x10) == 3)
        {
            *(short*)(e + 0x10) = 4;
            *(short*)(e + 0x14) = 2;
            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), scratch, (byte)(*(short*)(e + 0x98) + 0xc0), 0, -1);
        }

        if (*(short*)(e + 0x16) == 0) Aud.PlaySoundEffect(0x0f, 0x200, 0x1000, 0x1000);
        if (*(short*)(e + 0x16) == 1) Aud.PlaySoundEffect(9, 0x100, 0x1000, 0x1000);
        if (*(short*)(e + 0x16) == 2) Aud.PlaySoundEffect(0x2f, 0x400, 0x1000, 0x1000);

        (*(short*)(e + 0x16))++;

        short beat = *(short*)(e + 0x16);

        if (beat == 0x82) Aud.PlaySoundEffect(5, 0x100, 0x1000, 0x1000);
        if (beat == 0x83) Aud.PlaySoundEffect(5, 0x16a, 0x1000, 0x1000);

        if (beat > 0x81 && beat < 0x9b) ShiftCutsceneVeils(+1);

        if (beat == 0x9b)
        {
            byte* mainMem = GetMainMemPtr();
            byte* slot = Inp.s_SlotFlags_005e93c0;

            for (int i = 0; i < 4; i++, slot += 0x9c)
            {
                uint flags = *(uint*)slot;
                if ((flags & 0x80000000) == 0 || (flags & 0x50000000) != 0) continue;

                ApplyCutscenePose(slot, mainMem[(slot[8] + 0x78) * 0x2000 + 0x150]);
            }
        }

        if (beat > 0x9a && beat < 0xb4) ShiftCutsceneVeils(-1);

        if (beat == 200)
        {
            Mem.s_Unknown_005de028 = 0x01000000;
            Mem.s_Unknown_005de024 = 0x01000000;

            byte* labels =
                *(byte**)(*(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x70) + 0x490);

            BindMenuLabels(
                labels,
                Inp.s_SlotFlags_005e93c0 + *(short*)(e + 0x12) * 0x9c,
                s_WorldMapDescriptor_005633b0,
                0);
        }

        if (beat != 0xca) return;

        if (script != -1) RunEntityScript(s_Unknown_005e97cc, null, (uint)script);

        if (music != 0xffff)
        {
            s_Unknown_005de534 = (byte)music;

            if (s_Unknown_00566c8c != s_Unknown_005de534)
            {
                s_Unknown_00566c8c = (byte)s_Unknown_005de534;
                PlayMusicTrack(music & 0xff);                 // Ghidra: FUN_00529ad0

                byte* slot = Inp.s_SlotFlags_005e93c0;
                for (int i = 0; i < 4; i++, slot += 0x9c)
                {
                    uint flags = *(uint*)slot;
                    if ((flags & 0x80000000) == 0 || (flags & 0x50000000) != 0) continue;

                    SpawnEffectEntity(slot, 0x59, 0, -1);     // Ghidra: FUN_0047a9d0
                }
            }
        }

        ReleaseCutsceneCamera();
        *(uint*)e &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: <c>0x0040ef40</c> — <b>le geyser et sa partition</b>. Absent de <c>Blaze.c</c> ;
    /// releve au desassembleur, 158 instructions. Table <c>0x0056b2c8</c>, foret, sous-zones 0 a 4.
    ///
    /// <para>
    /// <b>Sa planche est le sixieme enregistrement d'un bloc deja releve</b> : <c>0x0054f7f0</c>
    /// est la tuile <c>0x17 x 0x0f</c> que le commentaire de <see cref="s_Descriptors_0054F7C8"/>
    /// signalait deja comme « d'une autre planche ». Troisieme fois que la regle « relever la
    /// plage » evite un trou.
    /// </para>
    /// <para>
    /// <b>Trois etats, et il ne dessine presque rien lui-meme.</b> A la naissance il monte de
    /// <c>0x28000</c> et seme un <c>0xfc</c> ; l'etat 1 seme un <c>0xfb</c> par image pendant
    /// soixante images, monte de <c>0x2000</c> et grandit de cent par axe — l'echelle horizontale
    /// bornee a <c>0x800</c>, la verticale a <c>0x9c4</c>, donc un jet qui s'etire plus haut que
    /// large ; l'etat 2 seme toujours et fait <b>onduler</b> la hauteur au sinus d'un angle qui
    /// avance de <c>0x50</c> par image, jusqu'a <c>0x2710</c>.
    /// </para>
    /// <para>
    /// <b>La partition est en dur, sur un compteur qui n'est jamais remis a zero.</b> Neuf sons
    /// aux images <c>0</c>, <c>1</c>, <c>2</c>, <c>3</c>, puis <c>0x28</c> a <c>0x2b</c>, puis
    /// <c>0x50</c> — deux accords de trois notes montantes suivis d'une basse, puis une reprise.
    /// Elle tourne a chaque image <b>sauf une</b> : le passage de l'etat 1 a l'etat 2 rend la main
    /// avant, et cette image-la est muette.
    /// </para>
    /// </summary>
    private static void EntityHandler_0040EF40(byte* e)
    {
        if (*(short*)(e + 0x10) == 0)
        {
            int spout = *(int*)(e + 0x1c) + 0x28000;

            *(short*)(e + 0x10) = 1;
            *(byte**)(e + 0x3c) = Descriptors0054F7C8() + 0x28;   // Ghidra: &DAT_0054f7f0
            e[0x40] = 0;
            e[0x0a] = 0x0a;
            e[0x0b] = 0;
            *(short*)(e + 0x28) = 0;
            *(short*)(e + 0x2a) = 0;
            *(short*)(e + 0x12) = 0;

            *(int*)(e + 0x1c) = spout;
            SpawnStatusEffectEntity_0047AC40(e, (int*)(e + 0x1c), null, 0xfc, 0, -1);

            *(short*)(e + 0x98) = 0;
        }

        if (*(short*)(e + 0x10) == 1)
        {
            SpawnStatusEffectEntity_0047AC40(e, (int*)(e + 0x1c), null, 0xfb, 0, -1);

            *(int*)(e + 0x20) += 0x2000;
            *(short*)(e + 0x28) += 100;
            *(short*)(e + 0x2a) += 100;

            if (*(short*)(e + 0x28) >= 0x800) *(short*)(e + 0x28) = 0x800;
            if (*(short*)(e + 0x2a) >= 0x9c4) *(short*)(e + 0x2a) = 0x9c4;

            (*(short*)(e + 0x12))++;

            if (*(short*)(e + 0x12) >= 0x3c)
            {
                // Le binaire rend la main ici : la partition ne joue pas a cette image.
                *(short*)(e + 0x10) = 2;
                *(short*)(e + 0x12) = 0;
                return;
            }
        }

        if (*(short*)(e + 0x10) == 2)
        {
            SpawnStatusEffectEntity_0047AC40(e, (int*)(e + 0x1c), null, 0xfb, 0, -1);

            short wave = *(short*)(e + 0x12);
            *(short*)(e + 0x12) += 0x50;
            *(int*)(e + 0x20) += (int)Winsys3d.GetSinTableEntry(wave) * 2;

            if (*(short*)(e + 0x12) > 0x2710) *(uint*)e &= 0x7fffffff;
        }

        GeyserScore(*(short*)(e + 0x98));
        (*(short*)(e + 0x98))++;
    }

    /// <summary>La partition du geyser : neuf notes a neuf images fixes, ecrites en toutes lettres
    /// dans le binaire. Les gains sont les memes partout (<c>0x1000</c> des deux cotes) ; seuls
    /// l'identifiant et la hauteur changent.</summary>
    private static void GeyserScore(short beat)
    {
        if (beat == 0) Aud.PlaySoundEffect(0x27, 0x200, 0x1000, 0x1000);
        if (beat == 1) Aud.PlaySoundEffect(0x27, 0x27f, 0x1000, 0x1000);
        if (beat == 2) Aud.PlaySoundEffect(0x27, 0x329, 0x1000, 0x1000);
        if (beat == 3) Aud.PlaySoundEffect(0x30, 0x200, 0x1000, 0x1000);

        if (beat == 0x28) Aud.PlaySoundEffect(0x27, 0x200, 0x1000, 0x1000);
        if (beat == 0x29) Aud.PlaySoundEffect(0x27, 0x2d4, 0x1000, 0x1000);
        if (beat == 0x2a) Aud.PlaySoundEffect(0x27, 0x37e, 0x1000, 0x1000);
        if (beat == 0x2b) Aud.PlaySoundEffect(0x30, 0x1bf, 0x1000, 0x1000);

        if (beat == 0x50) Aud.PlaySoundEffect(0x30, 0x27f, 0x1000, 0x1000);
    }

    /// <summary>Ghidra: <c>&amp;DAT_0054f840</c> — sept enregistrements jusqu'a
