    /// <summary>
    /// Ghidra: FUN_0044fb10 @ 0x0044fb10 — <b>l'etincelle de la bouffee</b> : le sous-type
    /// <c>0xa9</c> que <see cref="EntityHandler_00446790"/> seme par paires. Entree 169 de la table
    /// <b>statique</b> <c>0x00552230</c>. Decompilee dans <c>Blaze.c</c>.
    ///
    /// <para>
    /// <b>Elle tire tout son etat au hasard en naissant</b>, en sept appels au generateur : la
    /// vitesse de montee (<c>rand%10 + 12</c>), un cap sur le tour complet et un rayon, la vitesse
    /// d'ouverture (<c>rand%600 + 600</c>), la duree de vie (<c>rand%15 + 10</c> images) et le
    /// plafond d'ouverture (<c>rand%3000 + 4000</c>). Deux etincelles nees la meme image ne se
    /// ressemblent donc jamais.
    /// </para>
    /// <para>
    /// <b>Le cap est un modulo signe ecrit sans division.</b> Ghidra en rend les cinq operations
    /// telles quelles (<c>((u ^ m) - m &amp; 0xfff ^ m) - m</c> avec <c>m</c> le masque de signe) :
    /// c'est <c>x % 0x1000</c> a la mode du C, celui qui tronque vers zero et garde le signe du
    /// dividende. Rendu par ce qu'il calcule.
    /// </para>
    /// <para>
    /// Le rayon est tire modulo <c>+0x14</c>, que la mere a mis a <c>0x50</c> avant de la faire
    /// naitre — puis <b>le meme champ devient la duree de vie</b> quelques lignes plus bas. Un
    /// champ, deux roles successifs, et l'ordre des deux lectures est ce qui les separe.
    /// </para>
    /// <para>
    /// <b>Ensuite elle monte, s'ouvre et s'assombrit.</b> Chaque image : la teinte perd
    /// <c>3 + rand%7</c> sur les trois canaux, les deux rayons <c>+0x28</c> et <c>+0x2a</c>
    /// grandissent de <c>+0x16</c> jusqu'a leur plafond, la hauteur monte de la vitesse courante, et
    /// cette vitesse <b>accelere une image sur deux</b> — sur la parite de la duree de vie
    /// restante — jusqu'a <c>0x1e</c>. A zero, l'entite perd son bit <c>0x80000000</c>.
    /// </para>
    /// </summary>
    private static void EntityHandler_0044FB10(byte* e)
    {
        if (*(short*)(e + 0x10) == 0)
        {
            *(short*)(e + 0x10) = 1;
            *(byte**)(e + 0x3c) = Descriptors00551528();
            e[0x40] = 0;
            e[0x0a] = e[0x9a];
            e[0x0b] = 0;

            *(short*)(e + 0x12) = 0;
            *(int*)(e + 0x5c) = CrtRand() % 10 + 0xc;

            // Ghidra: les deux tirages sont faits AVANT que l'un ou l'autre ne serve — le cap est
            // calcule sur le premier, le rayon sur le second.
            int spun = CrtRand();
            int spread = CrtRand();

            short heading = (short)(spun % 0x1000);
            short radius = (short)(spread % *(short*)(e + 0x14));

            *(int*)(e + 0x1c) += (int)Winsys3d.GetSinTableEntry(heading) * radius;

            *(short*)(e + 0x28) = 0;
            *(short*)(e + 0x2a) = 0;

            *(int*)(e + 0x24) += Winsys3d.GetCosTableEntry(heading) * radius;

            int growth = CrtRand();
            e[0x38] = 0xb4;
            e[0x39] = 0xb4;
            e[0x3a] = 0xb4;
            *(short*)(e + 0x16) = (short)(growth % 600 + 600);

            // Le meme +0x14 qui vient de servir de borne au rayon devient la duree de vie.
            *(short*)(e + 0x14) = (short)(CrtRand() % 0xf + 10);
            *(short*)(e + 0x9a) = (short)(CrtRand() % 3000 + 4000);
        }

        if (*(short*)(e + 0x10) != 1) return;

        short fade = (short)(-3 - CrtRand() % 7);
        BrightenEntityTint_00404DE0(e, fade, fade, fade);

        *(short*)(e + 0x28) += *(short*)(e + 0x16);
        *(short*)(e + 0x2a) += *(short*)(e + 0x16);

        short ceiling = *(short*)(e + 0x9a);
        if (ceiling < *(short*)(e + 0x28)) *(short*)(e + 0x28) = ceiling;
        if (ceiling < *(short*)(e + 0x2a)) *(short*)(e + 0x2a) = ceiling;

        (*(short*)(e + 0x12))++;
        *(int*)(e + 0x20) += *(int*)(e + 0x5c) * 0x1000;

        // Ghidra: la parite est lue sur le mot NON SIGNE de +0x14, la duree de vie restante.
        if ((*(ushort*)(e + 0x14) & 1) != 0)
        {
            int rise = *(int*)(e + 0x5c) + 1;
            *(int*)(e + 0x5c) = rise;
            if (rise > 0x1e) *(int*)(e + 0x5c) = 0x1e;
        }

        short life = (short)(*(ushort*)(e + 0x14) - 1);
        *(short*)(e + 0x14) = life;
        if (life < 0) *(uint*)e &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: FUN_00446790 @ 0x00446790 — <b>la bouffee de l'objet utilise</b> : ce que le script
    /// d'une potion fait naitre au-dessus de celui qui s'en sert. Entree de la table <b>statique</b>
    /// <see cref="s_StaticEntityHandlers_00551c30"/>, donc valable dans les onze zones.
    /// Decompilee dans <c>Blaze.c</c>.
    ///
    /// <para>
    /// <b>Elle se recale sur son porteur a chaque image</b> : les trois mots de position viennent
    /// de l'entite de <c>+0x6c</c>, et <b>si ce champ est nul c'est l'enregistrement modele
    /// <c>0x005de558</c> qui sert de source</b> — une entite orpheline se pose donc a l'origine
    /// plutot que de dereferencer un pointeur nul. C'est une garde du binaire, pas de la
    /// transcription.
    /// </para>
    /// <para>
    /// <b>Sa premiere image seme quatre filles d'un coup</b> (sous-type <c>0xa9</c>, sans atlas),
    /// puis <b>deux de plus a chaque image impaire</b>. Les quatre appels sont ecrits quatre fois
    /// dans l'original avec les memes arguments — ce n'est pas une boucle deroulee par le
    /// compilateur mais quatre appels distincts, et la transcription les rend par une boucle de
    /// quatre tours, qui est le meme calcul.
    /// </para>
    /// <para>
    /// Deux sons, a des images precises et une seule fois chacun : <c>0x30</c> a l'image 0,
    /// <c>0x2f</c> a l'image 2. Puis le compteur <c>+0x16</c> monte, et passe <b>0x28</b> l'entite
    /// s'eteint en perdant son bit <c>0x80000000</c>.
    /// </para>
    /// <para>
    /// L'octet <c>+0x0a</c> — que <see cref="SpawnEffectEntity"/> a pose en naissant — sert deux
    /// fois : il devient le mot <c>+0x9a</c> a la premiere image, et il est le dernier argument de
    /// chaque naissance de fille. C'est la saveur de l'objet, transmise a l'effet visible.
    /// </para>
    /// </summary>
    private static void EntityHandler_00446790(byte* e)
    {
        // Ghidra: le corps entier est sous `if (param_1 != NULL)`.
        if (e == null) return;

        byte* parent = *(byte**)(e + 0x6c);
        if (parent == null) parent = Res.s_EntityList_005de558;

        *(int*)(e + 0x1c) = *(int*)(parent + 0x1c);
        *(int*)(e + 0x20) = *(int*)(parent + 0x20);
        *(int*)(e + 0x24) = *(int*)(parent + 0x24);

        if (*(short*)(e + 0x10) == 0)
        {
            *(short*)(e + 0x10) = 1;
            *(short*)(e + 0x12) = 0;
            *(short*)(e + 0x14) = 0x50;
            *(short*)(e + 0x16) = 0;
            *(ushort*)(e + 0x9a) = e[0x0a];

            // Ghidra: quatre appels identiques ecrits quatre fois.
            for (int i = 0; i < 4; i++)
            {
                SpawnStatusEffectEntity_0047AC40(e, (int*)(e + 0x1c), null, 0xa9, e[0x0b], e[0x0a]);
            }
        }

        if (*(short*)(e + 0x16) == 0) Aud.PlayPositionalSound(0x30, 0x200, 0x1000, (int*)(e + 0x1c));
        if (*(short*)(e + 0x16) == 2) Aud.PlayPositionalSound(0x2f, 0x653, 0x1500, (int*)(e + 0x1c));

        // Ghidra: `*(byte *)((int)param_1 + 0x16) & 1` — l'octet BAS du compteur, donc une image
        // sur deux.
        if ((e[0x16] & 1) != 0)
        {
            *(short*)(e + 0x14) = 0x50;

            for (int i = 0; i < 2; i++)
            {
                SpawnStatusEffectEntity_0047AC40(e, (int*)(e + 0x1c), null, 0xa9, e[0x0b], e[0x0a]);
            }
        }

        (*(short*)(e + 0x16))++;
        if (*(short*)(e + 0x16) > 0x28) *(uint*)e &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: <c>0x00447280</c> — <b>l'entree 57 de la table statique
    /// <see cref="s_StaticEntityHandlers_00551c30"/></b>, 255 octets, <b>absente de
    /// <c>Blaze.c</c></b> ; relevé garde sous <c>Legacy/Raw/Blaze/FUN_00447280.asm</c>.
    ///
    /// <para>
    /// <b>C'est l'ECLAT D'IMPACT que les neuf routines d'intelligence font naitre a chaque coup
    /// porte</b> — le <c>SpawnEffectEntity(e, 0x39, 0, -1)</c> du Crabe, du Grizzly et de
    /// l'Homme-lezard. Il ne vit que <b>deux images</b> : la premiere pose la gerbe, la seconde
    /// joue un second son et eteint l'entite.
    /// </para>
    /// <para>
    /// La gerbe est une <b>couronne de huit etincelles</b> (<see cref="EntityHandler_004474C0"/>,
    /// sous-type <c>0x98</c>), semees a huit angles reguliers ecrits dans <c>+0x16</c> avant chaque
    /// naissance — c'est ainsi que la fille herite du sien —, plus un anneau
    /// (<see cref="EntityHandler_00447380"/>, sous-type <c>0xa4</c>). L'eclat se souleve de
    /// <c>0x5a000</c> avant de semer.
    /// </para>
    /// <para>
    /// <b>Trois lignes mort-nees.</b> Le corps calcule l'encombrement de la victime a partir de son
    /// bloc de modele, le borne a <c>0x15e</c> puis a <c>0x64</c>, et <b>ecrase le resultat par la
    /// constante <c>0xb4</c></b> trois instructions plus loin. Le calcul est transcrit parce qu'il
    /// est dans le corps ; il ne sert a rien, et il ne consomme pas de tirage.
    /// </para>
    /// </summary>
    private static void EntityHandler_00447280(byte* e)
    {
        if (*(short*)(e + 0x10) == 1)
        {
            Aud.PlayPositionalSound(9, 0xb52, 0x1200, (int*)(e + 0x1c));
            *(uint*)e &= 0x7fffffff;
        }

        if (*(short*)(e + 0x10) != 0) return;

        byte* struck = *(byte**)(e + 0x70);
        if (struck == null) return;

        ResolveEntityBlocks(struck, out _, out _, out byte* model);

        // Mort-ne : ecrase par 0xb4 plus bas. Les additions sont sur SEIZE bits dans le binaire.
        short bulk = (short)(*(short*)(model + 0x20) + *(short*)(model + 0x1e) + *(short*)(model + 0x1c));
        *(short*)(e + 0x14) = bulk;
        if (bulk > 0x15e) *(short*)(e + 0x14) = 0x15e;
        if (*(short*)(e + 0x14) < 0x64) *(short*)(e + 0x14) = 0x64;

        *(int*)(e + 0x20) += 0x5a000;
        *(short*)(e + 0x14) = 0xb4;

        SpawnCastEntity_0047AAE0(e, 0xa4, 0, -1);

        // Huit etincelles, un huitieme de tour d'ecart. L'angle passe par +0x16, que la copie de
        // 0x27 dwords de FUN_0047ac40 transmet a la fille.
        for (short angle = 0; angle <= 0xe00; angle += 0x200)
        {
            *(short*)(e + 0x16) = angle;
            SpawnStatusEffectEntity_0047AC40(e, (int*)(e + 0x1c), null, 0x98, 0, -1);
        }

        Aud.PlayPositionalSound(5, 0x320, 0x1200, (int*)(e + 0x1c));
        *(short*)(e + 0x10) = 1;
    }

    /// <summary>
    /// Ghidra: FUN_00447380 @ 0x00447380 — <b>l'entree 164 de la table statique
    /// <see cref="s_StaticEntityHandlers_00551f30"/></b>, l'<b>anneau</b> que
    /// <see cref="EntityHandler_00447280"/> pose au point d'impact.
    ///
    /// <para>
    /// Il naît blanc et gros (les trois echelles a 500), tourne d'un quart de tour
    /// (<c>+0x32 += 0xc00</c>), et <b>s'ouvre en s'amortissant</b> : son rayon <c>+0x9a</c> croit
    /// de <c>+0x5c</c>, lequel est <b>divise par deux a chaque image</b> — l'anneau s'elargit vite
    /// puis se fige. Ses echelles rejoignent <c>+0x14 * 0x28</c> par quarts. Il s'assombrit de
    /// quinze par canal et meurt quand le rouge atteint zero.
    /// </para>
    /// </summary>
    private static void EntityHandler_00447380(byte* e)
    {
        if (*(short*)(e + 0x10) == 0)
        {
            e[0x38] = 0xff;
            e[0x39] = 0xff;
            e[0x3a] = 0xff;

            *(short*)(e + 0x32) += 0xc00;

            *(short*)(e + 0x28) = 500;
            *(short*)(e + 0x2a) = 500;
            *(short*)(e + 0x2c) = 500;

            e[4] = 7;
            *(int*)(e + 0x50) = *(int*)(e + 0x1c);
            e[0x0a] = 9;
            e[0x0b] = 0;
            *(short*)(e + 0x10) = 1;
            *(short*)(e + 0x34) = 0x400;
            *(int*)(e + 0x54) = *(int*)(e + 0x20);
            *(int*)(e + 0x58) = *(int*)(e + 0x24);
            *(short*)(e + 0x9a) = 0;
            *(int*)(e + 0x5c) = 0xc;
        }

        if (*(short*)(e + 0x10) != 1) return;

        int target = *(short*)(e + 0x14) * 0x28;
        *(short*)(e + 0x28) += (short)((target - *(short*)(e + 0x28)) >> 2);
        *(short*)(e + 0x2a) += (short)((target - *(short*)(e + 0x2a)) >> 2);
        *(short*)(e + 0x2c) += (short)((target - *(short*)(e + 0x2c)) >> 2);

        int course = *(short*)(e + 0x32) - 0xc00;
        short radius = *(short*)(e + 0x9a);

        *(int*)(e + 0x1c) = (int)Winsys3d.GetSinTableEntry(course) * radius + *(int*)(e + 0x50);
        *(int*)(e + 0x24) = Winsys3d.GetCosTableEntry(course) * radius + *(int*)(e + 0x58);

        *(short*)(e + 0x9a) = (short)(radius + *(int*)(e + 0x5c));
        *(int*)(e + 0x5c) -= *(int*)(e + 0x5c) >> 1;

        BrightenEntityTint_00404DE0(e, -0x0f, -0x0f, -0x0f);

        if (e[0x38] == 0) *(uint*)e &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: <c>0x004474c0</c> — <b>l'entree 152 de la table statique
    /// <see cref="s_StaticEntityHandlers_00552230"/></b>, 358 octets, <b>absente de
    /// <c>Blaze.c</c></b>. C'est l'<b>etincelle</b> de la couronne que
    /// <see cref="EntityHandler_00447280"/> seme par huit.
    ///
    /// <para>
    /// Chacune part dans sa direction — l'angle que le pere lui a ecrit en <c>+0x16</c> — et
    /// s'eloigne sur une sphere de rayon <c>+0x9a</c>, croissant de <c>+0x5c</c> qui perd un quart
    /// a chaque image : un jet vif qui retombe. Ses deux premieres echelles rejoignent
    /// <c>+0x14 * 30</c> par quarts ; la troisieme n'est jamais touchee.
    /// </para>
    /// <para>
    /// <b>Elle a trois images et les fait defiler elle-meme</b> : <c>+0x40</c> monte de un par
    /// image et repart a zero apres deux, en indexant <see cref="s_SparkDescriptors_005515A0"/>.
    /// Elle s'assombrit de quinze par canal et meurt quand le rouge atteint zero.
    /// </para>
    /// </summary>
    private static void EntityHandler_004474C0(byte* e)
    {
        if (*(short*)(e + 0x10) == 0)
        {
            e[0x38] = 0xff;
            e[0x39] = 0xff;
            e[0x3a] = 0xff;

            *(byte**)(e + 0x3c) = SparkDescriptors();        // Ghidra: &DAT_005515a0
            e[0x40] = 0;
            e[0x0a] = 2;
            e[0x0b] = 1;
            *(short*)(e + 0x10) = 1;

            *(short*)(e + 0x28) = 0;
            *(short*)(e + 0x2a) = 0;

            *(int*)(e + 0x50) = *(int*)(e + 0x1c);
            *(int*)(e + 0x54) = *(int*)(e + 0x20);
            *(int*)(e + 0x58) = *(int*)(e + 0x24);

            *(short*)(e + 0x9a) = 0;
            *(int*)(e + 0x5c) = 0x3c;
        }

        if (*(short*)(e + 0x10) != 1) return;

        int course = *(short*)(e + 0x32) + 0x400;
        short radius = *(short*)(e + 0x9a);
        short spread = *(short*)(e + 0x16);

        *(int*)(e + 0x24) =
            ((Winsys3d.GetCosTableEntry(course) * radius) >> 0xc)
            * (int)Winsys3d.GetSinTableEntry(spread) + *(int*)(e + 0x58);

        *(int*)(e + 0x1c) =
            (((int)Winsys3d.GetSinTableEntry(course) * radius) >> 0xc)
            * (int)Winsys3d.GetSinTableEntry(spread) + *(int*)(e + 0x50);

        *(int*)(e + 0x20) = Winsys3d.GetCosTableEntry(spread) * radius + *(int*)(e + 0x54);

        // Ghidra: `add di,[esi+5Ch]` — l'addition est sur SEIZE bits, le mot bas de +0x5c.
        *(short*)(e + 0x9a) = (short)(radius + *(short*)(e + 0x5c));
        *(int*)(e + 0x5c) -= *(int*)(e + 0x5c) >> 2;

        int target = *(short*)(e + 0x14) * 30;
        *(short*)(e + 0x28) += (short)((target - *(short*)(e + 0x28)) >> 2);
        *(short*)(e + 0x2a) += (short)((target - *(short*)(e + 0x2a)) >> 2);

        BrightenEntityTint_00404DE0(e, -0x0f, -0x0f, -0x0f);

        if (e[0x38] == 0) *(uint*)e &= 0x7fffffff;

        // L'image suivante, sur trois.
        e[0x40] += 1;
        if (e[0x40] == 3) e[0x40] = 0;
    }

    // =============================================================================================
    // LE TIR — les trois corps que le jet du Goblin (FUN_0049DA40, sous-type 8) fait naitre l'un
    // apres l'autre, transcrits le 2026-08-29. Aucun des trois n'est dans Blaze.c ; les deux
    // feuilles qu'ils appellent, si.
    //
    //   0x0047A100  le LANCEUR (sous-type 0x49) : choisit une cible dans un cone, oriente le tir,
    //               fait naitre le projectile et s'eteint dans la meme image.
    //   0x0047A270  la TRAJECTOIRE (sous-type 0x52) : vole, se dirige, touche, puis se PLANTE dans
    //               sa victime et la suit vingt images.
    //   0x00476320  l'IMPACT (sous-type 0xbd) : sept images de sprite et c'est fini.
    //
    // C'EST LE PREMIER SOUS-SYSTEME D'ATTAQUE A DISTANCE DU JEU, et il ne sert pas qu'au Goblin :
    // le Goblin-sorcier (sous-type 9) est le suivant du bloc de la foret.
    // =============================================================================================

    /// <summary>
    /// Ghidra: FUN_00474f00 @ 0x00474f00 — <b>choisir une cible dans un cone</b>. Elle balaie le
    /// <b>camp d'en face</b> : le groupe si l'appelant est une entite de scene, la table de scene si
    /// l'appelant porte le bit <c>0x800000</c> du groupe.
    ///
    /// <para>
    /// Trois filtres, dans cet ordre : l'emplacement doit etre vivant et sans les etats de
    /// <c>0x50002040</c> ; son bloc de statistiques doit partager un bit avec
    /// <paramref name="mask"/> en <c>+0x14</c> ; il ne doit etre ni tenu (<c>+0x74</c>) ni en train
    /// de clignoter (<c>+0x96</c>).
    /// </para>
    /// <para>
    /// <b>Le cone est etroit et le site large</b> : l'ecart de cap doit tenir dans <c>±0x100</c>
    /// (un trente-deuxieme de tour de chaque cote), l'ecart de site dans une bande de <c>0x301</c>
    /// prise a partir de <c>-0x100</c>. La portee maximale est <b>600</b>, et c'est la plus proche
    /// des candidates qui l'emporte.
    /// </para>
    /// </summary>
    /// <returns>L'emplacement retenu, ou <c>null</c>.</returns>
    private static byte* PickTargetInCone_00474F00(byte* shooter, uint mask)
    {
        byte* slot;
        byte* stats;
        int stride;
        int count;

        if ((*(uint*)shooter & 0x800000) == 0)
        {
            slot = Inp.s_SlotFlags_005e93c0;
            stride = 0x2000;
            stats = GetMainMemPtr() + 0xf0100;
            count = s_PartySize_005e9020;
        }
        else
        {
            slot = Mem.Entity(0x005ecaa0);
            stats = s_EntityStatBlocks_005ea560;
            stride = 0x120;
            count = 0x20;
        }

        int x = *(int*)(shooter + 0x1c);
        int y = *(int*)(shooter + 0x20);
        int z = *(int*)(shooter + 0x24);
        short heading = *(short*)(shooter + 0x32);

        byte* found = null;
        int nearest = 0x258;

        for (; count != 0; count--, slot += 0x9c, stats += stride)
        {
            if ((*(uint*)slot & 0x80000000) == 0) continue;
            if ((*(uint*)slot & 0x50002040) != 0) continue;
            if ((*(uint*)(stats + 0x14) & mask) == 0) continue;
            if (*(uint*)(slot + 0x74) != 0) continue;
            if (*(short*)(slot + 0x96) != 0) continue;

            int dx = (*(int*)(slot + 0x1c) - x) >> 0xc;
            int dz = (*(int*)(slot + 0x24) - z) >> 0xc;

            if (((((Winsys3d.Ordinal_457(dx, dz) - heading) & 0xfff) + 0x100) & 0xfff) >= 0x201)
            {
                continue;
            }

            int dy = (*(int*)(slot + 0x20) - y) >> 0xc;
            int flat = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));

            if (((uint)(Winsys3d.Ordinal_457(dy, flat) + 0x100) & 0xfff) >= 0x301) continue;

            int range = (int)Winsys3d.Ordinal_442((uint)(dy * dy + flat * flat));
            if (range < nearest)
            {
                nearest = range;
                found = slot;
            }
        }

        return found;
    }

    /// <summary>
    /// Ghidra: FUN_00519af0 @ 0x00519af0 — <b>le balayage des entites de scene</b>, la sœur de
    /// <see cref="SweepPartyForMeleeHit_00519C30"/> pour le camp d'en face.
    ///
    /// <para>
    /// <b>Elle ne parcourt pas une table mais la grille spatiale</b> : les neuf cases autour de la
    /// position, dans le meme decoupage que <see cref="LinkIntoWorldGrid"/> — d'ou le
    /// <c>0x389f * 0x20</c> du binaire, qui est <c>0x1c5000 / 4</c> moins une rangee, c'est-a-dire
    /// la case de rang <c>Z - 1</c>. Elle rend <b>la premiere</b> entite acceptee, pas la plus
    /// proche : la grille sert d'index, pas de tri.
    /// </para>
    /// <para>
    /// La parade est ici aussi, sur le bit <c>0x10</c> de l'entite au lieu du bit 4 d'un membre du
    /// groupe, et elle remet <c>DAT_005de0b8</c> a zero apres avoir joue son son.
    /// </para>
    /// </summary>
    private static byte* SweepSceneEntitiesForMeleeHit_00519AF0(
        byte* entity, int* position, short* probe, uint flags)
    {
        byte* mainMem = GetMainMemPtr();

        uint column = (uint)(((position[0] >> 0xc) + 0x2000) >> 9) - 1;
        uint row = (uint)((((position[2] >> 0xc) + 0x2000) >> 9) + 0x389f) * 0x20;

        for (int bands = 3; ; bands--, row += 0x20)
        {
            uint cell = column;

            for (int step = 3; step != 0; step--, cell++)
            {
                if (cell >= 0x20 || row >= 0x71800) continue;

                for (byte* found = *(byte**)(mainMem + (cell + row) * 4);
                     found != null;
                     found = *(byte**)(found + 0x68))
                {
                    if ((*(uint*)found & 0x400000) == 0) continue;
                    if ((*(uint*)found & 0x50102040) != 0) continue;
                    if (*(short*)(found + 0x96) != 0) continue;
                    if (!TestMeleeReach_00535A90(position, found, probe, entity)) continue;

                    if ((*(uint*)found & 0x10) != 0 && (flags & 0x800) == 0
                        && (uint)((*(short*)(found + 0x32) - *(short*)((byte*)position + 0x16)
                                   - *probe - 0x400) & 0xfff) < 0x800)
                    {
                        Aud.PlayPositionalSound(8, 0x800, 0x1000, (int*)(found + 0x1c));
                        *Mem.Camera(0x005de0b8) = 0;
                        return null;
                    }

                    *Mem.Camera(0x005de0b8) = 1;
                    return found;
                }
            }

            // Ghidra: `uVar5 = uVar6 - 2` — la colonne repart de X - 1 pour la rangee suivante.
            column = cell - 3;

            if (bands == 1)
            {
                *Mem.Camera(0x005de0b8) = 0;
                return null;
            }
        }
    }

    /// <summary>Ghidra: FUN_00474c70 @ 0x00474c70 — <b>balayer le camp d'en face</b>, l'aiguillage
    /// d'une ligne entre les deux balayages selon que l'appelant appartient au groupe
    /// (<c>0x800000</c>) ou a la scene. Les deux receveuses ont la meme signature, et le site
    /// d'appel pousse les memes quatre arguments dans les deux branches.</summary>
    private static byte* SweepOpposingSideForMeleeHit_00474C70(byte* entity, short* probe)
    {
        if ((*(uint*)entity & 0x800000) != 0)
        {
            return SweepSceneEntitiesForMeleeHit_00519AF0(entity, (int*)(entity + 0x1c), probe, 0);
        }

        return SweepPartyForMeleeHit_00519C30(entity, (int*)(entity + 0x1c), probe, 0);
    }

    /// <summary>
    /// Ghidra: <c>0x0047a100</c> — <b>l'entree 73 de la table statique
    /// <see cref="s_StaticEntityHandlers_00551c30"/></b>, 0x170 octets, <b>absente de
    /// <c>Blaze.c</c></b> ; releve garde sous <c>Legacy/Raw/Blaze/FUN_0047A100.asm</c>.
    ///
    /// <para>
    /// <b>C'est le LANCEUR</b>, l'effet <c>0x49</c> que le geste de jet du Goblin fait naitre a la
    /// septieme image. Il ne vit qu'une image : il choisit une cible, oriente le tir, fait naitre le
    /// projectile et <b>s'eteint</b> (<c>*e = 0</c>) avant de rendre la main.
    /// </para>
    /// <para>
    /// <b>Cap ET site.</b> <c>+0x32</c> recoit l'azimut de la cible, <c>+0x34</c> son elevation —
    /// c'est la premiere fois qu'une entite reconstruite vise en trois dimensions. Les trois
    /// vitesses en decoulent : <c>+0x50</c> et <c>+0x58</c> par le produit du sinus ou du cosinus
    /// d'azimut avec le cosinus de site, <c>+0x54</c> par le sinus de site seul. Sans cible, le
    /// site vaut <c>0x100</c> et le tir part droit devant.
    /// </para>
    /// <para>
    /// <b>Deux idiomes a ne pas normaliser.</b> Le <c>sar eax,5</c> suivi de <c>and al,80h</c> est
    /// un decalage de cinq bits puis un arrondi vers le bas au multiple de <c>0x80</c> — il ne
    /// touche que les sept bits bas. Et l'elevation ajoute <c>distance / 4</c> a l'angle : un tir
    /// long part plus haut, ce qui est une garde-au-but grossiere.
    /// </para>
    /// <para>
    /// Le depart est releve a la hauteur de bulle de la bete
    /// (<see cref="StatusBubbleHeight_00538BC0"/>, arrondie a un multiple de deux puis decalee de
    /// onze bits) : le projectile part de la main, pas des pieds.
    /// </para>
    /// </summary>
    private static void EntityHandler_0047A100(byte* e)
    {
        byte* target = PickTargetInCone_00474F00(e, 0xffffffff);

        *(ushort*)(e + 0x36) = (ushort)((*(ushort*)(e + 0x36) & ~4) | 2);
        *(uint*)e |= 2;

        *(short*)(e + 0x28) = 0x380;
        *(short*)(e + 0x2a) = 0x200;
        *(short*)(e + 0x2c) = 0x200;
        e[4] = 0x3a;                                        // le modele du projectile

        if (target != null)
        {
            int dx = (*(int*)(target + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
            int dy = (*(int*)(target + 0x20) - *(int*)(e + 0x20)) >> 0xc;
            int dz = (*(int*)(target + 0x24) - *(int*)(e + 0x24)) >> 0xc;

            int flat = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));
            short course = *(short*)(e + 0x32);

            // L'azimut est repris a partir du cap courant, l'ecart etant borne a un tour.
            *(short*)(e + 0x32) = (short)(((Winsys3d.Ordinal_457(dx, dz) - course) & 0xfff) + course);

            // Ghidra: `sar edi,2 ; add eax,edi` — l'elevation monte d'un quart de la distance.
            *(short*)(e + 0x34) = (short)(Winsys3d.Ordinal_457(dy, flat) + (flat >> 2));

            *(byte**)(e + 0x78) = target;
        }
        else
        {
            *(short*)(e + 0x34) = 0x100;
            *(uint*)(e + 0x78) = 0;
        }

        // Ghidra: LAB_0047a1cf
        int pitch = *(short*)(e + 0x34);
        int yaw = *(short*)(e + 0x32);

        *(short*)(e + 0x9a) = 0x7fff;                       // le rappel que la trajectoire amortit

        int rise = Winsys3d.GetCosTableEntry(pitch);

        *(int*)(e + 0x50) = (((int)Winsys3d.GetSinTableEntry(yaw) * rise) >> 5) & ~0x7f;
        *(int*)(e + 0x54) = (int)Winsys3d.GetSinTableEntry(pitch) << 7;
        *(int*)(e + 0x58) = ((Winsys3d.GetCosTableEntry(yaw) * rise) >> 5) & ~0x7f;

        byte* owner = *(byte**)(e + 0x6c);
        int muzzle = (StatusBubbleHeight_00538BC0((uint*)owner) & ~1) << 0x0b;

        *(short*)(e + 0x32) += 0x400;
        *(byte**)(e + 0x74) = owner;                        // qui repondra des degats
        *(int*)(e + 0x20) += muzzle;

        SpawnCastEntity_0047AAE0(e, 0x52, 1, 8);
        Aud.PlayPositionalSound(0x1f, 0x2000, 0x1200, (int*)(e + 0x1c));

        *(uint*)e = 0;                                      // le lanceur ne vit qu'une image
    }

    /// <summary>
    /// Ghidra: <c>&amp;DAT_00551a08</c> — <b>les sept images de l'eclaboussure</b> de
    /// <see cref="EntityHandler_00476320"/>, huit octets chacune. Sept, parce que le corps compte
    /// <c>+0x40</c> jusqu'a 7 avant de s'eteindre et que
    /// <see cref="SpawnStatusEffectEntity_0047AC40"/> le pose a zero. La huitieme entree
    /// (<c>0x00551a40</c>) n'a plus la meme forme — son cinquieme octet vaut 0 et son huitieme 1 —,
    /// ce qui borne la sequence.
    /// </summary>
    private static readonly byte[] s_SplashDescriptors_00551A08 =
    [
        0xc0, 0xb8, 0x18, 0x18, 0x01, 0x02, 0x10, 0x00,   // 0x00551a08
        0xd8, 0xb8, 0x18, 0x18, 0x01, 0x02, 0x10, 0x00,   // 0x00551a10
        0x60, 0xd0, 0x18, 0x18, 0x01, 0x02, 0x10, 0x00,   // 0x00551a18
        0x78, 0xd0, 0x18, 0x18, 0x01, 0x02, 0x10, 0x00,   // 0x00551a20
        0x90, 0xd0, 0x18, 0x18, 0x01, 0x02, 0x10, 0x00,   // 0x00551a28
        0xa8, 0xd0, 0x18, 0x18, 0x01, 0x02, 0x10, 0x00,   // 0x00551a30
        0xc0, 0xd0, 0x18, 0x18, 0x01, 0x02, 0x10, 0x00,   // 0x00551a38
    ];

    private static byte* s_SplashDescriptorStorage;

    /// <summary>Les sept images en memoire native : l'eclaboussure les garde par pointeur
    /// (<c>+0x3c</c>) et choisit la sienne par <c>+0x40</c>.</summary>
    private static byte* SplashDescriptors()
    {
        if (s_SplashDescriptorStorage == null)
        {
            s_SplashDescriptorStorage =
                (byte*)NativeMemory.Alloc((nuint)s_SplashDescriptors_00551A08.Length);

            for (int i = 0; i < s_SplashDescriptors_00551A08.Length; i++)
            {
                s_SplashDescriptorStorage[i] = s_SplashDescriptors_00551A08[i];
            }
        }

        return s_SplashDescriptorStorage;
    }

    /// <summary>
    /// Ghidra: <c>0x0047a270</c> — <b>l'entree 82 de la table statique
    /// <see cref="s_StaticEntityHandlers_00551f30"/></b>, 0x360 octets, <b>absente de
    /// <c>Blaze.c</c></b> ; releve garde sous <c>Legacy/Raw/Blaze/FUN_0047A270.asm</c>.
    ///
    /// <para>
    /// <b>C'est la TRAJECTOIRE</b>, et elle a deux vies separees par le bit <c>0x10000000</c> :
    /// avant, elle vole ; apres, elle est <b>plantee</b> dans quelque chose et le suit.
    /// </para>
    /// <para>
    /// <b>Plantee</b> (<c>0x10000000</c> pose) : elle clignote une image sur deux par le bit
    /// <c>0x4000</c>, recopie la position de sa victime augmentee de l'ecart fige a l'impact
    /// (<c>+0x44</c>/<c>+0x48</c>/<c>+0x4c</c>), et disparait a la vingtieme image.
    /// </para>
    /// <para>
    /// <b>En vol</b>, elle fait trois choses dans cet ordre :
    /// </para>
    /// <list type="number">
    /// <item><b>elle se dirige</b>, si elle a gardé une cible en <c>+0x78</c> : l'ecart de cap
    /// decide d'un virage de <c>±0x20</c> — jamais plus —, et les deux vitesses horizontales sont
    /// refaites a la meme norme. Un tir suit sa cible sans jamais la rattraper d'un coup ;</item>
    /// <item><b>elle avance en HUIT sous-pas</b> d'un huitieme de vitesse chacun, en appelant le
    /// placement a chaque sous-pas et en accumulant les drapeaux de collision de <c>+0x90</c>.
    /// C'est ce qui empeche un projectile rapide de traverser un mur ; l'avant-dernier sous-pas
    /// efface trois bits de l'accumulateur ;</item>
    /// <item><b>elle se reoriente sur le deplacement reellement obtenu</b> — pas sur la consigne —,
    /// le site rejoignant sa valeur par quarts.</item>
    /// </list>
    /// <para>
    /// <b>Elle touche de deux facons.</b> Le decor : les drapeaux accumules portent
    /// <c>0xa000</c>, ou bien elle est passee sous le sol de <c>+0x60</c> ; elle s'y plante alors et
    /// laisse l'eclaboussure <c>0xbd</c>. Une creature : le balayage
    /// <see cref="SweepOpposingSideForMeleeHit_00474C70"/>, et c'est <b>son proprietaire</b>
    /// (<c>+0x74</c>, pose par le lanceur) qui est passe a <c>FUN_00539b80</c> — les degats sont
    /// ceux du Goblin, pas ceux de la fleche.
    /// </para>
    /// <para>
    /// Sa sonde est batie sur la pile : <c>{-0x400, -0x80, 0x32, 0x32, 0, 0x80}</c>. Les deux
    /// premiers termes sont negatifs, ce qu'aucun gabarit de bete ne fait.
    /// </para>
    /// </summary>
    private static void EntityHandler_0047A270(byte* e)
    {
        short* probe = stackalloc short[6];
        probe[0] = unchecked((short)0xfc00);
        probe[1] = unchecked((short)0xff80);
        probe[2] = 0x32;
        probe[3] = 0x32;
        probe[4] = 0;
        probe[5] = 0x80;

        uint flags = *(uint*)e;

        // ================================================================ plantee
        if ((flags & 0x10000000) != 0)
        {
            *(short*)(e + 0x10) += 1;
            short age = *(short*)(e + 0x10);

            // Une image sur deux, le bit de clignotement.
            *(uint*)e = (age & 1) != 0 ? flags | 0x4000 : flags & 0xffffbfff;

            byte* host = *(byte**)(e + 0x78);
            if (host != null)
            {
                *(int*)(e + 0x1c) = *(int*)(e + 0x44) + *(int*)(host + 0x1c);
                *(int*)(e + 0x20) = *(int*)(e + 0x48) + *(int*)(host + 0x20);
                *(int*)(e + 0x24) = *(int*)(e + 0x4c) + *(int*)(host + 0x24);
            }

            if (age >= 0x14) *(uint*)e = 0;
            return;
        }

        // ================================================================ en vol
        byte* aim = *(byte**)(e + 0x78);

        int startX = *(int*)(e + 0x1c);
        int startY = *(int*)(e + 0x20);
        int startZ = *(int*)(e + 0x24);

        *(uint*)e = (flags & 0xfffff7ff) | 0x680;

        if (aim != null)
        {
            // Ghidra: 0x0047a32c — la norme horizontale est conservee, seul le cap tourne.
            int vx = *(int*)(e + 0x50) >> 0xc;
            int vz = *(int*)(e + 0x58) >> 0xc;
            int pace = (int)Winsys3d.Ordinal_442((uint)(vx * vx + vz * vz));

            int toX = (*(int*)(aim + 0x1c) - startX) >> 0xc;
            int toZ = (*(int*)(aim + 0x24) - startZ) >> 0xc;

            int off = (Winsys3d.Ordinal_457(toX, toZ) - 0x400 - *(short*)(e + 0x32)) & 0xfff;

            // Ghidra: `setge cl ; dec ecx ; and ecx,0FFFFFFC0h ; add ecx,20h` — un virage de
            // +0x20 ou de -0x20, jamais autre chose.
            *(short*)(e + 0x32) += (short)(off >= 0x800 ? 0x20 : -0x20);

            int course = *(short*)(e + 0x32) - 0x400;
            *(int*)(e + 0x50) = (int)Winsys3d.GetSinTableEntry(course) * pace;
            *(int*)(e + 0x58) = Winsys3d.GetCosTableEntry(course) * pace;
        }

        // Ghidra: LAB_0047a3b0 — meme amortissement que l'integration des betes, mais le rappel de
        // +0x9a compte au huitieme et non au deux-cent-cinquante-sixieme : ca tombe vite.
        int bob = *(short*)(e + 0x9a);

        int hx = *(int*)(e + 0x50);
        *(int*)(e + 0x50) = hx - (hx >> 3);

        int hy = *(int*)(e + 0x54);
        *(int*)(e + 0x54) = (bob >> 3) - (hy >> 3) + hy - bob;

        int hz = *(int*)(e + 0x58);
        *(int*)(e + 0x58) = hz - (hz >> 3);

        *(uint*)e &= 0xdfffffff;

        // Huit sous-pas : c'est ce qui empeche de traverser un mur en une image.
        uint hits = 0;
        for (int sub = 8; sub != 0; sub--)
        {
            *(int*)(e + 0x1c) += *(int*)(e + 0x50) >> 3;
            *(int*)(e + 0x20) += *(int*)(e + 0x54) >> 3;
            *(int*)(e + 0x24) += *(int*)(e + 0x58) >> 3;

            FinalizeEntityPlacement2((uint*)e);

            hits |= *(uint*)(e + 0x90);
            if (sub == 2) hits &= 0xfffff8ff;
        }

        *(uint*)(e + 0x90) = hits;

        // Ghidra: 0x0047a455 — le cap et le site sont refaits sur le deplacement OBTENU.
        int wentX = (*(int*)(e + 0x1c) - startX) >> 0xc;
        int wentY = (*(int*)(e + 0x20) - startY) >> 0xc;
        int wentZ = (*(int*)(e + 0x24) - startZ) >> 0xc;

        int span = (int)Winsys3d.Ordinal_442((uint)(wentX * wentX + wentZ * wentZ));

        short pitch = *(short*)(e + 0x34);
        *(short*)(e + 0x32) = (short)(Winsys3d.Ordinal_457(wentX, wentZ) + 0x400);
        *(short*)(e + 0x34) = (short)(pitch + ((Winsys3d.Ordinal_457(wentY, span) - pitch) >> 2));

        // ---------------------------------------------------------------- le decor
        bool misplaced = (hits & 0xa000) != 0;   // Ghidra: `test ah,0A0h ; jne` — un placement invalide interdit la plantee

        if (!misplaced && ((hits & 0x802) != 0 || *(int*)(e + 0x20) <= *(int*)(e + 0x60)))
        {
            // Ghidra: LAB_0047a4c9 — elle ne s'enfonce pas : la hauteur est ramenee au sol.
            if (*(int*)(e + 0x20) <= *(int*)(e + 0x60)) *(int*)(e + 0x20) = *(int*)(e + 0x60);

            *(uint*)e = (*(uint*)e & 0xffffff7f) | 0x10000000;
            *(uint*)(e + 0x78) = 0;

            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), SplashDescriptors(), 0xbd, 0, 4);
        }

        // ---------------------------------------------------------------- une creature
        // Ghidra: LAB_0047a505 — le balayage a lieu MEME quand elle vient de se planter dans le
        // decor : le binaire ne saute pas ce bloc.
        byte* victim = SweepOpposingSideForMeleeHit_00474C70(e, probe);

        if (victim != null)
        {
            if (*Mem.Camera(0x005de0b8) != 0)
            {
                // C'est le PROPRIETAIRE qui frappe, pas le projectile : +0x74 a ete pose par le
                // lanceur, et c'est lui que FUN_00539b80 lit pour l'attaque et l'experience.
                ResolveMeleeHit_00539B80(*(uint**)(e + 0x74), (uint*)victim);

                int course = *(short*)(e + 0x32) - 0x400;
                *(int*)(victim + 0x50) += (int)Winsys3d.GetSinTableEntry(course) << 4;
                *(int*)(victim + 0x58) += Winsys3d.GetCosTableEntry(course) << 4;

                *(ushort*)(victim + 0x96) = 0x10;
                *(uint*)victim |= 0x40;

                Aud.PlayPositionalSound(3, 0x400, 0x1800, (int*)(e + 0x1c));
            }

            // Ghidra: LAB_0047a586 — touchee ou parée, elle se plante et retient l'ecart.
            *(uint*)e = (*(uint*)e & 0xffffff7f) | 0x10000000;
            *(byte**)(e + 0x78) = victim;

            *(int*)(e + 0x44) = *(int*)(e + 0x1c) - *(int*)(victim + 0x1c);
            *(int*)(e + 0x48) = *(int*)(e + 0x20) - *(int*)(victim + 0x20);
            *(int*)(e + 0x4c) = *(int*)(e + 0x24) - *(int*)(victim + 0x24);
        }

        // Ghidra: LAB_0047a5b7 — sortie de zone : le placement l'a marquee, elle disparait.
        if ((*(uint*)e & 0x60000000) != 0) *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_00476320 @ 0x00476320 — <b>l'entree 189 de la table statique
    /// <see cref="s_StaticEntityHandlers_00552230"/></b>, 45 octets : l'<b>eclaboussure</b> que la
    /// trajectoire laisse la ou elle se plante.
    ///
    /// <para>
    /// Elle ne bouge pas et ne compte rien d'autre que ses images : la premiere pose l'echelle
    /// <c>0x1000</c> sur deux axes, et <c>+0x40</c> — l'indice d'image que
    /// <see cref="SpawnStatusEffectEntity_0047AC40"/> a mis a zero — monte d'un par image jusqu'a
    /// sept, ou l'entite s'eteint. Sept images, sept enregistrements dans
    /// <see cref="s_SplashDescriptors_00551A08"/>.
    /// </para>
    /// </summary>
    private static void EntityHandler_00476320(byte* e)
    {
        if (*(short*)(e + 0x10) != 0)
        {
            e[0x40] += 1;
            if (e[0x40] == 7) *(uint*)e = 0;
            return;
        }

        *(uint*)(e + 0x28) = 0x10001000;
        *(short*)(e + 0x10) = 1;
    }

    /// <summary>
    /// Ghidra: FUN_00445860 @ 0x00445860 — l'entree <b>0x9d</b> de la table statique
    /// <see cref="s_StaticEntityHandlers_00552230"/>, celle de la passe
    /// <see cref="TickEntityTable_005f2d40"/>. C'est le <b>premier</b> des 121 corps de gestionnaire
    /// de ces trois tables que <c>Blaze.c</c> decompile <b>et</b> dont un chemin reconstruit
    /// demontre qu'il est atteint : <see cref="EvaluatePartyDispersal"/> (etat 0xcd de
    /// <see cref="EntityAnimTail_00472E80"/>) engendre dans <c>0x005f2d40</c> avec ce sous-type.
    ///
    /// <para>
    /// L'entite est un <b>afficheur d'enonce</b> accroche a son porteur. Elle pose en <c>+0x3c</c>
    /// le bloc <c>&amp;DAT_00551640</c>, dont le flux d'etiquettes dit « 開かない！？ » — « ça ne
    /// s'ouvre pas ! ». Les huit premiers octets du bloc precedent le flux ; voir
    /// <c>BuildEntityParams_00551640</c> dans <c>Memory/GameMemory.cs</c>, ou les 0x200 octets sont
    /// releves.
    /// </para>
    /// <para>
    /// <b>Le porteur nul retombe sur <c>&amp;DAT_005de558</c></b> — l'entite factice de
    /// <see cref="Resources.s_EntityList_005de558"/>, deja rencontree ailleurs dans ce fichier. Ce
    /// n'est pas une garde defensive ajoutee par la transcription : le binaire fait
    /// <c>test eax,eax ; jne ; mov eax,5DE558h</c>, et tout le corps travaille ensuite sur ce
    /// substitut, y compris l'avance d'animation.
    /// </para>
    /// <para>
    /// Le porteur avance d'une image (<c>+0x1a</c>), bouclee sur le nombre d'images que declare sa
    /// planche d'animation — lue par <c>*(&amp;DAT_005e9680)[porteur[+4]]</c> puis <c>+0x16</c>. Les
    /// trois octets de teinte du porteur repartent a <c>0xff</c> et son bit <c>0x04</c> de
    /// <c>+0x36</c> tombe. Sans le bit <c>0x4000000</c> sur le porteur, l'afficheur s'eteint tout
    /// de suite : il ne vit qu'aussi longtemps que ce qu'il commente.
    /// </para>
    /// <para>
    /// L'echelle <c>+0x28</c>/<c>+0x2a</c> pulse a <c>0x1000 + sin(angle) / 4</c>, l'angle avancant
    /// de 400 par image sur douze bits. Le binaire appelle <c>Ordinal_451</c> <b>deux fois</b> avec
    /// le meme angle — table de sinus pure, donc deux fois la meme valeur ; les deux appels sont
    /// conserves.
    /// </para>
    /// </summary>
    private static void ShowEntityLabel_00445860(byte* effect)
    {
        byte* carrier = *(byte**)(effect + 0x6c);
        if (carrier == null) carrier = Res.s_EntityList_005de558;

        carrier[0x36] &= 0xfb;
        carrier[0x38] = 0xff;
        carrier[0x39] = 0xff;
        carrier[0x3a] = 0xff;
        *(ushort*)(carrier + 0x18) = 0;

        // Ghidra: `**(int **)(&DAT_005e9680 + (uint)(byte)puVar1[1] * 4)` — la planche
        // d'animation de la famille du porteur, dont +0x16 porte le nombre d'images.
        byte* sheet = *(byte**)*(byte***)(Mem.Arena(0x005e9680) + carrier[4] * 4);

        (*(short*)(carrier + 0x1a))++;
        if (*(short*)(carrier + 0x1a) >= (int)*(ushort*)(sheet + 0x16) - 1)
        {
            *(short*)(carrier + 0x1a) = 0;
        }

        if ((*(uint*)carrier & 0x4000000) == 0) *(uint*)effect &= 0x7fffffff;

        *(int*)(effect + 0x1c) = *(int*)(carrier + 0x1c);
        *(int*)(effect + 0x20) = *(int*)(carrier + 0x60) + 0x96000;
        *(int*)(effect + 0x24) = *(int*)(carrier + 0x24);

        if (*(short*)(effect + 0x10) == 0)
        {
            *(byte**)(effect + 0x3c) = Mem.s_EntityParams_00551640;   // Ghidra: &DAT_00551640
            effect[0x0a] = 10;
            effect[0x0b] = 0;
            *(short*)(effect + 0x10) = 1;
            *(short*)(effect + 0x12) = 0;
            effect[0x38] = 0xff;
            effect[0x39] = 0xff;
            effect[0x3a] = 0xff;
        }

        if (*(short*)(effect + 0x10) == 1)
        {
            short angle = *(short*)(effect + 0x12);
            *(short*)(effect + 0x28) = (short)(((int)Winsys3d.GetSinTableEntry(angle) >> 2) + 0x1000);
            *(short*)(effect + 0x2a) = (short)(((int)Winsys3d.GetSinTableEntry(angle) >> 2) + 0x1000);
            *(ushort*)(effect + 0x12) = (ushort)((angle + 400) & 0xfff);
        }
    }

    /// <summary>
    /// Ghidra: 0x00404e50 — <b>le changement de musique differe</b>. Absent de <c>Blaze.c</c> ;
    /// releve au desassembleur, 151 octets (<c>0x00404e50</c>..<c>0x00404ee6</c>) —
    /// <c>Legacy/Raw/Blaze/FUN_00404E50.asm</c>.
    ///
    /// <para>Atteint le 2026-08-25 par la femme a la petite harpe de la salle derriere le barman,
    /// entree 1 de la table installee par zone (<c>0x005ff400</c>) : elle propose de changer de
    /// musique, et c'est cette entite-ci qui execute le changement une fois qu'on accepte.</para>
    ///
    /// <para><b>Deux moities, et la seconde attend la premiere.</b> A chaque image il decompte
    /// <b>300</b> sur les deux <c>short</c> de <c>+0x10</c> et <c>+0x12</c> du bloc d'ecran
    /// <see cref="s_MenuScreenBlock_00566c48"/>, en les bornant a zero par le bas, remet le mot de
    /// tete du bloc a <c>0xc0</c> et le republie par <c>Ordinal_762</c>. Tant que l'un des deux est
    /// encore non nul, il s'arrete la — l'entite reste armee et repassera a l'image suivante.
    /// Quand les <b>deux</b> sont a zero, il choisit la piste et la lance, puis se desarme.</para>
    ///
    /// <para><b>La premiere moitie existe deja seule</b>, dans <c>Blaze.c</c> cette fois :
    /// <c>FUN_0041af50</c> (ligne 11043) en est le decompte nu, sans entite, sans musique et sans
    /// desarmement. Elle n'est pas transcrite — rien ne l'appelle encore dans le graphe reconstruit
    /// — mais elle confirme la lecture du bloc et des deux champs.</para>
    ///
    /// <para><b>Le choix de piste est le meme calcul qu'ailleurs, ecrit autrement.</b> Ici c'est une
    /// cascade de <c>cmp al,1</c> / <c>cmp al,2</c>, la ou <c>ScriptOpAreaVerbMusic</c> emploie un
    /// <c>setne / dec / and 2</c> sans branchement. Les deux calculent l'identite bornee : 0, 1 et 2
    /// se rendent eux-memes, <b>toute autre valeur rend 0</b>. Deux codegens pour une meme regle,
    /// ce qui la confirme.</para>
    ///
    /// <para><b>Ce que fait <c>Ordinal_762</c> n'est pas etabli.</b> Elle est declaree et deja
    /// appelee par <c>SetupMenuScreen</c> sur ce meme bloc ; sa decompilation dans
    /// <c>winsys3d.c</c> tombe sur un corps partage par des dizaines d'ordinaux, ce qui ne dit rien
    /// de plus. Les deux champs decomptes sont donc transcrits pour ce qu'ils sont — deux
    /// <c>short</c> du bloc — sans leur preter un role.</para>
    /// </summary>
    private static void EntityHandler_00404E50(uint* entity)
    {
        byte* block = (byte*)s_MenuScreenBlock_00566c48;

        // Ghidra: `movsx ebx,word [566C58h]` — la lecture est SIGNEE, et c'est ce qui rend la
        // borne a zero necessaire : sans elle le decompte passerait sous zero et repartirait.
        int a = *(short*)(block + 0x10) - 300;
        int b = *(short*)(block + 0x12) - 300;

        *(uint*)block = 0xc0;

        if (a < 0) a = 0;
        if (b < 0) b = 0;

        *(short*)(block + 0x10) = (short)a;
        *(short*)(block + 0x12) = (short)b;

        Winsys3d.Ordinal_762(block);

        if (a != 0 || b != 0) return;                      // encore en cours : on repassera

        byte source = *Mem.Arena(0x005e96fe);
        byte track = source <= 2 ? source : (byte)0;       // Ghidra: la cascade cmp al,1 / cmp al,2

        s_Unknown_005de534 = track;
        s_Unknown_00566c8c = track;
        PlayMusicTrack(track);                             // Ghidra: FUN_00529ad0

        entity[0] &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: FUN_00404ef0 @ 0x00404ef0 — le gestionnaire <b>0x404EF0</b> de la table des effets
    /// <c>0x005ff400</c> : il ne touche pas a sa propre entite mais <b>balaie les 0x20
    /// enregistrements de la table <c>0x005ecaa0</c></b> et reveille ceux qui portent a la fois le
    /// bit <c>0x80000000</c> et le bit <c>8</c>, en aiguillant sur leur octet <c>+0x0c</c>.
    ///
    /// <para>Il se desarme lui-meme en sortant (bit <c>0x80000000</c> de son propre mot d'etat), ce
    /// qui en fait une impulsion : une passe, une seule fois.</para>
    /// </summary>
    private static void EntityHandler_00404EF0(uint* entity)
    {
        byte* record = Mem.Entity(0x005ecaa0);

        for (int i = 0; i < 0x20; i++, record += 0x9c)
        {
            uint flags = *(uint*)record;
            if ((flags & 0x80000000) == 0 || (flags & 8) == 0) continue;

            switch (record[0x0c])
            {
                case 0: WakeSceneEntityKind0_00404F70(i); break;
                case 1: WakeSceneEntityKind1_00405240(i); break;
                case 2: WakeSceneEntityKind2_00405510(i); break;
            }
        }

        entity[0] &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: FUN_00404f70 @ 0x00404f70 — <b>le reveil d'une entite de scene de type 0</b> : il
    /// arme l'etat, puis aiguille sur les trente bits bas du mot <c>+0x5c</c>.
    ///
    /// <para>Les trois tests relisent <c>+0x5c</c> a chaque fois, et ce n'est pas une maladresse de
    /// transcription : <see cref="AdvanceSceneEntityState_00404FE0"/> et
    /// <see cref="HoldSceneEntityState_004050D0"/> ecrivent ce meme mot, donc un etat peut en
    /// declencher un autre dans le meme tour. Conserve tel quel.</para>
    /// </summary>
    private static void WakeSceneEntityKind0_00404F70(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1) AdvanceSceneEntityState_00404FE0(record, 2);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2) HoldSceneEntityState_004050D0(record, 0);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3) AdvanceSceneEntityState_00404FE0(record, 3);
    }

    /// <summary>
    /// Ghidra: FUN_004051d0 @ 0x004051d0 — <b>arme l'etat d'animation</b> d'une entite de scene
    /// depuis ses trois champs de consigne, avant que l'un des deux pas ci-dessous ne le fasse
    /// avancer.
    ///
    /// <para>Le mot <c>+0x5c</c> porte trois choses a la fois : ses trente bits bas sont le
    /// <b>numero d'etat</b>, le bit <c>0x40000000</c> dit « la consigne est deja lue » et le bit
    /// <c>0x80000000</c> « l'etat vient de changer ». Le dernier est efface en sortant, si bien
    /// qu'il ne vaut que pour un tour.</para>
    /// </summary>
    private static void ArmSceneEntityState_004051D0(byte* record)
    {
        uint wanted = (uint)(*(short*)(record + 0x10) & 0xff);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) != wanted
            && (*(uint*)(record + 0x5c) & 0x80000000) != 0)
        {
            *(uint*)(record + 0x5c) = wanted;
            *(int*)(record + 0x48) = *(short*)(record + 0x14);
        }

        if ((*(uint*)(record + 0x5c) & 0x40000000) == 0)
        {
            *(int*)(record + 0x44) = *(short*)(record + 0x10) >> 8;
            *(int*)(record + 0x4c) = *(short*)(record + 0x12);
            *(uint*)(record + 0x5c) |= 0x40000000;
        }

        *(uint*)(record + 0x5c) &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: FUN_00404fe0 @ 0x00404fe0 — <b>le pas d'animation qui va jusqu'au bout</b> : il
    /// avance le compteur d'images et, arrive a la derniere, lance le script accroche a l'entite.
    ///
    /// <para>Le champ <c>+0x48</c> est un compteur a double usage — au-dessus de 9 c'est un delai
    /// qui decompte, en dessous c'est un numero de phase (0 = a amorcer, 1 = en cours, 2 = fini et
    /// gele). Le passage de delai a phase se fait par le test <c>&lt; 10</c> qui le remet a zero.</para>
    ///
    /// <para><b>La fin de sequence a deux regimes</b>, selon <c>+0x4c</c> : a zero l'animation
    /// reboucle (compteur remis a zero), sinon elle <b>se fige sur sa derniere image</b>. Dans les
    /// deux cas, si <c>+0x44</c> porte un script, il part et le champ est vide pour qu'il ne parte
    /// qu'une fois.</para>
    ///
    /// <para>Ghidra rend la valeur de retour en <c>CONCAT22</c> avec une moitie haute qui n'est que
    /// du residu de registre ; <b>aucun appelant ne la lit</b>, et seule la moitie basse a un sens :
    /// 1 si un script a demarre, 0 sinon.</para>
    /// </summary>
    private static uint AdvanceSceneEntityState_00404FE0(byte* record, short kind)
    {
        int counter = *(int*)(record + 0x48);
        if (counter > 9)
        {
            counter--;
            *(int*)(record + 0x48) = counter;
            if (counter < 10) *(int*)(record + 0x48) = 0;
        }

        if (*(int*)(record + 0x48) == 0)
        {
            *(int*)(record + 0x48) = 1;
            *(short*)(record + 0x1a) = -1;
            *(short*)(record + 0x18) = kind;
        }

        if (*(int*)(record + 0x48) != 1) return 0;

        byte* animation = ((byte**)*(byte***)(Mem.s_AnimationTable_005e9640 + record[4] * 4))
                              [*(short*)(record + 0x18)];

        *(short*)(record + 0x1a) += 1;

        ushort frames = *(ushort*)(animation + 0x16);
        if (frames - 1 > *(short*)(record + 0x1a)) return 0;

        int script;
        if (*(int*)(record + 0x4c) == 0)
        {
            script = *(int*)(record + 0x44);
            *(short*)(record + 0x1a) = 0;
            *(uint*)(record + 0x5c) |= 0x80000000;
            if (script == 0) return 0;
        }
        else
        {
            *(ushort*)(record + 0x1a) = (ushort)(frames - 1);
            script = *(int*)(record + 0x44);
            *(uint*)(record + 0x5c) |= 0x80000000;
            if (script == 0)
            {
                *(int*)(record + 0x48) = 2;
                return 0;
            }
        }

        RunEntityScript(s_Unknown_005e97cc, *(byte**)(record + 0x6c), (uint)script);
        *(uint*)(record + 0x5c) |= 0x80000000;
        *(int*)(record + 0x44) = 0;
        return 1;
    }

    /// <summary>
    /// Ghidra: FUN_004050d0 @ 0x004050d0 — <b>la jumelle qui n'attend pas la fin de la sequence</b>.
    /// Meme compteur a double usage, meme fin en deux regimes, mais elle declenche des la
    /// <b>premiere</b> image (<c>0 &lt; +0x1a</c>) au lieu d'attendre la derniere.
    ///
    /// <para>Autre difference, plus discrete : elle lit l'entree d'animation <b>comme une valeur</b>
    /// et ne la dereference que dans la branche qui fige (<c>*(short *)(uVar1 + 0x16)</c>). Dans
    /// l'autre branche l'entree n'est jamais touchee — transcrit tel quel.</para>
    /// </summary>
    private static uint HoldSceneEntityState_004050D0(byte* record, short kind)
    {
        int counter = *(int*)(record + 0x48);
        if (counter > 9)
        {
            counter--;
            *(int*)(record + 0x48) = counter;
            if (counter < 10) *(int*)(record + 0x48) = 0;
        }

        if (*(int*)(record + 0x48) == 0)
        {
            *(int*)(record + 0x48) = 1;
            *(short*)(record + 0x1a) = -1;
            *(short*)(record + 0x18) = kind;
        }

        if (*(int*)(record + 0x48) != 1) return 0;

        byte* animation = ((byte**)*(byte***)(Mem.s_AnimationTable_005e9640 + record[4] * 4))
                              [*(short*)(record + 0x18)];

        *(short*)(record + 0x1a) += 1;
        if (*(short*)(record + 0x1a) <= 0) return 0;

        if (*(int*)(record + 0x4c) == 0)
        {
            *(short*)(record + 0x1a) = 0;
            *(uint*)(record + 0x5c) |= 0x80000000;

            if (*(int*)(record + 0x44) == 0) return 0;
        }
        else
        {
            *(short*)(record + 0x1a) = (short)(*(short*)(animation + 0x16) - 1);
            *(uint*)(record + 0x5c) |= 0x80000000;

            if (*(int*)(record + 0x44) == 0)
            {
                *(int*)(record + 0x48) = 2;
                return 0;
            }
        }

        RunEntityScript(s_Unknown_005e97cc, *(byte**)(record + 0x6c), (uint)*(int*)(record + 0x44));
        *(uint*)(record + 0x5c) |= 0x80000000;
        *(int*)(record + 0x44) = 0;
        return 1;
    }

    /// <summary>
    /// Ghidra: FUN_00405240 @ 0x00405240 — <b>le reveil d'une entite de scene de type 1</b>. Meme
    /// forme que <see cref="WakeSceneEntityKind0_00404F70"/> : on arme l'etat, puis on aiguille sur
    /// les trente bits bas de <c>+0x5c</c>, cinq branches cette fois au lieu de trois, chacune
    /// relisant le mot parce que la precedente a pu le changer.
    /// </summary>
    private static void WakeSceneEntityKind1_00405240(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1) AdvanceSceneEntityState_00404FE0(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2)
            CycleSceneEntityAnimations_004052F0(record, 2, 3, (short)(CrtRand() % 10));
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3) CountDownSceneEntityState_00405420(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 4) AdvanceSceneEntityState_00404FE0(record, 2);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 5) AdvanceSceneEntityState_00404FE0(record, 3);
    }

    /// <summary>
    /// Ghidra: FUN_00405510 @ 0x00405510 — <b>le reveil d'une entite de scene de type 2</b>, la
    /// jumelle de la precedente. Les cinq branches sont les memes a leurs arguments pres : l'etat 3
    /// avance ici au lieu de decompter, et les numeros d'animation sont decales d'un cran.
    /// </summary>
    private static void WakeSceneEntityKind2_00405510(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1) AdvanceSceneEntityState_00404FE0(record, 2);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2)
            CycleSceneEntityAnimations_004052F0(record, 3, 5, (short)(CrtRand() % 10));
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3) AdvanceSceneEntityState_00404FE0(record, 3);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 4) AdvanceSceneEntityState_00404FE0(record, 4);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 5) AdvanceSceneEntityState_00404FE0(record, 5);
    }

    /// <summary>
    /// Ghidra: FUN_004055c0 @ 0x004055c0 — <b>le second balayeur d'entites de scene</b>, jumeau de
    /// <see cref="EntityHandler_00404EF0"/> : meme forme, meme table <c>0x005ecaa0</c>, meme
    /// auto-desarmement en sortant, mais il reveille les types <b>3, 4, 5, 7 et 6</b> la ou son
    /// jumeau reveille 0, 1 et 2.
    ///
    /// <para>
    /// <b>Il n'est pas atteint par la branche basse.</b> C'est l'entree <c>0xe1</c> — donc
    /// <c>&gt;= 0xC0</c> — de la table installee par zone, celle qui deborde de trois tables et
    /// retombe dans <c>s_Vt_0056b0c8</c>. Le sous-type ne vient donc pas de <c>FUN_0047a9d0</c>,
    /// l'engendreur qui pose toujours <c>0x59</c> : il vient d'un des six sites qui ecrivent
    /// directement dans <c>DAT_005ff400</c> au chargement de la zone.
    /// </para>
    /// <para>
    /// Les cinq tests <b>relisent</b> le mot d'etat et l'octet de type a chaque fois. Ce n'est pas
    /// une maladresse de transcription : un reveil peut changer l'un comme l'autre, et le binaire
    /// recharge <c>[esi]</c> avant chaque comparaison.
    /// </para>
    /// <para>L'ordre 3, 4, 5, <b>7</b>, 6 est celui du binaire. Conserve tel quel.</para>
    /// </summary>
    private static void EntityHandler_004055C0(uint* entity)
    {
        byte* record = Mem.Entity(0x005ecaa0);

        for (int i = 0; i < 0x20; i++, record += 0x9c)
        {
            if (record[0x0c] == 3 && IsSceneEntityAwake(record)) WakeSceneEntityKind3_00405680(i);
            if (record[0x0c] == 4 && IsSceneEntityAwake(record)) WakeSceneEntityKind4_00405770(i);
            if (record[0x0c] == 5 && IsSceneEntityAwake(record)) WakeSceneEntityKind5_00405840(i);
            if (record[0x0c] == 7 && IsSceneEntityAwake(record)) WakeSceneEntityKind7_004059A0(i);
            if (record[0x0c] == 6 && IsSceneEntityAwake(record)) WakeSceneEntityKind6_004058F0(i);
        }

        entity[0] &= 0x7fffffff;
    }

    /// <summary>Les deux bits que les balayeurs testent avant chaque reveil — vivante
    /// (<c>0x80000000</c>) et eveillee (<c>8</c>). Relus a chaque test.</summary>
    private static bool IsSceneEntityAwake(byte* record)
        => (*(uint*)record & 0x80000000) != 0 && (*(uint*)record & 8) != 0;

    /// <summary>
    /// Ghidra: FUN_00405680 @ 0x00405680 — <b>le reveil d'une entite de scene de type 3</b>, et le
    /// seul des huit qui <b>deplace</b> son entite : aux etats 1 et 3, si le pas d'animation vient
    /// d'atteindre sa fin (<c>+0x48 == 1</c>) et que le bit « l'etat vient de changer » est retombe,
    /// il decale <c>+0x32</c> de <c>-0x22</c> puis de <c>+0x22</c>.
    ///
    /// <para>Aller-retour de 34 unites, donc, sur ce seul champ : une porte qui s'ouvre et se
    /// referme, ou un battant. Les deux decalages sont des additions <b>16 bits</b> dans le binaire
    /// (<c>add word [esi+32h],0FFDEh</c>), pas des ecritures de dword.</para>
    ///
    /// <para>Il sert aussi de type 0 au troisieme balayeur, <c>FUN_00405a70</c>, non transcrit.</para>
    /// </summary>
    private static void WakeSceneEntityKind3_00405680(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1)
        {
            AdvanceSceneEntityState_00404FE0(record, 1);
            if (*(int*)(record + 0x48) == 1 && (*(uint*)(record + 0x5c) & 0x80000000) == 0)
            {
                *(short*)(record + 0x32) -= 0x22;
            }
        }

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2)
            CycleSceneEntityAnimations_004052F0(record, 2, 4, (short)(CrtRand() % 10));

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3)
        {
            CountDownSceneEntityState_00405420(record, 1);
            if (*(int*)(record + 0x48) == 1 && (*(uint*)(record + 0x5c) & 0x80000000) == 0)
            {
                *(short*)(record + 0x32) += 0x22;
            }
        }

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 4) AdvanceSceneEntityState_00404FE0(record, 2);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 5) AdvanceSceneEntityState_00404FE0(record, 3);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 6) AdvanceSceneEntityState_00404FE0(record, 4);
    }

    /// <summary>
    /// Ghidra: FUN_00405770 @ 0x00405770 — <b>type 4</b>. Exactement
    /// <see cref="WakeSceneEntityKind3_00405680"/> <b>sans les deux decalages de <c>+0x32</c></b> :
    /// memes six etats, memes numeros d'animation. Ce qui distingue les deux types est donc le
    /// deplacement, et rien d'autre.
    /// </summary>
    private static void WakeSceneEntityKind4_00405770(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1) AdvanceSceneEntityState_00404FE0(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2)
            CycleSceneEntityAnimations_004052F0(record, 2, 4, (short)(CrtRand() % 10));
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3) CountDownSceneEntityState_00405420(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 4) AdvanceSceneEntityState_00404FE0(record, 2);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 5) AdvanceSceneEntityState_00404FE0(record, 3);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 6) AdvanceSceneEntityState_00404FE0(record, 4);
    }

    /// <summary>
    /// Ghidra: FUN_00405840 @ 0x00405840 — <b>type 5</b>. Cinq etats au lieu de six, et une plage
    /// d'inactivite plus courte (animations 1 a 2). Le decompte de l'etat 3 porte sur l'animation 2.
    /// </summary>
    private static void WakeSceneEntityKind5_00405840(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1) AdvanceSceneEntityState_00404FE0(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2)
            CycleSceneEntityAnimations_004052F0(record, 1, 2, (short)(CrtRand() % 10));
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3) CountDownSceneEntityState_00405420(record, 2);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 4) AdvanceSceneEntityState_00404FE0(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 5) AdvanceSceneEntityState_00404FE0(record, 2);
    }

    /// <summary>
    /// Ghidra: FUN_004058f0 @ 0x004058f0 — <b>type 6</b>, et le seul des huit dont la pause
    /// d'inactivite soit <b>decalee de dix</b> : <c>rand % 10 + 10</c> au lieu de <c>rand % 10</c>.
    /// Il se fige donc deux fois plus longtemps sur chaque animation.
    ///
    /// <para>Son etat 4 avance l'animation <b>0</b>, ce qu'aucun autre ne fait.</para>
    /// </summary>
    private static void WakeSceneEntityKind6_004058F0(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1) AdvanceSceneEntityState_00404FE0(record, 4);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2)
            CycleSceneEntityAnimations_004052F0(record, 2, 3, (short)(CrtRand() % 10 + 10));
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3) CountDownSceneEntityState_00405420(record, 4);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 4) AdvanceSceneEntityState_00404FE0(record, 0);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 5) AdvanceSceneEntityState_00404FE0(record, 5);
    }

    /// <summary>
    /// Ghidra: FUN_004059a0 @ 0x004059a0 — <b>type 7</b>. Six etats, plage d'inactivite 3 a 4, et
    /// l'etat 6 qui avance l'animation 2 — le seul a redescendre apres les etats 4 et 5.
    /// </summary>
    private static void WakeSceneEntityKind7_004059A0(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1) AdvanceSceneEntityState_00404FE0(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2)
            CycleSceneEntityAnimations_004052F0(record, 3, 4, (short)(CrtRand() % 10));
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3) CountDownSceneEntityState_00405420(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 4) AdvanceSceneEntityState_00404FE0(record, 3);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 5) AdvanceSceneEntityState_00404FE0(record, 4);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 6) AdvanceSceneEntityState_00404FE0(record, 2);
    }

    /// <summary>
    /// Ghidra: FUN_00405a70 @ 0x00405a70 — <b>le troisieme balayeur d'entites de scene</b>. Meme
    /// forme et meme table <c>0x005ecaa0</c> que <see cref="EntityHandler_00404EF0"/> et
    /// <see cref="EntityHandler_004055C0"/>, meme auto-desarmement en sortant. Il reveille les types
    /// <b>0 a 4</b>, dans l'ordre.
    ///
    /// <para><b>Les numeros de type sont relatifs au balayeur, pas au corps.</b> Son type 0 est
    /// <see cref="WakeSceneEntityKind3_00405680"/> — la meme fonction que le second balayeur appelle
    /// pour son type 3. Le suffixe d'adresse est donc la seule identite stable des huit corps, et
    /// c'est pourquoi les quatre nouveaux ci-dessous ne portent <b>pas</b> de numero de type : il
    /// n'y en a pas un seul a porter.</para>
    ///
    /// <para>Atteint le 2026-08-25 dans la salle derriere le barman, entree 0 de la table installee
    /// par zone (<c>0x005ff400</c>).</para>
    /// </summary>
    private static void EntityHandler_00405A70(uint* entity)
    {
        byte* record = Mem.Entity(0x005ecaa0);

        for (int i = 0; i < 0x20; i++, record += 0x9c)
        {
            if (record[0x0c] == 0 && IsSceneEntityAwake(record)) WakeSceneEntityKind3_00405680(i);
            if (record[0x0c] == 1 && IsSceneEntityAwake(record)) WakeSceneEntity_00405B30(i);
            if (record[0x0c] == 2 && IsSceneEntityAwake(record)) WakeSceneEntity_00405BE0(i);
            if (record[0x0c] == 3 && IsSceneEntityAwake(record)) WakeSceneEntity_00405CB0(i);
            if (record[0x0c] == 4 && IsSceneEntityAwake(record)) WakeSceneEntity_00405D20(i);
        }

        entity[0] &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: FUN_00405b30 @ 0x00405b30 — trois etats seulement, et <b>le seul des douze corps de
    /// reveil qui fasse du bruit</b> : a l'etat 1, si l'animation courante est exactement la 2 et
    /// que son compteur d'images vaut 0x12, il joue le son <c>+0x10</c> de la table de la zone.
    ///
    /// <para>La condition est etroite a dessein — une image precise d'une animation precise. C'est
    /// un bruitage cale sur un geste : le pas d'un pied, le choc d'un objet pose.</para>
    ///
    /// <para>Les deux champs testes sont <c>+0x1a</c> (le compteur d'images, celui que
    /// <see cref="AdvanceSceneEntityState_00404FE0"/> fait courir) et <c>+0x18</c> (le numero
    /// d'animation). Ghidra les rend en <c>(&amp;DAT_005ecaba)[i * 0x4e]</c> et
    /// <c>(&amp;DAT_005ecab8)[i * 0x4e]</c> — des <b>short</b>, pas des octets.</para>
    /// </summary>
    private static void WakeSceneEntity_00405B30(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1)
        {
            AdvanceSceneEntityState_00404FE0(record, 2);

            if (*(short*)(record + 0x1a) == 0x12 && *(short*)(record + 0x18) == 2)
            {
                byte* sounds = *(byte**)(*(byte***)(s_Unknown_005e97cc + 0xa8));
                TryPlaySoundNearEntity((uint*)record, sounds[0x10], 0x400, 0x1000, 0, 0);
            }
        }

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2) AdvanceSceneEntityState_00404FE0(record, 0);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3) AdvanceSceneEntityState_00404FE0(record, 1);
    }

    /// <summary>
    /// Ghidra: FUN_00405be0 @ 0x00405be0 — six etats, plage d'inactivite 2 a 4. C'est
    /// <see cref="WakeSceneEntityKind3_00405680"/> <b>sans les deux decalages de <c>+0x32</c></b>,
    /// donc le meme corps que <see cref="WakeSceneEntityKind4_00405770"/> — <b>a la lettre</b>.
    ///
    /// <para>Verifie plutot que suppose, comme la regle du depot le demande : les deux corps font
    /// 208 octets, et le desassemblage des deux ne differe que par les <c>jne short</c> internes,
    /// relogeables par nature. <b>Aucun <c>call</c> ne differe</b> — memes cibles, meme ordre.
    /// Le compilateur a emis le corps deux fois ; les deux adresses restent distinctes parce que la
    /// table de sauts les distingue.</para>
    /// </summary>
    private static void WakeSceneEntity_00405BE0(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 1) AdvanceSceneEntityState_00404FE0(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 2)
            CycleSceneEntityAnimations_004052F0(record, 2, 4, (short)(CrtRand() % 10));
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 3) CountDownSceneEntityState_00405420(record, 1);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 4) AdvanceSceneEntityState_00404FE0(record, 2);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 5) AdvanceSceneEntityState_00404FE0(record, 3);
        if ((*(uint*)(record + 0x5c) & 0x3fffffff) == 6) AdvanceSceneEntityState_00404FE0(record, 4);
    }

    /// <summary>
    /// Ghidra: FUN_00405cb0 @ 0x00405cb0 — trois etats, sans inactivite : deux pas d'animation puis
    /// un decompte. Le plus court des corps a plusieurs branches.
    /// </summary>
    private static void WakeSceneEntity_00405CB0(int index)
    {
        byte* record = Mem.Entity(0x005ecaa0) + index * 0x9c;

        ArmSceneEntityState_004051D0(record);

