        if (state != unchecked((short)0xFF01) && state != unchecked((short)0xFFFE) && state != 0
            && state != unchecked((short)0xFFFF) && state != 0xCA)
        {
            FreezeAllEntities();
            entity[0] &= 0xFBFFFFFF;
        }

