            // et le couvercle tourne de 35 par image.
            int target = *(int*)(e + 0x5c);
            int current = *Mem.EntityState(0x00571528);
            *Mem.EntityState(0x00571528) = current + ((target - current) >> 2);

            *(short*)(e + 0x34) += unchecked((short)0xFFDD);
            (*(short*)(e + 0x12))++;

