            if ((*(uint*)record & 0x80000000) == 0) continue;

            if ((*(uint*)record & 0x4000008) == 0)
            {
                record[0x36] &= 0x7f;
                CallIndexedEntityHandler(
                    0x00552230, 0x0056afc8, record[5], record,
                    $"FUN_0047acf0, table 0x005f2d40 entree {i}");
            }

