    private static byte* CutsceneVerb03_005038A0(byte* cursor, ref int carryOn)
    {
        byte* hold = Mem.EntityStateBytes(0x00571a34);
        if (*hold != 0)
        {
            if (--*hold == 0) return cursor + 2;
            carryOn = 0;
            return cursor;
