        goal[0] = *(short*)(owner + 0x30);
        goal[1] = (short)-*(short*)(owner + 0x32);
        goal[2] = *(short*)(owner + 0x34);

        *(byte**)Mem.EntityStateBytes(0x005719b0) = owner + 0x30;

        return cursor + 1;
