        int* goal = Mem.EntityState(0x005719f8);

        goal[0] = *(int*)(owner + 0x1c);
        goal[1] = *(int*)(owner + 0x20);
        goal[2] = *(int*)(owner + 0x24);

        *(byte**)Mem.EntityStateBytes(0x00571a14) = owner + 0x1c;

