    /// <summary>
    /// Le quart de tour d'angle du verbe 4. <paramref name="delta"/> est deja ramene sur douze bits,
    /// donc positif ; au-dela d'un demi-tour (<c>0x800</c>) c'est le complement au tour complet qui
    /// est pris, en negatif, ce qui fait tourner la camera du bon cote.
    /// </summary>
    private static int ShortestArcStep(int delta)
        => delta < 0x800 ? delta >> 2 : -((0x1000 - delta) >> 2);

    /// <summary>
    /// La meme chose pour le verbe 5, ou la duree remplace le quart.
    /// </summary>
    private static int ShortestArcOver(int delta, int frames)
        => delta < 0x800 ? delta / frames : -((0x1000 - delta) / frames);


    /// <summary>
    /// Ghidra: verbe 15 @ 0x00503e80 — <b>la camera prend une entite pour cible</b>. L'octet
    /// <c>+1</c> choisit la table d'entites et l'octet <c>+2</c> l'indice dedans ; les trois tables
    /// ont le meme pas de <c>0x9c</c> octets :
    /// <list type="bullet">
    ///   <item><term>0</term><description><c>0x005e93c0</c>, les membres du groupe</description></item>
    ///   <item><term>1</term><description><c>0x005ecaa0</c>, les entites de scene</description></item>
    ///   <item><term>2</term><description><c>0x005fa5e0</c>, la troisieme table d'entites</description></item>
    /// </list>
    ///
    /// <para>Le verbe copie ensuite le triplet de position de l'entite (<c>+0x30</c>) dans
    /// <c>DAT_005719f0</c> — le meme triplet que <c>BeginScriptedCamera</c> avait rempli depuis la
    /// vue courante — en <b>niant la composante du milieu</b>, et range dans <c>DAT_005719b0</c>
    /// l'adresse du triplet source, de sorte que la suite puisse <b>suivre</b> l'entite et pas
    /// seulement la viser une fois. Aucune fonction de <c>Blaze.c</c> ne lit <c>DAT_005719b0</c> :
    /// ses lecteurs sont d'autres verbes de la meme table, eux aussi non decompiles.</para>
    ///
    /// <para><b>Le cas par defaut lit le script lui-meme.</b> Pour toute autre valeur que 0, 1 ou 2
    /// l'original fait <c>mov eax,[esp+8]</c>, ce qui — apres le <c>push esi</c> de l'entree — est
    /// le <b>premier</b> parametre, donc le curseur : il va chercher son triplet trente octets plus
    /// loin dans le script. Transcrit tel quel ; c'est vraisemblablement une branche morte que le
    /// scenario n'emprunte jamais, pas une intention.</para>
    /// </summary>
    private static byte* CutsceneVerb15_00503E80(byte* cursor)
    {
        byte* record;
        switch (cursor[1])
        {
            case 0: record = Inp.s_SlotFlags_005e93c0 + cursor[2] * 0x9c; break;
            case 1: record = Mem.Entity(0x005ecaa0) + cursor[2] * 0x9c; break;
            case 2: record = Mem.Entity(0x005fa5e0) + cursor[2] * 0x9c; break;
            default: record = cursor; break;
        }

        short* target = (short*)Mem.EntityStateBytes(0x005719f0);
        target[0] = *(short*)(record + 0x30);
        target[1] = (short)-*(short*)(record + 0x32);
        target[2] = *(short*)(record + 0x34);

        *(byte**)Mem.EntityStateBytes(0x005719b0) = record + 0x30;

        return cursor + 3;
    }

    /// <summary>
    /// Ghidra: verbe 16 @ 0x00503f10 — <b>la camera se pose sur une entite</b>. Le jumeau exact du
    /// verbe 15 : meme choix de table par <c>+1</c>, meme indice par <c>+2</c>, meme cas par defaut
    /// qui relit le curseur. Il copie cette fois le triplet <c>+0x1c</c> — la <b>position</b>, trois
    /// entiers 32 bits — dans la consigne <c>DAT_005719f8</c>, et range l'adresse du triplet source
    /// dans <c>DAT_00571a14</c> pour que la camera puisse suivre l'entite.
    ///
    /// <para>Aucune negation ici, contrairement au verbe 15 : c'est bien une position, pas un cap.</para>
    /// </summary>
    private static byte* CutsceneVerb16_00503F10(byte* cursor)
    {
        byte* record;
        switch (cursor[1])
        {
            case 0: record = Inp.s_SlotFlags_005e93c0 + cursor[2] * 0x9c; break;
            case 1: record = Mem.Entity(0x005ecaa0) + cursor[2] * 0x9c; break;
            case 2: record = Mem.Entity(0x005fa5e0) + cursor[2] * 0x9c; break;
            default: record = cursor; break;
        }

        int* goal = Mem.EntityState(0x005719f8);
        goal[0] = *(int*)(record + 0x1c);
        goal[1] = *(int*)(record + 0x20);
        goal[2] = *(int*)(record + 0x24);

        *(byte**)Mem.EntityStateBytes(0x00571a14) = record + 0x1c;

        return cursor + 3;
    }

    /// <summary>
    /// Ghidra: verbe 17 @ 0x00503fa0 — <b>consigne d'angles litterale</b>. Il lit deux entiers
    /// 16 bits ecrits en clair dans le script — <c>+1..+2</c> et <c>+3..+4</c> — et les pose dans
    /// les deux premieres composantes de <c>DAT_005719f0</c>, la consigne d'angles que le verbe 15
    /// remplissait depuis une entite.
    ///
    /// <para><b>La troisieme composante n'est pas touchee</b> (<c>DAT_005719f4</c> garde ce que
    /// <c>BeginScriptedCamera</c> y avait mis) : le roulis ne se pilote pas par ce verbe.</para>
    /// </summary>
    private static byte* CutsceneVerb17_00503FA0(byte* cursor)
    {
        short* goal = (short*)Mem.EntityStateBytes(0x005719f0);
        goal[0] = (short)(cursor[1] | (cursor[2] << 8));
        goal[1] = (short)(cursor[3] | (cursor[4] << 8));
        return cursor + 5;
    }

    /// <summary>
    /// Ghidra: verbe 18 @ 0x00503fd0 — <b>consigne de position litterale</b>. Trois entiers signes
    /// de 16 bits lus dans le script (<c>+1..+6</c>), <b>decales de douze bits vers la gauche</b>,
    /// vers la consigne de position <c>DAT_005719f8</c> que le verbe 16 remplissait depuis une
    /// entite. Le decalage dit la convention du bloc de camera : du virgule fixe 20.12, dont le
    /// script n'ecrit que la partie entiere.
    /// </summary>
    private static byte* CutsceneVerb18_00503FD0(byte* cursor)
    {
        int* goal = Mem.EntityState(0x005719f8);
        goal[0] = (short)(cursor[1] | (cursor[2] << 8)) << 12;
        goal[1] = (short)(cursor[3] | (cursor[4] << 8)) << 12;
        goal[2] = (short)(cursor[5] | (cursor[6] << 8)) << 12;
        return cursor + 7;
    }

    /// <summary>
    /// Ghidra: verbe 19 @ 0x00504020 — <b>consigne de cible litterale</b>. Meme lecture que le
    /// verbe 18 — trois entiers signes de 16 bits — mais vers <c>DAT_00571a28</c>, le troisieme
    /// triplet que <c>BeginScriptedCamera</c> avait sauvegarde, et <b>sans le decalage de douze
    /// bits</b>. Les deux triplets ne sont donc pas dans la meme echelle, et c'est voulu.
    /// </summary>
    private static byte* CutsceneVerb19_00504020(byte* cursor)
    {
        int* goal = Mem.EntityState(0x00571a28);
        goal[0] = (short)(cursor[1] | (cursor[2] << 8));
        goal[1] = (short)(cursor[3] | (cursor[4] << 8));
        goal[2] = (short)(cursor[5] | (cursor[6] << 8));
        return cursor + 7;
    }

    /// <summary>
    /// Ghidra: verbe 20 @ 0x00504070 — <b>le verbe 17 en relatif</b> : meme lecture de deux entiers
    /// 16 bits, mais <c>add</c> au lieu de <c>mov</c> sur la consigne d'angles. L'addition se fait
    /// <b>sur seize bits</b> (<c>add [5719F0h],cx</c>), donc elle boucle naturellement autour du
    /// tour complet — ce qui est exactement ce qu'on veut d'un cap.
    /// </summary>
    private static byte* CutsceneVerb20_00504070(byte* cursor)
    {
        short* goal = (short*)Mem.EntityStateBytes(0x005719f0);
        goal[0] += (short)(cursor[1] | (cursor[2] << 8));
        goal[1] += (short)(cursor[3] | (cursor[4] << 8));
        return cursor + 5;
    }

    /// <summary>
    /// Ghidra: verbe 21 @ 0x005040a0 — <b>le verbe 18 en relatif</b> : trois entiers signes de
    /// 16 bits, decales de douze bits, <b>ajoutes</b> a la consigne de position.
    /// </summary>
    private static byte* CutsceneVerb21_005040A0(byte* cursor)
    {
        int* goal = Mem.EntityState(0x005719f8);
        goal[0] += (short)(cursor[1] | (cursor[2] << 8)) << 12;
        goal[1] += (short)(cursor[3] | (cursor[4] << 8)) << 12;
        goal[2] += (short)(cursor[5] | (cursor[6] << 8)) << 12;
        return cursor + 7;
    }

    /// <summary>
    /// Ghidra: verbe 22 @ 0x00504110 — <b>le verbe 19 en relatif</b> : trois entiers signes de
    /// 16 bits <b>ajoutes</b> a la consigne de cible, toujours sans decalage.
    /// </summary>
    private static byte* CutsceneVerb22_00504110(byte* cursor)
    {
        int* goal = Mem.EntityState(0x00571a28);
        goal[0] += (short)(cursor[1] | (cursor[2] << 8));
        goal[1] += (short)(cursor[3] | (cursor[4] << 8));
        goal[2] += (short)(cursor[5] | (cursor[6] << 8));
        return cursor + 7;
    }

    // ---------------------------------------------------------------------------------------------
    // Les verbes 23 a 25 rappellent la camera libre. Les trois blocs qu'ils lisent sont ceux que la
    // carte du monde utilise hors scenette, et ce sont les memes que `BeginScriptedCamera` avait
    // debranches en leur substituant ses copies de travail :
    //
    //     DAT_005e9ae0 -> &DAT_00564650   les trois angles      (shorts)
    //     DAT_005edebc -> &DAT_005de068   la position           (ints)
    //     DAT_005eca94 -> &DAT_005de078   la cible              (ints)
    //
    // Un verbe 23/24/25 remet donc la consigne correspondante sur la valeur de la camera libre :
    // c'est le « reviens ou tu etais » du scenariste, composante par composante.
    // ---------------------------------------------------------------------------------------------

    /// <summary>
    /// Ghidra: verbe 23 @ 0x00504170 — <b>consigne d'angles = ceux de la camera libre</b>
    /// (<c>DAT_00564650</c>, trois <c>short</c>). Un seul octet : le verbe n'a pas d'operande.
    /// </summary>
    private static byte* CutsceneVerb23_00504170(byte* cursor)
    {
        short* free = (short*)s_WorldMapCamera_00564650;
        short* goal = (short*)Mem.EntityStateBytes(0x005719f0);
        goal[0] = free[0];
        goal[1] = free[1];
        goal[2] = free[2];
        return cursor + 1;
    }

    /// <summary>
    /// Ghidra: verbe 24 @ 0x005041a0 — <b>consigne de position = celle de la camera libre</b>
    /// (<c>DAT_005de068</c>, trois <c>int</c>). Sans operande.
    /// </summary>
    private static byte* CutsceneVerb24_005041A0(byte* cursor)
    {
        int* goal = Mem.EntityState(0x005719f8);
        goal[0] = *Mem.Camera(0x005de068);
        goal[1] = *Mem.Camera(0x005de06c);
        goal[2] = *Mem.Camera(0x005de070);
        return cursor + 1;
    }

    /// <summary>
    /// Ghidra: verbe 25 @ 0x005041d0 — <b>consigne de cible = celle de la camera libre</b>
    /// (<c>DAT_005de078</c>, trois <c>int</c>). Sans operande.
    /// </summary>
    private static byte* CutsceneVerb25_005041D0(byte* cursor)
    {
        int* goal = Mem.EntityState(0x00571a28);
        goal[0] = *Mem.Camera(0x005de078);
        goal[1] = *Mem.Camera(0x005de07c);
        goal[2] = *Mem.Camera(0x005de080);
        return cursor + 1;
    }

    /// <summary>
    /// Ghidra: verbe 26 @ 0x00504200 — <b>le mouvement inverse des trois precedents</b> : il verse
    /// l'etat courant de la scenette <b>dans</b> les blocs de la camera libre, de sorte que la
    /// sortie de scenette ne fasse pas sauter l'image.
    ///
    /// <list type="bullet">
    ///   <item>les trois angles de travail (<c>DAT_005719e8</c>) vers <c>DAT_00564650</c> ;</item>
    ///   <item>la cible de travail (<c>DAT_00571a08</c>) <b>moins</b> <c>DAT_005de088</c> vers
    ///         <c>DAT_00564658</c>.</item>
    /// </list>
    ///
    /// <para>La soustraction n'est pas gratuite : <c>FUN_00516350</c> fait le chemin dans l'autre
    /// sens — <c>DAT_005de078 = DAT_00564658 + DAT_005de088</c>, apres avoir amorti
    /// <c>DAT_00564658</c> d'un huitieme a chaque image. <c>DAT_00564658</c> est donc un
    /// <b>ecart</b> par rapport a <c>DAT_005de088</c>, et pas une position ; le verbe le reconstitue
    /// dans la bonne unite pour que l'amortissement reprenne sans discontinuite.</para>
    ///
    /// <para>Sans operande, comme les trois precedents.</para>
    /// </summary>
    private static byte* CutsceneVerb26_00504200(byte* cursor)
    {
        short* viewWork = (short*)Mem.EntityStateBytes(0x005719e8);
        short* free = (short*)s_WorldMapCamera_00564650;
        free[0] = viewWork[0];
        free[1] = viewWork[1];
        free[2] = viewWork[2];

        int* targetWork = Mem.EntityState(0x00571a08);
        int* slide = (int*)(s_WorldMapCamera_00564650 + 8);
        slide[0] = targetWork[0] - *Mem.Camera(0x005de088);
        slide[1] = targetWork[1] - *Mem.Camera(0x005de08c);
        slide[2] = targetWork[2] - *Mem.Camera(0x005de090);

        return cursor + 1;
    }

    /// <summary>
    /// Ghidra: verbe 27 @ 0x00504270 — <b>pose des bits dans le mot de scenette</b>. Il lit
    /// l'octet qui suit l'indice et l'ajoute par <c>ou</c> a <c>DAT_00604b78</c>, puis avance de
    /// deux. Il ne touche pas a <c>continuer</c> : le verbe suivant part dans le meme appel.
    ///
    /// <para>L'original travaille <b>sur un octet</b> (<c>mov dl,[604B78h]</c> … <c>or dl,cl</c>) ;
    /// comme l'operande est lui-meme un octet, le resultat sur le mot complet est identique et
    /// l'ecriture ci-dessous est fidele.</para>
    ///
    /// <para>Le bit 0 est celui que <c>BeginScriptedCamera</c> pose et que l'echappement du joueur
    /// teste plus haut : ce verbe est donc, entre autres, le « rends la main au joueur » du
    /// scenariste.</para>
    /// </summary>
    private static byte* CutsceneVerb27_00504270(byte* cursor)
    {
        Saves.s_CutsceneActive_00604b78 |= cursor[1];
        return cursor + 2;
    }

    /// <summary>
    /// Ghidra: verbe 28 @ 0x00504290 — <b>l'exact contraire du verbe 27</b> : il <c>et-non</c>
    /// l'octet <c>+1</c> dans <c>DAT_00604b78</c> au lieu de l'y ajouter par <c>ou</c>, et avance
    /// lui aussi de deux. Meme remarque sur la largeur : l'original travaille sur l'octet bas, et
    /// comme le complement d'un octet laisse les bits hauts a un, l'ecriture sur le mot entier est
    /// fidele.
    /// </summary>
    private static byte* CutsceneVerb28_00504290(byte* cursor)
    {
        Saves.s_CutsceneActive_00604b78 &= ~cursor[1];
        return cursor + 2;
    }

    /// <summary>
    /// Ghidra: verbe 29 @ 0x005042b0 — <b>secousse d'angles</b>. Deux amplitudes de 16 bits lues
    /// dans le script ; pour chacune, <c>CrtRand() % (2 * amplitude) - amplitude</c> est
    /// <b>ajoute</b> a la consigne d'angles. C'est le tremblement de camera, tire a neuf a chaque
    /// passage du verbe.
    ///
    /// <para>Une amplitude nulle est <b>remontee a un</b> avant la division, ce qui evite le
    /// division-par-zero et donne un tirage constamment nul — le verbe reste donc inoffensif si le
    /// scenario ecrit un zero.</para>
    ///
    /// <para><b>Le diviseur et le recentrage n'ont pas la meme signature.</b> L'original divise par
    /// <c>movsx ecx,di</c> — l'amplitude <b>signee</b> sur 16 bits — puis retranche <c>edi</c>, qui
    /// est la meme amplitude <b>non signee</b>. Les deux ne coincident que sous 0x8000 ; transcrit
    /// tel quel plutot que normalise.</para>
    /// </summary>
    private static byte* CutsceneVerb29_005042B0(byte* cursor)
    {
        int rangeA = cursor[1] | (cursor[2] << 8);
        int rangeB = cursor[3] | (cursor[4] << 8);
        if ((ushort)rangeA == 0) rangeA = 1;
        if ((ushort)rangeB == 0) rangeB = 1;

        short* goal = (short*)Mem.EntityStateBytes(0x005719f0);
        goal[0] += (short)(CrtRand() % ((short)rangeA * 2) - rangeA);
        goal[1] += (short)(CrtRand() % ((short)rangeB * 2) - rangeB);

        return cursor + 5;
    }

    /// <summary>
    /// Ghidra: verbe 30 @ 0x00504310 — <b>secousse de position</b>, le verbe 29 porte a trois
    /// composantes et applique a la consigne de position, avec le decalage de douze bits qui est la
    /// convention de ce bloc. Meme remontee des amplitudes nulles a un, meme melange d'amplitude
    /// signee au diviseur et non signee au recentrage.
    /// </summary>
    private static byte* CutsceneVerb30_00504310(byte* cursor)
    {
        int rangeX = cursor[1] | (cursor[2] << 8);
        int rangeY = cursor[3] | (cursor[4] << 8);
        int rangeZ = cursor[5] | (cursor[6] << 8);
        if ((ushort)rangeX == 0) rangeX = 1;
        if ((ushort)rangeY == 0) rangeY = 1;
        if ((ushort)rangeZ == 0) rangeZ = 1;

        int* goal = Mem.EntityState(0x005719f8);
        goal[0] += (CrtRand() % ((short)rangeX * 2) - rangeX) << 12;
        goal[1] += (CrtRand() % ((short)rangeY * 2) - rangeY) << 12;
        goal[2] += (CrtRand() % ((short)rangeZ * 2) - rangeZ) << 12;

        return cursor + 7;
    }

    /// <summary>
    /// Ghidra: verbe 31 @ 0x005043c0 — <b>secousse de cible</b>, le troisieme du triptyque
    /// 29/30/31 : meme tirage <c>CrtRand() % (2 * amplitude) - amplitude</c> sur trois composantes,
    /// applique cette fois a la consigne de cible <c>DAT_00571a28</c>, et sans decalage — la meme
    /// difference d'echelle qui separe deja les verbes 18 et 19.
    ///
    /// <para><b>L'ecart de 0x8c0 octets jusqu'a l'entree suivante de la table ne mesure rien</b> :
    /// le verbe se termine des <c>0x0050445d</c>, et le code qui suit (a partir de
    /// <c>0x00504460</c>, une initialisation qui alloue huit tampons et ouvre un fichier) n'a rien
    /// a voir avec lui. Un ecart entre deux entrees d'une table de pointeurs n'est pas une taille.</para>
    /// </summary>
    private static byte* CutsceneVerb31_005043C0(byte* cursor)
    {
        int rangeX = cursor[1] | (cursor[2] << 8);
        int rangeY = cursor[3] | (cursor[4] << 8);
        int rangeZ = cursor[5] | (cursor[6] << 8);
        if ((ushort)rangeX == 0) rangeX = 1;
        if ((ushort)rangeY == 0) rangeY = 1;
        if ((ushort)rangeZ == 0) rangeZ = 1;

        int* goal = Mem.EntityState(0x00571a28);
        goal[0] += CrtRand() % ((short)rangeX * 2) - rangeX;
        goal[1] += CrtRand() % ((short)rangeY * 2) - rangeY;
        goal[2] += CrtRand() % ((short)rangeZ * 2) - rangeZ;

        return cursor + 7;
    }

    // =====================================================================
    // FUN_0050bf20 — LE PAS PAR PERSONNAGE
    //
    // 1 002 lignes de pseudo-C, 8 Ko de code, appelees une fois par membre du groupe et par image.
    // C'est le plus gros corps que le depot ait transcrit, et **la pseudo-C seule n'y suffit pas** :
    // Ghidra y perd trois registres et tout un bloc de calcul. Les quatre points ci-dessous ont ete
    // tranches au desassembleur avant d'ecrire une ligne, et ils valent pour toute fonction de
    // cette taille.
    //
    // **`iStack_4`, jamais affecte dans la pseudo-C, est `[esp+68h]`** — et `[esp+68h]` est
    // l'emplacement du PARAMETRE, que le prologue ecrase (`mov [esp+68h],eax` en 0x0050bf52) avec
    // `&DAT_005e9180 + membre * 0x4c`, l'entree d'emplacement. Confirme en 0x0050ce71 :
    // `mov edi,[esp+68h] ; movsx ebx,word [edi+44h]` est exactement le `*(short *)(iStack_4 + 0x44)`
    // de la pseudo-C. C'est donc le `puVar11` que Ghidra nomme correctement ailleurs dans la meme
    // fonction : **le meme objet sous deux noms**, l'un des deux perdu.
    //
    // **`unaff_EBP` est le bloc par personnage** (`MainMem + 0xf0000 + membre * 0x2000`), pose en
    // 0x0050bf61 et sauve en `[esp+10h]`. C'est le `iVar23` de la pseudo-C ; Ghidra le perd parce
    // que 0x0050cee9 (`mov ebp,[esi+78h]`) reutilise le registre en cours de route.
    //
    // **`unaff_EBX` est l'etat de manette** (`&DAT_00604a20 + slotKind * 0x10`), pose en 0x0050bf63
    // et sauve en `[esp+14h]`. C'est le `puVar21`.
    //
    // **Le bloc de matrices de 0x0050cfb1..0x0050d290** est rendu par Ghidra comme une cascade de
    // `__allmul`/`__allshr` dont les resultats sont perdus, ce qui le rend illisible. Au
    // desassembleur c'est deux produits matrice-vecteur parfaitement reguliers, decalage `>> 12`
    // (le `mov ecx,0Ch` de 0x0050d02f et de ses cinq jumeaux). Voir
    // <see cref="ComputeCarrierOffset"/>.
    // =====================================================================

    /// <summary>
    /// Ghidra: <c>&amp;DAT_00562cc0</c> — huit entiers releves dans le binaire
    /// (<c>at Legacy/Binaries/Blaze.exe 0x00562cc0 32</c>), indexes par les trois bits bas de
    /// <c>bloc + 0x150</c>, la posture. C'est la <b>vitesse de deplacement</b> de cette posture.
    ///
    /// <para>
    /// <b>Le role n'a ete etabli qu'avec le deuxieme lecteur.</b> Vu de
    /// <see cref="TickFollowingMember"/> seul, la table ressemblait a une portee de detection ; vu
    /// de <see cref="HandleDirectionalInput_0050E140"/>, qui la decale de 12 bits pour en faire
    /// directement la vitesse du personnage, c'est une vitesse. Les deux se recoupent : le membre
    /// suivi s'arrete a une distance egale a un pas de son meneur, quelle que soit la posture.
    /// </para>
    /// </summary>
    private static readonly int[] s_PostureSpeed_00562cc0 =
        [0x13, 0x13, 0x15, 0x12, 0x14, 0x14, 0x12, 0x15];

    /// <summary>
    /// Ghidra: <c>&amp;DAT_00562dc8</c> — seize octets releves dans le binaire, juste apres la table
    /// de pas sonores. Indexes par le <b>quartet haut</b> de <c>manette[0]</c>, c'est-a-dire la
    /// croix directionnelle : ils rendent un <b>secteur sur huit</b>, ou zero quand la direction
    /// est nulle ou contradictoire.
    ///
    /// <para>
    /// Le contenu se lit tout seul une fois qu'on remarque que les quatre bits sont haut, droite,
    /// bas, gauche dans cet ordre : <c>1→1</c>, <c>3→2</c>, <c>2→3</c>, <c>6→4</c>, <c>4→5</c>,
    /// <c>12→6</c>, <c>8→7</c>, <c>9→8</c> — les huit secteurs dans le sens horaire, diagonales
    /// comprises. Les deux paires opposees (<c>5</c> = haut+bas, <c>10</c> = gauche+droite) et
    /// toutes les combinaisons de trois touches rendent zero : elles s'annulent, et c'est ce zero
    /// qui fait retomber le personnage a l'arret.
    /// </para>
    /// </summary>
    private static readonly sbyte[] s_PadDirection_00562dc8 =
        [0, 1, 3, 2, 5, 0, 4, 0, 7, 8, 0, 0, 6, 0, 0, 0];

    /// <summary>
    /// Ghidra: <c>&amp;PTR_FUN_00562ca0</c> — huit gestionnaires de posture, releves dans le binaire.
    /// <b>Quatre d'entre eux sont <c>0x0040A600</c></b>, le corps vide deja verifie au
    /// desassembleur, donc seules les postures 0, 4, 6 et 7 font quelque chose.
    /// </summary>
    private static readonly uint[] s_PostureHandlers_00562ca0 =
        [0x0051A670, 0x0040A600, 0x0040A600, 0x0040A600, 0x0051A6B0, 0x0040A600, 0x0051A700, 0x0051A710];

    /// <summary>
    /// Ghidra: <c>&amp;PTR_FUN_00562ce0</c> — quatre gestionnaires de commande, releves dans le
    /// binaire. Aucun n'est le corps vide.
    /// </summary>
    private static readonly uint[] s_InputHandlers_00562ce0 =
        [0x0050E140, 0x0050DE90, 0x0050DD00, 0x0050DFF0];

    /// <summary>Ghidra: DAT_005de708 — l'index de membre que le declenchement du repartiteur
    /// <c>DAT_005e9ae4</c> met de cote, en meme temps que <c>DAT_005de540</c>. Hors du bloc de
    /// camera (qui s'arrete a 0x005de100), donc declare a part.</summary>
    private static int s_Unknown_005de708;

    /// <summary>
    /// Ghidra: FUN_0050bf20 @ 0x0050bf20 — <b>le pas par personnage</b>. Voir le pave ci-dessus pour
    /// les quatre lectures que seule la machine donne.
    ///
    /// <para>
    /// La fonction fait, dans l'ordre : avancer l'animation, lire la manette (ou l'intention de
    /// l'IA), decider d'un changement d'etat, appliquer le deplacement au terrain, gerer le
    /// portage par une autre entite, puis publier le resultat. Elle sort tot dans six cas
    /// distincts, tous conserves.
    /// </para>
    /// <para>
    /// <b>Onze appelees ne sont pas encore transcrites</b> et levent chacune en se nommant. Toutes
    /// sont dans <c>Blaze.c</c> — aucune ne demande de desassemblage. Elles n'ont pas ete ecrites
    /// d'avance : c'est le jeu qui dira lesquelles il emprunte, comme pour les verbes de zone et
    /// les gestionnaires d'entite.
    /// </para>
    /// </summary>
    private static void TickPartyMember(int member)
    {
        byte* mainMem = GetMainMemPtr();

        byte* s = Inp.s_SlotFlags_005e93c0 + member * 0x9c;      // Ghidra: puVar3
        uint* slot = (uint*)s;
        byte* entry = Inp.s_SlotArea_005e9180 + member * 0x4c;   // Ghidra: puVar11, alias iStack_4
        byte slotKind = Inp.s_PlayerSlots_005e9188[member * 0x4c];
        byte* pad = Inp.s_InputStateBase_00604a20 + slotKind * 0x10;   // Ghidra: puVar21, alias unaff_EBX
        byte* perChar = mainMem + 0xf0000 + member * 0x2000;           // Ghidra: iVar23, alias unaff_EBP

        if ((*slot & 0x4000008) != 0) return;

        if (perChar[0x207] != 0) perChar[0x207]--;

        // La cible tenue a +0x74 est oubliee des qu'elle cesse d'etre active.
        byte* watched = *(byte**)(s + 0x74);
        if (watched != null && (*(uint*)watched & 0x80000000) == 0) *(byte**)(s + 0x74) = null;

        // Le bouton 3 ouvre le menu, mais seulement si le repartiteur est au repos.
        if ((*slot & 0x40010000) == 0 && (pad[2] & 8) != 0 && (*(uint*)Mem.Arena(0x005e9ae4) & 3) == 0)
        {
            s_Unknown_005de540 = s[8];
            s_Unknown_005de708 = s_Unknown_005de540;
            (*Mem.Arena(0x005e9ae4))++;
            *Mem.Entity(0x005fa580) = 1;
        }

        // Le compte a rebours de transition : tant qu'il tourne, le membre est fige.
        if (*(ushort*)(s + 0x12) != 0)
        {
            *(ushort*)(s + 0x12) = 0x14;
            if ((*slot & 0x10000000) != 0) return;

            *(short*)(s + 0x32) = *(short*)(s + 0x98);
            *slot |= 0x10000000;
            return;
        }

        // ---------------------------------------------------------------- animation
        uint state = *slot;
        uint running = state & 0xfdffffff;
        *slot = running;

        byte* animSet = *(byte**)(Mem.Arena(0x005e9680) + s[4] * 4);
        byte* anim = *(byte**)(animSet + *(short*)(s + 0x18) * 4);

        if ((state & 0x1000000) == 0)
        {
            short frame = *(short*)(s + 0x1a);
            if (frame + 1 < (int)*(ushort*)(anim + 0x16))
            {
                // Un membre porte par une autre entite (0x40000000) n'avance qu'une image sur deux.
                if ((state & 0x40000000) == 0) *(short*)(s + 0x1a) = (short)(frame + 1);
                else if ((*(uint*)Mem.Entity(0x005f2cf0) & 1) != 0) *(short*)(s + 0x1a) = (short)(frame + 1);
            }
            else
            {
                *slot = running | 0x2000000;
                if ((state & 0x40000005) == 0)
                {
                    // Ghidra rend l'ecriture par CONCAT31 — c'est un `mov [.],al` sur l'octet bas,
                    // qui laisse la valeur inchangee puisque 0x2000000 ne touche pas cet octet.
                    *(uint*)(s + 0x18) = 0;
                    *slot = ((running | 0x2000000) & 0xfffffffd) | 0x1000000;
                }

                if ((*slot & 0x40) != 0) *slot &= 0xffffffbf;
            }
        }
        else
        {
            (*(short*)(s + 0x1a))++;
            if ((int)*(ushort*)(anim + 0x16) <= *(short*)(s + 0x1a)) *(short*)(s + 0x1a) = 0;
        }

        short stateId = *(short*)(s + 0x18);
        if (stateId == 0) *slot &= 0xfffffffb;

        state = *slot;
        if ((state & 0x40000000) == 0)
        {
            // La regeneration lente, un centieme d'image, tant qu'aucune touche n'est tenue.
            if ((*(ushort*)pad & *(ushort*)(perChar + 0x1fc4)) == 0)
            {
                short maximum = *(short*)(perChar + 0x14a);
                if (*(short*)(perChar + 0x14e) < maximum
                    && (perChar[0x140] & 2) == 0
                    && (state & 0x80) == 0
                    && *(uint*)Mem.Entity(0x005f2cf0) % 100 == 0)
                {
                    short raised = (short)(*(short*)(perChar + 0x156) + *(short*)(perChar + 0x14e));
                    *(short*)(perChar + 0x14e) = raised;
                    if (maximum < raised) *(short*)(perChar + 0x14e) = maximum;
                }
            }
        }
        else if (stateId == 7)
        {
            if ((state & 0x2000000) != 0 && (state & 0x200000) == 0) *slot = state | 0x200000;
        }
        else
        {
            // Porte, mais pas dans l'etat de portage : on y bascule.
            *(uint*)Mem.Arena(0x005e99c0) = 0;
            TriggerEquippedItems_005238E0(slot, 0x15);

            state = *slot;
            if ((state & 0x40000000) != 0)
            {
                *(uint*)(s + 0x18) = 7;
                *(uint*)(s + 0x38) = 0xffffff;
                *slot = (state & 0xf6fffff9) | 0x12000;
                byte carried = s[8];
                *(short*)(s + 0x36) = 1;
                *(short*)(s + 0x96) = 0;

                if (carried == (byte)Mem.s_Unknown_005de538)
                {
                    PassLeaderToNextEligible(slot, entry, 0);
                }

                *(uint*)(perChar + 0x140) = 0x40000000;
                for (int i = 0; i < 0x20; i++) ((uint*)(perChar + 0x180))[i] = 0;
            }
        }

        *(uint*)(s + 0x5c) = 0;

        // ---------------------------------------------------------------- l'aiguillage principal
        if ((*(uint*)(perChar + 0x140) & 0x400001c0) != 0)
        {
            // Hors de combat : l'etat retombe et le role de meneur passe.
            if ((*slot & 0x40000000) == 0) *(uint*)(s + 0x18) = 0;

            byte previousLeader = (byte)Mem.s_Unknown_005de538;
            if (s[8] == previousLeader)
            {
                PassLeaderToNextEligible(slot, entry, 0);
                if (previousLeader != (byte)Mem.s_Unknown_005de538) *slot |= 0x10000;
            }

            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        if ((*slot & 0x80) != 0)
        {
            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        if (*(ushort*)(pad + 2) != 0)
        {
        }

        if ((*slot & 0x8000000) != 0)
        {
            TickQuickMenu_00530070(slot, entry, perChar, pad);
            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        // Le tampon de commande : quatre images de memoire sur le bouton d'action.
        if (pad[0x0e] != 0) pad[0x0e]--;
        if ((*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc4)) != 0) pad[0x0e] = 4;

        if ((*slot & 0x10002) == 0)
        {
            if ((*slot & 0x40) == 0)
            {
                DispatchInputHandler(perChar[0x2b7], slot, perChar, pad);
            }

            if ((*slot & 1) == 0)
            {
                ApplyGroundMotion_0051A020(slot, entry, perChar, pad, anim);
            }
        }

        DispatchPostureHandler((byte)(perChar[0x150] & 7), slot, entry, perChar, pad, anim);

        state = *slot;
        if ((state & 4) != 0)
        {
            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        if ((state & 0x10000) == 0)
        {
            TickPlayableMember(member, s, slot, entry, slotKind, pad, perChar, state);
            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        // ---------------------------------------------------------------- le membre suivi par l'IA
        if (s[8] == (byte)Mem.s_Unknown_005de538) PassLeaderToNextEligible(slot, entry, 0);

        uint follow = Mem.Entity(0x005edec0)[*Mem.Entity(0x005f2ce4)];
        (*Mem.Entity(0x005f2ce4))++;

        if (*(ushort*)(Inp.s_SlotFlags_005e93c0 + follow * 0x9c + 0x12) != 0)
        {
            uint held = *slot;
            *(short*)(s + 0x98) = *(short*)(s + 0x32);
            *slot = (held & 0xf7fffdff) | 0x2000;
            (*(ushort*)(s + 0x12))++;
            return;
        }

        TickFollowingMember(member, s, slot, entry, slotKind, pad, perChar, mainMem, follow);
        TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
    }

    /// <summary>
    /// Ghidra: la branche <c>(*puVar3 &amp; 0x10000) == 0</c> de <see cref="TickPartyMember"/>
    /// (0x0050c396..0x0050c771) — <b>le membre que le joueur pilote</b>. Elle lit la manette et rien
    /// d'autre : coup, saut, et le tampon de quatre images qui rattrape une frappe legerement en
    /// avance.
    ///
    /// <para>
    /// Les deux moities du <c>if</c> final se ressemblent au point qu'on les croirait factorisables
    /// — meme pose de <c>0x4000</c> dans <c>+0x9a</c>, meme etat 4, meme decalage de position quand
    /// <c>+0x90</c> porte <c>0x100</c>. Elles different par une seule ligne : la premiere choisit sa
    /// portee selon le bouton tenu, la seconde la fixe a <c>0x1c000</c>. Transcrites separement,
    /// parce que ce sont deux blocs distincts du binaire et que l'oracle compare des corps.
    /// </para>
    /// </summary>
    private static void TickPlayableMember(
        int member, byte* s, uint* slot, byte* entry, byte slotKind, byte* pad, byte* perChar, uint state)
    {
        // Le coup : bouton d'attaque, pas deja en train de frapper, et le mode de mise au point
        // n'est pas en train de geler le monde.
        if ((state & 0x42) == 0
            && (*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc0)) != 0
            && (sbyte)perChar[0x2b0] != -1
            && s_Unknown_00566c84 != 0
            && (perChar[0x140] & 0x10) == 0)
        {
            *(uint*)Mem.Arena(0x005e99c0) = 0;
            TriggerEquippedItems_005238E0(slot, 1);
            *slot = (*slot & 0xfcffffff) | 2;

            *(uint*)(s + 0x18) = (perChar[0x150] & 7) == 0 && (pad[2] & 0xf0) != 0 ? 6u : 3u;
        }

        // Le tampon de saut : quatre images de memoire sur le bouton, remis a zero si le bouton
        // RELACHE arrive dans la meme image — d'ou les deux mots de manette lus, +2 et +4.
        if ((sbyte)pad[0x0c] != 0) pad[0x0c]--;
        if ((*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc2)) != 0) pad[0x0c] = 4;

        if ((*(ushort*)(perChar + 0x1fc2) & *(ushort*)(pad + 4)) != 0)
        {
            pad[0x0c] = 0;
            *(short*)(s + 0x9a) = 0x6000;
        }

        if ((*slot & 0x47) == 0)
        {
            if (pad[0x0c] == 0)
            {
                // Rien de tampon : reste le bouton de garde, qui libere une texture et un son.
                if ((*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fca)) != 0)
                {
                    Winsys3d.ReleaseTexture(0x18);
                    uint held = *slot;
                    *(uint*)(s + 0x18) = 0;
                    *slot = held | 0x9000000;
                    pad[0x0a] = 0xff;
                    Aud.PlayUiSound38();
                }

                return;
            }

            pad[0x0c] = 0;
            uint before = *slot;
            *(short*)(s + 0x9a) = 0x4000;
            *slot = (before & 0xfcffffff) | 1;

            // La portee du saut depend du bouton tenu, sauf en mode de mise au point.
            *(int*)(s + 0x54) = Mem.s_DebugModeLatch_005633a8 == 0
                ? (int)((uint)-(((*(ushort*)pad & 1) != 0) ? 1 : 0) & 0x7a000) + 0x1c000
                : 0x1c000;

            uint attributes = *(uint*)(s + 0x90);
            *(uint*)(s + 0x18) = 4;
            if ((attributes & 0x100) != 0)
            {
                *(int*)(s + 0x50) += *(short*)(entry + 0x44) * 8;
                *(int*)(s + 0x58) += *(short*)(entry + 0x48) * 8;
            }

            entry[0x0a] = 0;
        }
        else
        {
            if ((*slot & 0x46) != 0 || entry[0x0a] == 0) return;

            entry[0x0a]--;
            if ((*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc2)) == 0) return;

            entry[0x0a] = 0;
            uint before = *slot;
            *(short*)(s + 0x9a) = 0x4000;
            *(int*)(s + 0x54) = 0x1c000;
            *slot = (before & 0xfcffffff) | 1;

            uint attributes = *(uint*)(s + 0x90);
            *(uint*)(s + 0x18) = 4;
            if ((attributes & 0x100) != 0)
            {
                *(int*)(s + 0x50) += *(short*)(entry + 0x44) * 8;
                *(int*)(s + 0x58) += *(short*)(entry + 0x48) * 8;
            }
        }

        Aud.PlayPositionalSound(0, 0xd00, 0x800, (int*)(s + 0x1c));
    }

    /// <summary>
    /// Ghidra: la branche <c>else</c> de 0x0050c3c8..0x0050caf3 — <b>le membre que l'IA fait
    /// suivre</b>. Il court derriere sa cible tant qu'il en est loin, se tourne vers elle en
    /// arrivant, et sonde le terrain devant lui pour sauter ce qui doit l'etre.
    ///
    /// <para>
    /// <b>Le flot a ete reconstruit, pas translittere.</b> Ghidra en rend deux labels
    /// (<c>LAB_0050c4d6</c> et <c>LAB_0050c781</c>) sautes depuis trois endroits, ce qui donne
    /// l'impression d'un graphe irreductible. Il ne l'est pas : <b>toutes</b> les routes qui
    /// atteignent <c>LAB_0050c781</c> le font avec une distance restante nulle ou negative, et
    /// toutes celles qui atteignent le bloc de sonde le font avec une distance d'au moins 1. Les
    /// deux labels se ramenent donc a un seul <c>if (distance &gt;= 1)</c>, et le drapeau
    /// « entrer en approche » que la lecture naive suggere est inutile.
    /// </para>
    /// <para>
    /// La cible est le membre suivant dans la liste <c>DAT_005edec0</c> quand celui-ci est
    /// disponible, sinon le meneur ; la distance d'arret vaut 100 dans le premier cas et la portee
    /// de posture <see cref="s_PostureSpeed_00562cc0"/> dans le second.
    /// </para>
    /// </summary>
    private static void TickFollowingMember(
        int member, byte* s, uint* slot, byte* entry, byte slotKind,
        byte* pad, byte* perChar, byte* mainMem, uint follow)
    {
        // L'echelle de portee, choisie par les drapeaux du bloc par personnage.
        uint posture = *(uint*)(perChar + 0x140);
        int scale = 0x1000;
        if ((posture & 0x4000) != 0) scale = 0x1333;
        if ((posture & 0x8000) != 0) scale = 0xccc;
        if ((posture & 4) != 0) scale = 0x800;

        uint leaderIndex = (uint)(byte)Mem.s_Unknown_005de538;
        byte* leaderSlot = Inp.s_SlotFlags_005e93c0 + leaderIndex * 0x9c;
        byte* leaderBlock = mainMem + 0xf0000 + leaderIndex * 0x2000;

        int reach = s_PostureSpeed_00562cc0[leaderBlock[0x150] & 7] * scale >> 0xc;

        int dx = 0;
        int dz = 0;
        int distance;

        if (*(ushort*)(Inp.s_SlotFlags_005e93c0 + follow * 0x9c + 0x12) == 0
            && (leaderSlot[0] & 1) == 0)
        {
            byte* target = Inp.s_SlotFlags_005e93c0 + follow * 0x9c;
            dx = (*(int*)(target + 0x1c) - *(int*)(s + 0x1c)) >> 0xc;
            dz = (*(int*)(target + 0x24) - *(int*)(s + 0x24)) >> 0xc;
            distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz)) - 100;
        }
        else if ((*(uint*)(leaderSlot + 0x90) & 0x8000) == 0)
        {
            dx = (*(int*)(leaderSlot + 0x1c) - *(int*)(s + 0x1c)) >> 0xc;
            dz = (*(int*)(leaderSlot + 0x24) - *(int*)(s + 0x24)) >> 0xc;
            distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz)) - reach;
        }
        else
        {
            // Ghidra laisse ici dx et dz a leur valeur precedente ; ils sont pourtant relus par
            // l'appel a ratan2 ci-dessous. Conserve tel quel — c'est ce que fait l'original, qui
            // lit deux emplacements de pile non ecrits sur ce chemin.
            distance = 0;
        }

        uint held = *slot;
        if ((distance < 1 && (held & 1) == 0) || (held & 2) != 0)
        {
            if (*(short*)(s + 0x18) != 0 && (*slot & 0x47) == 0)
            {
                *(uint*)(s + 0x18) = 0;
                *slot |= 0x1000000;
            }

            *(short*)(s + 0x98) = *(short*)(s + 0x32);
        }
        else
        {
            *(short*)(s + 0x98) = (short)Winsys3d.Ordinal_457(dx, dz);

            if ((*(uint*)(leaderSlot + 0x90) & 0x8000) == 0 && (*slot & 0x40) == 0)
            {
                held = *slot;
                if ((held & 7) == 0 && *(short*)(s + 0x18) != 1)
                {
                    *(uint*)(s + 0x18) = 1;
                    *slot = held | 0x1000000;
                }

                if (distance > 0)
                {
                    *(uint*)(s + 0x5c) = (uint)Math.Min(distance, reach) << 0xc;
                }
            }
        }

        if (distance >= 1)
        {
            if ((*slot & 0x46) == 0 && entry[0x0a] != 0)
            {
                entry[0x0a]--;
                if (ProbeGroundAhead(member, s, slot, entry, perChar, mainMem)) return;
            }
        }
        else if ((*slot & 0x46) == 0)
        {
            byte* obstacle = FindNearestOpponent_00474EB0(slot, 0xffffffff, 1);
            if (obstacle != null)
            {
                int ox = (*(int*)(obstacle + 0x1c) - *(int*)(s + 0x1c)) >> 0xc;
                int oy = (*(int*)(obstacle + 0x20) - *(int*)(s + 0x20)) >> 0xc;
                int oz = (*(int*)(obstacle + 0x24) - *(int*)(s + 0x24)) >> 0xc;
                int range = (int)Winsys3d.Ordinal_442((uint)(ox * ox + oy * oy + oz * oz));

                // Ghidra passe `iStack_24` en premier argument de ratan2, un emplacement qu'aucune
                // route n'ecrit sur ce chemin. Conserve tel quel.
                uint turn = (uint)(Winsys3d.Ordinal_457(ox, oy) - *(ushort*)(s + 0x32)) & 0xfff;
                byte stance = (byte)(perChar[0x150] & 7);

                if (range < (int)((uint)-(stance != 4 ? 1 : 0) & 0xffffff06) + 400
                    && ((turn + 0x80) & 0xfff) < 0x100
                    && *(ushort*)Mem.Arena(0x005e9ae6) != 0)
                {
                    if ((perChar[0x140] & 0x10) == 0 && (sbyte)perChar[0x2b0] != -1
                        && s_Unknown_00566c84 != 0)
                    {
                        *(uint*)Mem.Arena(0x005e99c0) = 0;
                        TriggerEquippedItems_005238E0(slot, 1);
                        held = *slot;
                        short facing = *(short*)(s + 0x98);
                        *(uint*)(s + 0x18) = 3;
                        *slot = (held & 0xfcffffff) | 2;
                        *(short*)(s + 0x32) = facing;
                        return;
                    }
                }
                else if (range < (int)((uint)-(stance != 4 ? 1 : 0) & 0xfffffed4) + 500
                         && ((turn + 0x80) & 0xfff) > 0x100)
                {
                    // Un pas de 0x80 vers la cible, dans le sens le plus court.
                    *(short*)(s + 0x98) += (short)((((turn > 0x7ff ? 1 : 0) - 1) & 0x100) - 0x80);
                }
            }
        }

        *(short*)(s + 0x32) = *(short*)(s + 0x98);
    }

    /// <summary>
    /// Ghidra: 0x0050c4f0..0x0050c780 — <b>la sonde de terrain</b> que le membre suivi lance devant
    /// lui avant d'avancer. Elle recopie l'entite dans le bloc d'essai <c>DAT_005e9a40</c>, la
    /// deplace de quatre pas d'un seizieme d'unite le long de son cap, et regarde ce que
    /// <see cref="FinalizeEntityPlacement2"/> rend a chaque pas.
    ///
    /// <para>
    /// <b>L'axe de chaque pas a ete verifie au desassembleur, pas suppose</b> : Ghidra reutilise le
    /// meme emplacement de pile pour le sinus et le cosinus, si bien que la pseudo-C ajoute deux
    /// fois la meme valeur. Le binaire (0x0050c512..0x0050c57b) donne <c>sinus &lt;&lt; 4</c> sur X et
    /// <c>cosinus &lt;&lt; 4</c> sur Z — la meme convention que
    /// <see cref="TrySpawnRandomEncounter"/>.
    /// </para>
    /// <para>
    /// Deux verdicts sortent de la sonde : un obstacle franchissable (bit 1) fait sauter, un mur
    /// (bit 0x800) fait tourner. Le bloc de rotation calcule l'angle de la pente rencontree et
    /// arrondit le cap au multiple le plus proche, avec trois plages distinctes selon l'ecart.
    /// </para>
    /// </summary>
    /// <returns><c>true</c> quand la sonde a change l'etat du membre et que l'appelant doit rendre
    /// la main sans poser le cap.</returns>
    private static bool ProbeGroundAhead(
        int member, byte* s, uint* slot, byte* entry, byte* perChar, byte* mainMem)
    {
        int facing = *(short*)(s + 0x98);
        int stepX = (int)Winsys3d.GetSinTableEntry(facing) << 4;
        int stepZ = Winsys3d.GetCosTableEntry(facing) << 4;

        byte* probe = Mem.Arena(0x005e9a40);
        byte* probeEntry = Mem.Entity(0x005f7d80);

        Mem.CopyDwords(slot, (uint*)probe, 0x27);
        Mem.CopyDwords((uint*)entry, (uint*)probeEntry, 0x13);
        *(uint*)probe |= 0x2000;

        *(int*)(probe + 0x1c) = *(int*)(s + 0x1c) + stepX;
        *(int*)(probe + 0x20) = *(int*)(s + 0x60) + 0x6e000;
        *(int*)(probe + 0x24) = *(int*)(s + 0x24) + stepZ;

        uint verdict = 0;
        int ground = *(int*)(s + 0x60);

        // Ghidra: `iStack_c = DAT_005e9abc;` avant chaque placement, restaure au bloc de rotation.
        // C'est une mise de cote, pas un calcul.
        int savedAbc = *(int*)Mem.Arena(0x005e9abc);
        int hereY = *(int*)(s + 0x20);

        FinalizeEntityPlacement2((uint*)probe);
        ApplyEntityMotion_00519DF0((uint*)probe, probeEntry);

        if ((*(uint*)(probe + 0x90) & 0x800) == 0)
        {
            if ((*(uint*)(probe + 0x90) & 0x2000) != 0) verdict |= 2;

            if ((*(uint*)(probe + 0x90) & 0x8000) == 0
                && (((*(uint*)(probe + 0x90) & 0x400) != 0
                     && (perChar[0x150] & 7) != 7
                     && (*(uint*)(perChar + 0x140) & 0x400000) == 0)
                    || ground + 0x32000 <= *(int*)(probe + 0x64)
                    || *(int*)(probe + 0x64) <= ground - 0x64000
                    || ((*(uint*)(probe + 0x90) & 0x100) != 0 && ground < *(int*)(probe + 0x60))))
            {
                verdict |= 1;
            }

            bool blocked = false;
            for (int step = 3; step != 0; step--)
            {
                ground = *(int*)(probe + 0x60);
                hereY = ground;
                savedAbc = *(int*)Mem.Arena(0x005e9abc);
                *(int*)(probe + 0x1c) += stepX;
                *(int*)(probe + 0x20) = *(int*)(probe + 0x60) + 0x6e000;
                *(int*)(probe + 0x24) += stepZ;

                FinalizeEntityPlacement2((uint*)probe);
                ApplyEntityMotion_00519DF0((uint*)probe, probeEntry);

                if ((*(uint*)(probe + 0x90) & 0x800) != 0) { blocked = true; break; }

                if ((*(uint*)(probe + 0x90) & 0x8000) == 0 && ground + 0x32000 <= *(int*)(probe + 0x64))
                {
                    verdict = 1;
                }
                else if (step == 3 && (*(uint*)(probe + 0x90) & 0x2000) == 0)
                {
                    verdict &= 1;
                }
            }

            if (!blocked)
            {
                if (verdict == 0) return false;

                // Franchissable : le membre saute, exactement comme le fait la branche jouable.
                entry[0x0a] = 0;
                uint before = *slot;
                uint attributes = *(uint*)(s + 0x90);
                *(short*)(s + 0x9a) = 0x4000;
                *slot = (before & 0xfcffffff) | 1;
                *(int*)(s + 0x54) = 0x1c000;
                *(uint*)(s + 0x18) = 4;

                if ((attributes & 0x100) != 0)
                {
                    *(int*)(s + 0x50) += *(short*)(entry + 0x44) * 8;
                    *(int*)(s + 0x58) += *(short*)(entry + 0x48) * 8;
                }

                Aud.PlayPositionalSound(0, 0xd00, 0x800, (int*)(s + 0x1c));
                *(short*)(s + 0x32) = *(short*)(s + 0x98);
                return true;
            }
        }

        // Ghidra: LAB_0050dc15 — un mur. Le cap est recale sur la normale de la pente rencontree,
        // et l'arrondi depend de l'ecart : moins d'un huitieme de tour se colle, sinon on tourne
        // d'un quart de l'ecart, dans un sens ou dans l'autre.
        if (*(uint*)Mem.Arena(0x005e9ab8) != 0) return false;

        *(int*)Mem.Arena(0x005e9abc) = savedAbc;

        // Ghidra passe `&iStack_20`, c'est-a-dire l'adresse de trois locales contigues : la
        // position du membre, avec en Y la hauteur de sol relevee au dernier pas de sonde.
        int* here = stackalloc int[3];
        here[0] = *(int*)(s + 0x1c);
        here[1] = hereY;
        here[2] = *(int*)(s + 0x24);

        int wallAngle = GroundSlopeAngle_005335E0((uint*)probe, here);
        ushort probeFacing = *(ushort*)(probe + 0x32);

        int corrected = ((wallAngle - (uint)*(ushort*)(s + 0x98)) & 0xfff) < 0x800
            ? wallAngle - 0x428
            : wallAngle + 0x428;

        *(ushort*)(s + 0x98) = probeFacing;
        uint delta = (uint)(corrected - probeFacing) & 0xfff;

        short newFacing;
        if (((delta + 0x80) & 0xfff) < 0x101)
        {
            uint signed = delta > 0x7ff ? delta - 0x1000 : delta;
            newFacing = (short)(probeFacing + (short)signed);
        }
        else if (delta < 0x800)
        {
            newFacing = (short)(probeFacing + (short)((int)delta >> 2));
        }
        else
        {
            newFacing = (short)(probeFacing - (short)((int)(0x1000 - delta) >> 2));
        }

        *(short*)(s + 0x98) = newFacing;
        *(short*)(s + 0x32) = newFacing;
        return true;
    }

    // =====================================================================
    // Les lacunes de FUN_0050bf20. Toutes ses appelees manquantes sont dans `Blaze.c` — aucune ne
    // demande de desassemblage — et aucune n'a ete ecrite d'avance : c'est le jeu qui dira
    // lesquelles il emprunte, comme pour les verbes de zone et les gestionnaires d'entite.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_005238e0 @ 0x005238e0 — <b>l'evenement d'objet equipe</b> : elle balaie les cinq
    /// emplacements de <c>+0x2b0</c> et fait tourner le script <b>declenche</b> de chaque objet dont
    /// <c>item[0x84]</c> vaut <paramref name="ev"/>.
    ///
    /// <para>C'est la <b>seconde entree</b> de <see cref="RunItemScript_00523AA0"/>, et elle ne
    /// prend pas le meme script que la premiere : <c>FUN_00523a20</c> part de <c>item[0x82]</c> la
    /// ou <c>FUN_00523860</c> part de <c>item[0x80]</c>. Chaque bloc d'objet porte donc deux
    /// scripts — celui qu'on declenche en s'en servant, et celui qui reagit aux evenements.</para>
    ///
    /// <para><b>Trois protections encadrent l'appel</b>, et elles disent que ce script peut en
    /// declencher un autre :</para>
    /// <list type="bullet">
    /// <item><c>DAT_005e99c0</c> est un masque de cinq bits, un par emplacement : un objet deja
    /// entre ne se re-declenche pas. C'est l'appelant qui le remet a zero avant d'ouvrir une
    /// serie.</item>
    /// <item>la banque de variables de script (<c>0x005e9060</c>, 0x10 dwords) est empilee dans
    /// <c>0x005de170</c> au pas de 0x40, et depilee au retour.</item>
    /// <item>la cible <c>slot[0x70]</c> est empilee en parallele dans <c>0x005de2b8</c>.</item>
    /// </list>
    ///
    /// <para>La profondeur vit dans l'octet bas de <c>0x005de2b0</c> — et <b>ce compteur suit
    /// immediatement la pile qu'il indexe</b> : <c>0x005de170 + 5 * 0x40</c> vaut exactement
    /// <c>0x005de2b0</c>. Cinq places, cinq emplacements d'equipement ; la disposition de 1998 est
    /// juste au dernier octet pres, et c'est pourquoi la pile de sauvegarde et son compteur vivent
    /// dans la meme allocation ici.</para>
    ///
    /// <para>Le nom precedent, « SetEntityAnimationState », etait faux : rien dans ce corps ne
    /// touche a une animation.</para>
    /// </summary>
    private static void TriggerEquippedItems_005238E0(uint* slot, uint ev)
    {

        byte* record = GetMainMemPtr() + (((byte*)slot)[8] + 0x78) * 0x2000;

        byte* entered = Mem.Arena(0x005e99c0);
        byte* bank = Mem.Arena(0x005e9060);
        byte* saveStack = Mem.ItemMenuBytes(0x005de170);
        byte* depth = Mem.ItemMenuBytes(0x005de2b0);
        byte* targetStack = Mem.ItemMenuBytes(0x005de2b8);

        for (int i = 0; i < 5; i++)
        {
            if ((*entered & (byte)(1 << i)) != 0) continue;

            byte worn = record[0x2b0 + i];
            if (worn >= 10) continue;

            int block = worn * 0x280;
            if (*(ushort*)(record + block + 0x384) != ev) continue;

            // La premiere entree d'une serie repart d'une pile vide.
            if (*entered == 0) *depth = 0;

            Mem.CopyDwords((uint*)bank, (uint*)(saveStack + *depth * 0x40), 0x10);
            byte slotOfSave = *depth;
            (*depth)++;
            *(uint*)(targetStack + slotOfSave * 4) = *(uint*)((byte*)slot + 0x70);

            *entered |= (byte)(1 << i);

            RunTriggeredItemScript_00523A20(slot, record, record + block + 0x300);

            (*depth)--;
            Mem.CopyDwords((uint*)(saveStack + *depth * 0x40), (uint*)bank, 0x10);
            *(uint*)((byte*)slot + 0x70) = *(uint*)(targetStack + *depth * 4);
        }
    }

    /// <summary>
    /// Ghidra: FUN_00523a20 @ 0x00523a20 — le meme sas que <see cref="RunItemScriptSaved_00523860"/>
    /// autour de l'allocateur de <c>winsys3d</c>, mais sur le script <b>declenche</b> de
    /// <c>item[0x82]</c> et non sur celui de <c>item[0x80]</c>.
    ///
    /// <para>Ghidra y perd le meme parametre que dans son jumeau — sa seconde branche appelle
    /// <c>FUN_00523aa0(unaff_retaddr, param_1, param_2, …)</c>, decalee d'un cran. Trois arguments
    /// dans les deux branches.</para>
    /// </summary>
    private static void RunTriggeredItemScript_00523A20(uint* slot, byte* record, byte* item)
    {
        byte* script = item + *(ushort*)(item + 0x82);

        if (Winsys3d.Ordinal_46() < 0)
        {
            RunItemScript_00523AA0(slot, record, item, script);
            return;
        }

        *(int*)Mem.Arena(0x005e9318) = Winsys3d.Ordinal_46();
        Winsys3d.Ordinal_45(GetMainMemPtr() + 0x1c0000);
        RunItemScript_00523AA0(slot, record, item, script);
        Winsys3d.Ordinal_45((void*)(nint)(*(int*)Mem.Arena(0x005e9318)));
    }

    /// <summary>Ghidra: &amp;DAT_00564600 — <b>le nombre de sorts par école</b>, indexé par
    /// <c>personnage[0x2b5]</c>. Trois écoles seulement : la table de pointeurs
    /// <c>PTR_DAT_00564640</c> porte trois rangées puis un mot nul, et la rangée cumulée voisine
    /// (<c>DAT_00564608</c>, <c>00 1d 35 49</c>) est bien la somme courante de <c>1d 18 14</c>.
    /// Relevé verbatim dans <c>Legacy/Binaries/Blaze.exe</c>.
    ///
    /// <para>Ces comptes bornent le balayage de <see cref="TickQuickMenu_00530070"/> et l'index de
    /// bit dans <c>personnage + 0x160 + école * 8</c>, huit octets par école — soit 64 bits pour au
    /// plus 29 sorts.</para></summary>
    private static readonly byte* s_SpellCounts_00564600 = AllocBytes([
        0x1d, 0x18, 0x14, 0x01, 0x01, 0x01, 0x26, 0x00,
    ]);

    // =====================================================================
    // Le menu rapide — l'anneau au-dessus du personnage, ouvert par le bouton `+0x1fca`.
    //
    // `DrawSpeechOverlay_005309B0` le dessine ; `TickQuickMenu_00530070` le pilote. Les deux lisent
    // la meme table de disposition `s_MenuLayout_0056a850` : la categorie courante est
    // `personnage[0x2be] & 0xf`, l'entree choisie dans la categorie est `personnage[0x2bf]`, et
    // `personnage[0x2d0]` porte le nombre d'entrees que la categorie courante propose (la liste
    // elle-meme etant a `+0x2d1`).
    //
    // Le bit 0x80 de `personnage[0x2be]` distingue les deux etages : eteint on change de categorie,
    // allume on parcourt les entrees de la categorie. Le bit 0x8000000 du mot d'etat est ce qui
    // maintient l'anneau a l'ecran ; l'eteindre le ferme.
    //
    // Les quatre sons sont ceux de tout le jeu : 0x38 valider, 0x39 annuler, 0x3a deplacer,
    // 0x3b refuser (Ghidra: FUN_0053db80 / FUN_0053dba0 / FUN_0053db60 / FUN_0053dbc0, quatre
    // enveloppes d'une ligne autour de FUN_0053cea0).
    // =====================================================================

    private static void QuickMenuConfirmSound() => Aud.PlaySoundEffect(0x38, 0x400, 0x2000, 0x2000);
    private static void QuickMenuCancelSound() => Aud.PlaySoundEffect(0x39, 0x400, 0x2000, 0x2000);
    private static void QuickMenuMoveSound() => Aud.PlaySoundEffect(0x3a, 0x400, 0x2000, 0x2000);
    private static void QuickMenuRefuseSound() => Aud.PlaySoundEffect(0x3b, 0x400, 0x2000, 0x2000);

    /// <summary>
    /// Ghidra: FUN_00530070 @ 0x00530070 — <b>le menu rapide</b>, la boucle d'entree de l'anneau
    /// qu'un membre du groupe ouvre au-dessus de lui. Prise quand le mot d'etat porte
    /// <c>0x8000000</c>.
    ///
    /// <para>Elle fait trois choses dans cet ordre : ouvrir, fermer ou valider l'etage courant ;
    /// deplacer le curseur d'entree et agir sur la validation, par un aiguillage sur le genre de la
    /// categorie ; puis — c'est la queue commune, atteinte par tous les chemins — deplacer le
    /// curseur de categorie et <b>recalculer la liste d'entrees</b> que la nouvelle categorie
    /// propose.</para>
    ///
    /// <para><b>Les deux axes ne font pas la meme chose selon que le bouton d'ouverture est
    /// tenu.</b> Bouton tenu : haut/bas changent de categorie, gauche/droite changent d'entree.
    /// Bouton relache : les deux axes changent d'entree, et la categorie ne bouge que si l'anneau
    /// n'est pas encore ouvert. Le repetiteur est <c>manette[6]</c>, le mot que
    /// <see cref="Input.UpdateButtonEdges"/> remplit avec la croix et sa repetition automatique —
    /// <c>0x10</c> haut, <c>0x20</c> droite, <c>0x40</c> bas, <c>0x80</c> gauche.</para>
    ///
    /// <para><b>Le test « le curseur a-t-il bouge » du genre 6 lit un registre ecrase.</b> Ghidra
    /// rend <c>puVar11</c> comme la valeur d'avant le deplacement, puis les deux boucles de
    /// recherche l'ecrasent avec leur compteur d'essais restants ; le binaire confirme
    /// (<c>cmp ebx,edx</c> en <c>0x00530376</c>, ou <c>ebx</c> sort de <c>dec ebx</c>). Transcrit
    /// tel quel : le son de deplacement se declenche donc des qu'une recherche a tourne, meme si
    /// elle est revenue sur le meme sort. C'est le comportement de 1998.</para>
    ///
    /// <para><b>Le genre <c>-1</c> de la table est inatteignable</b> — voir
    /// <see cref="s_MenuLayout_0056a850"/>. Le binaire n'y initialise pas le masque de la queue : le
    /// <c>ja</c> non signe saute par-dessus les cinq <c>mov ebx</c>, puis le <c>jg</c> signe laisse
    /// entrer la boucle avec <c>ebx</c> = le pointeur de manette. On pose zero a la place, ce qui
    /// rend la liste vide plutot qu'aleatoire, et on le dit ici.</para>
    ///
    /// <para><b>Un seul trou</b> : le genre 5 valide fait tourner le script d'objet
    /// (<see cref="RunItemScript_00523AA0"/>), une seconde machine a opcodes de 23 gestionnaires
    /// que le depot n'a pas encore abordee. Tout le reste du menu — navigation, equipement,
    /// sorts, passage de la main — est transcrit.</para>
    ///
    /// <para>Le desassemblage complet est conserve dans
    /// <c>Legacy/Raw/Blaze/FUN_00530070.disasm.txt</c> : Ghidra s'arrete au <c>ret</c> de
    /// <c>0x00530714</c> alors que les genres 8 et 9 vivent apres lui, et trois tables de sauts
    /// (<c>0x00530948</c>, <c>0x00530970</c>, <c>0x00530998</c>) ne se lisent que la.</para>
    /// </summary>
    private static void TickQuickMenu_00530070(uint* slot, byte* entry, byte* perChar, byte* pad)
    {

        byte state = perChar[0x2be];
        int kind = (sbyte)s_SpeechIconIndex_0056a851[(state & 0xf) + (perChar[0x150] & 7) * 9];

        ushort openMask = *(ushort*)(perChar + 0x1fca);
        byte* target = pad;                    // Ghidra: puVar7 / eax, l'emplacement qu'on equipera
        bool close = false;                    // Ghidra: LAB_005304f7, atteint des deux etages

        if ((state & 0x80) == 0)
        {
            // ---------------------------------------------- l'anneau n'est pas encore ouvert
            ushort edge = *(ushort*)(pad + 2);
            ushort dismiss = (ushort)(openMask | 0x4000);

            if ((dismiss & edge) != 0)
            {
                *(ushort*)(pad + 2) = (ushort)(~dismiss & edge);
                close = true;
            }
            else if (((*(ushort*)pad & openMask) != 0 && (pad[6] & 0xa0) != 0)
                     || (edge & 0x8000) != 0)
            {
                // Le genre 5 se refuse tant que le delai d'objet du personnage court.
                if ((kind == 5 && perChar[0x207] != 0) || perChar[0x2d0] == 0)
                {
                    QuickMenuRefuseSound();
                }
                else
                {
                    perChar[0x2be] = (byte)(state | 0x80);
                    QuickMenuConfirmSound();
                }
            }
        }
        else
        {
            // ---------------------------------------------- l'anneau est ouvert sur une categorie
            ushort edge = *(ushort*)(pad + 2);

            if ((edge & openMask) != 0)
            {
                *(ushort*)(pad + 2) = (ushort)(edge & ~openMask);
                close = true;
            }
            else if (((*(ushort*)pad & openMask) != 0 && (pad[6] & 0x50) != 0)
                     || (edge & 0x4000) != 0)
            {
                perChar[0x2be] = (byte)(state & 0xf);
                QuickMenuCancelSound();
            }
            else if (perChar[0x2d0] != 0)
            {
                byte entries = perChar[0x2d0];            // Ghidra: bVar1, releve une seule fois

                // --- le curseur d'entree ; le genre 6 a son propre balayage plus bas ------------
                if (kind != 6)
                {
                    sbyte before = (sbyte)perChar[0x2bf];
                    byte repeat = pad[6];
                    byte forward;

                    if ((*(ushort*)pad & openMask) == 0)
                    {
                        if ((repeat & 0x90) != 0) perChar[0x2bf] = (byte)(before - 1);
                        forward = (byte)(pad[6] & 0x60);
                    }
                    else
                    {
                        if ((repeat & 0x80) != 0) perChar[0x2bf] = (byte)(before - 1);
                        forward = (byte)(pad[6] & 0x20);
                    }

                    if (forward != 0) perChar[0x2bf]++;
                    if (perChar[0x2bf] == 0xff) perChar[0x2bf] = (byte)(entries - 1);
                    if (perChar[0x2bf] >= entries) perChar[0x2bf] = 0;
                    if (before != (sbyte)perChar[0x2bf]) QuickMenuMoveSound();
                }

                switch (kind)
                {
                    // --- 0 a 4 : les cinq emplacements d'equipement ----------------------------
                    case 0:
                    case 1:
                    case 2:
                    case 3:
                    case 4:
                        target = perChar + 0x2b0 + kind;
                        break;

                    // --- 5 : se servir de l'objet designe --------------------------------------
                    case 5:
                    {
                        byte item = perChar[perChar[0x2bf] + 0x2d1];

                        if ((pad[3] & 0x80) != 0)
                        {
                            if ((perChar[item * 0x280 + 0x313] & 0x10) == 0
                                || s_Unknown_00566c84 == 0
                                || (*(uint*)(perChar + 0x140) & 0x400003c0) != 0)
                            {
                                QuickMenuRefuseSound();
                            }
                            else
                            {
                                UseCarriedItem_00523820(slot, item);
                                CommitStagedStatBlock(perChar);              // Ghidra: FUN_00538ab0
                                ScaleStatBlockByDifficulty(perChar + 0x100); // Ghidra: FUN_00538f50
                                ComputeDerivedStats(perChar);                // Ghidra: FUN_00538c50
                                ApplyEquipmentStatBonuses(perChar);          // Ghidra: FUN_00538e20
                                FinalizeEquipmentEffects(perChar + 0x100);   // Ghidra: FUN_00538fa0
                                QuickMenuConfirmSound();

                                perChar[0x207] = 0x28;
                                perChar[0x2be] &= 0xf;
                                *slot &= 0xf7ffffff;
                            }
                        }
                        break;
                    }

                    // --- 6 : les sorts, parcourus en sautant ceux qui ne sont pas appris --------
                    case 6:
                    {
                        byte school = perChar[0x2b5];
                        int spells = s_SpellCounts_00564600[school];
                        uint* learned = (uint*)(perChar + 0x160 + school * 8);

                        // Ghidra: puVar11 / ebx. Charge ici avec l'index d'avant, puis ecrase par
                        // le compteur d'essais de chaque recherche — voir l'en-tete.
                        int witness = perChar[0x2bf];

                        ushort held = (ushort)(*(ushort*)pad & openMask);
                        if ((held != 0 && (pad[6] & 0x80) != 0)
                            || (held == 0 && (pad[6] & 0x90) != 0))
                        {
                            int index = witness;
                            int tries = spells;
                            while (tries != 0)
                            {
                                index--;
                                if (index < 0) index = spells - 1;
                                if ((learned[index >> 5] & (1u << (index & 0x1f))) != 0) break;
                                tries--;
                            }
                            witness = tries;
                            perChar[0x2bf] = (byte)index;
                        }

                        held = (ushort)(*(ushort*)pad & openMask);
                        if ((held != 0 && (pad[6] & 0x20) != 0)
                            || (held == 0 && (pad[6] & 0x60) != 0))
                        {
                            int index = perChar[0x2bf];
                            int tries = spells;
                            while (tries != 0)
                            {
                                index = (index + 1) % spells;
                                if ((learned[index >> 5] & (1u << (index & 0x1f))) != 0) break;
                                tries--;
                            }
                            witness = tries;
                            perChar[0x2bf] = (byte)index;
                        }

                        if (witness != perChar[0x2bf]) QuickMenuMoveSound();

                        if ((pad[3] & 0x80) != 0)
                        {
                            perChar[0x2b6] = perChar[0x2bf];
                            perChar[0x2be] &= 0xf;
                            *slot &= 0xf7ffffff;
                            QuickMenuConfirmSound();
                        }
                        break;
                    }

                    // --- 7 : un choix simple, garde a +0x2b6 -----------------------------------
                    case 7:
                        if ((*(ushort*)(pad + 2) & 0x8000) != 0)
                        {
                            perChar[0x2b6] = perChar[0x2bf];
                            perChar[0x2be] &= 0xf;
                            *slot &= 0xf7ffffff;
                            QuickMenuConfirmSound();
                        }
                        break;

                    // --- 8 : trois reglages selon la tranche ou tombe l'entree ------------------
                    case 8:
                        if ((*(ushort*)(pad + 2) & 0x8000) != 0)
                        {
                            byte pick = perChar[0x2bf];
                            if (pick <= 2) perChar[0x2b7] = pick;
                            if (pick >= 3 && pick <= 4) perChar[0x2b9] = (byte)((pick - 3) ^ 1);
                            if (pick >= 5 && pick <= 6) perChar[0x2ba] = (byte)((pick - 5) ^ 1);
                            QuickMenuConfirmSound();
                        }
                        break;

                    // --- 9 : passer la main a un autre membre ----------------------------------
                    case 9:
                    {
                        ushort confirmed = *(ushort*)(pad + 2);
                        if ((confirmed & 0x8000) != 0)
                        {
                            *(ushort*)(pad + 2) = (ushort)(confirmed & 0xfff);
                            pad[0x0e] = 0;

                            byte pick = perChar[0x2bf];
                            uint* pickFlags = (uint*)(Inp.s_SlotFlags_005e93c0 + pick * 0x9c);

                            if ((byte)Mem.s_Unknown_005de538 == pick
                                || (*pickFlags & 0x50000000) != 0)
                            {
                                QuickMenuRefuseSound();
                            }
                            else
                            {
                                // Ecriture d'octet dans l'original ; les huit ecrivains du global
                                // n'y posent jamais plus de 255, donc l'affectation entiere donne
                                // la meme valeur — voir DataSymbols.md, « 0x005de538 ».
                                Mem.s_Unknown_005de538 = pick;

                                if ((*pickFlags & 0x10000) == 0)
                                {
                                    QuickMenuConfirmSound();
                                }
                                else
                                {
                                    // Le membre vise etait mene par l'IA : on lui donne la manette.
                                    byte* mainMem = GetMainMemPtr();
                                    byte leader = (byte)Mem.s_Unknown_005de538;
                                    byte* leaderBlock = mainMem + 0xf0000 + leader * 0x2000;

                                    leaderBlock[0x2d0] = (byte)s_PartySize_005e9020;
                                    leaderBlock[0x2be] = (byte)(
                                        s_MenuLayout_0056a850[(leaderBlock[0x150] & 7) * 9] - 1);
                                    leaderBlock[0x2bf] = leader;
                                    leaderBlock[0x2b8] = 0;

                                    perChar[0x2b8] = 1;
                                    perChar[0x2be] &= 0xf;

                                    // Les deux octets d'affectation de manette s'echangent entre
                                    // l'entree de ce membre et celle du nouveau meneur.
                                    byte* leaderEntry = Inp.s_PlayerSlots_005e9188 + leader * 0x4c;
                                    byte keptKind = entry[9];
                                    byte keptPad = entry[8];
                                    entry[8] = leaderEntry[0];
                                    entry[9] = leaderEntry[1];
                                    leaderEntry[0] = keptPad;
                                    leaderEntry[1] = keptKind;

                                    *(uint*)(Inp.s_SlotFlags_005e93c0 + leader * 0x9c) &= 0xfffeffff;
                                    *slot |= 0x10000;
                                    QuickMenuConfirmSound();
                                }
                            }

                            perChar[0x2be] &= 0xf;
                            *slot &= 0xf7ffffff;
                            *(uint*)(Inp.s_SlotFlags_005e93c0
                                     + (byte)Mem.s_Unknown_005de538 * 0x9c) &= 0xf7ffffff;
                        }
                        break;
                    }
                }

                // --- la validation des cinq emplacements d'equipement --------------------------
                if (kind < 5)
                {
                    byte item = perChar[perChar[0x2bf] + 0x2d1];

                    if ((pad[3] & 0x80) != 0)
                    {
                        if ((*(ushort*)(perChar + item * 0x280 + 0x312)
                             & *(ushort*)(perChar + 0x112)) == 0)
                        {
                            QuickMenuRefuseSound();
                        }
                        else
                        {
                            // Les deux mains, +0x2b3 et +0x2b4, ne peuvent pas tenir le meme objet :
                            // on refuse quand la validation viserait une main alors que l'autre le
                            // porte deja. Tout autre emplacement passe.
                            byte* left = perChar + 0x2b3;
                            byte* right = perChar + 0x2b4;

                            if ((target == left && perChar[0x2b4] != item)
                                || (target == right && perChar[0x2b3] != item)
                                || (target != left && target != right))
                            {
                                // Revalider l'objet deja en place le retire.
                                *target = *target == item ? (byte)0xff : item;

                                CommitStagedStatBlock(perChar);              // Ghidra: FUN_00538ab0
                                ScaleStatBlockByDifficulty(perChar + 0x100); // Ghidra: FUN_00538f50
                                ComputeDerivedStats(perChar);                // Ghidra: FUN_00538c50
                                ApplyEquipmentStatBonuses(perChar);          // Ghidra: FUN_00538e20
                                FinalizeEquipmentEffects(perChar + 0x100);   // Ghidra: FUN_00538fa0
                                QuickMenuConfirmSound();
                            }
                            else
                            {
                                QuickMenuRefuseSound();
                            }
                        }
                    }
                }
            }
        }

        if (close)
        {
            perChar[0x2be] &= 0xf;
            *slot &= 0xf7ffffff;
            QuickMenuCancelSound();
        }

        // ------------------------------------------------------ la queue : le curseur de categorie
        ushort menuHeld = (ushort)(*(ushort*)pad & *(ushort*)(perChar + 0x1fca));

        // On ne change de categorie que si le bouton est tenu, ou si l'anneau n'est pas ouvert.
        if (menuHeld != 0 || (perChar[0x2be] & 0x80) == 0)
        {
            byte before = perChar[0x2be];
            int beforeCategory = before & 0xf;
            byte repeat = pad[6];
            byte forward;

            if (menuHeld != 0)
            {
                if ((repeat & 0x10) != 0) perChar[0x2be] = (byte)(before - 1);
                forward = (byte)(pad[6] & 0x40);
            }
            else
            {
                if ((repeat & 0x90) != 0) perChar[0x2be] = (byte)(before - 1);
                forward = (byte)(pad[6] & 0x60);
            }

            if (forward != 0) perChar[0x2be]++;

            sbyte categories = (sbyte)s_MenuLayout_0056a850[(perChar[0x150] & 7) * 9];
            if ((perChar[0x2be] & 0xf) == 0xf) perChar[0x2be] = (byte)(categories - 1);
            if ((perChar[0x2be] & 0xf) >= categories) perChar[0x2be] = 0;

            if (beforeCategory != (perChar[0x2be] & 0xf))
            {
                QuickMenuMoveSound();

                // La nouvelle categorie repart d'un etat par defaut, propre a son genre.
                switch ((sbyte)s_SpeechIconIndex_0056a851[
                            (perChar[0x2be] & 0xf) + (perChar[0x150] & 7) * 9])
                {
                    case 0:
                    case 1:
                    case 2:
                    case 3:
                    case 4:
                    case 5:
                        perChar[0x2bf] = 0;
                        break;

                    case 6:
                        perChar[0x2d0] = 1;
                        perChar[0x2bf] = perChar[0x2b6];
                        break;

                    case 7:
                        perChar[0x2d0] = 7;
                        perChar[0x2bf] = perChar[0x2b6];
                        break;

                    case 8:
                        perChar[0x2d0] = 7;
                        perChar[0x2bf] = 0;
                        break;

                    case 9:
                        perChar[0x2d0] = (byte)s_PartySize_005e9020;
                        perChar[0x2bf] = 0;
                        break;
                }
            }
        }

        // ------------------------------------------------ la liste d'entrees de la categorie
        // Les genres 0 a 5 listent les objets portes dont le mot de type porte le bit de la
        // categorie ; les autres genres gardent la liste que le bloc ci-dessus leur a posee.
        int shown = (sbyte)s_SpeechIconIndex_0056a851[
                        (perChar[0x2be] & 0xf) + (perChar[0x150] & 7) * 9];

        uint slotBit = shown switch
        {
            0 => 0x100u,
            1 => 0x200u,
            2 => 0x400u,
            3 or 4 => 0x800u,
            5 => 0x1000u,
            _ => 0u,                            // inatteignable — voir l'en-tete
        };

        if (shown < 6)
        {
            perChar[0x2d0] = 0;

            for (int i = 0; i < 10; i++)
            {
                byte* item = perChar + 0x300 + i * 0x280;
                if (item[0] == 0 || (*(ushort*)(item + 0x12) & slotBit) == 0) continue;

                perChar[0x2d1 + perChar[0x2d0]] = (byte)i;
                perChar[0x2d0]++;
            }
        }
    }

    /// <summary>
    /// Ghidra: FUN_00523820 @ 0x00523820 — <b>se servir d'un objet porte</b>. Elle retrouve le bloc
    /// du personnage a partir de l'index range en <c>emplacement[8]</c>, puis lance le script de
    /// l'objet <paramref name="item"/> par <c>FUN_00523860</c>.
    ///
    /// <para>Le garde <c>item &lt; 10</c> est celui de l'original : dix objets portes au plus, et
    /// un index hors borne ne fait rien du tout.</para>
    /// </summary>
    private static void UseCarriedItem_00523820(uint* slot, uint item)
    {
        if (item >= 10) return;

        byte* record = GetMainMemPtr() + (((byte*)slot)[8] + 0x78) * 0x2000;
        RunItemScriptSaved_00523860(slot, record, record + item * 0x280 + 0x300);
    }

    /// <summary>
    /// Ghidra: FUN_00523860 @ 0x00523860 — le meme sas que <see cref="RunEntityScript"/> : bascule
    /// l'allocateur de <c>winsys3d</c> sur le tampon de travail le temps du script d'objet, si tant
    /// est qu'il y ait un etat a preserver.
    ///
    /// <para><b>Ghidra perd un parametre dans la seconde branche</b> — elle y appelle
    /// <c>FUN_00523aa0(unaff_retaddr, param_1, param_2, …)</c>, decale d'un cran, et prend le mot
    /// de retour pour un argument. Les deux branches passent les memes trois arguments ; c'est la
    /// forme retenue ici, et <c>FUN_00539190</c> porte le meme defaut sur le meme squelette.</para>
    /// </summary>
    private static void RunItemScriptSaved_00523860(uint* slot, byte* record, byte* item)
    {
        byte* script = item + *(ushort*)(item + 0x80);

        if (Winsys3d.Ordinal_46() < 0)
        {
            RunItemScript_00523AA0(slot, record, item, script);
            return;
        }

        *(int*)Mem.Arena(0x005e9318) = Winsys3d.Ordinal_46();
        Winsys3d.Ordinal_45(GetMainMemPtr() + 0x1c0000);
        RunItemScript_00523AA0(slot, record, item, script);
        Winsys3d.Ordinal_45((void*)(nint)(*(int*)Mem.Arena(0x005e9318)));
    }

    // =====================================================================
    // La machine a opcodes des objets (Ghidra: FUN_00523aa0 et la table PTR_LAB_00564f80).
    //
    // C'est la SECONDE machine a opcodes du jeu. Sa boucle est celle de `RunScript` a la ligne
    // pres — arret sur 0xff, ou des qu'un gestionnaire pose un resultat, sauf l'opcode 2 qui est
    // la branche — mais sa table est autre : 23 opcodes, 22 corps distincts (12 et 19 partagent le
    // meme), de 0x00523b00 a 0x00524170.
    //
    // **Onze de ces vingt-deux corps sont absents de `Blaze.c`.** Ghidra ne les a vus que pris en
    // adresse dans la table, d'ou le prefixe `PTR_LAB_`. Ils sont transcrits depuis le
    // desassemblage, conserve dans `Legacy/Raw/Blaze/FUN_00523aa0-handlers.disasm.txt`.
    //
    // Les quatre arguments que chaque gestionnaire recoit, etablis en croisant les corps decompiles
    // avec les decalages de pile des autres :
    //
    //   slot    l'enregistrement d'entite de 0x9c octets de celui qui se sert de l'objet ;
    //           `slot[0x70]` designe sa cible, ce que les opcodes 16 et 17 posent
    //   record  son bloc par personnage de 0x2000 octets (statistiques, equipement, inventaire)
    //   item    le bloc de 0x280 octets de l'objet employe, dans `record + 0x300 + n * 0x280`
    //   s       le curseur de script, qui vit DANS le bloc d'objet — d'ou les sauts des opcodes
    //           1 et 2, qui sont relatifs a `item` et non a `s`
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_00523aa0 @ 0x00523aa0 — <b>la machine a opcodes des objets</b>. Jumelle exacte
    /// de <see cref="RunScript"/> : elle s'arrete sur <c>0xff</c>, et aussi des qu'un gestionnaire
    /// pose un resultat non nul — <b>sauf pour l'opcode 2</b>, le seul a continuer malgre un
    /// resultat pose. C'est le mecanisme de condition : un test rend 1, la boucle s'arreterait, et
    /// l'opcode 2 est la branche qui reprend la main.
    /// </summary>
    private static void RunItemScript_00523AA0(uint* slot, byte* record, byte* item, byte* script)
    {
        NoteItemUsed(item);          // ECHAFAUDAGE : hors du binaire, voir la sonde plus bas.

        uint condition = 0;                              // Ghidra: local_4

        for (uint op = *script; op != 0xff && (op == 2 || condition == 0); op = *script)
        {
            script = DispatchItemOp(op, slot, record, item, script, &condition);
        }
    }

    // =====================================================================
    // ECHAFAUDAGE — LA SONDE D'OBJETS (2026-08-30)
    //
    // Jumelle de NoteHandlerSeen, sur l'autre bout du meme chantier. Celle-la dit quel gestionnaire
    // d'entite a tourne ; celle-ci dit quel OBJET a ete employe. Les deux sont necessaires parce
    // qu'elles ne repondent pas a la meme question : un gestionnaire exerce prouve qu'un corps
    // tourne, un objet exerce prouve qu'un objet ENTIER se comporte bien de bout en bout.
    //
    // LA CLE EST L'HEXA DES SEIZE PREMIERS OCTETS DE LA FICHE, pas le nom lisible. La premiere
    // version relevait le nom court decode, et c'etait une faute : les noms d'objet ne sont pas de
    // l'ASCII — le jeu a son propre jeu de caracteres —, si bien que la moitie du releve sortait en
    // mojibake et que le tri n'avait plus de sens. L'hexa n'a aucun de ces problemes : il est
    // exact, stable, et `census-item-effects.sh` le recalcule a l'identique depuis la colonne
    // `octets` d'objets.csv pour retrouver le nom deja decode. La cle est technique, l'affichage
    // est lisible, et les deux ne se melangent pas.
    //
    // Releve dans Documentation/Etat/objets-exerces.tsv, meme forme et memes garanties que son
    // ainee : union avec l'existant, ecriture immediate, suivi par git. OPENFORESIA_NO_PROBE=1
    // desarme les deux.
    // =====================================================================

    private static readonly SortedSet<string> s_ItemsSeen = new(StringComparer.Ordinal);

    private static SortedSet<string> s_ItemProbeAll;

    private static string ItemProbePath => System.IO.Path.GetFullPath(System.IO.Path.Combine(
        AppContext.BaseDirectory, "..", "..", "..", "..",
        "Documentation", "Etat", "objets-exerces.tsv"));

    /// <summary>
    /// Note qu'un objet vient d'etre employe. Appelee sur les deux scripts — l'emploi et le
    /// declenchement — puisque tous deux passent par
    /// <see cref="RunItemScript_00523AA0"/>.
    /// </summary>
    private static void NoteItemUsed(byte* item)
    {
        if (!s_ProbeEnabled || item == null) return;

        string key = ItemKey(item);

        string line = $"{key}\t{Res.s_Unknown_005de528 & 0xff}\t{s_Unknown_005de52c}";

        if (!s_ItemsSeen.Add(line)) return;

        LoadItemProbe();
        if (!s_ItemProbeAll.Add(line)) return;

        WriteItemProbe();

        Console.Error.WriteLine(
            $"[SONDE OBJET] nouveau : {key} zone={Res.s_Unknown_005de528 & 0xff} " +
            $"sous-zone={s_Unknown_005de52c} ({s_ItemProbeAll.Count} couples connus)");
    }

    /// <summary>
    /// La <b>cle</b> d'une fiche d'objet : ses seize premiers octets en hexadecimal. C'est le champ
    /// du nom court, mais pris <b>brut</b> — voir l'en-tete de section pour pourquoi il ne faut pas
    /// le decoder ici.
    /// </summary>
    private static string ItemKey(byte* item)
    {
        var text = new System.Text.StringBuilder(0x20);
        for (int i = 0; i < 0x10; i++) text.Append(item[i].ToString("x2"));
        return text.ToString();
    }

    private static void LoadItemProbe()
    {
        if (s_ItemProbeAll != null) return;

        s_ItemProbeAll = new SortedSet<string>(StringComparer.Ordinal);

        try
        {
            if (System.IO.File.Exists(ItemProbePath))
            {
                foreach (string line in System.IO.File.ReadAllLines(ItemProbePath))
                {
                    if (line.Length != 0 && line[0] != '#') s_ItemProbeAll.Add(line);
                }
            }
        }
        catch (Exception error)
        {
            Console.Error.WriteLine($"[SONDE OBJET] fichier non relu : {error.Message}");
        }
    }

    private static void WriteItemProbe()
    {
        try
        {
            var text = new System.Text.StringBuilder();
            text.AppendLine("# Les objets REELLEMENT employes en jeu, une ligne par couple");
            text.AppendLine("# (cle de fiche, zone, sous-zone). La CLE est l hexa des seize premiers");
            text.AppendLine("# octets de la fiche — le champ du nom court, pris brut : les noms ne sont");
            text.AppendLine("# pas de l ASCII. census-item-effects.sh la recalcule depuis objets.csv");
            text.AppendLine("# pour retrouver le nom lisible. Ecrit par la sonde de");
            text.AppendLine("# Screens/State03/WorldMapTick.cs des qu'un couple est nouveau, en");
            text.AppendLine("# UNION avec ce que le fichier portait deja. Ne pas editer a la main :");
            text.AppendLine("# il se lit comme une preuve accumulee, pas comme une intention.");
            text.AppendLine("#");
            text.AppendLine("# cle\tzone\tsous-zone");
            foreach (string line in s_ItemProbeAll) text.AppendLine(line);

            // UTF8Encoding(false) et non Encoding.UTF8 : celui-ci pose un BOM, et un BOM en tete
            // fait que la premiere ligne ne commence plus par '#'. Tout lecteur qui filtre les
            // commentaires par `^#` prend alors l'en-tete pour une donnee — c'est arrive.
            System.IO.File.WriteAllText(
                ItemProbePath, text.ToString(), new System.Text.UTF8Encoding(false));
        }
        catch (Exception error)
        {
            Console.Error.WriteLine($"[SONDE OBJET] releve non ecrit : {error.Message}");
        }
    }

    // =====================================================================
    // ECHAFAUDAGE — LA SONDE DE SORTS (2026-08-31)
    //
    // La troisieme du meme chantier, apres NoteHandlerSeen (quel gestionnaire a tourne) et
    // NoteItemUsed (quel objet a ete employe). Celle-ci dit quelle FICHE DE SORT est partie.
    //
    // LA CLE EST LA PAIRE FAMILLE/INDICE, pas le nom : c'est exactement ce que
    // CastSpell_0053A980 recoit, et c'est ce qui adresse la fiche dans la table +0x9c du
    // repertoire d'etat. Les noms, eux, vivent sur le CD, et `census-spells.sh` les retrouve dans
    // Documentation/Reference/Bestiaire/sorts.csv a partir de la meme paire. La cle est technique,
    // l'affichage est lisible, et les deux ne se melangent pas — meme partage que pour les objets.
    //
    // ELLE NE DISTINGUE PAS LE LANCEUR, et c'est voulu. L'incantation d'un personnage, l'opcode 14
    // d'un script d'objet et le mot +0x06 d'une entite de scene entrent tous les trois par
    // CastSpell_0053A980 : ce qu'on veut savoir est si LA FICHE a ete exercee, pas par quel chemin.
    //
    // Releve dans Documentation/Etat/sorts-exerces.tsv, memes garanties que ses deux ainees :
    // union avec l'existant, ecriture immediate (une exception non rattrapee ne leve pas
    // ProcessExit, et c'est precisement le cas interessant), suivi par git. OPENFORESIA_NO_PROBE=1
    // desarme les trois.
    // =====================================================================

    private static readonly SortedSet<string> s_SpellsSeen = new(StringComparer.Ordinal);

    private static SortedSet<string> s_SpellProbeAll;

    private static string SpellProbePath => System.IO.Path.GetFullPath(System.IO.Path.Combine(
        AppContext.BaseDirectory, "..", "..", "..", "..",
        "Documentation", "Etat", "sorts-exerces.tsv"));

    /// <summary>
    /// Note qu'une fiche de sort vient d'etre declenchee, avec le lieu ou elle l'a ete.
    /// </summary>
    private static void NoteSpellCast(int family, int index)
    {
        if (!s_ProbeEnabled) return;

        string line = $"{family}\t{index}\t{Res.s_Unknown_005de528 & 0xff}\t{s_Unknown_005de52c}";

        if (!s_SpellsSeen.Add(line)) return;

        LoadSpellProbe();
        if (!s_SpellProbeAll.Add(line)) return;

        WriteSpellProbe();

        Console.Error.WriteLine(
            $"[SONDE SORT] nouveau : famille {family} indice {index} " +
            $"zone={Res.s_Unknown_005de528 & 0xff} sous-zone={s_Unknown_005de52c} " +
            $"({s_SpellProbeAll.Count} couples connus)");
    }

    private static void LoadSpellProbe()
    {
        if (s_SpellProbeAll != null) return;

        s_SpellProbeAll = new SortedSet<string>(StringComparer.Ordinal);

        try
        {
            if (System.IO.File.Exists(SpellProbePath))
            {
                foreach (string line in System.IO.File.ReadAllLines(SpellProbePath))
                {
                    if (line.Length != 0 && line[0] != '#') s_SpellProbeAll.Add(line);
                }
            }
        }
        catch (Exception error)
        {
            Console.Error.WriteLine($"[SONDE SORT] fichier non relu : {error.Message}");
        }
    }

    private static void WriteSpellProbe()
    {
        try
        {
            var text = new System.Text.StringBuilder();
            text.AppendLine("# Les fiches de sort REELLEMENT declenchees en jeu, une ligne par");
            text.AppendLine("# couple (famille, indice, zone, sous-zone). La paire famille/indice est");
            text.AppendLine("# ce que CastSpell_0053A980 recoit ; census-spells.sh retrouve le nom");
            text.AppendLine("# lisible dans Bestiaire/sorts.csv a partir d'elle. Le lanceur n'est pas");
            text.AppendLine("# releve : une incantation, un script d'objet et une entite de scene");
            text.AppendLine("# entrent par la meme fonction, et c'est la FICHE qu'on verifie.");
            text.AppendLine("# Ecrit par la sonde de Screens/State03/WorldMapTick.cs des qu'un couple");
            text.AppendLine("# est nouveau, en UNION avec ce que le fichier portait deja. Ne pas");
            text.AppendLine("# editer a la main : il se lit comme une preuve accumulee, pas comme une");
            text.AppendLine("# intention.");
            text.AppendLine("#");
            text.AppendLine("# famille\tindice\tzone\tsous-zone");
            foreach (string line in s_SpellProbeAll) text.AppendLine(line);

            // UTF8Encoding(false) et non Encoding.UTF8 : celui-ci pose un BOM, et un BOM en tete
            // fait que la premiere ligne ne commence plus par '#'. Tout lecteur qui filtre les
            // commentaires par `^#` prend alors l'en-tete pour une donnee — c'est arrive.
            System.IO.File.WriteAllText(
                SpellProbePath, text.ToString(), new System.Text.UTF8Encoding(false));
        }
        catch (Exception error)
        {
            Console.Error.WriteLine($"[SONDE SORT] releve non ecrit : {error.Message}");
        }
    }

    /// <summary>
    /// Ghidra: <c>(*(code *)(&amp;PTR_LAB_00564f80)[opcode])(…)</c> — les 23 gestionnaires.
    ///
    /// <para>Rendue en <c>switch</c> comme <see cref="DispatchScriptOp"/>, et pour la meme raison :
    /// c'est une table de sauts dans l'original, et <c>Strategy.md</c> demande de reconstruire le
    /// flot. L'etendue est <b>deduite</b> : le dword qui suit l'entree 22 est nul.</para>
    ///
    /// <para><b>Un opcode inconnu n'est pas garde dans l'original</b> — il saute dans la table sans
    /// borne, donc au-dela de 22 il lit un pointeur quelconque. Le rendre bruyant ici vaut mieux
    /// qu'un saut dans le vide : c'est le seul endroit ou la transcription s'ecarte, et elle
    /// s'ecarte vers un plantage nomme.</para>
    /// </summary>
    private static byte* DispatchItemOp(
        uint op, uint* slot, byte* record, byte* item, byte* s, uint* result)
        => op switch
        {
            0 => ItemOpConsume(record, item, s),                          // 0x00523b00
            1 => ItemOpJump(item, s),                                     // 0x00523bb0
            2 => ItemOpJumpIf(item, s, result),                           // 0x00523bd0
            3 => ItemOpAluSelf(slot, s, result),                          // 0x00523c00
            4 => ItemOpAluTarget(slot, s, result),                        // 0x00523c30
            5 => ItemOpAluRecord(record, 0x100, s, result),               // 0x00523c70
            6 => ItemOpAluTargetStats(slot, 0, s, result),                // 0x00523cb0
            7 => ItemOpAluRecord(record, 0x200, s, result),               // 0x00523d20
            8 => ItemOpAluTargetStats(slot, 0x100, s, result),            // 0x00523d60
            9 => ItemOpSpawnSelf(slot, s),                                // 0x00523dd0
            10 => ItemOpSpawnTarget(slot, s),                             // 0x00523e10
            11 => ItemOpAluBank(s, result),                               // 0x00523e50
            12 => ItemOpParticleSelf(slot, s),                            // 0x00524060
            13 => ItemOpAluEquipped(record, s, result),                   // 0x00523e80
            14 => ItemOpCast(slot, s),                                    // 0x00523ed0
            15 => ItemOpRefuseSound(s),                                   // 0x00523f00
            16 => ItemOpPickTargetByIndex(slot, s, result),               // 0x00523f10
            17 => ItemOpPickTargetBySearch(slot, s, result),              // 0x00523f80
            18 => ItemOpApplyEffect(slot, item, s, result),               // 0x00523fc0
            19 => ItemOpParticleSelf(slot, s),                            // 0x00524060, le meme
            20 => ItemOpParticleTarget(slot, s),                          // 0x005240d0
            21 => ItemOpSound(s),                                         // 0x00524140
            22 => ItemOpOpenItemMenu(s),                                  // 0x00524170
            _ => throw new NotImplementedException(
                     $"Script d'objet : opcode {op} hors des 23 de PTR_LAB_00564f80. "
                     + "L'original saute dans la table sans borne ; ici on le dit."),
        };

    /// <summary>Ghidra: LAB_00523b00 — <b>consommer l'objet</b>, avec une chance sur cent de
    /// <c>s[1]</c>.
    ///
    /// <para>Le tirage rate ne fait rien du tout. Reussi, il decremente le compte de l'objet
    /// (<c>item[0x10]</c>, un mot) et, <b>seulement si ce compte tombe pile a zero</b>, vide
    /// l'emplacement puis reconstruit deux choses : la liste d'inventaire de <c>record[0x2c0]</c> /
    /// <c>+0x2c1</c>, et les cinq emplacements d'equipement de <c>+0x2b0</c>, dont celui qui
    /// designait l'objet retire repasse a <c>0xff</c>.</para>
    ///
    /// <para>La liste de <c>+0x2c0</c> n'est pas celle du menu rapide (<c>+0x2d0</c>/<c>+0x2d1</c>,
    /// voir <see cref="TickQuickMenu_00530070"/>) : celle-ci recense tous les objets portes, celle-la
    /// ceux d'une categorie.</para>
    ///
    /// <para>Un compte deja nul retombe a <c>0xffff</c> et l'objet survit : c'est ce que fait
    /// l'original, le test porte sur l'egalite a zero et non sur le signe.</para></summary>
    private static byte* ItemOpConsume(byte* record, byte* item, byte* s)
    {
        if (CrtRand() % 100 >= s[1]) return s + 2;        // Ghidra: FUN_00547140

        if (--*(ushort*)(item + 0x10) != 0) return s + 2;

        item[0] = 0;
        record[0x2c0] = 0;

        for (int i = 0; i < 10; i++)
        {
            byte* candidate = record + 0x300 + i * 0x280;

            if (candidate[0] != 0)
            {
                record[0x2c1 + record[0x2c0]] = (byte)i;
                record[0x2c0]++;
                continue;
            }

            // L'emplacement vide qu'on vient de liberer, et lui seul, deshabille le personnage.
            if (candidate != item) continue;

            byte* worn = record + 0x2b0;
            for (int k = 5; k != 0; k--, worn++)
            {
                if (*worn == i) { *worn = 0xff; break; }
            }
        }

        return s + 2;
    }

    /// <summary>Ghidra: LAB_00523bb0 — le saut. La destination est un decalage de <b>seize bits</b>
    /// depuis le debut du <b>bloc d'objet</b>, pas depuis le curseur : le script vit dans ce bloc,
    /// donc c'est bien lui la base.</summary>
    private static byte* ItemOpJump(byte* item, byte* s) => item + (s[1] | (s[2] << 8));

    /// <summary>Ghidra: LAB_00523bd0 — le saut conditionnel, et <b>le seul opcode que la boucle
    /// laisse passer quand un resultat est pose</b>. Il saute si la condition est non nulle, et la
    /// remet a zero du meme geste ; sinon il avance de trois.</summary>
    private static byte* ItemOpJumpIf(byte* item, byte* s, uint* result)
    {
        if (*result == 0) return s + 3;

        byte* destination = item + (s[1] | (s[2] << 8));
        *result = 0;
        return destination;
    }

    /// <summary>Ghidra: FUN_00523c00 — l'unite arithmetique sur <b>l'enregistrement d'entite</b> de
    /// celui qui se sert de l'objet.</summary>
    private static byte* ItemOpAluSelf(uint* slot, byte* s, uint* result)
    {
        *result = ApplyScriptOp((byte*)slot + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523c30 — la meme, sur l'enregistrement de <b>la cible</b>
    /// (<c>slot[0x70]</c>).</summary>
    private static byte* ItemOpAluTarget(uint* slot, byte* s, uint* result)
    {
        byte* target = *(byte**)((byte*)slot + 0x70);
        *result = ApplyScriptOp(target + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523c70 (<paramref name="bank"/> = 0x100) et FUN_00523d20
    /// (0x200) — l'unite arithmetique sur l'une des deux banques du <b>bloc par personnage</b>.
    /// Deux corps identiques a la constante pres dans l'original.</summary>
    private static byte* ItemOpAluRecord(byte* record, int bank, byte* s, uint* result)
    {
        *result = ApplyScriptOp(record + bank + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: LAB_00523cb0 (<paramref name="bank"/> = 0) et LAB_00523d60 (0x100) —
    /// l'unite arithmetique sur le <b>bloc de statistiques de la cible</b>.
    ///
    /// <para>La resolution du bloc est celle de <see cref="StatusBubbleHeight_00538BC0"/>, et elle
    /// depend du bit <c>0x800000</c> : un membre du groupe passe par <c>MainMem + 0xf0100</c>, toute
    /// autre entite par <see cref="s_EntityStatBlocks_005ea560"/>. Passer par une vue d'arene ici
    /// serait le defaut d'aliasing deja resolu une fois pour cette table.</para></summary>
    private static byte* ItemOpAluTargetStats(uint* slot, int bank, byte* s, uint* result)
    {
        byte* target = *(byte**)((byte*)slot + 0x70);

        byte* stats = (*(uint*)target & 0x800000) != 0
            ? GetMainMemPtr() + 0xf0100 + target[8] * 0x2000
            : s_EntityStatBlocks_005ea560 + target[8] * 0x120;

        *result = ApplyScriptOp(stats + bank + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523dd0 — <b>engendre un effet sur soi</b>. Le mot de <c>+0x0a</c> est
    /// mis a zero le temps de l'appel puis restaure : c'est ce qui empeche l'effet d'heriter du
    /// compteur de son parent.</summary>
    private static byte* ItemOpSpawnSelf(uint* slot, byte* s)
    {
        byte* e = (byte*)slot;
        ushort kept = *(ushort*)(e + 0x0a);
        *(ushort*)(e + 0x0a) = 0;
        SpawnEffectEntity(e, s[1], s[2], s[3]);          // Ghidra: FUN_0047a9d0
        *(ushort*)(e + 0x0a) = kept;
        return s + 4;
    }

    /// <summary>Ghidra: LAB_00523e10 — la meme, sur <b>la cible</b>.</summary>
    private static byte* ItemOpSpawnTarget(uint* slot, byte* s)
    {
        byte* target = *(byte**)((byte*)slot + 0x70);
        ushort kept = *(ushort*)(target + 0x0a);
        *(ushort*)(target + 0x0a) = 0;
        SpawnEffectEntity(target, s[1], s[2], s[3]);     // Ghidra: FUN_0047a9d0
        *(ushort*)(target + 0x0a) = kept;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523e50 — l'unite arithmetique sur <b>la banque de variables de
    /// script</b>, celle que les deux machines partagent.</summary>
    private static byte* ItemOpAluBank(byte* s, uint* result)
    {
        *result = ApplyScriptOp(Mem.Arena(0x005e9060) + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523e80 — l'unite arithmetique sur le bloc de <b>l'objet equipe</b> a
    /// l'emplacement <c>s[1]</c> : <c>record[0x2b0 + s[1]]</c> donne l'indice, et le bloc suit a
    /// <c>record + 0x300 + indice * 0x280</c>. Cinq octets d'opcode, seul de son espece.</summary>
    private static byte* ItemOpAluEquipped(byte* record, byte* s, uint* result)
    {
        byte* equipped = record + 0x300 + record[0x2b0 + s[1]] * 0x280;
        *result = ApplyScriptOp(equipped + s[2], s[3], s[4]) ? 1u : 0u;
        return s + 5;
    }

    /// <summary>Ghidra: FUN_00523ed0 — <b>declenche un sort ou un effet d'objet</b> par
    /// <see cref="CastSpell_0053A980"/>. Les quatre octets de script sont pousses en <b>zero</b>
    /// extension (<c>xor</c> puis <c>mov al</c> dans le binaire), donc les deux tests de signe de
    /// l'appelee ne peuvent pas se declencher par ce chemin — ils servent a ses autres
    /// appelants.</summary>
    private static byte* ItemOpCast(uint* slot, byte* s)
    {
        CastSpell_0053A980(slot, s[1], s[2], s[3], s[4]);
        return s + 5;
    }

    /// <summary>Ghidra: LAB_00523f00 — le son de refus, et rien d'autre. Un octet
    /// d'opcode.</summary>
    private static byte* ItemOpRefuseSound(byte* s)
    {
        QuickMenuRefuseSound();                          // Ghidra: FUN_0053dbc0
        return s + 1;
    }

    /// <summary>Ghidra: LAB_00523f10 — <b>choisit la cible par son indice</b>, pris dans la banque
    /// de variables a <c>s[2]</c> et non dans le script : c'est donc une cible calculee.
    ///
    /// <para><c>s[1]</c> choisit la famille : zero les quatre emplacements de groupe
    /// (<see cref="Input.s_SlotFlags_005e93c0"/>), non nul les trente-deux entites de scene
    /// (<c>0x005ecaa0</c>). Les deux tables ont le meme pas de <c>0x9c</c>. Un indice hors borne
    /// <b>pose la condition a 1</b> et laisse la cible inchangee — c'est le seul opcode de choix
    /// qui signale son echec.</para></summary>
    private static byte* ItemOpPickTargetByIndex(uint* slot, byte* s, uint* result)
    {
        uint index = Mem.Arena(0x005e9060)[s[2]];

        if (s[1] != 0)
        {
            if (index >= 0x20) { *result = 1; return s + 3; }
            *(byte**)((byte*)slot + 0x70) = Mem.Entity(0x005ecaa0) + index * 0x9c;
        }
        else
        {
            if (index >= 4) { *result = 1; return s + 3; }
            *(byte**)((byte*)slot + 0x70) = Inp.s_SlotFlags_005e93c0 + index * 0x9c;
        }

        return s + 3;
    }

    /// <summary>Ghidra: LAB_00523f80 — <b>choisit la cible par recherche</b>.
    ///
    /// <para>Le tour de passe-passe est dans les trois champs sauves : <c>+0x74</c> est pointe sur
    /// l'entite elle-meme le temps de l'appel, parce que <c>FUN_00474ad0</c> cherche depuis
    /// <c>[+0x74]</c> et non depuis son argument ; puis le resultat, que la recherche a range en
    /// <c>+0x78</c>, est recopie en <c>+0x70</c>, et <c>+0x74</c> comme <c>+0x78</c> sont
    /// restaures. La cible du script est donc <b>ce que la recherche a trouve</b>, sans que rien
    /// d'autre de l'entite ne bouge.</para></summary>
    private static byte* ItemOpPickTargetBySearch(uint* slot, byte* s, uint* result)
    {
        byte* e = (byte*)slot;

        byte* keptWatched = *(byte**)(e + 0x74);
        byte* keptFound = *(byte**)(e + 0x78);

        *(byte**)(e + 0x74) = e;
        *result = PickTargetBySearch_00474AD0(slot, s[1]);

        byte* found = *(byte**)(e + 0x78);
        *(byte**)(e + 0x74) = keptWatched;
        *(byte**)(e + 0x70) = found;
        *(byte**)(e + 0x78) = keptFound;

        return s + 2;
    }

    /// <summary>Ghidra: &amp;DAT_0052403c — <b>la famille de l'objet</b>, indexee par le mot de
    /// <c>item[0x84]</c> (0 a 0x15). Relevee verbatim. Elle ne sert qu'a choisir, par la table de
    /// sauts de <c>0x00524014</c>, entre les deux seules valeurs que l'opcode 18 passe en troisieme
    /// argument : <b>0 ou 1</b>. Les familles 1, 3, 5 et 7 donnent 1, les autres 0.</summary>
    private static readonly byte[] s_ItemFamily_0052403c =
    [
        0x00, 0x00, 0x01, 0x01, 0x01, 0x02, 0x02, 0x03, 0x03, 0x03, 0x03,
        0x04, 0x05, 0x05, 0x05, 0x06, 0x06, 0x07, 0x07, 0x07, 0x07, 0x08,
    ];

    /// <summary>Ghidra: LAB_00523fc0 — <b>applique un effet</b> de la table de 48 fonctions de
    /// <c>0x0056d4e0</c>, choisi par <c>s[1]</c>.
    ///
    /// <para>Le troisieme argument vaut 1 pour les familles impaires 1, 3, 5 et 7 de
    /// <see cref="s_ItemFamily_0052403c"/>, et 0 partout ailleurs — <b>y compris</b> quand
    /// <c>item[0x84]</c> depasse 0x15, ou le binaire saute directement a la branche zero. Le detour
    /// par une table de sauts a neuf entrees dont sept sont des doublons est ce que le compilateur
    /// a fait d'un <c>switch</c> ; le resultat tient en une comparaison.</para></summary>
    private static byte* ItemOpApplyEffect(uint* slot, byte* item, byte* s, uint* result)
    {
        ushort kind = *(ushort*)(item + 0x84);

        uint flag = 0;
        if (kind <= 0x15)
        {
            byte family = s_ItemFamily_0052403c[kind];
            flag = family == 1 || family == 3 || family == 5 || family == 7 ? 1u : 0u;
        }

        byte* target = *(byte**)((byte*)slot + 0x70);
        *result = ApplyItemEffect_0056D4E0(s[1], slot, target, flag);
        return s + 2;
    }

    /// <summary>Ghidra: FUN_00524060 (opcodes 12 et 19, le meme corps) — <b>pose une particule</b>
    /// a la position de celui qui se sert de l'objet.
    ///
    /// <para><c>s[1]</c> dit la largeur avec laquelle lire la banque de variables a <c>s[2]</c> :
    /// 0 octet, 1 mot, 2 double mot. <b>Toute autre valeur passe le curseur de script lui-meme</b>
    /// comme parametre — le registre n'est pas initialise dans cette branche, et Ghidra le rend
    /// exactement ainsi (<c>uVar2 = param_4</c>). Transcrit tel quel.</para></summary>
    private static byte* ItemOpParticleSelf(uint* slot, byte* s)
    {
        SpawnParticle_0050F070((uint*)((byte*)slot + 0x1c), ScriptBankValue(s), s[3]);
        return s + 4;
    }

    /// <summary>Ghidra: FUN_005240d0 (opcode 20) — la meme, a la position de <b>la cible</b>.</summary>
    private static byte* ItemOpParticleTarget(uint* slot, byte* s)
    {
        byte* target = *(byte**)((byte*)slot + 0x70);
        SpawnParticle_0050F070((uint*)(target + 0x1c), ScriptBankValue(s), s[3]);
        return s + 4;
    }

    /// <summary>La lecture de banque commune aux opcodes 12, 19 et 20 — voir
    /// <see cref="ItemOpParticleSelf"/> pour la quatrieme branche, celle qui n'initialise
    /// rien.</summary>
    private static uint ScriptBankValue(byte* s)
    {
        byte* bank = Mem.Arena(0x005e9060);

        return s[1] switch
        {
            0 => bank[s[2]],
            1 => *(ushort*)(bank + s[2]),
            2 => *(uint*)(bank + s[2]),
            _ => (uint)(nuint)s,
        };
    }

    /// <summary>Ghidra: FUN_00524140 — <b>joue un son</b>. Le meme mot sert de gain gauche et de
    /// gain droit : l'original lit deux fois <c>s+4</c>, ce n'est pas une coquille de
    /// transcription.</summary>
    private static byte* ItemOpSound(byte* s)
    {
        Aud.PlaySoundEffect(s[1], *(ushort*)(s + 2), *(ushort*)(s + 4), *(ushort*)(s + 4));
        return s + 6;
    }

    /// <summary>Ghidra: LAB_00524170 — <b>ouvre le menu objets</b>, ecran complet, depuis le script
    /// de l'objet. Le corps est celui de <see cref="RunItemMenuState"/> (<c>FUN_00524180</c>)
    /// duplique par le compilateur, a ceci pres que le second appel y est un saut de queue.
    ///
    /// <para><b>TODO(REVERSE) — cet opcode rend une valeur qui n'est pas un curseur de script.</b>
    /// Le saut de queue fait de la valeur rendue celle de <c>FUN_00524320</c>, dont le dernier
    /// appel est <c>FUN_00524190</c> — <see cref="DrawItemMenuTitle"/>, qui rend un <b>curseur de
    /// liste d'affichage</b>. La boucle de la machine dereference ensuite ce pointeur comme un
    /// opcode. C'est un defaut de 1998, latent : il ne se manifeste que si un script d'objet emet
    /// reellement l'opcode 22, ce qu'on n'a pas observe. Il n'est donc pas verse dans
    /// <c>legacy-bug.md</c>, qui ne recense que l'observe.</para>
    ///
    /// <para>La transcription s'arrete au bord : elle fait les deux appels de l'original et leve
    /// plutot que d'inventer une valeur de retour. Le jour ou le jeu y passe, la levee dira ou
    /// regarder.</para></summary>
    private static byte* ItemOpOpenItemMenu(byte* s)
    {
        _ = s;
        LoadItemMenuResources();                         // Ghidra: FUN_00524210
        RunItemMenuFrameLoop();                          // Ghidra: FUN_00524320

        throw new NotImplementedException(
            "Script d'objet, opcode 22 (LAB_00524170) : l'ecran du menu objets a tourne, et "
            + "l'original rend ici la valeur de FUN_00524320 — c'est-a-dire le curseur de liste "
            + "d'affichage de FUN_00524190, pas un curseur de script. La machine le dereference "
            + "ensuite comme un opcode. Defaut de 1998, jamais observe jusqu'ici : voir le "
            + "TODO(REVERSE) sur ItemOpOpenItemMenu avant de choisir quoi en faire.");
    }

    /// <summary>Ghidra: FUN_0050f070 @ 0x0050f070 — <b>pose une particule</b> dans le pool de 64
    /// emplacements de <c>0x005e9b60</c>, pas <c>0x28</c>.
    ///
    /// <para>Le mot d'etat de <c>+0x24</c> empile trois choses : <c>0x14</c> en octet haut, qui est
    /// le compte a rebours que <c>FUN_0050f0d0</c> decremente par image, le genre en octet 2, et
    /// l'indice de l'emplacement en octet 1. Le pool plein ne fait rien du tout.</para></summary>
    private static void SpawnParticle_0050F070(uint* position, uint kind, byte flavour)
    {
        int index = AllocEntitySlot((ushort*)Mem.Arena(0x005e99e0));   // Ghidra: FUN_00532740
        if (index < 0) return;

        byte* entry = Mem.Arena(0x005e9b60) + index * 0x28;

        *(ushort*)(entry + 0x0c) = (ushort)kind;
        *(uint*)(entry + 0x24) = ((0x1400u | flavour) << 8 | (uint)(index & 0xff)) << 8;

        *(uint*)(entry + 0) = position[0];
        *(uint*)(entry + 4) = position[1];
        *(uint*)(entry + 8) = position[2];
    }

    /// <summary>Ghidra: FUN_0053a980 @ 0x0053a980 — <b>declenche le sort ou l'effet d'objet</b>
    /// designe par sa famille et son indice.
    ///
    /// <para>L'entree de description vit dans le repertoire de ressources : la table de
    /// <c>+0x9c</c> donne un tableau par famille, indexe au pas de <c>0x30</c>. Ses octets
    /// <c>+0x10</c>, <c>+0x11</c> et <c>+0x12</c> fournissent le genre d'effet et deux parametres —
    /// et ce sont eux qui servent quand l'appelant passe <c>-1</c>, ce que le script d'objet ne
    /// fait jamais mais que ses autres appelants font.</para>
    ///
    /// <para>Comme <see cref="ItemOpSpawnSelf"/>, elle neutralise trois champs de l'entite le temps
    /// de l'appel — <c>+0x74</c>, <c>+0x78</c> et le mot de <c>+0x0a</c> — puis les restaure.
    /// L'entree trouvee est rendue : deux appelants la relisent.</para></summary>
    private static byte* CastSpell_0053A980(uint* caster, int family, int index, int a, int b)
    {
        NoteSpellCast(family, index);   // ECHAFAUDAGE : hors du binaire, voir la sonde plus bas.

        byte* e = (byte*)caster;

        // Le mot de +6 porte les DEUX : la famille en octet haut, l'indice en octet bas. Ghidra
        // l'ecrit `CONCAT31((int3)param_2, (char)param_3)` tronque en `short`, ce qui se lit mal ;
        // le binaire est sans ambiguite (`mov dh,cl ; mov dl,al ; mov [esi+6],dx` en 0x0053a991).
        *(short*)(e + 6) = (short)(((family & 0xff) << 8) | (index & 0xff));

        byte* keptWatched = *(byte**)(e + 0x74);
        byte* keptFound = *(byte**)(e + 0x78);
        ushort keptCounter = *(ushort*)(e + 0x0a);

        byte* entry = *(byte**)(*(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x9c) + family * 4)
                      + index * 0x30;

        *(byte**)(e + 0x74) = e;
        *(byte**)(e + 0x78) = null;
        *(ushort*)(e + 0x0a) = 0;

        if (a < 0) a = entry[0x11];
        if (b < 0) b = entry[0x12];

        SpawnEffectEntity(e, entry[0x10], (byte)a, b);   // Ghidra: FUN_0047a9d0

        *(byte**)(e + 0x78) = keptFound;
        *(byte**)(e + 0x74) = keptWatched;
        *(ushort*)(e + 0x0a) = keptCounter;

        return entry;
    }

    /// <summary>
    /// Ghidra: FUN_00474ad0 @ 0x00474ad0 — <b>la recherche de cible</b> de l'opcode 17 du script
    /// d'objet. Elle balaie autour de l'acteur avec la sonde ci-dessous et range le premier
    /// trouve en <c>+0x78</c> de l'enregistrement.
    ///
    /// <para>
    /// <b>L'argument choisit le camp, le bit <c>0x800000</c> dit d'ou l'on part.</b> Le bit
    /// marque un <b>membre du groupe</b>, et les deux balayages sont les memes que ceux de la
    /// melee : <see cref="SweepSceneEntitiesForMeleeHit_00519AF0"/> pour la scene,
    /// <see cref="SweepPartyForMeleeHit_00519C30"/> pour le groupe. Le croisement des deux donne :
    /// </para>
    /// <list type="bullet">
    /// <item><b>mode 0</b> — le balayage <b>du meme camp</b> : un membre du groupe cherche un
    /// membre du groupe, une entite de scene cherche une entite de scene. C'est le mode de la
    /// potion qu'on donne a quelqu'un.</item>
    /// <item><b>mode non nul</b> — le camp <b>d'en face</b>, exactement l'aiguillage de
    /// <see cref="ProbeMeleeTarget_00474CA0"/>.</item>
    /// </list>
    /// <para>
    /// <b>Le mode 0 pose le bit <c>0x2000</c> sur l'acteur le temps du balayage</b>, puis restaure
    /// le mot d'etat entier. C'est ce qui empeche le balayage du groupe de se rendre lui-meme
    /// quand la source est elle-meme dans le groupe.
    /// </para>
    /// <para>
    /// <b>Le piege des arguments, deja rencontre sur la sœur <c>FUN_00474ca0</c>.</b> Ghidra rend
    /// deux des quatre appels sans leur quatrieme argument. Le desassembleur tranche : le
    /// <c>push 800h</c> est fait <b>une seule fois, avant le branchement</b> (0x00474b11 et
    /// 0x00474b47), donc <b>les quatre appels recoivent <c>0x800</c></b>. Rien a deviner.
    /// </para>
    /// </summary>
    /// <returns><b>0</b> quand une cible est trouvee, <b>1</b> sinon — et dans ce cas
    /// <c>+0x78</c> recoit l'acteur lui-meme, jamais un pointeur nul.</returns>
    private static uint PickTargetBySearch_00474AD0(uint* slot, byte mode)
    {
        byte* record = (byte*)slot;
        byte* actor = *(byte**)(record + 0x74);

        // Les six mots de la sonde, empiles sur place a chaque appel. Le sens de chacun est
        // etabli par TestMeleeReach_00535A90 : decalage de cap, avance, demi-largeur, tolerance
        // en hauteur, ouverture, profondeur. Ici un cone large et court, sans decalage de cap.
        short* probe = stackalloc short[6] { 0, 10, 0x28, 100, 0x100, 0x96 };

        byte* found;

        if (mode == 0)
        {
            // Ghidra: `mov eax,edi ; or ah,20h` — le bit 0x2000, pose puis retire.
            uint flags = *(uint*)actor;
            *(uint*)actor = flags | 0x2000;

            found = (flags & 0x800000) != 0
                ? SweepPartyForMeleeHit_00519C30(actor, (int*)(actor + 0x1c), probe, 0x800)
                : SweepSceneEntitiesForMeleeHit_00519AF0(actor, (int*)(actor + 0x1c), probe, 0x800);

            *(uint*)actor = flags;
        }
        else
        {
            found = (*(uint*)actor & 0x800000) != 0
                ? SweepSceneEntitiesForMeleeHit_00519AF0(actor, (int*)(actor + 0x1c), probe, 0x800)
                : SweepPartyForMeleeHit_00519C30(actor, (int*)(actor + 0x1c), probe, 0x800);
        }

        if (found != null)
        {
            *(byte**)(record + 0x78) = found;
            return 0;
        }

        *(byte**)(record + 0x78) = actor;
        return 1;
    }

    /// <summary>
    /// Ghidra: FUN_00474ba0 @ 0x00474ba0 — <b>la meme recherche de cible que
    /// <see cref="PickTargetBySearch_00474AD0"/>, mais qui rend le resultat</b> au lieu de le ranger.
    /// Decompilee dans <c>Blaze.c</c>.
    ///
    /// <para>
    /// <b>Les deux fonctions se suivent dans le binaire et ont le meme corps a la queue pres</b> :
    /// meme sonde de six mots, meme bit <c>0x2000</c> pose puis retire en mode 0, meme aiguillage
    /// des deux balayages. Elles ne different que par ce qu'elles font du resultat — celle-la
    /// l'ecrit en <c>+0x78</c> et rend un etat, celle-ci rend le pointeur. Le compilateur a emis
    /// les deux ; elles restent deux ici, comme dans le binaire.
    /// </para>
    /// <para>
    /// <b>Elle ne rend jamais <c>null</c> quand l'acteur existe</b> : faute de cible, elle rend
    /// l'acteur lui-meme. C'est ce qui permet a ses appelants de ranger le resultat sans garde.
    /// </para>
    /// <para>
    /// Ghidra rend deux des quatre appels de balayage sans leur quatrieme argument, le meme
    /// artefact que sur ses deux sœurs : le <c>push 800h</c> est fait avant le branchement, donc
    /// les quatre le recoivent.
    /// </para>
    /// </summary>
    private static byte* FindTargetAround_00474BA0(byte* record, int mode)
    {
        byte* actor = *(byte**)(record + 0x74);
        if (actor == null) return null;

        short* probe = stackalloc short[6] { 0, 10, 0x28, 100, 0x100, 0x96 };

        byte* found;

        if (mode == 0)
        {
            uint flags = *(uint*)actor;
            *(uint*)actor = flags | 0x2000;

            found = (flags & 0x800000) != 0
                ? SweepPartyForMeleeHit_00519C30(actor, (int*)(actor + 0x1c), probe, 0x800)
                : SweepSceneEntitiesForMeleeHit_00519AF0(actor, (int*)(actor + 0x1c), probe, 0x800);

            *(uint*)actor = flags;
        }
        else
        {
            found = (*(uint*)actor & 0x800000) != 0
                ? SweepSceneEntitiesForMeleeHit_00519AF0(actor, (int*)(actor + 0x1c), probe, 0x800)
                : SweepPartyForMeleeHit_00519C30(actor, (int*)(actor + 0x1c), probe, 0x800);
        }

        return found != null ? found : actor;
    }

    /// <summary>
    /// Ghidra: FUN_00475090 @ 0x00475090 — <b>reserver des emplacements d'entite a l'avance</b>,
    /// sans les prendre. Decompilee dans <c>Blaze.c</c>, jamais transcrite jusqu'ici faute
    /// d'appelant.
    ///
    /// <para>
    /// La liste libre d'un pool est un octet de curseur, un octet de capacite, puis les indices
    /// disponibles. Cette fonction <b>trie les <paramref name="count"/> plus petits indices
    /// restants vers la tete</b> par une selection partielle, <b>sans avancer le curseur</b> :
    /// l'appelant peut donc lire d'avance quels indices les prochaines allocations lui donneront,
    /// et s'en servir comme d'un rendez-vous.
    /// </para>
    /// <para>
    /// <b>C'est exactement ce que fait Demon polaire</b> : il reserve deux emplacements, range
    /// leurs indices dans <c>+0x16</c> et <c>+0x17</c>, puis engendre ses deux moities — qui se
    /// retrouvent ensuite par <c>0x005edee0 + indice * 0x9c</c>, sans jamais se passer de pointeur.
    /// </para>
    /// </summary>
    /// <returns>1 si la place existait, 0 sinon — et dans ce cas rien n'est touche.</returns>
    private static uint ReserveEntitySlots_00475090(byte* pool, int count)
    {
        if (pool[1] < count + pool[0]) return 0;

        byte* list = pool + pool[0] + 2;

        for (; count != 0; count--, list++)
        {
            int smallest = 0;
            byte value = *list;

            for (int i = 1; i < count; i++)
            {
                if (list[i] < value)
                {
                    smallest = i;
                    value = list[i];
                }
            }

            byte swap = list[smallest];
            list[smallest] = *list;
            *list = swap;
        }

        return 1;
    }

    /// <summary>
    /// Ghidra: FUN_00475110 @ 0x00475110 — <b>le lanceur tient-il encore ?</b> Decompilee dans
    /// <c>Blaze.c</c>. C'est la garde des sorts <b>entretenus</b> : elle rend <b>0</b> tant que le
    /// lanceur peut continuer, <b>1</b> des qu'il faut couper.
    ///
    /// <para>
    /// Trois conditions doivent tenir ensemble pour continuer : le lanceur est <b>vivant</b>
    /// (<c>0x80000000</c>), il n'est <b>ni mort ni en train de mourir</b> (<c>0x50000000</c>
    /// absent), et son bloc de combat ne porte <b>aucune</b> alteration du masque
    /// <c>0x400003e8</c> en <c>+0x40</c> — le meme masque que
    /// <see cref="ApplyGroundMotion_0051A020"/> teste avant d'ouvrir la posture d'incantation.
    /// Etourdi, endormi ou petrifie, on ne tient pas un sort.
    /// </para>
    /// <para>
    /// Le bloc vient de la meme paire que <see cref="StatusBubbleHeight_00538BC0"/> : un membre du
    /// groupe le tient de <c>MainMem</c>, une entite de scene de
    /// <see cref="s_EntityStatBlocks_005ea560"/>.
    /// </para>
    /// </summary>
    private static uint CanSustainChannel_00475110(byte* record)
    {
        uint* actor = *(uint**)(record + 0x74);
        uint flags = *actor;

        byte* block = (flags & 0x800000) == 0
            ? s_EntityStatBlocks_005ea560 + (byte)actor[2] * 0x120
            : GetMainMemPtr() + (byte)actor[2] * 0x2000 + 0xf0100;

        if ((flags & 0x80000000) != 0
            && (flags & 0x50000000) == 0
            && (*(uint*)(block + 0x40) & 0x400003e8) == 0)
        {
            return 0;
        }

        return 1;
    }

    /// <summary>Ghidra: FUN_0051a020 @ 0x0051a020 (221 l.) — l'integration du deplacement au sol,
    /// appelee quand le personnage n'est pas en l'air.</summary>
    private static void ApplyGroundMotion_0051A020(uint* slot, byte* entry, byte* perChar, byte* pad, byte* anim)
    {
        byte* s = (byte*)slot;

        switch (perChar[0x150] & 7)
        {
            // ------------------------------------------------ la marche et sa variante
            case 0:
            case 6:
                if (pad[0x0e] != 0
                    && (sbyte)perChar[0x2b2] != -1
                    && s_Unknown_00566c84 != 0
                    && (*slot & 0x44) == 0
                    && (*(uint*)(perChar + 0x140) & 0x400003c0) == 0)
                {
                    *(uint*)(s + 0x18) = 5;
                    *slot = (*slot & 0xfeffffff) | 4;
                }

                if ((*(ushort*)pad & *(ushort*)(perChar + 0x1fc4)) == 0 && (*slot & 0x2000000) != 0)
                {
                    *slot &= 0xfffffffb;
                }

                if (*(short*)(s + 0x18) == 5)
                {
                    *(int*)(s + 0x5c) = 0;
                    return;
                }

                break;

            // ------------------------------------------------ les quatre postures d'incantation
            case 1:
            case 3:
            case 5:
            case 7:
            {
                byte* spellSet = *(byte**)(*(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x9c)
                                           + perChar[0x2b5] * 4);
                uint held = *slot;

                if ((held & 4) == 0)
                {
                    if ((held & 0x40) != 0) return;
                    if ((*(uint*)(perChar + 0x140) & 0x400003e8) != 0) return;

                    if ((*(ushort*)(pad + 2) & 1) != 0 && s_Unknown_00566c84 != 0)
                    {
                        // Annulation : l'incantation part quand meme, mais sans effet retenu.
                        *slot = held | 0x1000004;
                        *(uint*)(s + 0x18) = 5;
                        entry[0x0b] = 0;
                        *(ushort*)(pad + 0x0c) = 0;
                        *(ushort*)(pad + 0x0e) = 0;
                        *(short*)(s + 0x14) = 0;
                        SpawnCastEntity_0047AAE0(s, 0xbd, 0, 0);
                        return;
                    }

                    if ((*(ushort*)(perChar + 0x1fc4) & *(ushort*)(pad + 2)) == 0) return;
                    if (s_Unknown_00566c84 == 0) return;

                    *(uint*)(s + 0x18) = 5;
                    *slot = held | 0x1000004;

                    byte* spell = spellSet + perChar[0x2b6] * 0x30;
                    *(ushort*)(s + 0x14) = spell[0x13];
                    *(ushort*)(perChar + 0x204) = *(ushort*)(spell + 0x14);
                    SpawnCastEntity_0047AAE0(s, 0xbd, 0, 0);
                    *(uint*)Mem.Arena(0x005e99c0) = 0;
                    TriggerEquippedItems_005238E0(slot, 5);
                    return;
                }

                *(int*)(s + 0x5c) = 0;

                if (*(short*)(s + 0x18) == 5)
                {
                    if (*(short*)(s + 0x14) == 0)
                    {
                        if ((*(ushort*)pad & 1) == 0)
                        {
                            // Le bouton est relache : on choisit la cible et on passe a l'etat 6.
                            *slot = held & 0xfeffffff;
                            *(uint*)(s + 0x18) = 6;
                            *(short*)(s + 0x14) = 5;

                            int chosen = PickCastTarget_0051A5D0(entry, perChar);
                            bool armed = false;

                            if (chosen >= 0)
                            {
                                uint* mask = (uint*)(perChar + ((chosen >> 5) + 0x58 + perChar[0x2b5] * 2) * 4);
                                if ((*mask & (1u << (chosen & 0x1f))) != 0)
                                {
                                    *(ushort*)(perChar + 0x204) = *(ushort*)(spellSet + chosen * 0x30 + 0x14);
                                    *(short*)(s + 0x16) = (short)chosen;
                                    armed = true;
                                }
                            }

                            if (!armed)
                            {
                                *slot = (*slot & 0xfffffffb) | 0x1000000;
                                *(uint*)(s + 0x18) = 0;
                            }
                        }
                        else if ((*(ushort*)(pad + 2) & 0xf000) != 0 && entry[0x0b] < 0x10)
                        {
                            // Le bouton est tenu : chaque direction s'empile dans la combinaison.
                            entry[0x0c + entry[0x0b]] = (byte)((*(ushort*)(pad + 2) >> 8) & 0xf0);
                            entry[0x0b]++;
                        }
                    }
                    else
                    {
                        if ((*(ushort*)pad & *(ushort*)(perChar + 0x1fc4)) == 0)
                        {
                            *slot = (held & 0xfffffffb) | 0x1000000;
                            *(uint*)(s + 0x18) = 0;
                        }
                        else
                        {
                            short remaining = (short)(*(short*)(s + 0x14) - 1);
                            *(short*)(s + 0x14) = remaining;
                            if (remaining == 0)
                            {
                                *(uint*)(s + 0x18) = 6;
                                *slot = held & 0xfeffffff;
                                *(short*)(s + 0x14) = 5;

                                uint index = perChar[0x2b6];
                                uint* mask = (uint*)(perChar + (((int)index >> 5) + 0x58 + perChar[0x2b5] * 2) * 4);
                                if ((*mask & (1u << (perChar[0x2b6] & 0x1f))) == 0) index = 0xffffffff;
                                *(short*)(s + 0x16) = (short)index;
                            }
                        }
                    }
                }

                if (*(short*)(s + 0x18) == 6)
                {
                    held = *slot;
                    if ((held & 0x2000000) != 0)
                    {
                        *(short*)(s + 0x14) = (short)(*(short*)(s + 0x14) - 1);
                        if (*(short*)(s + 0x14) == 0)
                        {
                            *(uint*)(s + 0x18) = 0;
                            *slot = (held & 0xfffffffb) | 0x1000000;
                            return;
                        }

                        *slot = held & 0xfeffffff;

                        // L'etat et l'image sont poses d'un seul dword : l'animation demarre a sa
                        // DERNIERE image.
                        *(uint*)(s + 0x18) = ((uint)(*(ushort*)(anim + 0x16) - 1) << 0x10) | 6;

                        if (*(short*)(s + 0x16) >= 0)
                        {
                            *(uint*)Mem.Arena(0x005e99c0) = 0;
                            TriggerEquippedItems_005238E0(slot, 6);

                            // Le cout n'est preleve que si la reserve le couvre — sinon
                            // l'incantation part sans rien consommer ni produire.
                            if (*(ushort*)(perChar + 0x204) <= (int)*(short*)(perChar + 0x14e))
                            {
                                *(ushort*)(perChar + 0x14e) =
                                    (ushort)(*(short*)(perChar + 0x14e) - *(ushort*)(perChar + 0x204));
                                CastSpell_0053A980(slot, perChar[0x2b5], *(short*)(s + 0x16), -1, -1);
                            }

                            *(ushort*)(s + 0x16) = 0xffff;
                            return;
                        }
                    }
                }

                break;
            }

            // ------------------------------------------------ la charge
            case 2:
                if (*(short*)(s + 0x18) != 5 || (*slot & 0x2000000) != 0)
                {
                    *(short*)(s + 0x14) = 0;
                    *slot &= 0xfffffffb;
                }

                if (*(short*)(s + 0x14) == 0)
                {
                    if (pad[0x0e] != 0
                        && (*slot & 0x44) == 0
                        && (*(uint*)(perChar + 0x140) & 0x400003c0) == 0)
                    {
                        *(ushort*)(pad + 2) &= 0x7fff;
                        *(uint*)(s + 0x18) = 5;
                        *(short*)(s + 0x14) = 0x10;
                        *slot = (*slot & 0xfeffffff) | 4;
                        *(short*)(s + 0x98) = *(short*)(s + 0x32);
                    }
                }
                else
                {
                    short remaining = (short)(*(short*)(s + 0x14) - 1);
                    *(short*)(s + 0x14) = remaining;
                    if (remaining == 0) *slot &= 0xfffffffb;
                }

                if (*(short*)(s + 0x18) == 5)
                {
                    uint posture = *(uint*)(perChar + 0x140);
                    int scale = 0x1000;
                    if ((posture & 0x4000) != 0) scale = 0x1333;
                    if ((posture & 0x8000) != 0) scale = 0xccc;
                    if ((posture & 4) != 0) scale = 0x800;

                    // La charge decelere toute seule : la vitesse suit le compte a rebours.
                    *(int*)(s + 0x5c) = *(short*)(s + 0x14) * 0x2000 * scale >> 0xc;
                    return;
                }

                break;

            // ------------------------------------------------ l'objet consommable
            case 4:
                if ((*slot & 0x44) == 0
                    && (*(ushort*)pad & *(ushort*)(perChar + 0x1fc4)) != 0
                    && (*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc4)) != 0
                    && s_Unknown_00566c84 != 0
                    && (*(uint*)(perChar + 0x140) & 0x400003c0) == 0)
                {
                    *(uint*)(s + 0x18) = 5;
                    *slot = (*slot & 0xfcffffff) | 4;
                    *(short*)(s + 0x14) = 5;
                }

                if ((*slot & 4) != 0)
                {
                    if ((*slot & 0x2000000) != 0)
                    {
                        if (*(short*)(s + 0x14) == 5)
                        {
                            // Ghidra lit ici les huit octets de +0x160 comme un COMPTE par
                            // emplacement, la ou la posture d'incantation lit la meme region
                            // comme un MASQUE de bits. Les deux vues coexistent dans l'original ;
                            // transcrites telles quelles. TODO(REVERSE) : etablir laquelle est la
                            // bonne, ou si les deux `kind` ne se recouvrent jamais.
                            byte* charges = perChar + 0x160 + perChar[0x2b5] * 8;
                            sbyte left = (sbyte)charges[perChar[0x2b6]];
                            if (left != 0)
                            {
                                charges[perChar[0x2b6]] = (byte)(left - 1);
                                s[6] = perChar[0x2b6];
                                *slot |= 0x800;
                                CastSpell_0053A980(slot, perChar[0x2b5], perChar[0x2b6], -1, -1);
                            }
                        }

                        *(short*)(s + 0x14) = (short)(*(short*)(s + 0x14) - 1);
                        if (*(short*)(s + 0x14) != 0)
                        {
                            *slot &= 0xfeffffff;
                            ushort frames = *(ushort*)(anim + 0x16);
                            *(int*)(s + 0x5c) = 0;
                            *(uint*)(s + 0x18) = ((uint)(frames - 1) << 0x10) | 5;
                            return;
                        }

                        *(uint*)(s + 0x18) = 0;
                        *slot = (*slot & 0xfffffffb) | 0x1000000;
                    }

                    *(int*)(s + 0x5c) = 0;
                    return;
                }

                break;

            default:
                *slot &= 0xfffffffb;
                break;
        }
    }

    /// <summary>
    /// Ghidra: FUN_0047aae0 @ 0x0047aae0 — <b>fait naitre une entite d'incantation</b> dans la table
    /// <c>DAT_005edee0</c>, en recopiant les 0x27 dwords du lanceur puis en remplacant six champs.
    /// Jumelle de <c>SpawnEffectEntity</c> (<c>FUN_0047a9d0</c>) a la table pres.
    ///
    /// <para>Le masque final <c>&amp; 0x10e82f02 | 0x80109000</c> ne garde du mot d'etat copie que ce
    /// qui a un sens pour une entite d'effet.</para>
    /// </summary>
    /// <returns>1 si un emplacement etait libre, 0 sinon.</returns>
    private static uint SpawnCastEntity_0047AAE0(byte* source, byte subtype, byte param3, int param4)
    {
        int index = AllocEntitySlot((ushort*)Mem.Entity(0x006007a0));
        if (index < 0) return 0;

        byte* born = Mem.Entity(0x005edee0) + index * 0x9c;
        Mem.CopyDwords((uint*)source, (uint*)born, 0x27);

        born[0x36] |= 0x80;
        born[0x08] = (byte)index;
        born[0x05] = subtype;
        *(byte**)(born + 0x6c) = source;
        born[0x0b] = param3;
        if (param4 >= 0) born[0x0a] = (byte)param4;

        *(uint*)born = (*(uint*)born & 0x10e82f02) | 0x80109000;
        *(ushort*)(born + 0x10) = 0;
        return 1;
    }

    /// <summary>
    /// Ghidra: FUN_004765d0 @ 0x004765d0 — <b>l'aureole d'incantation</b> : le gestionnaire du
    /// sous-type <c>0xbd</c>, creneau 189 de la table statique <see cref="s_StaticEntityHandlers_00551f30"/>.
    /// 350 octets, <b>absente de <c>Blaze.c</c></b>, transcrite au desassembleur — le releve est
    /// garde sous <c>Legacy/Raw/Blaze/FUN_004765D0.asm</c>.
    ///
    /// <para>
    /// C'est le pendant vivant de <see cref="SpawnCastEntity_0047AAE0"/> : ce que
    /// <see cref="ApplyGroundMotion_0051A020"/> fait naitre a chaque fois qu'un personnage prend la
    /// posture d'incantation (<c>+0x18 == 5</c>), et ce qui plantait a l'appui sur Select en foret.
    /// </para>
    ///
    /// <para>
    /// <b>La premiere entite n'est qu'une graine.</b> Le sous-type se comporte de deux façons selon
    /// que sa source porte ou non le bit <c>0x100000</c> — celui qui, dans la boucle de dessin de la
    /// grille, designe une entite <b>rendue comme modele du paquet</b>, indexee par <c>+0x04</c>.
    /// Un personnage ne le porte pas (il passe par la branche <c>0x440000</c>, le modele anime),
    /// mais <see cref="SpawnCastEntity_0047AAE0"/> le <b>force</b> sur tout ce qu'elle engendre.
    /// Le test lit donc « ma source est-elle une de mes semblables ? » :
    /// </para>
    /// <list type="bullet">
    /// <item><b>source = le personnage</b> — la graine se recopie <b>deux fois</b> par
    /// <see cref="SpawnCastEntity_0047AAE0"/>, en avançant sa rotation <c>+0x32</c> de <c>0x800</c>
    /// avant chaque copie, puis se marque <c>0x2000000</c> et s'eteint a l'image suivante. Trois
    /// tiers de tour, donc, dont il ne reste que deux exemplaires.</item>
    /// <item><b>source = la graine</b> — la copie se reaccroche au <b>personnage</b>
    /// (<c>source + 0x6c</c>), prend le modele <c>0x3d</c>, la teinte pleine <c>0xffffff</c>, et
    /// mesure une fois pour toutes la hauteur de tete du lanceur par
    /// <see cref="StatusBubbleHeight_00538BC0"/>.</item>
    /// </list>
    ///
    /// <para>
    /// Ensuite, a chaque image : la position est recopiee du lanceur avec la hauteur en decalage
    /// vertical (<c>(hauteur &amp; ~1) &lt;&lt; 11</c>), l'echelle des trois axes <b>approche</b> sa
    /// cible d'un quart de la distance restante — la cible etant <c>(hauteur &lt;&lt; 12) / 150</c>,
    /// que le binaire ecrit en multiplication magique <c>0x1B4E81B5</c> suivie de <c>sar 4</c> —
    /// et la rotation avance de <c>0x40</c> sur <c>+0x32</c>, <c>0x80</c> sur <c>+0x34</c>.
    /// </para>
    /// <para>
    /// <b>Trois conditions rendent la main</b>, et posent <c>0x2000000</c> sur le mot d'etat, ce qui
    /// bascule l'entite dans la branche d'extinction : le lanceur porte <c>0x50000000</c> ; c'est un
    /// membre du groupe (<c>0x800000</c>) qui a <b>quitte la posture 5</b> ; ou son mot d'etat
    /// vaut <c>0x400000</c> sur le masque <c>0x400004</c>. L'extinction <b>divise l'echelle par
    /// deux</b> a chaque image et rend le creneau des qu'elle passe sous <c>0x100</c>, en mettant le
    /// mot d'etat a zero — la passe <see cref="TickEntityTable_005edee0"/> relit ce mot juste apres
    /// et libere l'emplacement.
    /// </para>
    /// </summary>
    private static void TickCastAura_004765D0(byte* record)
    {
        byte* e = record;

        // ------------------------------------------------------------------ l'extinction
        if ((*(uint*)e & 0x2000000) != 0)
        {
            int scale = *(short*)(e + 0x28);
            scale -= scale >> 1;                       // la moitie, arrondie vers le haut

            *(short*)(e + 0x2c) = (short)scale;
            *(uint*)(e + 0x28) = ((uint)scale << 0x10) | (uint)scale;

            *(ushort*)(e + 0x32) += 0x40;
            *(ushort*)(e + 0x34) += 0x80;

            // Le mot d'etat a zero : la passe rend le creneau au pool 0x006007a0.
            if (scale < 0x100) *(uint*)e = 0;
            return;
        }

        // ------------------------------------------------------------------ l'amorcage
        if (*(ushort*)(e + 0x10) == 0)
        {
            byte* source = *(byte**)(e + 0x6c);

            e[0x36] |= 6;
            *(ushort*)(e + 0x10) = 1;
            *(uint*)(e + 0x38) = 0xffffff;
            *(uint*)(e + 0x28) = 0;
            *(ushort*)(e + 0x2c) = 0;
            *(ushort*)(e + 0x34) = 0;

            if ((*(uint*)source & 0x100000) == 0)
            {
                // Ghidra: LAB_004766f4 — la graine se dedouble et se marque pour l'extinction.
                *(ushort*)(e + 0x32) += 0x800;
                SpawnCastEntity_0047AAE0(e, 0xbd, 0, 0);
                *(ushort*)(e + 0x32) += 0x800;
                SpawnCastEntity_0047AAE0(e, 0xbd, 0, 0);

                *(uint*)e |= 0x2000000;
                return;
            }

            // La copie saute par-dessus la graine et se raccroche au lanceur lui-meme.
            byte* caster = *(byte**)(source + 0x6c);
            e[0x04] = 0x3d;
            *(byte**)(e + 0x6c) = caster;
            e[0x0b] = 0;
            e[0x0a] = 0x0f;
            *(short*)(e + 0x12) = (short)StatusBubbleHeight_00538BC0((uint*)caster);
        }

        // Ghidra: LAB_0047666c — le suivi, hors de toute branche d'etat.
        int height = *(short*)(e + 0x12);
        byte* anchor = *(byte**)(e + 0x6c);

        // `imul 0x1B4E81B5` puis `sar edx,4` et la correction de signe : une division signee par
        // 150, l'idiome du compilateur de 1998.
        int target = (height << 0xc) / 150;
        int current = *(short*)(e + 0x28);
        current += (target - current) >> 2;            // un quart de ce qui reste, par image

        *(short*)(e + 0x2c) = (short)current;
        *(uint*)(e + 0x28) = ((uint)current << 0x10) | (uint)current;

        *(int*)(e + 0x1c) = *(int*)(anchor + 0x1c);
        *(int*)(e + 0x20) = *(int*)(anchor + 0x20) + ((height & ~1) << 0xb);
        *(int*)(e + 0x24) = *(int*)(anchor + 0x24);

        uint state = *(uint*)anchor;
        bool spent;

        if ((state & 0x50000000) != 0) spent = true;
        else if ((state & 0x800000) != 0 && *(ushort*)(anchor + 0x18) != 5) spent = true;
        else spent = (state & 0x400004) == 0x400000;   // Ghidra: LAB_004766d3

        if (spent) *(uint*)e |= 0x2000000;

        // Ghidra: LAB_004766e5 — la rotation, commune aux deux branches.
        *(ushort*)(e + 0x32) += 0x40;
        *(ushort*)(e + 0x34) += 0x80;
    }

    // =====================================================================
    // BALLE DE FEU — le premier sort, ecole 0 indice 0, sous-type 0x00
    //
    // Deux corps, et c'est la forme generale d'un sort de projectile :
    //
    //   0x0047ADD0   LA GRAINE. Sous-type 0 de la table statique 0x00551c30, celle que la passe
    //                FUN_0047aa70 emprunte pour la table des effets 0x005ff400 — c'est-a-dire
    //                exactement ce que CastSpell_0053A980 fait naitre. Elle ne vit qu'UNE image :
    //                elle se pose devant le lanceur, se donne un modele et une taille, lache le
    //                projectile, joue le son, et s'eteint.
    //   0x0047AE80   LE PROJECTILE. Sous-type 0x64 de la table statique 0x00551f30, celle de la
    //                table d'incantation 0x005edee0 ou SpawnCastEntity_0047AAE0 depose. Il avance,
    //                traine des etincelles, cherche une cible douze images durant, et au contact
    //                appelle ResolveSpellHit_0053A2B0.
    //
    // Les deux sont ABSENTES de Blaze.c — Ghidra ne les a pas decompilees, elles n'existent que
    // comme entrees de table. Transcrites au desassembleur ; les releves sont gardes sous
    // Legacy/Raw/Blaze/FUN_0047add0.asm et FUN_0047AE80.asm.
    //
    // LE QUART DE TOUR. La graine avance de 80 unites dans la direction +0x32 heritee du lanceur,
    // puis AJOUTE 0x400 a cette direction avant de lacher le projectile ; le projectile, lui,
    // RETRANCHE 0x400 avant d'avancer. Les deux se compensent exactement, et le projectile part
    // donc bien droit devant. Le detour sert au dessin, qui lit +0x32 tel quel.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047add0 @ 0x0047add0 — <b>la graine de Balle de feu</b> : le sous-type
    /// <c>0x00</c>, creneau 0 de <see cref="s_StaticEntityHandlers_00551c30"/>. 161 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Elle ne tourne qu'une image. Le mot d'etat est mis a zero en sortie, ce qui rend le creneau
    /// a la passe suivante — la meme extinction que <see cref="DespawnEntity_0047ADC0"/>, mais
    /// apres avoir fait son travail.
    /// </para>
    /// <para>
    /// <b>Elle se place a hauteur de tete du LANCEUR</b>, pas au sol :
    /// <see cref="StatusBubbleHeight_00538BC0"/> mesure <c>+0x74</c> — que
    /// <see cref="CastSpell_0053A980"/> a pointe sur le lanceur lui-meme juste avant la naissance —
    /// et la hauteur, arrondie au pair, monte en <c>+0x20</c> decalee de 11 bits. C'est la meme
    /// mesure et le meme arrondi que <see cref="TickCastAura_004765D0"/>.
    /// </para>
    /// <para>
    /// Les quatre champs poses avant la naissance du projectile sont recopies dedans par
    /// <see cref="SpawnCastEntity_0047AAE0"/>, qui duplique les <c>0x27</c> dwords de la source :
    /// le modele <c>0x39</c>, l'echelle <c>0x640</c> sur les trois axes, la teinte pleine
    /// <c>0xffffff</c>. La graine s'habille pour son enfant.
    /// </para>
    /// </summary>
    private static void SpawnFireball_0047ADD0(byte* record)
    {
        byte* e = record;

        e[0x36] |= 6;

        int heading = *(short*)(e + 0x32);

        // 80 unites devant le lanceur, dans le plan. `lea eax,[eax+eax*4] ; shl eax,4` = *80.
        *(int*)(e + 0x1c) += (int)Winsys3d.GetSinTableEntry(heading) * 80;
        *(int*)(e + 0x24) += Winsys3d.GetCosTableEntry(heading) * 80;

        // La hauteur de tete du lanceur, arrondie au pair : `and al,0FEh` n'efface que le bit 0.
        int height = StatusBubbleHeight_00538BC0(*(uint**)(e + 0x74));
        *(int*)(e + 0x20) += (height & ~1) << 0xb;

        *(ushort*)(e + 0x32) += 0x400;

        *(uint*)(e + 0x28) = 0x06400640;              // echelle X et Y
        *(ushort*)(e + 0x2c) = 0x0640;                // echelle Z
        *(uint*)(e + 0x38) = 0x00ffffff;              // teinte pleine
        e[0x04] = 0x39;                               // le modele

        SpawnCastEntity_0047AAE0(e, 0x64, e[0x0b], -1);

        Aud.PlayPositionalSound(0x1f, 0x6fd, 0x1200, (int*)(e + 0x1c));   // Ghidra: FUN_0053db20

        *(uint*)e = 0;                                // la graine s'eteint des cette image
    }

    /// <summary>
    /// Ghidra: <c>&amp;DAT_00551ad8</c> — l'atlas des etincelles que le projectile de Balle de feu
    /// traine derriere lui. <b>Quatre enregistrements</b> : quatre carreaux de 16x16 alignes en
    /// <c>u = 0x60, 0x70, 0x80, 0x90</c> sur la meme ligne <c>v = 0xa8</c>.
    ///
    /// <para>
    /// <b>La borne se lit dans le corps du consommateur</b>, comme pour
    /// <see cref="s_Descriptors_00551A60"/> et non a l'aveugle :
    /// <see cref="TickSpark_0047B050"/> pose <c>+0x40 = compteur &gt;&gt; 1</c> et s'eteint des que
    /// ce quotient atteint <b>4</b>. Il n'existe donc que quatre images. La donnee le confirme —
    /// <c>0x00551af8</c> change de planche (<c>v</c> passe a <c>0x68</c>, les attributs de
    /// <c>01 02</c> a <c>00 00</c>).
    /// </para>
    /// </summary>
    private static readonly byte[] s_Descriptors_00551AD8 =
    [
        0x60, 0xa8, 0x10, 0x10, 0x01, 0x02, 0x10, 0x00,   // 0x00551ad8
        0x70, 0xa8, 0x10, 0x10, 0x01, 0x02, 0x10, 0x00,   // 0x00551ae0
        0x80, 0xa8, 0x10, 0x10, 0x01, 0x02, 0x10, 0x00,   // 0x00551ae8
        0x90, 0xa8, 0x10, 0x10, 0x01, 0x02, 0x10, 0x00,   // 0x00551af0
    ];

    private static byte* s_Descriptors00551AD8Storage;

    /// <summary>Les quatre descripteurs en memoire native.</summary>
    private static byte* Descriptors00551AD8()
        => NativeCopy(s_Descriptors_00551AD8, ref s_Descriptors00551AD8Storage);

    /// <summary>
    /// <c>&amp;DAT_00551ba8</c>, l'atlas de la <b>Boule de lumiere</b> — le <b>deuxieme</b>
    /// enregistrement de la plage <see cref="s_Descriptors_00551BA0"/>, pas une table a lui.
    ///
    /// <para>
    /// <b>Il avait ete releve a part le 2026-08-31, et c'etait la faute que le depot s'etait deja
    /// faite une fois</b> : les deux tuiles de <c>0x00551ba8</c> et <c>0x00551bb0</c> etaient
    /// recopiees dans un tableau neuf alors que <c>s_Descriptors_00551BA0</c> les portait deja.
    /// Deux relevés du meme octet finissent par diverger, et surtout l'indexation en avant — la
    /// convention des fonctions de dessin — n'aurait plus rien trouve au-dela du second.
    /// Adresser par decalage dans la plage est la seule forme juste.
    /// </para>
    /// <para>
    /// <see cref="TickLightBall_0047B150"/> ne touche pas a son propre <c>+0x40</c>, que
    /// <see cref="SpawnStatusEffectEntity_0047AC40"/> a mis a zero : la boule garde donc la tuile
    /// <c>0x18 x 0x18</c> de <c>0x00551ba8</c> toute sa vie.
    /// </para>
    /// </summary>
    private static byte* Descriptors00551BA8() => Descriptors00551BA0() + 8;

    /// <summary>
    /// <c>&amp;DAT_00551bd8</c>, l'atlas de <b>la boule des sorts de monstre</b> — le
    /// <b>huitieme</b> et dernier enregistrement releve de la plage
    /// <see cref="s_Descriptors_00551BA0"/>, adresse par decalage comme
    /// <see cref="Descriptors00551BA8"/> et <see cref="Descriptors00551BC0"/>.
    ///
    /// <para>
    /// Son seul emploi est <see cref="TickMonsterOrbCast_004769A0"/>. C'est aussi <b>le premier
    /// appelant connu du huitieme enregistrement</b> : la note portee sur la plage disait que huit
    /// etaient relevés « parce que huit sont lisibles, pas parce qu'une borne les designe », et
    /// celui-ci en avait donc un.
    /// </para>
    /// </summary>
    private static byte* Descriptors00551BD8() => Descriptors00551BA0() + 0x38;

    /// <summary>
    /// <c>&amp;DAT_00551bb8</c>, l'atlas de l'<b>eclaboussure</b> de Pieds mouilles — le
    /// <b>quatrieme</b> enregistrement de la meme plage
    /// <see cref="s_Descriptors_00551BA0"/>. <see cref="TickWetFeetSplash_0047B750"/> ne touche pas
    /// non plus a son <c>+0x40</c> : une seule tuile, <c>0x10 x 0x10</c>.
    /// </summary>
    private static byte* Descriptors00551BB8() => Descriptors00551BA0() + 0x18;

    /// <summary>
    /// Ghidra: FUN_0047ae80 @ 0x0047ae80 — <b>le projectile de Balle de feu</b> : le sous-type
    /// <c>0x64</c>, creneau 100 de <see cref="s_StaticEntityHandlers_00551f30"/>. 455 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Chaque image, dans cet ordre</b> : il avance de 40 unites sur son cap (moins le quart de
    /// tour que la graine avait ajoute) ; il lache une etincelle <c>0x46</c> <b>derriere lui</b> —
    /// le cap plus un demi-tour, a 60 unites, plus un bruit de +/-32 unites de 4096 sur les trois
    /// axes, trois tirages consecutifs ; il repose son placement par
    /// <see cref="FinalizeEntityPlacement2"/> ; il cherche une cible.
    /// </para>
    /// <para>
    /// <b>La hauteur est sauvee et rendue autour du placement.</b>
    /// <c>FinalizeEntityPlacement2</c> pose l'entite <i>sur le sol</i>, ce qui ecraserait
    /// <c>+0x20</c> ; le binaire garde la valeur dans un registre et la remet juste apres. La
    /// balle vole donc a la hauteur ou la graine l'a lachee, et le placement ne sert qu'a la
    /// detection.
    /// </para>
    /// <para>
    /// <b>Trois fins</b>. Le decor : le mot d'etat porte <c>0x40000000</c>, ou <c>+0x90</c> porte
    /// l'un des bits <c>0x8802</c> — la balle s'eteint sans rien faire. Le temps : douze images
    /// sans cible, comptees dans <c>+0x10</c>. La cible : <c>ProbeMeleeTarget_00474CA0</c> rend une
    /// victime, et alors <see cref="ResolveSpellHit_0053A2B0"/> resout le coup avec la paire
    /// famille/indice que <see cref="CastSpell_0053A980"/> avait rangee en <c>+0x06</c>, la victime
    /// est <b>poussee</b> de 16 unites sur le cap de la balle, marquee <c>0x40</c> et
    /// <c>+0x96 = 0x10</c>, et un second son part.
    /// </para>
    /// <para>
    /// La sonde de portee est la meme forme que celle de <see cref="PickTargetBySearch_00474AD0"/>
    /// et de la melee : six mots — decalage de cap, avance, demi-largeur, tolerance en hauteur,
    /// ouverture, profondeur.
    /// </para>
    /// </summary>
    private static void TickFireball_0047AE80(byte* record)
    {
        byte* e = record;

        // Ghidra: les six mots de la sonde, empiles sur place. -1024 de decalage de cap, -100
        // d'avance, 50 de demi-largeur, 100 de tolerance en hauteur, aucune ouverture, 100 de
        // profondeur. Les trois ints qui suivent recoivent la position de l'etincelle : le binaire
        // n'a qu'un seul bloc de 0x18 octets sur sa pile, et il s'en sert des deux façons.
        short* probe = stackalloc short[6] { -0x0400, -0x0064, 0x0032, 0x0064, 0x0000, 0x0064 };
        int* sparkAt = stackalloc int[3];

        if (*(ushort*)(e + 0x10) == 0) *(uint*)e |= 0x80;   // la premiere image

        // Le cap, moins le quart de tour que la graine avait ajoute.
        int heading = *(short*)(e + 0x32) - 0x400;

        // 40 unites d'avance : `lea eax,[eax+eax*4] ; shl eax,3`.
        *(int*)(e + 0x1c) += (int)Winsys3d.GetSinTableEntry(heading) * 40;
        *(int*)(e + 0x24) += Winsys3d.GetCosTableEntry(heading) * 40;

        // L'etincelle part DERRIERE, a 60 unites (`*3` puis `*5` puis `*4`), et chaque axe recoit
        // un bruit de (rand & 0x3f) - 0x20 quarts d'unite. L'ordre des trois tirages est celui du
        // binaire — ils partagent une seule suite pseudo-aleatoire.
        int behind = heading + 0x800;

        int back = (int)Winsys3d.GetSinTableEntry(behind) * 60;
        sparkAt[0] = *(int*)(e + 0x1c) + back + (((CrtRand() & 0x3f) - 0x20) << 0xc);

        sparkAt[1] = *(int*)(e + 0x20) + (((CrtRand() & 0x3f) - 0x20) << 0xc);

        back = Winsys3d.GetCosTableEntry(behind) * 60;
        sparkAt[2] = *(int*)(e + 0x24) + back + (((CrtRand() & 0x3f) - 0x20) << 0xc);

        SpawnStatusEffectEntity_0047AC40(e, sparkAt, Descriptors00551AD8(), 0x46, e[0x0b], -1);

        // Le placement ecraserait la hauteur : elle est mise de cote et rendue tout de suite apres.
        int keptHeight = *(int*)(e + 0x20);
        FinalizeEntityPlacement2((uint*)e);               // Ghidra: FUN_00533940
        uint state = *(uint*)e;
        *(int*)(e + 0x20) = keptHeight;

        if ((state & 0x40000000) != 0 || (*(uint*)(e + 0x90) & 0x8802) != 0)
        {
            *(uint*)e = 0;                                // le decor : elle s'eteint sur place
            return;
        }

        byte* victim = ProbeMeleeTarget_00474CA0(e, probe);

        if (victim == null)
        {
            *(ushort*)(e + 0x10) += 1;
            if (*(short*)(e + 0x10) < 0x0c) return;       // douze images de vol

            *(uint*)e = 0;
            return;
        }

        // ------------------------------------------------------------------ le coup
        ResolveSpellHit_0053A2B0(*(uint**)(e + 0x74), (uint*)victim, e[7], e[6], 0);

        // La poussee : 16 unites sur le cap de la balle, celui-la NON corrige du quart de tour.
        int push = *(short*)(e + 0x32);
        *(int*)(victim + 0x50) += (int)Winsys3d.GetSinTableEntry(push) << 4;
        *(int*)(victim + 0x58) += Winsys3d.GetCosTableEntry(push) << 4;

        *(uint*)victim |= 0x40;
        *(ushort*)(victim + 0x96) = 0x10;

        Aud.PlayPositionalSound(0x13, 0x653, 0x1200, (int*)(e + 0x1c));   // Ghidra: FUN_0053db20

        *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_0047b050 @ 0x0047b050 — <b>l'etincelle</b> que le projectile de Balle de feu
    /// laisse derriere lui : le sous-type <c>0x46</c> de
    /// <see cref="s_StaticEntityHandlers_00552230"/>, la table de la passe <c>FUN_0047acf0</c> sur
    /// <c>0x005f2d40</c>. 91 octets, <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Le corps le plus court de la chaine, et le seul qui compte des images.</b> Le compteur
    /// <c>+0x10</c> monte d'une unite par image ; l'image d'atlas <c>+0x40</c> est sa <b>moitie</b>,
    /// si bien que chacun des quatre carreaux de <see cref="s_Descriptors_00551AD8"/> tient deux
    /// images. A la huitieme, le quotient atteint 4 et le mot d'etat passe a zero : l'etincelle
    /// vit <b>huit images</b>, ni plus ni moins.
    /// </para>
    /// <para>
    /// Pendant ce temps elle <b>monte</b> de <c>0xa000</c> par image, <b>retrecit</b> de
    /// <c>0x100</c> sur X et Y, et <b>palit</b> de <c>0x18</c> sur les trois canaux. Les deux
    /// dernieres sont des additions de <b>dword</b> dans l'original (<c>0xfeffff00</c> et
    /// <c>0xffe7e7e8</c>, soit <c>-0x01000100</c> et <c>-0x00181818</c>) : deux shorts et trois
    /// octets traites d'un seul coup, retenue comprise. C'est transcrit tel quel — la retenue fait
    /// partie du comportement, pas de l'astuce d'ecriture.
    /// </para>
    /// <para>
    /// L'echelle et la teinte ne sont posees qu'a la <b>premiere</b> image (<c>+0x10 == 0</c>) :
    /// <c>0x1800</c> sur X et Y, blanc plein. <see cref="SpawnStatusEffectEntity_0047AC40"/> a mis
    /// <c>+0x10</c> et <c>+0x40</c> a zero a la naissance, donc la branche est prise une fois.
    /// </para>
    /// </summary>
    private static void TickSpark_0047B050(byte* record)
    {
        byte* e = record;

        ushort counter = *(ushort*)(e + 0x10);

        if (counter == 0)
        {
            *(uint*)(e + 0x28) = 0x18001800;          // echelle X et Y
            *(uint*)(e + 0x38) = 0x00ffffff;          // teinte pleine
        }
        else
        {
            // Deux shorts et trois octets, en une addition de dword chacune.
            unchecked
            {
                *(uint*)(e + 0x28) += 0xfeffff00;     // -0x100 sur X et sur Y
                *(uint*)(e + 0x38) += 0xffe7e7e8;     // -0x18 sur les trois canaux
            }
        }

        *(int*)(e + 0x20) += 0xa000;                  // elle monte

        // `mov cx,dx ; sar cx,1` : la moitie, en SIGNE et sur seize bits. `cmp cl,4 ; jb` compare
        // ensuite l'octet BAS, non signe.
        short half = (short)((short)counter >> 1);
        e[0x40] = (byte)half;

        if ((byte)half >= 4) *(uint*)e = 0;

        *(ushort*)(e + 0x10) = (ushort)(counter + 1);
    }

    // =====================================================================
    // BOULE DE LUMIERE — le deuxieme sort, ecole 0 indice 1, sous-type 0x01
    //
    // Quatre corps, tous absents de Blaze.c. La forme est celle de Balle de feu, avec UNE
    // difference de fond : la boule ne meurt pas au contact.
    //
    //   0x0047B0B0   LA GRAINE. Sous-type 1 de 0x00551c30. Une image, comme celle du feu, mais
    //                elle avance de 40 et non de 80, ne se donne pas de modele, et fait naitre son
    //                enfant dans la table 0x005f2d40 par SpawnStatusEffectEntity_0047AC40 — pas
    //                dans celle des incantations. Il n'y a donc pas de projectile au sens du feu.
    //   0x0047B150   LA BOULE. Sous-type 0x47 de 0x00552230. Elle avance, seme deux sortes
    //                d'entites, cherche une cible — et CONTINUE apres l'avoir touchee. Douze
    //                images de vie quoi qu'il arrive.
    //   0x0047B340   L'ETINCELLE semee a chaque image (sous-type 0x48). Six images, trois tuiles
    //                en anneau.
    //   0x0047B3A0   LE HALO accroche a l'ancre (sous-type 0x49). Vingt images, il se recolle a
    //                chaque image sur l'entite de +0x78 et tire son image au hasard sur trois.
    //
    // CE QUI DISTINGUE CE SORT DU PRECEDENT. Balle de feu s'eteint des qu'elle touche
    // (`mov dword [esi],0` dans la branche du coup) ; ici la branche du coup RETOMBE sur le
    // vieillissement commun. Elle traverse donc, et peut frapper a chaque image de ses douze.
    // C'est ecrit tel quel : le binaire n'a aucune garde contre le coup repete.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047b0b0 @ 0x0047b0b0 — <b>la graine de Boule de lumiere</b> : le sous-type
    /// <c>0x01</c>, creneau 1 de <see cref="s_StaticEntityHandlers_00551c30"/>. 159 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Meme geste que <see cref="SpawnFireball_0047ADD0"/> — une image, se placer devant le lanceur
    /// a hauteur de tete, lacher l'enfant, jouer le son, s'eteindre — a quatre details pres :
    /// l'avance est de <b>40</b> et non 80, il n'y a <b>ni modele ni quart de tour</b>, l'echelle
    /// est <c>0x1400</c>, et l'enfant nait par
    /// <see cref="SpawnStatusEffectEntity_0047AC40"/> dans <c>0x005f2d40</c> et non par
    /// <see cref="SpawnCastEntity_0047AAE0"/> dans <c>0x005edee0</c>.
    /// </para>
    /// <para>
    /// <c>+0x36</c> est traite en <b>mot</b> (<c>&amp; 0xfffb | 2</c>) la ou la graine du feu se
    /// contentait d'un <c>|= 6</c> sur l'octet : ici le bit <c>4</c> est explicitement <b>efface</b>.
    /// </para>
    /// </summary>
    private static void SpawnLightBall_0047B0B0(byte* record)
    {
        byte* e = record;

        // `mov ax,[esi+36h] ; and al,0FBh ; or al,2 ; mov [esi+36h],ax` — l'octet haut est garde.
        *(ushort*)(e + 0x36) = (ushort)((*(ushort*)(e + 0x36) & 0xfffb) | 2);

        int heading = *(short*)(e + 0x32);

        // 40 unites devant le lanceur : `lea eax,[eax+eax*4] ; shl ecx,3`.
        *(int*)(e + 0x1c) += (int)Winsys3d.GetSinTableEntry(heading) * 40;
        *(int*)(e + 0x24) += Winsys3d.GetCosTableEntry(heading) * 40;

        int height = StatusBubbleHeight_00538BC0(*(uint**)(e + 0x74));
        *(int*)(e + 0x20) += (height & ~1) << 0xb;

        *(uint*)(e + 0x28) = 0x14001400;              // echelle X et Y
        *(uint*)(e + 0x38) = 0x00ffffff;              // teinte pleine

        SpawnStatusEffectEntity_0047AC40(
            e, (int*)(e + 0x1c), Descriptors00551BA8(), 0x47, e[0x0b], -1);

        Aud.PlayPositionalSound(0x14, 0x653, 0x1200, (int*)(e + 0x1c));   // Ghidra: FUN_0053db20

        *(uint*)e = 0;                                // la graine s'eteint des cette image
    }

    /// <summary>
    /// Ghidra: FUN_0047b150 @ 0x0047b150 — <b>la Boule de lumiere</b> elle-meme : le sous-type
    /// <c>0x47</c>, creneau 71 de <see cref="s_StaticEntityHandlers_00552230"/>. 492 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>A la premiere image</b> elle pose <c>0x80</c> sur son mot d'etat, se designe elle-meme en
    /// <c>+0x78</c> — le champ « cible trouvee », qui sert ici d'<b>ancre</b> pour le halo —, prend
    /// l'echelle <c>0x1000</c> et le blanc plein, et lache un premier halo <c>0x49</c>.
    /// </para>
    /// <para>
    /// <b>A chaque image</b> : 40 unites d'avance sur <c>+0x32</c> — <b>sans</b> la correction de
    /// quart de tour du projectile de feu, sa graine n'en ayant pas ajoute —, une etincelle
    /// <c>0x48</c> semee a la position bruitee de +/-32 unites de 4096 sur les trois axes, le
    /// replacement, puis la recherche de cible.
    /// </para>
    /// <para>
    /// <b>Le coup ne l'arrete pas.</b> La branche du contact resout les degats, <b>rattache le halo
    /// a la victime</b> (<c>+0x78</c> change d'ancre, et un second halo nait), pousse et marque la
    /// victime — puis <b>retombe sur le vieillissement commun</b>. Seules les douze images, le
    /// decor (<c>0x40000000</c>) ou <c>+0x90</c> sur le masque <c>0x8802</c> la tuent.
    /// </para>
    /// <para>
    /// <b>La poussee emploie <c>+0x32 - 0x400</c></b> alors que l'avance emploie <c>+0x32</c> nu.
    /// L'asymetrie est dans le binaire ; elle n'est pas expliquee ici, elle est transcrite.
    /// </para>
    /// </summary>
    private static void TickLightBall_0047B150(byte* record)
    {
        byte* e = record;

        // Meme forme que le projectile de feu : six mots de sonde, puis trois ints de position
        // dans le meme bloc de 0x18 octets. Aucun decalage de cap ici, et la moitie de l'avance.
        short* probe = stackalloc short[6] { 0x0000, -0x0032, 0x0032, 0x0064, 0x0000, 0x0064 };
        int* sparkAt = stackalloc int[3];

        if (*(ushort*)(e + 0x10) == 0)
        {
            *(uint*)e |= 0x80;

            // Elle est sa propre ancre tant qu'elle n'a rien touche.
            *(byte**)(e + 0x78) = e;

            *(uint*)(e + 0x28) = 0x10001000;
            *(uint*)(e + 0x38) = 0x00ffffff;

            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), Descriptors00551A60(), 0x49, e[0x0b], -1);
        }

        // Ghidra: LAB_0047b1c1 — le cap, pris tel quel.
        int heading = *(short*)(e + 0x32);

        *(int*)(e + 0x1c) += (int)Winsys3d.GetSinTableEntry(heading) * 40;
        *(int*)(e + 0x24) += Winsys3d.GetCosTableEntry(heading) * 40;

        // L'etincelle nait sur place, seulement bruitee. L'ordre des trois tirages est celui du
        // binaire — ils partagent une seule suite pseudo-aleatoire.
        sparkAt[0] = *(int*)(e + 0x1c) + (((CrtRand() & 0x3f) - 0x20) << 0xc);
        sparkAt[1] = *(int*)(e + 0x20) + (((CrtRand() & 0x3f) - 0x20) << 0xc);
        sparkAt[2] = *(int*)(e + 0x24) + (((CrtRand() & 0x3f) - 0x20) << 0xc);

        SpawnStatusEffectEntity_0047AC40(e, sparkAt, Descriptors005519A0(), 0x48, e[0x0b], -1);

        // Le placement ecraserait la hauteur : elle est mise de cote et rendue tout de suite apres.
        int keptHeight = *(int*)(e + 0x20);
        FinalizeEntityPlacement2((uint*)e);               // Ghidra: FUN_00533940
        uint state = *(uint*)e;
        *(int*)(e + 0x20) = keptHeight;

        if ((state & 0x40000000) != 0 || (*(uint*)(e + 0x90) & 0x8802) != 0)
        {
            *(uint*)e = 0;                                // le decor : elle s'eteint sur place
            return;
        }

        byte* victim = ProbeMeleeTarget_00474CA0(e, probe);

        if (victim != null)
        {
            ResolveSpellHit_0053A2B0(*(uint**)(e + 0x74), (uint*)victim, e[7], e[6], 0);

            // Le halo change d'ancre : il suivra desormais la victime.
            *(byte**)(e + 0x78) = victim;

            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), Descriptors00551A60(), 0x49, e[0x0b], -1);

            int push = *(short*)(e + 0x32) - 0x400;
            *(int*)(victim + 0x50) += (int)Winsys3d.GetSinTableEntry(push) << 4;
            *(int*)(victim + 0x58) += Winsys3d.GetCosTableEntry(push) << 4;

            *(uint*)victim |= 0x40;
            *(ushort*)(victim + 0x96) = 0x10;

            Aud.PlayPositionalSound(0x14, 0x800, 0x1200, (int*)(e + 0x1c));
        }

        // Ghidra: LAB_0047b319 — le vieillissement, commun aux deux branches. C'est LA difference
        // avec Balle de feu : le coup n'eteint pas la boule, elle traverse.
        *(ushort*)(e + 0x10) += 1;
        if (*(short*)(e + 0x10) < 0x0c) return;

        *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_0047b340 @ 0x0047b340 — <b>l'etincelle de Boule de lumiere</b> : le sous-type
    /// <c>0x48</c>, creneau 72 de <see cref="s_StaticEntityHandlers_00552230"/>. 88 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// La sœur de <see cref="TickSpark_0047B050"/>, a trois differences : elle vit <b>six</b>
    /// images et non huit, elle palit deux fois plus vite (<c>-0x20</c> par canal contre
    /// <c>-0x18</c>), et son image d'atlas <b>tourne en anneau</b> sur les trois tuiles de
    /// <see cref="s_Descriptors_005519A0"/> au lieu d'etre la moitie du compteur. C'est ce
    /// bouclage a 3 qui borne cet atlas, et il le borne deja pour un autre consommateur.
    /// </para>
    /// </summary>
    private static void TickLightSparkle_0047B340(byte* record)
    {
        byte* e = record;

        ushort counter = *(ushort*)(e + 0x10);

        if (counter == 0)
        {
            *(uint*)(e + 0x28) = 0x10001000;          // echelle X et Y
            *(uint*)(e + 0x38) = 0x00ffffff;          // teinte pleine
        }
        else
        {
            // Deux shorts et trois octets, en une addition de dword chacune.
            unchecked
            {
                *(uint*)(e + 0x28) += 0xfeffff00;     // -0x100 sur X et sur Y
                *(uint*)(e + 0x38) += 0xffdfdfe0;     // -0x20 sur les trois canaux
            }
        }

        // `inc dl ; cmp dl,3 ; mov [eax+40h],dl ; jb ; mov byte [eax+40h],0` — l'ecriture precede
        // la remise a zero, ce qui revient a un anneau de trois.
        byte frame = (byte)(e[0x40] + 1);
        e[0x40] = frame < 3 ? frame : (byte)0;

        counter = (ushort)(counter + 1);
        *(ushort*)(e + 0x10) = counter;

        if ((short)counter >= 6) *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_0047b3a0 @ 0x0047b3a0 — <b>le halo de Boule de lumiere</b> : le sous-type
    /// <c>0x49</c>, creneau 73 de <see cref="s_StaticEntityHandlers_00552230"/>. 191 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Il ne se deplace pas, il se recolle.</b> A chaque image il reprend la position de l'entite
    /// que <c>+0x78</c> designe — la boule d'abord, la victime ensuite — bruitee de +/-32 unites de
    /// 4096 sur X et Z, et decalee en hauteur de la tete de l'ancre. Son image d'atlas est
    /// <b>tiree au hasard sur trois</b> a chaque image, ce qui borne
    /// <see cref="s_Descriptors_00551A60"/> exactement comme <c>FUN_00475910</c> le borne deja.
    /// </para>
    /// <para>
    /// <b>La taille est celle de l'ancre</b>, mesuree une seule fois : <c>(hauteur &lt;&lt; 12) /
    /// 150</c>, la meme division par multiplication magique <c>0x1B4E81B5</c> que
    /// <see cref="TickCastAura_004765D0"/> emploie. Le calcul est saute quand l'ancre porte
    /// <c>0x100000</c> — le bit du modele de paquet —, auquel cas <c>+0x12</c> reste nul et le halo
    /// colle au sol.
    /// </para>
    /// <para>
    /// <b>Deux fins</b> : vingt images, ou l'ancre qui s'eteint (son bit <c>0x80000000</c> tombe).
    /// La seconde est ce qui fait disparaitre le halo avec la boule.
    /// </para>
    /// </summary>
    private static void TickLightHalo_0047B3A0(byte* record)
    {
        byte* e = record;
        byte* anchor = *(byte**)(e + 0x78);

        if (*(ushort*)(e + 0x10) == 0 && (*(uint*)anchor & 0x100000) == 0)
        {
            short height = (short)StatusBubbleHeight_00538BC0((uint*)anchor);
            *(short*)(e + 0x12) = height;

            // `imul 0x1B4E81B5 ; sar edx,4` et la correction de signe : une division par 150.
            int scale = (height << 0xc) / 150;
            *(uint*)(e + 0x28) = ((uint)scale << 0x10) | (uint)scale;
        }

        // Ghidra: LAB_0047b3e6 — le recollage, hors de toute branche d'etat.
        *(int*)(e + 0x1c) = *(int*)(anchor + 0x1c) + (((CrtRand() & 0x3f) - 0x20) << 0xc);

        // La hauteur n'est pas bruitee comme les deux autres axes : `lea eax,[edx+eax*2-40h]` la
        // melange au tirage AVANT le decalage de 11 bits, l'arrondi au pair compris.
        int lift = (*(short*)(e + 0x12) & ~1) + (CrtRand() & 0x3f) * 2 - 0x40;
        *(int*)(e + 0x20) = *(int*)(anchor + 0x20) + (lift << 0xb);

        *(int*)(e + 0x24) = *(int*)(anchor + 0x24) + (((CrtRand() & 0x3f) - 0x20) << 0xc);

        *(ushort*)(e + 0x10) += 1;

        if (*(short*)(e + 0x10) >= 0x14 || (*(uint*)anchor & 0x80000000) == 0)
        {
            *(uint*)e = 0;
            return;
        }

        e[0x40] = (byte)(CrtRand() % 3);              // `cdq ; idiv 3`, le reste
    }

    // =====================================================================
    // PIEDS MOUILLES — le troisieme sort, ecole 0 indice 2, sous-type 0x02
    //
    // Trois corps, et une forme NOUVELLE : il n'y a pas de graine. Le sous-type 2 de la table des
    // effets EST le sort — il se deplace, rebondit et frappe lui-meme, la ou les deux premiers
    // sorts naissaient d'une graine d'une seule image.
    //
    //   0x0047B460   LA VAGUE. Sous-type 2 de 0x00551c30. Vingt images. Elle avance de 20 par
    //                image, TOMBE (une vitesse verticale en +0x54 que la gravite ronge), colle au
    //                sol quand elle le touche, seme deux enfants a chaque image et frappe.
    //   0x0047B6B0   LA CRETE, sous-type 0x66 de 0x00551f30, semee par SpawnCastEntity_0047AAE0.
    //                Modele 0x1e, huit images, et sa hauteur suit une SINUSOIDE amortie.
    //   0x0047B750   L'ECLABOUSSURE, sous-type 0x4a de 0x00552230. Elle vole par
    //                IntegrateWithDrag_00535880 et s'eteint quand sa teinte atteint zero.
    //
    // LE PRET DES TROIS CHAMPS DE VITESSE. Avant de lacher l'eclaboussure, le corps ECRASE
    // +0x50/+0x54/+0x58 avec une impulsion tiree au hasard, appelle SpawnStatusEffectEntity_0047AC40
    // — qui recopie les 0x27 dwords, donc emporte l'impulsion — puis les REND. C'est le meme geste
    // que CastSpell_0053A980 fait sur +0x74/+0x78 : passer un argument par un champ de l'entite,
    // faute de parametre.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047b460 @ 0x0047b460 — <b>Pieds mouilles</b> : le sous-type <c>0x02</c>,
    /// creneau 2 de <see cref="s_StaticEntityHandlers_00551c30"/>. 583 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Le premier sort qui n'a pas de graine.</b> Les deux precedents naissaient d'un corps
    /// d'une seule image qui lachait le vrai projectile ; ici le sous-type que
    /// <see cref="CastSpell_0053A980"/> fait naitre est deja la vague, et il vit vingt images.
    /// </para>
    /// <para>
    /// <b>Et le premier qui tombe.</b> <c>+0x54</c> porte une vitesse verticale, <c>+0x9a</c> une
    /// constante de <c>0x6000</c> reecrite a chaque image, et la mise a jour est
    /// <c>v' = v + (c &gt;&gt; 8) - (v &gt;&gt; 8) - c</c> : un frottement au 256e et une chute
    /// constante, dans la meme expression. Le sol vient de <c>+0x60</c>, que
    /// <see cref="FinalizeEntityPlacement2"/> vient de renseigner.
    /// </para>
    /// <para>
    /// <b>Le contact avec le sol se decide sur la distance parcourue</b>, pas sur la seule hauteur :
    /// si la hauteur d'avant le placement, majoree de <c>0xa000</c>, depasse encore la hauteur
    /// d'apres, la vague <b>colle au sol</b> ; sinon elle marque <c>0x800</c> dans <c>+0x90</c> —
    /// le drapeau qui la tuera a l'image suivante par le masque <c>0x802</c>. Dans les deux cas la
    /// vitesse verticale est remise a zero.
    /// </para>
    /// <para>
    /// La poussee de la victime emploie <c>+0x32</c> nu et marque <c>+0x96 = 4</c>, non
    /// <c>0x10</c> : un clignotement plus court que celui des deux premiers sorts. Il n'y a
    /// <b>pas de son au contact</b> — le seul son est celui de la premiere image.
    /// </para>
    /// </summary>
    private static void TickWetFeet_0047B460(byte* record)
    {
        byte* e = record;

        // Six mots de sonde : aucun decalage de cap, 10 en arriere, 60 de demi-largeur — deux fois
        // plus large que les deux sorts precedents, c'est une vague.
        short* probe = stackalloc short[6] { 0x0000, -0x000a, 0x003c, 0x0064, 0x0000, 0x0064 };

        if (*(ushort*)(e + 0x10) == 0)
        {
            *(uint*)e |= 0x80;
            *(ushort*)(e + 0x36) = (ushort)((*(ushort*)(e + 0x36) & 0xfffb) | 2);
            *(short*)(e + 0x2e) = -0x14;
            *(int*)(e + 0x54) = 0;                    // la vitesse verticale part de zero

            Aud.PlayPositionalSound(0x18, 0x6fd, 0x1200, (int*)(e + 0x1c));
        }

        // Ghidra: LAB_0047b4d3 — tout ce qui suit tourne a chaque image.
        int heading = *(short*)(e + 0x32);
        *(short*)(e + 0x9a) = 0x6000;                 // reecrite a chaque image, jamais lue ailleurs

        // 20 unites d'avance : `lea eax,[eax+eax*4] ; shl eax,2`.
        *(int*)(e + 0x1c) += (int)Winsys3d.GetSinTableEntry(heading) * 20;
        *(int*)(e + 0x24) += Winsys3d.GetCosTableEntry(heading) * 20;

        // La chute. L'ordre compte : la hauteur prend l'ANCIENNE vitesse.
        int gravity = *(short*)(e + 0x9a);
        int velocity = *(int*)(e + 0x54);
        *(int*)(e + 0x20) += velocity;
        *(int*)(e + 0x54) = velocity + (gravity >> 8) - (velocity >> 8) - gravity;

        SpawnCastEntity_0047AAE0(e, 0x66, e[0x0b], -1);

        // ---------------------------------------------------------------- l'eclaboussure
        // Les trois champs de vitesse sont PRETES a l'enfant : il en herite par la recopie des
        // 0x27 dwords, puis ils sont rendus intacts.
        int keptX = *(int*)(e + 0x50);
        int keptY = *(int*)(e + 0x54);
        int keptZ = *(int*)(e + 0x58);

        // Un cap disperse sur un quart de tour, decale d'un tiers et demi : `rand & 0x3ff`,
        // plus le cap, plus 0x600.
        int spray = (CrtRand() & 0x3ff) + *(short*)(e + 0x32) + 0x600;

        *(int*)(e + 0x50) = (int)Winsys3d.GetSinTableEntry(spray) * 20;
        *(int*)(e + 0x54) = ((CrtRand() & 0xf) + 0x14) << 0xc;
        *(int*)(e + 0x58) = Winsys3d.GetCosTableEntry(spray) * 20;

        SpawnStatusEffectEntity_0047AC40(
            e, (int*)(e + 0x1c), Descriptors00551BB8(), 0x4a, e[0x0b], -1);

        int beforePlacement = *(int*)(e + 0x20);

        *(int*)(e + 0x50) = keptX;
        *(int*)(e + 0x54) = keptY;
        *(int*)(e + 0x58) = keptZ;

        FinalizeEntityPlacement2((uint*)e);           // Ghidra: FUN_00533940

        // ---------------------------------------------------------------- le sol
        int height = *(int*)(e + 0x20);
        int ground = *(int*)(e + 0x60);

        if (height >= ground && (*(uint*)(e + 0x90) & 0x2200) != 0x2000)
        {
            if (beforePlacement + 0xa000 > height) *(int*)(e + 0x20) = ground;
            else *(uint*)(e + 0x90) |= 0x800;         // `or dh,8`

            *(int*)(e + 0x54) = 0;
        }

        // Ghidra: LAB_0047b60b — le masque est 0x802 ici, pas 0x8802 : le bit 0x8000 ne la tue pas.
        if ((*(uint*)e & 0x40000000) != 0 || (*(uint*)(e + 0x90) & 0x802) != 0)
        {
            *(uint*)e = 0;
            return;
        }

        byte* victim = ProbeMeleeTarget_00474CA0(e, probe);

        if (victim != null)
        {
            ResolveSpellHit_0053A2B0(*(uint**)(e + 0x74), (uint*)victim, e[7], e[6], 0);

            int push = *(short*)(e + 0x32);
            *(int*)(victim + 0x50) += (int)Winsys3d.GetSinTableEntry(push) << 4;
            *(ushort*)(victim + 0x96) = 4;
            *(int*)(victim + 0x58) += Winsys3d.GetCosTableEntry(push) << 4;
            *(uint*)victim |= 0x40;
        }

        // Ghidra: LAB_0047b687 — deux compteurs avancent, un seul borne la vie. `+0x12` est celui
        // que la crete lit pour sa sinusoide.
        *(ushort*)(e + 0x10) += 1;
        ushort age = *(ushort*)(e + 0x10);
        *(ushort*)(e + 0x12) += 1;

        if ((short)age >= 0x14) *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_0047b6b0 @ 0x0047b6b0 — <b>la crete de Pieds mouilles</b> : le sous-type
    /// <c>0x66</c>, creneau 102 de <see cref="s_StaticEntityHandlers_00551f30"/>. 148 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Sa hauteur est une sinusoide amortie</b>, et c'est ce qui donne la vague : l'echelle Y
    /// (<c>+0x2a</c>) vaut <c>|sin(+0x12 &lt;&lt; 8)| * (0x1000 - age * 0x200) &gt;&gt; 11</c>.
    /// Le <c>+0x12</c> vient de la vague qui l'a semee — chaque crete nait donc un cran plus loin
    /// dans la sinusoide que la precedente, et l'ensemble ondule.
    /// </para>
    /// <para>
    /// <b>La valeur absolue est calculee en appelant la table DEUX FOIS.</b> Le binaire teste le
    /// signe du premier appel puis rappelle <c>Ordinal_451</c> avec le meme angle, pour nier ou non.
    /// La table est une lecture pure, donc le second appel rend exactement le premier : c'est
    /// ecrit ici comme la valeur absolue qu'il calcule, et non comme deux appels.
    /// </para>
    /// <para>
    /// Pendant ce temps l'echelle X perd <c>0x380</c> par image et la teinte <c>0x101010</c> — le
    /// blanc plein <c>0x808080</c> de la convention winsys3d, pas <c>0xffffff</c>. Huit images.
    /// </para>
    /// </summary>
    private static void TickWetFeetWave_0047B6B0(byte* record)
    {
        byte* e = record;

        if (*(ushort*)(e + 0x10) == 0)
        {
            *(uint*)(e + 0x38) = 0x00808080;          // le blanc PLEIN de winsys3d
            *(ushort*)(e + 0x28) = 0x1800;
            *(ushort*)(e + 0x2c) = 0x1800;
            e[0x04] = 0x1e;                           // le modele
        }
        else
        {
            unchecked { *(uint*)(e + 0x38) += 0xffefeff0; }   // -0x101010
        }

        // Ghidra: LAB_0047b6de — l'aplatissement et l'onde, communs aux deux branches.
        unchecked { *(ushort*)(e + 0x28) += 0xfc80; }         // -0x380

        int angle = *(short*)(e + 0x12) << 8;
        int wave = (int)Winsys3d.GetSinTableEntry(angle);
        if (wave < 0) wave = -wave;                   // le binaire rappelle la table pour nier

        ushort age = *(ushort*)(e + 0x10);
        int decay = 0x1000 - ((short)age << 9);
        *(short*)(e + 0x2a) = (short)(decay * wave >> 0xb);

        age = (ushort)(age + 1);
        *(ushort*)(e + 0x10) = age;

        if ((short)age >= 8) *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_0047b750 @ 0x0047b750 — <b>l'eclaboussure de Pieds mouilles</b> : le sous-type
    /// <c>0x4a</c>, creneau 74 de <see cref="s_StaticEntityHandlers_00552230"/>. 66 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Le seul corps de la chaine qui ne compte pas les images : <b>c'est sa teinte qui lui tient
    /// lieu d'horloge</b>. Elle part de <c>0xf0f0f0</c> et perd <c>0x101010</c> par image ; a la
    /// seizieme le dword tombe pile a zero et l'entite s'eteint. Le test est
    /// <c>e[0x38] == 0</c> — une egalite exacte, qui ne tient que parce que les trois canaux
    /// descendent du meme pas et partent de la meme valeur.
    /// </para>
    /// <para>
    /// Son mouvement est celui que la vague lui a prete dans <c>+0x50</c>/<c>+0x54</c>/<c>+0x58</c>,
    /// integre par <see cref="IntegrateWithDrag_00535880"/>.
    /// </para>
    /// </summary>
    private static void TickWetFeetSplash_0047B750(byte* record)
    {
        byte* e = record;

        if (*(ushort*)(e + 0x10) == 0)
        {
            *(ushort*)(e + 0x10) = 1;
            *(uint*)(e + 0x38) = 0x00f0f0f0;
            *(uint*)(e + 0x28) = 0x20002000;
        }

        IntegrateWithDrag_00535880(e);                // Ghidra: FUN_00535880

        uint tint = *(uint*)(e + 0x38);

        if (tint == 0)
        {
            *(uint*)e = 0;
            return;
        }

        unchecked { *(uint*)(e + 0x38) = tint + 0xffefeff0; }   // -0x101010
    }

    // =====================================================================
    // ROCHER — le quatrieme sort, ecole 0 indice 3, sous-type 0x03
    //
    // Trois corps, et une forme encore nouvelle : le sort ne va nulle part, il TOURNE AUTOUR DU
    // LANCEUR et compte ses enfants.
    //
    //   0x0047B7A0   LE CERCLE. Sous-type 3 de 0x00551c30. Il se colle au lanceur, ne bouge pas,
    //                et lache un rocher toutes les quatre images pendant seize — quatre rochers.
    //                Puis il ATTEND : il ne s'eteint que lorsque ses deux compteurs tombent a zero.
    //   0x0047B850   LE ROCHER, sous-type 0x69 de 0x00551f30. Il orbite autour du lanceur, son
    //                orbite ralentit d'un huitieme par image, puis il est PROJETE et vole librement
    //                jusqu'au sol ou jusqu'a une cible.
    //   0x0047BB10   LA POUSSIERE, sous-type 0x4b de 0x00552230. Huit images, quatre tuiles.
    //
    // LES DEUX COMPTEURS SONT UN COMPTE DE REFERENCES, le premier du depot. Le cercle pose
    // +0x14 = +0x16 = 4 ; chaque rocher DECREMENTE +0x14 du cercle (par son +0x6c) quand il quitte
    // l'orbite, et +0x16 quand il meurt. Le cercle relache la marque 0x80 du lanceur quand +0x14
    // atteint zero — les quatre rochers sont partis — et ne s'eteint lui-meme que quand +0x16
    // atteint zero — les quatre sont retombes. C'est ce qui tient le lanceur immobile le temps du
    // sort.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047b7a0 @ 0x0047b7a0 — <b>le cercle de Rocher</b> : le sous-type <c>0x03</c>,
    /// creneau 3 de <see cref="s_StaticEntityHandlers_00551c30"/>. 176 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Il ne se deplace pas : a chaque image il <b>recopie la position du lanceur</b> et se pose a
    /// <c>+0x60</c> — le <b>sol</b> sous lui, pas sa hauteur. Toutes les quatre images
    /// (<c>compteur &amp; 3</c>) il lache un rocher et joue un son ; seize images, donc quatre
    /// rochers.
    /// </para>
    /// <para>
    /// <b>Ensuite il attend.</b> Passe la seizieme image il ne fait plus que surveiller ses deux
    /// compteurs : <c>+0x14</c> a zero relache la marque <c>0x80</c> qu'il avait posee sur le
    /// lanceur, <c>+0x16</c> a zero l'eteint lui-meme. Ce sont les rochers qui les decrementent —
    /// voir <see cref="TickRock_0047B850"/>.
    /// </para>
    /// </summary>
    private static void TickRockCircle_0047B7A0(byte* record)
    {
        byte* e = record;
        ushort age = *(ushort*)(e + 0x10);

        if ((short)age >= 0x10)
        {
            // Ghidra: LAB_0047b82f — l'attente. Les deux compteurs sont tenus par les rochers.
            if (*(ushort*)(e + 0x14) == 0) *(uint*)(*(byte**)(e + 0x74)) &= 0xffffff7f;
            if (*(ushort*)(e + 0x16) == 0) *(uint*)e = 0;
            return;
        }

        byte* caster = *(byte**)(e + 0x74);

        if (age == 0)
        {
            *(uint*)caster |= 0x80;                   // le lanceur est immobilise
            *(ushort*)(e + 0x36) = (ushort)((*(ushort*)(e + 0x36) & 0xfffb) | 2);
            *(uint*)(e + 0x38) = 0x01000000;
            e[0x40] = 0;
            *(ushort*)(e + 0x14) = 4;                 // quatre rochers a lacher
            *(ushort*)(e + 0x16) = 4;                 // quatre rochers a voir mourir
        }

        // Ghidra: LAB_0047b7e5 — il se recolle au lanceur a chaque image.
        *(int*)(e + 0x1c) = *(int*)(caster + 0x1c);
        *(int*)(e + 0x24) = *(int*)(caster + 0x24);
        *(int*)(e + 0x20) = *(int*)(caster + 0x60);   // le SOL sous le lanceur

        if ((e[0x10] & 3) == 0)
        {
            SpawnCastEntity_0047AAE0(e, 0x69, e[0x0b], -1);
            Aud.PlayPositionalSound(0x16, 0x329, 0x1200, (int*)(e + 0x1c));
        }

        *(ushort*)(e + 0x10) += 1;
    }

    /// <summary>
    /// Ghidra: FUN_0047b850 @ 0x0047b850 — <b>le rocher</b> : le sous-type <c>0x69</c>, creneau 105
    /// de <see cref="s_StaticEntityHandlers_00551f30"/>. 700 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Deux vies en une.</b> Tant que <c>+0x12</c> — la vitesse angulaire — vaut <c>0x10</c> ou
    /// plus, le rocher <b>orbite</b> : sa position est recalculee a 90 unites du lanceur sur le cap
    /// <c>+0x32</c>, il monte de <c>0x7000</c> par image, et la vitesse angulaire perd un huitieme
    /// d'elle-meme a chaque tour. Des qu'elle passe sous <c>0x10</c> il est <b>projete</b> : une
    /// impulsion tiree au hasard part dans <c>+0x50</c>/<c>+0x58</c>, le bit <c>0x2000000</c> le
    /// marque comme lance, et il vole ensuite par
    /// <see cref="IntegrateWithDrag_00535880"/>.
    /// </para>
    /// <para>
    /// <b>Il tient les comptes de son semeur</b>, atteint par <c>+0x6c</c> : <c>-1</c> sur
    /// <c>+0x14</c> quand il quitte l'orbite, <c>-1</c> sur <c>+0x16</c> quand il meurt. Le bit
    /// <c>0x2000000</c> sert de garde — un rocher qui meurt avant d'avoir ete lance decremente
    /// <b>les deux</b>, pour que le compte reste juste.
    /// </para>
    /// <para>
    /// <b>Le test de sol est inverse par rapport a Pieds mouilles</b>, et c'est dans le binaire :
    /// <see cref="TickWetFeet_0047B460"/> traite le sol quand <c>+0x20 &gt;= +0x60</c>, celui-ci
    /// quand <c>+0x20 &lt;= +0x60</c>. Les deux sont transcrits tels quels ;
    /// <c>TODO(REVERSE)</c> : etablir lequel des deux lit le champ dans le bon sens, ou si les deux
    /// chemins ne se recouvrent jamais.
    /// </para>
    /// </summary>
    private static void TickRock_0047B850(byte* record)
    {
        byte* e = record;
        byte* caster = *(byte**)(e + 0x74);

        short* probe = stackalloc short[6] { 0x0000, -0x0032, 0x0032, 0x0064, 0x0000, 0x0064 };

        if (*(ushort*)(e + 0x10) == 0)
        {
            // ------------------------------------------------------------ la naissance
            *(uint*)e |= 0x80;

            // Le binaire garde le tirage ENTIER dans un registre et n'en range que les seize bits
            // bas ; la table de trigonometrie ne lit que douze bits, donc les deux sont le meme
            // angle. Ecrit comme le binaire le fait.
            int spin = CrtRand();
            *(short*)(e + 0x32) = (short)spin;
            *(short*)(e + 0x34) = (short)CrtRand();

            *(int*)(e + 0x20) = *(int*)(caster + 0x60) + 1;

            // 90 unites : `lea *5 ; lea *9 ; lea [edx+ecx*2]`.
            *(int*)(e + 0x1c) = *(int*)(caster + 0x1c) + (int)Winsys3d.GetSinTableEntry(spin) * 90;
            *(int*)(e + 0x24) = *(int*)(caster + 0x24) + Winsys3d.GetCosTableEntry(spin) * 90;

            uint scale = (uint)((CrtRand() & 0x1ff) + 0x600);
            *(uint*)(e + 0x28) = (scale << 0x10) | scale;
            *(ushort*)(e + 0x2c) = (ushort)scale;
            *(uint*)(e + 0x38) = 0x02ffffff;
            e[0x04] = 0x1b;                           // le modele

            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), Descriptors00551A98(), 0x4b, e[0x0b], -1);

            *(short*)(e + 0x12) = 0x200;              // la vitesse angulaire de depart
        }
        else if (*(short*)(e + 0x12) >= 0x10)
        {
            // ------------------------------------------------------------ l'orbite
            short speed = *(short*)(e + 0x12);
            speed -= (short)(speed >> 3);             // elle perd un huitieme par image
            *(short*)(e + 0x32) += speed;
            *(short*)(e + 0x12) = speed;

            int heading = *(short*)(e + 0x32);
            *(int*)(e + 0x1c) = *(int*)(caster + 0x1c) + (int)Winsys3d.GetSinTableEntry(heading) * 90;
            *(int*)(e + 0x24) = *(int*)(caster + 0x24) + Winsys3d.GetCosTableEntry(heading) * 90;
            *(int*)(e + 0x20) += 0x7000;

            if (*(short*)(e + 0x12) < 0x10)
            {
                // ------------------------------------------------------------ la projection
                *(short*)(e + 0x9a) = 0x6000;

                // Le cap du LANCEUR, disperse sur un huitieme de tour et recentre de 0x100.
                int throwAngle = (CrtRand() & 0x1ff) + *(short*)(caster + 0x32) - 0x100;

                int sin = (int)Winsys3d.GetSinTableEntry(throwAngle);
                *(int*)(e + 0x50) = sin * ((CrtRand() & 0x1f) + 0x32);

                int cos = Winsys3d.GetCosTableEntry(throwAngle);
                *(int*)(e + 0x58) = cos * ((CrtRand() & 0x1f) + 0x32);

                (*(ushort*)(*(byte**)(e + 0x6c) + 0x14))--;   // un rocher de moins en orbite
                *(uint*)e |= 0x2000000;
            }
        }
        else
        {
            // Ghidra: LAB_0047b9ee — le vol libre, une fois l'orbite quittee.
            IntegrateWithDrag_00535880(e);            // Ghidra: FUN_00535880
        }

        // Ghidra: LAB_0047b9f7 — le placement, commun aux trois branches.
        FinalizeEntityPlacement2((uint*)e);           // Ghidra: FUN_00533940

        uint contact = *(uint*)(e + 0x90);
        bool airborne = (contact & 0xa000) != 0;      // `test ah,0A0h`

        if (!airborne && (contact & 0x802) == 0 && *(int*)(e + 0x20) > *(int*)(e + 0x60))
        {
            airborne = true;
        }

        if (!airborne)
        {
            // ------------------------------------------------------------ l'impact au sol
            *(int*)(e + 0x20) = *(int*)(e + 0x60);

            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), Descriptors00551A98(), 0x4b, e[0x0b], -1);

            byte* circle = *(byte**)(e + 0x6c);
            if ((*(uint*)e & 0x2000000) == 0) (*(ushort*)(circle + 0x14))--;
            (*(ushort*)(circle + 0x16))--;

            *(uint*)e = 0;

            Aud.PlayPositionalSound(4, 0x4aa, 0x1200, (int*)(e + 0x1c));
            return;
        }

        // Ghidra: LAB_0047ba78 — en l'air : il cherche une cible.
        byte* victim = ProbeMeleeTarget_00474CA0(e, probe);

        if (victim != null)
        {
            ResolveSpellHit_0053A2B0(*(uint**)(e + 0x74), (uint*)victim, e[7], e[6], 0);

            int push = *(short*)(e + 0x32);
            *(int*)(victim + 0x50) += (int)Winsys3d.GetSinTableEntry(push) << 4;
            *(ushort*)(victim + 0x96) = 0x10;
            *(int*)(victim + 0x58) += Winsys3d.GetCosTableEntry(push) << 4;
            *(uint*)victim |= 0x40;
        }

        // Ghidra: LAB_0047badc — le mot d'etat est relu APRES le coup.
        uint state = *(uint*)e;
        *(ushort*)(e + 0x10) += 1;

        if ((state & 0x60000000) != 0)
        {
            byte* circle = *(byte**)(e + 0x6c);
            if ((state & 0x2000000) == 0) (*(ushort*)(circle + 0x14))--;
            (*(ushort*)(circle + 0x16))--;

            *(uint*)e = 0;
        }
    }

    /// <summary>
    /// Ghidra: FUN_0047bb10 @ 0x0047bb10 — <b>la poussiere de Rocher</b> : le sous-type <c>0x4b</c>,
    /// creneau 75 de <see cref="s_StaticEntityHandlers_00552230"/>. 60 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// La jumelle de <see cref="TickSpark_0047B050"/> : huit images, l'image d'atlas est la moitie
    /// du compteur, quatre tuiles. Deux differences, toutes deux dans le binaire — le decalage est
    /// <b>non signe</b> (<c>shr</c> et non <c>sar</c>) et la comparaison porte sur le <b>mot</b>
    /// entier (<c>cmp cx,4</c>) et non sur son octet bas. Ni echelle ni teinte ne bougent apres la
    /// premiere image : elle ne fait que derouler ses quatre images.
    /// </para>
    /// </summary>
    private static void TickRockDust_0047BB10(byte* record)
    {
        byte* e = record;

        ushort counter = *(ushort*)(e + 0x10);
        ushort frame = (ushort)(counter >> 1);        // `shr cx,1` — NON signe

        if (counter == 0)
        {
            *(uint*)(e + 0x28) = 0x10001000;
            *(uint*)(e + 0x38) = 0x01000000;
            *(short*)(e + 0x2e) = -0x14;
        }

        if (frame >= 4) *(uint*)e = 0;

        e[0x40] = (byte)frame;
        *(ushort*)(e + 0x10) = (ushort)(counter + 1);
    }

    // =====================================================================
    // FEU D'ENFER — le cinquieme sort, ecole 0 indice 4, sous-type 0x04
    //
    // Trois corps a ecrire, et un quatrieme qui existait deja.
    //
    //   0x0047BB50   LE SORT. Sous-type 4 de 0x00551c30. Il CHOISIT UNE CIBLE des la premiere
    //                image, lache six flammes et un embrasement autour d'elle, puis attend
    //                soixante images avant de poser l'effet d'etat et de s'eteindre.
    //   0x0047BC40   LA FLAMME, sous-type 0x67 de 0x00551f30. Six exemplaires, en deux anneaux de
    //                trois inclines en sens contraires.
    //   0x0047BDF0   L'EMBRASEMENT, sous-type 0x4c de 0x00552230. Il grossit, puis a la 32e image
    //                lache DEUX braises 0x68 et se resorbe.
    //   0x0047BD00   LA BRAISE, sous-type 0x68 — deja ecrite et deja exercee en foret. Rien a
    //                faire : ce sort est le premier a reutiliser un corps que le depot avait.
    //
    // LE PREMIER SORT QUI VISE. Les quatre precedents partaient devant le lanceur ou tournaient
    // autour de lui ; celui-ci appelle FindTargetAround_00474BA0 des sa naissance, range la cible
    // en +0x78, et TOUS ses enfants la suivent — la recopie des 0x27 dwords la leur transmet. Les
    // flammes et l'embrasement se recollent sur elle a chaque image.
    //
    // ET LE PREMIER A DIFFERER SON EFFET. A la soixantieme image il recopie sa paire
    // famille/indice sur le lanceur et appelle ApplyStatusEffect_0053BA90 — l'entree 15 de la table
    // des 48. Il n'y a pas de recherche de cible a ce moment-la : c'est celle d'il y a soixante
    // images qui brule.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047bb50 @ 0x0047bb50 — <b>Feu d'enfer</b> : le sous-type <c>0x04</c>, creneau 4
    /// de <see cref="s_StaticEntityHandlers_00551c30"/>. 240 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>A la naissance</b> il choisit sa cible par
    /// <see cref="FindTargetAround_00474BA0"/> et la range en <c>+0x78</c>, prend le modele
    /// <c>0x0f</c>, puis lache <b>six flammes en deux anneaux</b> : trois a l'inclinaison
    /// <c>+0x155</c>, trois a <c>-0x155</c>, chacune decalee d'un tiers de tour
    /// (<c>0x555</c>) et les deux anneaux decales entre eux de <c>0x2aa</c> — un sixieme de tour.
    /// Puis l'embrasement et le son.
    /// </para>
    /// <para>
    /// <b>Ensuite il ne fait plus que compter</b>, jusqu'a la soixantieme image. La il recopie sa
    /// paire famille/indice dans le <c>+0x06</c> du <b>lanceur</b> — pour que
    /// <see cref="ResolveSpellHit_0053A2B0"/> lise la bonne fiche s'il y arrive — et appelle
    /// <see cref="ApplyStatusEffect_0053BA90"/>, l'entree 15 de la table des 48, sur le couple
    /// (lanceur, cible). Puis il s'eteint.
    /// </para>
    /// </summary>
    private static void TickHellfire_0047BB50(byte* record)
    {
        byte* e = record;
        ushort age = *(ushort*)(e + 0x10);

        if (age != 0)
        {
            if ((short)age < 0x3c)
            {
                *(ushort*)(e + 0x10) += 1;            // Ghidra: LAB_0047bc38
                return;
            }

            // La soixantieme image : l'effet d'etat, enfin.
            byte* caster = *(byte**)(e + 0x74);
            *(ushort*)(caster + 6) = *(ushort*)(e + 6);

            ApplyStatusEffect_0053BA90((uint*)caster, *(uint**)(e + 0x78), 0);

            *(ushort*)(e + 0x10) += 1;
            *(uint*)e = 0;
            return;
        }

        // Ghidra: LAB_0047bb95 — la naissance.
        e[0x36] |= 6;

        *(byte**)(e + 0x78) = FindTargetAround_00474BA0(e, 0);
        e[0x04] = 0x0f;                               // le modele
        *(short*)(e + 0x34) = 0x155;                  // l'inclinaison du premier anneau

        // Trois flammes, un tiers de tour d'ecart. 0x555 est le tiers de 0x1000 arrondi en bas.
        for (int i = 0; i < 3; i++)
        {
            SpawnCastEntity_0047AAE0(e, 0x67, e[0x0b], -1);
            *(short*)(e + 0x32) += 0x555;
        }

        // Le second anneau : un sixieme de tour plus loin, et l'inclinaison inversee.
        *(short*)(e + 0x32) = (short)(*(short*)(e + 0x32) + 0x2aa);
        *(short*)(e + 0x34) = -0x155;

        for (int i = 0; i < 3; i++)
        {
            SpawnCastEntity_0047AAE0(e, 0x67, e[0x0b], -1);
            *(short*)(e + 0x32) += 0x555;
        }

        SpawnStatusEffectEntity_0047AC40(
            e, (int*)(e + 0x1c), Descriptors00551BA0(), 0x4c, e[0x0b], -1);

        Aud.PlayPositionalSound(0x10, 0x400, 0x1200, (int*)(e + 0x1c));

        *(ushort*)(e + 0x10) += 1;
    }

    /// <summary>
    /// Ghidra: FUN_0047bc40 @ 0x0047bc40 — <b>la flamme de Feu d'enfer</b> : le sous-type
    /// <c>0x67</c>, creneau 103 de <see cref="s_StaticEntityHandlers_00551f30"/>. 181 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Elle ne se deplace pas d'elle-meme : a chaque image elle <b>se recolle sur la cible</b>
    /// (<c>+0x78</c>, heritee du sort) et tourne de <c>-0xc0</c> sur <c>+0x32</c>. Six exemplaires
    /// tournant ensemble font la couronne.
    /// </para>
    /// <para>
    /// <b>Trois ages.</b> A la naissance elle prend l'echelle <c>0x1800</c> sur les trois axes et
    /// une teinte <b>nulle</b> — invisible. Jusqu'a la 32e image elle <b>s'eclaircit</b> de
    /// <c>0x101010</c> par image jusqu'a <c>0xf0f0f0</c>, et retrecit de <c>0x80</c> tant que son
    /// echelle depasse <c>0xc00</c>. Au-dela elle ne fait plus que retrecir, sans plancher — et
    /// c'est <b>l'echelle nulle qui l'eteint</b>, pas un compteur.
    /// </para>
    /// <para>
    /// <b>La hauteur est celle de la tete du LANCEUR</b> (<c>+0x74</c>), pas de la cible : la
    /// position vient de l'une et l'altitude de l'autre. C'est dans le binaire, et c'est ce qui
    /// pose la couronne a hauteur d'homme quelle que soit la taille du monstre vise.
    /// </para>
    /// </summary>
    private static void TickHellfireFlame_0047BC40(byte* record)
    {
        byte* e = record;
        byte* target = *(byte**)(e + 0x78);
        ushort age = *(ushort*)(e + 0x10);

        if (age == 0)
        {
            *(uint*)(e + 0x28) = 0x18001800;
            *(ushort*)(e + 0x2c) = 0x1800;
            *(uint*)(e + 0x38) = 0;                   // invisible a la naissance
        }
        else if ((short)age < 0x20)
        {
            if (*(short*)(e + 0x28) > 0x0c00)
            {
                unchecked
                {
                    *(uint*)(e + 0x28) += 0xff7fff80;  // -0x80 sur X et sur Y
                    *(ushort*)(e + 0x2c) += 0xff80;    // -0x80 sur Z
                }
            }

            uint tint = *(uint*)(e + 0x38);
            if (tint < 0x00f0f0f0) *(uint*)(e + 0x38) = tint + 0x00101010;
        }
        else
        {
            // Ghidra: LAB_0047bc9b — passe la 32e image elle ne fait plus que retrecir.
            unchecked
            {
                *(uint*)(e + 0x28) += 0xff7fff80;
                *(ushort*)(e + 0x2c) += 0xff80;
            }
        }

        // Ghidra: LAB_0047bcac — le recollage, commun aux trois ages.
        *(int*)(e + 0x1c) = *(int*)(target + 0x1c);
        *(int*)(e + 0x24) = *(int*)(target + 0x24);

        int height = StatusBubbleHeight_00538BC0(*(uint**)(e + 0x74));
        unchecked { *(ushort*)(e + 0x32) += 0xff40; }  // -0xc0 de rotation par image
        *(int*)(e + 0x20) = *(int*)(target + 0x20) + ((height & ~1) << 0xb);

        // C'est l'echelle a zero qui l'eteint — les deux shorts d'un coup.
        if (age != 0 && *(uint*)(e + 0x28) == 0) *(uint*)e = 0;

        *(ushort*)(e + 0x10) = (ushort)(age + 1);
    }

    /// <summary>
    /// Ghidra: FUN_0047bdf0 @ 0x0047bdf0 — <b>l'embrasement de Feu d'enfer</b> : le sous-type
    /// <c>0x4c</c>, creneau 76 de <see cref="s_StaticEntityHandlers_00552230"/>. 270 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Meme forme que la flamme — il se recolle sur la cible a chaque image, a la hauteur de tete
    /// du lanceur, et c'est sa <b>teinte a zero</b> qui l'eteint. Il naît invisible et sans taille,
    /// grossit de <c>0x100</c> par image jusqu'a <c>0x1000</c> et s'eclaircit de <c>0x080808</c>
    /// jusqu'a <c>0xd0d0d0</c>.
    /// </para>
    /// <para>
    /// <b>A la 32e image exactement</b> — pas avant, pas apres : le test est une egalite — il lache
    /// <b>deux braises</b> <c>0x68</c>, qui sont
    /// <see cref="EntityHandler_0047BD00"/>, deja transcrite et deja exercee en foret. Ensuite il se
    /// resorbe : la teinte redescend de <c>0x080808</c> et l'echelle <b>approche</b> <c>0x2000</c>
    /// d'un quart de la distance restante a chaque image — elle grandit donc encore en s'effacant.
    /// </para>
    /// </summary>
    private static void TickHellfireBlaze_0047BDF0(byte* record)
    {
        byte* e = record;
        byte* target = *(byte**)(e + 0x78);
        ushort age = *(ushort*)(e + 0x10);

        if (age == 0)
        {
            *(uint*)(e + 0x28) = 0;
            *(uint*)(e + 0x38) = 0;
            *(ushort*)(e + 0x0a) = 7;
            *(short*)(e + 0x2e) = -0x14;
        }
        else if ((short)age < 0x20)
        {
            // La croissance : le dword porte les deux shorts, le test ne regarde que le bas.
            if (*(short*)(e + 0x28) < 0x1000) *(uint*)(e + 0x28) += 0x01000100;

            uint tint = *(uint*)(e + 0x38);
            if (tint < 0x00d0d0d0) *(uint*)(e + 0x38) = tint + 0x00080808;
        }
        else
        {
            // Ghidra: LAB_0047be4a — les deux braises, a la 32e image et a elle seule.
            if (age == 0x20)
            {
                *(short*)(e + 0x12) = 0;
                *(ushort*)(e + 0x14) = 0x2000;
                SpawnCastEntity_0047AAE0(e, 0x68, e[0x0b], -1);
                SpawnCastEntity_0047AAE0(e, 0x68, e[0x0b], -1);
            }

            // Ghidra: LAB_0047be7e — la resorption.
            uint tint = *(uint*)(e + 0x38);
            if (tint != 0) unchecked { *(uint*)(e + 0x38) = tint + 0xfff7f7f8; }   // -0x080808

            // L'echelle approche 0x2000 d'un quart de ce qui reste, sur X puis sur Y.
            short x = *(short*)(e + 0x28);
            *(short*)(e + 0x28) = (short)(x + ((0x2000 - x) >> 2));

            short y = *(short*)(e + 0x2a);
            *(short*)(e + 0x2a) = (short)(y + ((0x2000 - y) >> 2));
        }

        // Ghidra: LAB_0047bebb — le recollage, commun aux trois ages.
        *(int*)(e + 0x1c) = *(int*)(target + 0x1c);
        *(int*)(e + 0x24) = *(int*)(target + 0x24);

        int height = StatusBubbleHeight_00538BC0(*(uint**)(e + 0x74));
        *(int*)(e + 0x20) = *(int*)(target + 0x20) + ((height & ~1) << 0xb);

        if (age != 0 && *(uint*)(e + 0x38) == 0) *(uint*)e = 0;

        *(ushort*)(e + 0x10) = (ushort)(age + 1);
    }

    // =====================================================================
    // WONDER — le sixieme sort, ecole 0 indice 5, sous-type 0x05
    //
    // Trois corps, et la forme la plus riche jusqu'ici : c'est le premier sort ENTRETENU.
    //
    //   0x0047BF00   LE SORT. Sous-type 5 de 0x00551c30, 724 octets. Il immobilise le lanceur,
    //                s'envole tout droit avec frottement, frappe, et TIENT tant que le joueur
    //                garde le bouton d'incantation enfonce — en lui prenant 2 PM toutes les vingt
    //                images.
    //   0x0047C1E0   L'AURA, sous-type 0x6a de 0x00551f30. Deux exemplaires, colles au sort.
    //   0x0047C2C0   L'ANNEAU, sous-type 0x4d de 0x00552230. Colle au sort lui aussi.
    //
    // LE BIT 0x2000000 EST LE SIGNAL DE FIN, ET IL SE PROPAGE. Le sort se le pose quand il doit
    // s'arreter ; ses deux enfants LISENT le mot d'etat de leur pere par +0x6c et en heritent
    // (`and 3000000h ; or`). Ils basculent alors en resorption et s'eteignent d'eux-memes. C'est le
    // pendant du compte de references de Rocher : ici le pere ne compte pas ses fils, il leur fait
    // signe.
    //
    // ET IL PEINT LE FOND DE L'ECRAN. La naissance ecrit 0x005e9160..0x005e9166 — trois canaux a
    // 0xc4 et le mode 2 —, la fin remet le mode a zero. C'est la couleur de fond de la scene, celle
    // que WorldMap.cs fait converger a chaque image : le sort blanchit le decor tant qu'il dure.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047bf00 @ 0x0047bf00 — <b>Wonder</b> : le sous-type <c>0x05</c>, creneau 5 de
    /// <see cref="s_StaticEntityHandlers_00551c30"/>. 724 octets, <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Le premier sort entretenu du depot.</b> Passe la seizieme image, si le lanceur est un
    /// membre du groupe, il relit <b>la manette de ce joueur</b> — l'emplacement vient de
    /// <c>s_PlayerSlots_005e9188[indice * 0x4c]</c>, l'etat de
    /// <c>s_InputStateBase_00604a20 + emplacement * 0x10</c>, et le masque compare est
    /// <c>+0x1fc4</c> du bloc du personnage, celui-la meme qui ouvre la posture d'incantation. Le
    /// bouton relache, le sort se marque <c>0x2000000</c> et tout s'arrete.
    /// </para>
    /// <para>
    /// <b>Il coute 2 PM toutes les vingt images</b>, cadence sur le compteur global
    /// <c>0x005f2cf0</c> — donc sur l'horloge du monde, pas sur son propre age. A court de PM il
    /// les met a zero et se coupe. Un lanceur qui n'est pas du groupe n'a ni manette ni PM : il
    /// tient <b>120 images</b> et s'arrete.
    /// </para>
    /// <para>
    /// <b>Le mouvement est une ligne droite qui s'essouffle</b> : la vitesse posee a la naissance
    /// (40 unites sur le cap) perd un huitieme <b>et</b> un 256e d'elle-meme a chaque image. Le
    /// placement ne sert qu'a detecter le decor — la hauteur est sauvee et rendue autour, comme
    /// pour les autres projectiles —, et un contact sur <c>0x8802</c> annule la vitesse sans tuer
    /// le sort : il reste sur place jusqu'a ce que le joueur lache.
    /// </para>
    /// </summary>
    private static void TickWonder_0047BF00(byte* record)
    {
        byte* e = record;
        uint state = *(uint*)e;

        // Une sonde plus large et plus profonde que celles des sorts precedents : 70 de
        // demi-largeur, 140 de profondeur.
        short* probe = stackalloc short[6] { 0x0000, -0x0046, 0x0046, 0x0064, 0x0000, 0x008c };

        if ((state & 0x2000000) != 0)
        {
            // ------------------------------------------------------------ la fin
            *(uint*)(*(uint**)(e + 0x74)) &= 0xffffff7f;   // le lanceur est relache
            *(uint*)e = 0;
            *(ushort*)Mem.Arena(0x005e9166) = 0;           // le fond reprend sa couleur
            return;
        }

        ushort age = *(ushort*)(e + 0x10);

        if (age == 0)
        {
            // ------------------------------------------------------------ la naissance
            byte* caster = *(byte**)(e + 0x74);
            *(uint*)caster |= 0x80;                        // le lanceur est immobilise
            *(uint*)e |= 0x80;
            e[0x36] |= 6;
            *(short*)(e + 0x2e) = -0x14;

            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), Descriptors00551BA0(), 0x4d, e[0x0b], -1);

            *(ushort*)(e + 0x12) = 0x1000;
            SpawnCastEntity_0047AAE0(e, 0x6a, e[0x0b], -1);
            SpawnCastEntity_0047AAE0(e, 0x6a, e[0x0b], -1);

            int height = StatusBubbleHeight_00538BC0(*(uint**)(e + 0x74));
            int heading = *(short*)(e + 0x32);
            *(int*)(e + 0x20) += (height & ~1) << 0xb;

            *(int*)(e + 0x50) = (int)Winsys3d.GetSinTableEntry(heading) * 40;
            *(int*)(e + 0x58) = Winsys3d.GetCosTableEntry(heading) * 40;

            // La couleur de fond de la scene : trois canaux a 0xc4, mode 2.
            *(uint*)Mem.Arena(0x005e9160) = 0x00c400c4;
            *(uint*)Mem.Arena(0x005e9164) = 0x000200c4;

            Aud.PlayPositionalSound(0x2d, 0x400, 0x1200, (int*)(e + 0x1c));
        }
        else if ((short)age >= 0x10)
        {
            // ------------------------------------------------------------ l'entretien
            if ((state & 0x800000) != 0)
            {
                byte* caster = *(byte**)(e + 0x74);
                uint index = ((uint*)caster)[2] & 0xff;
                byte* perChar = GetMainMemPtr() + (index + 0x78) * 0x2000;

                // La manette du joueur qui tient ce personnage. Le pas est 0x4c dans la table des
                // emplacements et 0x10 dans celle des etats — le meme piege que PollInputAndAudio
                // documente : la pseudo-C ecrit `* 4` parce que le symbole est typé `undefined4`.
                int slot = Inp.s_PlayerSlots_005e9188[index * 0x4c];
                ushort pad = *(ushort*)(Inp.s_InputStateBase_00604a20 + slot * 0x10);

                if ((*(ushort*)(perChar + 0x1fc4) & pad) == 0)
                {
                    state |= 0x2000000;                    // le bouton est relache
                    *(uint*)e = state;
                }

                // Ghidra: LAB_0047c07f — la ponction, cadencee sur l'horloge du monde.
                if (*(uint*)Mem.Entity(0x005f2cf0) % 20 == 0)
                {
                    short mana = *(short*)(perChar + 0x14e);

                    if (mana >= 2)
                    {
                        *(short*)(perChar + 0x14e) = (short)(mana - 2);
                    }
                    else
                    {
                        *(ushort*)(perChar + 0x14e) = 0;
                        *(uint*)e = *(uint*)e | 0x2000000;
                    }
                }
            }
            else if ((short)age >= 0x78)
            {
                // Un lanceur hors groupe n'a ni manette ni PM : 120 images, et c'est tout.
                *(uint*)e |= 0x2000000;
            }

            // Ghidra: LAB_0047c0c2 — et dans tous les cas, le lanceur doit tenir debout.
            if (CanSustainChannel_00475110(e) != 0) *(uint*)e |= 0x2000000;
        }

        // Ghidra: LAB_0047c0d5 — le vol, commun aux trois branches.
        int vx = *(int*)(e + 0x50);
        int vz = *(int*)(e + 0x58);

        *(int*)(e + 0x1c) += vx;
        *(int*)(e + 0x24) += vz;

        // Le frottement prend un huitieme ET un 256e : la vitesse s'eteint en une trentaine
        // d'images.
        *(int*)(e + 0x50) = vx - (vx >> 3) - (vx >> 8);
        *(int*)(e + 0x58) = vz - (vz >> 8) - (vz >> 3);

        int keptHeight = *(int*)(e + 0x20);
        FinalizeEntityPlacement2((uint*)e);                // Ghidra: FUN_00533940
        uint contact = *(uint*)(e + 0x90);
        *(int*)(e + 0x20) = keptHeight;

        if ((contact & 0x8802) != 0)
        {
            // Le decor l'arrete, mais ne le tue pas : il reste la tant qu'on le tient.
            *(int*)(e + 0x50) = 0;
            *(int*)(e + 0x58) = 0;
        }

        byte* victim = ProbeMeleeTarget_00474CA0(e, probe);

        if (victim != null)
        {
            ResolveSpellHit_0053A2B0(*(uint**)(e + 0x74), (uint*)victim, e[7], e[6], 0);

            int push = *(short*)(e + 0x32);
            *(int*)(victim + 0x50) += (int)Winsys3d.GetSinTableEntry(push) << 4;
            *(int*)(victim + 0x58) += Winsys3d.GetCosTableEntry(push) << 4;
            *(uint*)victim |= 0x40;
            *(ushort*)(victim + 0x96) = 0x10;

            Aud.PlayPositionalSound(0x0f, 0xaa8, 0x1200, (int*)(e + 0x1c));
        }

        // Ghidra: LAB_0047c1ad — le sort meurt avec son lanceur.
        uint now = *(uint*)e;

        if ((now & 0x40000000) != 0 || (*(uint*)(*(uint**)(e + 0x74)) & 0x40000000) != 0)
        {
            *(uint*)e = now | 0x2000000;
        }

        *(ushort*)(e + 0x10) += 1;
    }

    /// <summary>
    /// Ghidra: FUN_0047c1e0 @ 0x0047c1e0 — <b>l'aura de Wonder</b> : le sous-type <c>0x6a</c>,
    /// creneau 106 de <see cref="s_StaticEntityHandlers_00551f30"/>. 216 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Elle herite du mot d'etat de son pere</b> a chaque image : les deux bits <c>0x3000000</c>
    /// du sort (<c>+0x6c</c>) sont recopies dans le sien. C'est ainsi que la fin se propage — le
    /// sort se marque, l'aura le voit a l'image suivante et bascule en resorption sans que
    /// personne ne la previenne autrement.
    /// </para>
    /// <para>
    /// Tant que le pere tient, elle se colle a lui, tourne de <c>0x30</c> et <c>0x40</c> sur ses
    /// deux axes, et <b>approche d'un quart</b> deux cibles : l'echelle vers <c>+0x12</c> (que le
    /// sort a pose a <c>0x1000</c>) et la teinte vers <c>0xff</c>. Une fois marquee elle perd un
    /// quart de chaque par image et s'eteint sous <c>0x100</c> d'echelle.
    /// </para>
    /// <para>
    /// <b>Un seul canal est lu, trois sont ecrits</b> : le binaire prend l'octet bas de
    /// <c>+0x38</c> et le replique sur les trois. L'aura est donc toujours grise.
    /// </para>
    /// </summary>
    private static void TickWonderAura_0047C1E0(byte* record)
    {
        byte* e = record;
        uint state = *(uint*)e;

        int scale;
        int channel;

        if ((state & 0x3000000) != 0)
        {
            // ------------------------------------------------------------ la resorption
            scale = *(short*)(e + 0x28);
            scale -= scale >> 2;

            channel = e[0x38];
            channel -= channel >> 2;

            if (scale < 0x100) *(uint*)e = 0;
        }
        else
        {
            // Ghidra: LAB_0047c219 — l'heritage des deux bits du pere.
            byte* parent = *(byte**)(e + 0x6c);
            *(uint*)e = (*(uint*)parent & 0x3000000) | state;

            if (*(ushort*)(e + 0x10) == 0)
            {
                *(ushort*)(e + 0x10) = 1;
                *(int*)(e + 0x28) = 0;
                *(short*)(e + 0x2c) = 0;
                *(short*)(e + 0x30) = (short)CrtRand();
                *(short*)(e + 0x32) = (short)CrtRand();
                *(short*)(e + 0x34) = (short)CrtRand();
                e[0x04] = 0x1d;                            // le modele
            }

            // Ghidra: LAB_0047c25c — les deux approches, chacune d'un quart.
            scale = *(short*)(e + 0x28);
            scale += (*(short*)(e + 0x12) - scale) >> 2;

            channel = e[0x38];
            channel += (0xff - channel) >> 2;

            *(int*)(e + 0x1c) = *(int*)(parent + 0x1c);
            *(int*)(e + 0x20) = *(int*)(parent + 0x20);
            *(int*)(e + 0x24) = *(int*)(parent + 0x24);

            *(ushort*)(e + 0x32) += 0x30;
            *(ushort*)(e + 0x34) += 0x40;
        }

        // Ghidra: LAB_0047c298 — l'echelle et la teinte, communes aux deux branches.
        *(short*)(e + 0x2c) = (short)scale;
        // `mov edx,eax ; shl edx,10h ; or edx,eax` porte sur le registre ENTIER : une echelle
        // negative garderait ses bits de signe dans la moitie haute. Ecrit tel quel.
        *(uint*)(e + 0x28) = ((uint)scale << 0x10) | (uint)scale;
        *(uint*)(e + 0x38) = (uint)(((channel << 8 | channel) << 8) | channel);
    }

    /// <summary>
    /// Ghidra: FUN_0047c2c0 @ 0x0047c2c0 — <b>l'anneau de Wonder</b> : le sous-type <c>0x4d</c>,
    /// creneau 77 de <see cref="s_StaticEntityHandlers_00552230"/>. 219 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Meme heritage du mot d'etat que <see cref="TickWonderAura_0047C1E0"/>, meme resorption sous
    /// <c>0x100</c>. Deux differences : son echelle approche <c>0x1800</c> <b>de moitie</b> et non
    /// d'un quart, et sa teinte <b>bat</b> — elle suit
    /// <c>(sin(age &lt;&lt; 9) &gt;&gt; 7) + 0x80</c>, approchee d'un quart. L'anneau pulse donc
    /// pendant que l'aura ne fait que monter.
    /// </para>
    /// <para>
    /// Le binaire garde le canal dans <b>l'emplacement de son propre argument</b> sur la pile, et y
    /// travaille en octet. Ecrit ici avec une variable locale : c'est la meme valeur, sans le
    /// detour.
    /// </para>
    /// </summary>
    private static void TickWonderRing_0047C2C0(byte* record)
    {
        byte* e = record;
        uint state = *(uint*)e;

        int scale;
        int channel;

        if ((state & 0x3000000) != 0)
        {
            // ------------------------------------------------------------ la resorption
            int current = *(short*)(e + 0x28);
            scale = current - (current >> 2) * 2;

            channel = e[0x38];
            channel = (byte)(channel - (channel >> 2));

            if (scale < 0x100) *(uint*)e = 0;
        }
        else
        {
            // Ghidra: LAB_0047c305 — l'heritage des deux bits du pere.
            byte* parent = *(byte**)(e + 0x6c);
            ushort age = *(ushort*)(e + 0x10);
            *(uint*)e = (*(uint*)parent & 0x3000000) | state;

            if (age == 0) *(int*)(e + 0x28) = 0;

            // Ghidra: LAB_0047c324 — l'echelle approche 0x1800 de moitie.
            int current = *(short*)(e + 0x28);
            scale = current + ((0x1800 - current) >> 2) * 2;

            channel = e[0x38];

            // La teinte bat : elle approche d'un quart la cible (sin(age << 9) >> 7) + 0x80.
            int beat = (int)Winsys3d.GetSinTableEntry((short)age << 9);
            channel = (byte)(channel + (((beat >> 7) - channel + 0x80) >> 2));

            *(int*)(e + 0x1c) = *(int*)(parent + 0x1c);
            *(int*)(e + 0x20) = *(int*)(parent + 0x20);
            *(int*)(e + 0x24) = *(int*)(parent + 0x24);
        }

        // Ghidra: LAB_0047c375 — l'age avance dans les deux branches, l'echelle et la teinte aussi.
        *(ushort*)(e + 0x10) += 1;
        // Meme forme que dans l aura : le OU porte sur le registre entier.
        *(uint*)(e + 0x28) = ((uint)scale << 0x10) | (uint)scale;
        *(uint*)(e + 0x38) = (uint)(((channel << 8 | channel) << 8) | channel);
    }

    // =====================================================================
    // TENEBRES — le septieme sort, ecole 0 indice 6, sous-type 0x06
    //
    // Deux corps seulement, mais l'ombre est le premier corps du depot qui ANNULE SON PROPRE
    // DEPLACEMENT.
    //
    //   0x0047C3A0   LE SORT. Sous-type 6 de 0x00551c30, 173 octets. Une seule image : il lache
    //                CINQ ombres en eventail sur un quart de tour, assombrit le fond de l'ecran et
    //                s'eteint.
    //   0x0047C450   L'OMBRE, sous-type 0x6b de 0x00551f30, 520 octets. Elle glisse, grossit, et
    //                REBONDIT sur le decor.
    //
    // LE REBOND EST UN RETOUR EN ARRIERE. L'ombre met de cote sa position et les CINQ dwords de
    // +0x80 a +0x90 — l'etat de collision que FinalizeEntityPlacement2 va ecrire —, avance, puis
    // appelle le placement. Si le contact a mordu (masque 0x802), elle remet tout en place, fait
    // demi-tour sur +0x32 et INVERSE ses deux vitesses. Rien de ce que le placement a ecrit ne
    // subsiste : c'est une annulation, pas une correction.
    //
    // ET SA PORTEE GROSSIT AVEC ELLE. Les mots 2 et 3 de la sonde — demi-largeur et tolerance en
    // hauteur — sont recalcules a chaque image depuis l'echelle. Une ombre qui a grandi frappe plus
    // large, ce qu'aucun des six sorts precedents ne faisait.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047c3a0 @ 0x0047c3a0 — <b>Tenebres</b> : le sous-type <c>0x06</c>, creneau 6 de
    /// <see cref="s_StaticEntityHandlers_00551c30"/>. 173 octets, <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Une seule image, comme les graines de Balle de feu et de Boule de lumiere — mais elle lache
    /// <b>cinq</b> enfants et non un. Le cap recule d'abord de <c>0x200</c>, puis chaque ombre part
    /// <c>0x100</c> plus loin que la precedente : l'eventail est centre sur le cap du lanceur et
    /// couvre <b>un quart de tour</b>. La vitesse posee est de 22 unites sur le cap de chacune.
    /// </para>
    /// <para>
    /// <b>Il assombrit la scene</b> : les trois canaux de fond passent a <c>0x60</c> avec le mode 2,
    /// la ou <see cref="TickWonder_0047BF00"/> les monte a <c>0xc4</c>. Il ne remet pas le mode a
    /// zero — ce sont ses ombres qui le font en mourant.
    /// </para>
    /// </summary>
    private static void TickDarkness_0047C3A0(byte* record)
    {
        byte* e = record;

        e[0x36] |= 6;
        unchecked { *(ushort*)(e + 0x32) += 0xfe00; }   // -0x200 : le bord de l'eventail
        *(int*)(e + 0x28) = 0;
        *(short*)(e + 0x2c) = 0;
        *(uint*)(e + 0x38) = 0xc0e0e0e0;
        *(short*)(e + 0x2e) = -0x14;
        e[0x04] = 0x1e;                                // le modele

        for (int i = 0; i < 5; i++)
        {
            int heading = *(short*)(e + 0x32);

            // 22 unites : `lea *5 ; lea [eax+ecx*2]` donne *11, puis `shl 1`.
            *(int*)(e + 0x50) = (int)Winsys3d.GetSinTableEntry(heading) * 22;
            *(int*)(e + 0x58) = Winsys3d.GetCosTableEntry(heading) * 22;

            SpawnCastEntity_0047AAE0(e, 0x6b, e[0x0b], -1);

            *(ushort*)(e + 0x32) += 0x100;
        }

        // Le fond de la scene, assombri : trois canaux a 0x60, mode 2.
        *(uint*)Mem.Arena(0x005e9160) = 0x00600060;
        *(uint*)Mem.Arena(0x005e9164) = 0x00020060;

        Aud.PlayPositionalSound(0x1a, 0x400, 0x1200, (int*)(e + 0x1c));

        *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_0047c450 @ 0x0047c450 — <b>l'ombre de Tenebres</b> : le sous-type <c>0x6b</c>,
    /// creneau 107 de <see cref="s_StaticEntityHandlers_00551f30"/>. 520 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Elle rebondit, et le rebond est une annulation.</b> Avant d'avancer elle met de cote sa
    /// position et les <b>cinq dwords de <c>+0x80</c> a <c>+0x90</c></b> — l'etat de collision que
    /// <see cref="FinalizeEntityPlacement2"/> s'apprete a ecrire. Si le contact a mordu sur le
    /// masque <c>0x802</c>, elle remet les sept valeurs en place, ajoute <c>0x800</c> a son cap et
    /// <b>nie ses deux vitesses</b>. L'image ou elle touche est donc exactement l'image d'avant,
    /// vue a l'envers.
    /// </para>
    /// <para>
    /// <b>Sa portee grossit avec elle.</b> Les mots 2 et 3 de la sonde — demi-largeur et tolerance
    /// en hauteur — valent <c>(echelle &gt;&gt; 7) + 0x1e</c> et <c>(echelle &gt;&gt; 6) + 0x1e</c>,
    /// recalcules a chaque image. L'echelle, elle, approche <c>0x3000</c> d'un huitieme : l'ombre
    /// enfle et frappe de plus en plus large. Aucun des six sorts precedents ne faisait varier sa
    /// sonde.
    /// </para>
    /// <para>
    /// <b>Sa poussee est deux fois celle des autres</b> — <c>&lt;&lt; 5</c> et non <c>&lt;&lt; 4</c>.
    /// </para>
    /// <para>
    /// Elle n'a pas de compteur de vie : la teinte part de <c>0xe0e0e0</c>, perd <c>0x080808</c> par
    /// image, et l'ombre s'eteint quand les vingt-quatre bits bas atteignent zero — vingt-huit
    /// images. En mourant elle <b>rend au fond sa couleur</b>, ce que le sort lui-meme ne fait pas.
    /// </para>
    /// </summary>
    private static void TickDarknessShade_0047C450(byte* record)
    {
        byte* e = record;

        // {decalage de cap, avance, demi-largeur, tolerance en hauteur, ouverture, profondeur}.
        // Les mots 2 et 3 sont reecrits plus bas a chaque image ; le binaire les initialise quand
        // meme, et c'est reproduit tel quel.
        short* probe = stackalloc short[6] { 0x0000, -0x0028, 0x0000, 0x0064, 0x0000, 0x0050 };

        if (*(ushort*)(e + 0x10) == 0)
        {
            *(ushort*)(e + 0x10) = 1;
            *(uint*)e |= 0x80;
        }

        // Ghidra: LAB_0047c493 — tout est mis de cote AVANT le placement.
        uint kept80 = *(uint*)(e + 0x80);
        uint kept84 = *(uint*)(e + 0x84);
        uint kept88 = *(uint*)(e + 0x88);
        uint kept8c = *(uint*)(e + 0x8c);
        uint kept90 = *(uint*)(e + 0x90);
        int keptX = *(int*)(e + 0x1c);
        int keptZ = *(int*)(e + 0x24);

        int vx = *(int*)(e + 0x50);
        int vz = *(int*)(e + 0x58);

        *(int*)(e + 0x1c) = keptX + vx;
        *(int*)(e + 0x24) = keptZ + vz;

        // Le frottement prend un 256e ET un 32e : plus mordant que celui de Wonder.
        *(int*)(e + 0x50) = vx - (vx >> 8) - (vx >> 5);
        *(int*)(e + 0x58) = vz - (vz >> 5) - (vz >> 8);

        int keptY = *(int*)(e + 0x20);
        FinalizeEntityPlacement2((uint*)e);            // Ghidra: FUN_00533940
        uint contact = *(uint*)(e + 0x90);
        *(int*)(e + 0x20) = keptY;

        if ((contact & 0x802) != 0)
        {
            // Le rebond : l'image est annulee, et le cap fait demi-tour.
            *(ushort*)(e + 0x32) += 0x800;

            *(uint*)(e + 0x80) = kept80;
            *(uint*)(e + 0x84) = kept84;
            *(uint*)(e + 0x8c) = kept8c;
            *(uint*)(e + 0x90) = kept90;
            *(uint*)(e + 0x88) = kept88;

            *(int*)(e + 0x1c) = keptX;
            *(int*)(e + 0x24) = keptZ;
            *(int*)(e + 0x50) = -*(int*)(e + 0x50);
            *(int*)(e + 0x58) = -*(int*)(e + 0x58);
        }

        // Ghidra: LAB_0047c571 — l'enflement et l'effacement.
        int scale = *(short*)(e + 0x28);
        scale += (int)((uint)(0x3000 - scale) >> 3);   // `shr`, non signe

        unchecked { *(uint*)(e + 0x38) += 0xfff7f7f8; }   // -0x080808

        *(uint*)(e + 0x28) = ((uint)scale << 0x10) | (uint)scale;
        *(short*)(e + 0x2c) = (short)((uint)scale >> 1);

        // La sonde suit l'echelle : plus l'ombre est grande, plus elle mord large.
        probe[2] = (short)(((uint)scale >> 7) + 0x1e);
        probe[3] = (short)(((uint)scale >> 6) + 0x1e);

        byte* victim = ProbeMeleeTarget_00474CA0(e, probe);

        if (victim != null)
        {
            ResolveSpellHit_0053A2B0(*(uint**)(e + 0x74), (uint*)victim, e[7], e[6], 0);

            int push = *(short*)(e + 0x32);
            *(int*)(victim + 0x50) += (int)Winsys3d.GetSinTableEntry(push) << 5;
            *(int*)(victim + 0x58) += Winsys3d.GetCosTableEntry(push) << 5;
            *(uint*)victim |= 0x40;
            *(ushort*)(victim + 0x96) = 0x10;

            Aud.PlayPositionalSound(0x1a, 0xea4, 0x1200, (int*)(e + 0x1c));
        }

        // Ghidra: LAB_0047c630 — la teinte epuisee, ou le drapeau de fin.
        if ((*(uint*)(e + 0x38) & 0xffffff) == 0 || (*(uint*)e & 0x40000000) != 0)
        {
            *(uint*)e = 0;
            *(ushort*)Mem.Arena(0x005e9166) = 0;       // le fond reprend sa couleur
        }
    }

    // =====================================================================
    // ONDE DE CHOC — le huitieme sort, ecole 0 indice 7, sous-type 0x07
    //
    // Deux corps, et deux premieres.
    //
    //   0x0047C660   LE SORT. Sous-type 7 de 0x00551c30, 450 octets. Il ne va nulle part : il reste
    //                colle au lanceur treize images, tourne sur lui-meme et frappe tout ce qui
    //                passe a portee. Il lache DEUX anneaux, l'un au sol, l'autre a hauteur de tete.
    //   0x0047C830   L'ANNEAU, sous-type 0x6c de 0x00551f30, 210 octets.
    //
    // LA POUSSEE EST RADIALE, ET C'EST LA PREMIERE. Les sept sorts precedents poussaient leur
    // victime sur le cap du projectile ; celui-ci calcule l'angle qui va de l'onde VERS la victime
    // (Ordinal_457, le ratan2 de libgte, sur les deux ecarts) et y ajoute un demi-tour. Chaque
    // victime part donc dans une direction qui lui est propre — mais VERS le centre, pas au loin :
    // le demi-tour renverse le sens. C'est ce que le binaire fait, et ce n'est pas commente ici
    // autrement que pour le signaler.
    //
    // L'ANNEAU S'ACCROCHE PAR UN DECALAGE, PAS PAR UNE COPIE. Ses champs +0x44/+0x48/+0x4c portent
    // un ecart au lanceur, et sa position est recalculee a chaque image comme ancre + ecart. C'est
    // ce qui permet aux deux anneaux de partager un corps : le premier a un ecart nul (il est au
    // sol), le second a la hauteur de tete du lanceur.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047c660 @ 0x0047c660 — <b>Onde de choc</b> : le sous-type <c>0x07</c>, creneau 7
    /// de <see cref="s_StaticEntityHandlers_00551c30"/>. 450 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Il immobilise le lanceur et reste sur lui.</b> Treize images durant, il recopie la
    /// position du lanceur, tourne de <c>0xcc</c> sur <c>+0x32</c>, et frappe par la meme sonde
    /// large que Wonder (70 de demi-largeur, 140 de profondeur). Puis il relache la marque
    /// <c>0x80</c> et s'eteint.
    /// </para>
    /// <para>
    /// <b>Ses deux anneaux se distinguent par trois champs, pas par leur sous-type.</b> Il pose
    /// <c>+0x44</c>/<c>+0x48</c>/<c>+0x4c</c> — l'ecart a l'ancre — et
    /// <c>+0x50</c>/<c>+0x54</c>/<c>+0x58</c> — les trois echelles visees — puis engendre, deux fois
    /// de suite, le meme <c>0x6c</c>. Le premier part au sol avec le modele <c>7</c> et vise
    /// <c>0x1800</c>/<c>0x1c00</c>/<c>0x1800</c> ; le second a hauteur de tete avec le modele
    /// <c>2</c> et vise <c>0x1000</c> partout. <b>Le premier recoit aussi <c>param4 = 4</c></b>,
    /// que <see cref="SpawnCastEntity_0047AAE0"/> range en <c>+0x0a</c>.
    /// </para>
    /// </summary>
    private static void TickShockwave_0047C660(byte* record)
    {
        byte* e = record;
        byte* caster = *(byte**)(e + 0x74);

        short* probe = stackalloc short[6] { 0x0000, -0x0046, 0x0046, 0x0064, 0x0000, 0x008c };

        if (*(ushort*)(e + 0x10) == 0)
        {
            // ------------------------------------------------------------ la naissance
            *(uint*)caster |= 0x80;                    // le lanceur est immobilise
            e[0x36] |= 6;
            *(byte**)(e + 0x70) = caster;              // l'ancre des anneaux
            *(int*)(e + 0x28) = 0;
            *(short*)(e + 0x2c) = 0;
            *(uint*)(e + 0x38) = 0x00808080;           // le blanc plein de winsys3d
            *(short*)(e + 0x2e) = -0x14;

            // L'anneau du sol : aucun ecart, et une echelle plus haute que large.
            *(int*)(e + 0x44) = 0;
            *(int*)(e + 0x48) = 0;
            *(int*)(e + 0x4c) = 0;
            *(int*)(e + 0x50) = 0x1800;
            *(int*)(e + 0x54) = 0x1c00;
            *(int*)(e + 0x58) = 0x1800;
            e[0x04] = 7;

            SpawnCastEntity_0047AAE0(e, 0x6c, 0, 4);

            // L'anneau de tete : l'ecart vertical vaut la hauteur du lanceur, arrondie au pair.
            *(int*)(e + 0x44) = 0;
            int height = StatusBubbleHeight_00538BC0((uint*)caster);
            *(int*)(e + 0x48) = (height & ~1) << 0xb;
            *(int*)(e + 0x50) = 0x1000;
            *(int*)(e + 0x54) = 0x1000;
            *(int*)(e + 0x58) = 0x1000;
            *(int*)(e + 0x4c) = 0;
            e[0x04] = 2;

            SpawnCastEntity_0047AAE0(e, 0x6c, e[0x0b], -1);

            Aud.PlayPositionalSound(0x23, 0x194a, 0x1200, (int*)(e + 0x1c));
        }

        // Ghidra: LAB_0047c743 — l'onde ne quitte pas son lanceur.
        *(int*)(e + 0x1c) = *(int*)(caster + 0x1c);
        *(int*)(e + 0x20) = *(int*)(caster + 0x20);
        *(int*)(e + 0x24) = *(int*)(caster + 0x24);
        *(ushort*)(e + 0x32) += 0xcc;

        byte* victim = ProbeMeleeTarget_00474CA0(e, probe);

        if (victim != null)
        {
            ResolveSpellHit_0053A2B0(*(uint**)(e + 0x74), (uint*)victim, e[7], e[6], 0);

            // LA POUSSEE RADIALE : l'angle va de l'onde vers la victime, plus un demi-tour. Les
            // deux ecarts sont ramenes en unites entieres (>> 12) avant le ratan2, comme partout.
            int dz = (*(int*)(victim + 0x24) - *(int*)(e + 0x24)) >> 0xc;
            int dx = (*(int*)(victim + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
            int away = Winsys3d.Ordinal_457(dx, dz) + 0x800;   // Ghidra: FUN_00545a22, ratan2

            *(int*)(victim + 0x50) += (int)Winsys3d.GetSinTableEntry(away) << 4;
            *(int*)(victim + 0x58) += Winsys3d.GetCosTableEntry(away) << 4;
            *(ushort*)(victim + 0x96) = 0x10;
            *(uint*)victim |= 0x40;

            Aud.PlayPositionalSound(0x1e, 0x800, 0x1200, (int*)(e + 0x1c));
        }

        // Ghidra: LAB_0047c7fb — treize images, ou le drapeau de fin.
        if (*(short*)(e + 0x10) >= 0x0d || (*(uint*)e & 0x40000000) != 0)
        {
            *(uint*)caster &= 0xffffff7f;              // le lanceur est relache
            *(uint*)e = 0;
        }

        *(ushort*)(e + 0x10) += 1;
    }

    /// <summary>
    /// Ghidra: FUN_0047c830 @ 0x0047c830 — <b>l'anneau d'Onde de choc</b> : le sous-type
    /// <c>0x6c</c>, creneau 108 de <see cref="s_StaticEntityHandlers_00551f30"/>. 210 octets,
    /// <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Il se place par un ecart, pas par une copie</b> : sa position vaut a chaque image
    /// <c>ancre + (+0x44, +0x48, +0x4c)</c>, l'ancre etant l'entite de <c>+0x70</c> — le lanceur,
    /// que le sort y a range avant d'engendrer. C'est ce qui laisse un seul corps servir les deux
    /// anneaux : celui du sol a un ecart nul, celui de tete un ecart vertical.
    /// </para>
    /// <para>
    /// <b>Sans ancre, il devient sa propre ancre</b> : la branche <c>+0x70 == 0</c> replie la
    /// position courante dans l'ecart, met la position a zero et prend son propre enregistrement
    /// comme reference. Aucun appelant transcrit n'y passe — le sort pose toujours
    /// <c>+0x70</c> — mais elle est ecrite parce qu'elle est la.
    /// </para>
    /// <para>
    /// Les trois echelles approchent d'un quart les cibles que le sort a posees en
    /// <c>+0x50</c>/<c>+0x54</c>/<c>+0x58</c>, et la teinte perd <c>0x080808</c> par image : c'est
    /// elle, une fois nulle, qui eteint l'anneau.
    /// </para>
    /// <para>
    /// <b>Un detail du binaire qui ne se voit pas ici</b> : les trois approches se font dans un
    /// registre dont les seize bits hauts portent encore le pointeur d'ancre. Seule la moitie basse
    /// est rangee, donc le resultat est juste — mais c'est pourquoi la pseudo-C de ce genre de corps
    /// est illisible.
    /// </para>
    /// </summary>
    private static void TickShockwaveRing_0047C830(byte* record)
    {
        byte* e = record;
        byte* anchor = *(byte**)(e + 0x70);

        if (anchor == null)
        {
            if (*(ushort*)(e + 0x10) == 0)
            {
                // La position courante devient l'ecart, une fois pour toutes.
                *(int*)(e + 0x44) += *(int*)(e + 0x1c);
                *(int*)(e + 0x48) += *(int*)(e + 0x20);
                *(int*)(e + 0x4c) += *(int*)(e + 0x24);
                *(ushort*)(e + 0x10) = 1;
            }

            // Ghidra: LAB_0047c869
            *(int*)(e + 0x1c) = 0;
            *(int*)(e + 0x20) = 0;
            *(int*)(e + 0x24) = 0;
            anchor = e;
        }

        // Ghidra: LAB_0047c880 — ancre plus ecart.
        *(int*)(e + 0x1c) = *(int*)(e + 0x44) + *(int*)(anchor + 0x1c);
        *(int*)(e + 0x20) = *(int*)(e + 0x48) + *(int*)(anchor + 0x20);
        *(int*)(e + 0x24) = *(int*)(e + 0x4c) + *(int*)(anchor + 0x24);

        // Les trois echelles, chacune approchant sa cible d'un quart.
        short x = *(short*)(e + 0x28);
        *(short*)(e + 0x28) = (short)(((*(int*)(e + 0x50) - x) >> 2) + x);

        short y = *(short*)(e + 0x2a);
        *(short*)(e + 0x2a) = (short)(((*(int*)(e + 0x54) - y) >> 2) + y);

        short z = *(short*)(e + 0x2c);
        *(short*)(e + 0x2c) = (short)(((*(int*)(e + 0x58) - z) >> 2) + z);

        uint tint;
        unchecked { tint = *(uint*)(e + 0x38) + 0xfff7f7f8; }   // -0x080808
        *(uint*)(e + 0x38) = tint;

        ushort age = *(ushort*)(e + 0x10);
        if (age != 0 && tint == 0) *(uint*)e = 0;

        *(ushort*)(e + 0x10) = (ushort)(age + 1);
    }

    // =====================================================================
    // FLECHES MAGIQUES — le neuvieme sort, ecole 0 indice 8, sous-type 0x08
    //
    // Trois corps, et le premier projectile A TETE CHERCHEUSE du depot.
    //
    //   0x0047C910   LE SORT. Sous-type 8 de 0x00551c30, 309 octets. Une image : il CHERCHE
    //                l'adversaire le plus proche, calcule le cap et le tangage qui y menent, pose
    //                la vitesse et lache la fleche.
    //   0x0047CA50   LA FLECHE, sous-type 0x6d de 0x00551f30. 1007 octets — le plus gros corps de
    //                sort transcrit. Elle recorrige son cap vers la cible a chaque image.
    //   0x00475F60   L'ETINCELLE de sa trainee, sous-type 0xbf de 0x00552230. 87 octets.
    //
    // LA CIBLE EST TENUE DES DEUX COTES. La fleche range son adversaire en +0x78 et s'ecrit
    // elle-meme dans le +0x74 de celui-ci — un lien reciproque, que la mort de l'un rompt pour
    // l'autre. C'est la premiere fois qu'un sort marque sa victime AVANT de la toucher.
    //
    // LES SIX CHAMPS PRETES. Comme Pieds mouilles, la fleche ecrase +0x50/+0x54/+0x58, +0x28,
    // +0x2c et +0x38 pour parametrer l'etincelle qu'elle seme, puis les rend. Six champs cette
    // fois, et le passage par la pile est le meme.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047c910 @ 0x0047c910 — <b>Fleches magiques</b> : le sous-type <c>0x08</c>,
    /// creneau 8 de <see cref="s_StaticEntityHandlers_00551c30"/>. 309 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Une seule image. Il se hisse a hauteur de tete du lanceur, puis demande a
    /// <see cref="FindNearestOpponent_00474EB0"/> l'adversaire le plus proche — <b>pas</b> la sonde
    /// conique des sorts precedents, une vraie recherche du plus proche.
    /// </para>
    /// <para>
    /// <b>Avec une cible</b>, il calcule les trois ecarts, en tire la distance horizontale par
    /// <c>Ordinal_442</c> (le <c>SquareRoot0</c> de libgte), puis deux angles par deux
    /// <c>ratan2</c> : le cap, <b>disperse d'un tirage sur douze bits</b> et decale de
    /// <c>0xa00</c>, et le tangage decale de <c>0x100</c>. La vitesse sort de
    /// <see cref="SetVectorFromAngles_00532AD0"/> a <c>0x20</c>.
    /// </para>
    /// <para>
    /// <b>Sans cible</b>, la fleche part droit devant a <c>rsin/rcos &lt;&lt; 6</c>, sans
    /// composante verticale, et le cap avance de <c>0x400</c> — de quoi eventer les tirs suivants.
    /// </para>
    /// </summary>
    private static void TickMagicArrow_0047C910(byte* record)
    {
        byte* e = record;
        byte* caster = *(byte**)(e + 0x74);

        int height = StatusBubbleHeight_00538BC0((uint*)caster);
        *(int*)(e + 0x20) += (height & ~1) << 0xb;

        byte* target = FindNearestOpponent_00474EB0((uint*)caster, 0xffffffff, 1);

        *(uint*)(e + 0x38) = 0x00f0f0f0;
        *(uint*)(e + 0x28) = 0x08000c00;
        *(ushort*)(e + 0x2c) = 0x0800;

        if (target != null)
        {
            *(byte**)(e + 0x78) = target;

            int dx = (*(int*)(target + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;

            // La visee monte a la tete de la cible, pas a ses pieds.
            int targetHead = StatusBubbleHeight_00538BC0((uint*)target);
            int dy = (((targetHead & ~1) << 0xb) + *(int*)(target + 0x20) - *(int*)(e + 0x20)) >> 0xc;
            int dz = (*(int*)(target + 0x24) - *(int*)(e + 0x24)) >> 0xc;

            // Ghidra: FUN_00545a10 — winsys3d Ordinal_442, le SquareRoot0 de libgte.
            int flat = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));

            // Le cap, disperse : le tirage sur douze bits couvre un tour entier, et le 0xa00 le
            // recentre. C'est ce qui fait qu'une volee de fleches ne part pas en faisceau.
            int yaw = Winsys3d.Ordinal_457(dx, dz) + (CrtRand() & 0xfff) + 0xa00;
            *(short*)(e + 0x32) = (short)yaw;

            int pitch = Winsys3d.Ordinal_457(dy, flat) + 0x100;
            *(short*)(e + 0x34) = (short)pitch;

            SetVectorFromAngles_00532AD0(
                (int*)(e + 0x50), *(short*)(e + 0x32) - 0x400, (short)pitch, 0x20);
        }
        else
        {
            // Ghidra: LAB_0047c9fb — droit devant, a plat.
            int heading = *(short*)(e + 0x32);
            *(int*)(e + 0x50) = (int)Winsys3d.GetSinTableEntry(heading) << 6;
            *(int*)(e + 0x54) = 0;
            *(int*)(e + 0x58) = Winsys3d.GetCosTableEntry(heading) << 6;
            *(ushort*)(e + 0x32) += 0x400;
        }

        // Ghidra: LAB_0047ca24
        e[0x04] = 0x14;                                // le modele
        SpawnCastEntity_0047AAE0(e, 0x6d, e[0x0b], -1);
        *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_0047ca50 @ 0x0047ca50 — <b>la fleche magique</b> : le sous-type <c>0x6d</c>,
    /// creneau 109 de <see cref="s_StaticEntityHandlers_00551f30"/>. <b>1007 octets</b>, le plus
    /// gros corps de sort du depot, <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// <b>Elle poursuit.</b> Tant qu'elle a une cible en <c>+0x78</c>, elle recalcule a chaque image
    /// les deux angles qui y menent et <b>ajoute</b> le vecteur correspondant a sa vitesse, laquelle
    /// perd ensuite un huitieme sur chaque axe. Ce n'est donc pas une correction de cap mais une
    /// <b>poussee continue</b> vers la cible : la fleche decrit une courbe et peut depasser.
    /// </para>
    /// <para>
    /// <b>Le lien est reciproque.</b> Elle ecrit son propre enregistrement dans le <c>+0x74</c> de
    /// sa cible, et le remet a zero en mourant — au contact comme sur le decor. Une cible qui porte
    /// <c>0x50000000</c> (morte ou mourante) est relachee et la fleche redevient libre.
