                dy = 0x190;
            }
            else if (fall < 0x64)
            {
                dy = -0x190;
            }
            else
            {
                *(uint*)e = state | 0x20000000;        // le signal que la chaine suivra
                return;
            }

            // Ce chemin saute l'heritage : il est deja dedans.
            dying = true;
        }
        else
