                prey = FindNearestOpponent_00474EB0(*(uint**)(e + 0x74), 0xffffffff, 1);
            }

            // Ghidra: LAB_00481ee1
            short age = *(short*)(e + 0x10);

            if (age < 0x1e)
            {
                dy = 0x190;                            // les trente premieres images : elle monte
            }
            else if (prey != null)
            {
                *(byte**)(e + 0x78) = prey;
                dx = (*(int*)(prey + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
                *(byte**)(prey + 0x74) = e;

