            *(short*)(e + 0x14) = 0x1e;      // sa duree de croissance
            *(int*)(e + 0x44) = 0x5a;        // son rayon de depart
            *(int*)(e + 0x5c) = 0x78;        // son pas angulaire

            *(int*)(e + 0x48) = 0;
            SpawnStatusEffectEntity_0047AC40(e, (int*)(e + 0x1c), null, 0x8d, 0, -1);

            *(int*)(e + 0x48) = 0x800;
            SpawnStatusEffectEntity_0047AC40(e, (int*)(e + 0x1c), null, 0x8d, 0, -1);
