            *(ushort*)(e + 0x2a) = *(ushort*)(e + 0x9a);
            e[0x38] = 0;
            e[0x39] = 0;
            e[0x3a] = 0;
            *(short*)(e + 0x2e) = -60;

            *(ushort*)(e + 0x32) = (ushort)(CrtRand() % 0x1000);
