            *(short*)(e + 0x28) += (short)((10000 - *(short*)(e + 0x28)) >> 2);
            *(short*)(e + 0x2c) += (short)((10000 - *(short*)(e + 0x2c)) >> 2);

            BrightenEntityTint_00404DE0(e, 10, 10, 10);

