            *(short*)(e + 0x2c) += (short)(-(int)*(short*)(e + 0x2c) >> 3);
            *(short*)(e + 0x2a) += (short)(-(int)*(short*)(e + 0x2a) >> 3);

            BrightenEntityTint_00404DE0(e, -5, -5, -5);

