            *(short*)(e + 0x32) = (short)(CrtRand() % 0x1000);
            *(short*)(e + 0x34) = (short)(CrtRand() % 0x1000);

            *(short*)(e + 0x12) = (short)(CrtRand() % 100 - 0x32);
            *(short*)(e + 0x16) = 0;
