        if (anchor == null) anchor = Res.s_EntityList_005de558;

        *(int*)(e + 0x1c) = *(int*)(anchor + 0x1c);
        *(int*)(e + 0x20) = *(int*)(anchor + 0x60);   // LE PLANCHER
        *(int*)(e + 0x24) = *(int*)(anchor + 0x24);

        if (*(short*)(e + 0x10) == 0)
