            e[0x0b] = 0;
            *(short*)(e + 0x10) = 1;
            *(int*)(e + 0x5c) = 0xfa;
            *(short*)(e + 0x28) = 0;
            *(short*)(e + 0x2a) = 0;
            e[0x38] = 0;
            e[0x39] = 0;
            e[0x3a] = 0;
            *(short*)(e + 0x2e) = -60;
