        if (*(short*)(e + 0x10) == 1)
        {
            *(short*)(e + 0x28) += (short)((0x0bb8 - *(short*)(e + 0x28)) >> 2);
            *(short*)(e + 0x2a) += (short)((0x0bb8 - *(short*)(e + 0x2a)) >> 2);

