                    *(byte**)(e + 0x70) = victim;

                    SpawnCastEntity_0047AAE0(e, 0x7c, e[0x0b], -1);

                    Aud.PlayPositionalSound(0x1e, 0x200, 0x1200, (int*)(e + 0x1c));
                }

                // Qu'il ait passe ou non, la boule s'eteint : les deux chemins tombent sur
                // LAB_00478093.
            }
