    //   0x0047A730   LE GRAIN, sous-type 0x2b de 0x00552230. DECOMPILE.
    //   0x00476140   LA GRAINE QUI TOURNE, sous-type 0x2d de 0x00552230. Decompilee, mais avec
    //                DEUX PARAMETRES PERDUS (unaff_EBX, unaff_retaddr) — resolus au desassembleur,
    //                releve garde sous Legacy/Raw/Blaze/FUN_00476140.asm.
    //
    // UN SEUL CORPS POUR SEPT FICHES, ET IL SE BRANCHE SUR SON +0x06. C'est la meme forme que la
    // fratrie des elementaires, a ceci pres que le branchement ne choisit pas un decor mais
    // L'EFFET : le sort appelle (&PTR_FUN_0056d4c0)[plante] — voir ApplyHerbEffect_0056D4C0 —
    // et rien d'autre ne distingue Lavande de Belladone. Meme mise en scene pour les sept.
    //
    // ET IL EST INJOUABLE. DAT_00564600 ne declare qu'un sort pour l'ecole 3, le Chasseur ne lance
    // rien, et aucune classe n'a l'ecole 3 : ces onze corps ne tournent dans aucune partie. Ils
    // sont transcrits parce qu'ils existent et qu'ils completent la carte, pas parce qu'on les
    // attend a l'ecran. Voir Documentation/Reference/Sorts.md.
    //
    // LA MISE EN SCENE, en vingt-quatre images :
    //   image 0   — il recopie le lanceur de +0x6c vers +0x74 (c'est la que ses enfants iront le
    //               chercher), cherche une cible par FindTargetAround_00474BA0 et la range en
    //               +0x78, POSE L'EFFET DE SA PLANTE, lache le halo 0x2c avec l'atlas propre a la
    //               plante lu sur le CD, puis SIX graines 0x2d en couronne (0x2aa de pas, soit un
    //               sixieme de tour) lancees vers le haut a 0x10000 par image ;
    //   0 a 0x17  — un grain 0x2b par image, et son cap tourne d'un quart de tour a chaque fois ;
    //   0x18      — il s'efface.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0047a5d0 @ 0x0047a5d0 — <b>l'herboristerie</b> : le sous-type <c>0x4f</c>,
    /// creneau 79 de <see cref="s_StaticEntityHandlers_00551c30"/>, et <b>les sept fiches de
    /// l'ecole 3 a elles toutes</b> — Lavande, Sauge, Verveine, Mercuriale, Fenouil, Hysopius,
    /// Belladone.
    ///
    /// <para>
    /// <b>Ce qui distingue les sept plantes ne tient qu'en deux lignes</b> : l'effet, choisi par
    /// <see cref="ApplyHerbEffect_0056D4C0"/> sur l'octet <c>+0x06</c>, et l'atlas du halo, lu au
    /// meme indice dans une table de huit octets du repertoire de ressources
    /// (<c>+0x94</c> → <c>+0x1c</c>). <b>Tout le reste est commun.</b>
    /// </para>
    /// <para>
    /// <b>Il pose son effet a la premiere image, et une seule fois</b> : la cible vient de
    /// <see cref="FindTargetAround_00474BA0"/> en mode 0, elle est rangee en <c>+0x78</c>, et
    /// l'effet lui est applique immediatement. Les vingt-quatre images qui suivent ne sont que du
    /// decor — <b>le sort a deja agi</b>.
    /// </para>
    /// <para>
    /// <b>Le lanceur passe de <c>+0x6c</c> a <c>+0x74</c></b> a la premiere image. C'est necessaire :
    /// <see cref="SpawnEffectEntity"/> range le lanceur en <c>+0x6c</c>, mais
    /// <see cref="SpawnStatusEffectEntity_0047AC40"/> ecrase ce meme <c>+0x6c</c> chez l'enfant avec
    /// le <b>sort</b>. Sans la recopie, les graines n'auraient plus aucun moyen de retrouver celui
    /// qui les a semees.
    /// </para>
    /// <para>
    /// <b>Si aucune cible n'est trouvee, le sort deposera un halo autour d'un pointeur nul.</b>
    /// <see cref="TickHerbMote_0047A730"/> lit <c>+0x78</c> sans le tester ; l'original ne teste pas
    /// non plus le retour de la recherche. Transcrit tel quel.
    /// </para>
    /// </summary>
    private static void TickHerbalism_0047A5D0(byte* record)
    {
        byte* e = record;

        if (*(short*)(e + 0x10) == 0)
        {
            // Le lanceur, recopie la ou les enfants iront le chercher.
            *(byte**)(e + 0x74) = *(byte**)(e + 0x6c);

            e[0x40] = 0;
            *(uint*)(e + 0x38) = 0x00f0f0f0;
            *(uint*)(e + 0x28) = 0x10001000;

            byte* target = FindTargetAround_00474BA0(e, 0);
            *(byte**)(e + 0x78) = target;

            // L'EFFET DE LA PLANTE, pose une fois pour toutes. Le binaire passe un troisieme
            // argument nul qu'aucune des sept ne lit.
            ApplyHerbEffect_0056D4C0(e[6], *(uint**)(e + 0x6c), (uint*)target);

            int* here = (int*)(e + 0x1c);

            // LE HALO, avec l'atlas propre a la plante : huit octets par entree.
            byte* atlas = *(byte**)(*(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x94) + 0x1c)
                          + e[6] * 8;

            SpawnStatusEffectEntity_0047AC40(e, here, atlas, 0x2c, 0, 0);

            int height = StatusBubbleHeight_00538BC0(*(uint**)(e + 0x6c));

            *(ushort*)(e + 0x9a) = 0x4000;                // la gravite que les graines heriteront
            *(int*)(e + 0x20) += height * 0x1000;         // et elles naissent a hauteur de tete

            // SIX GRAINES EN COURONNE, un sixieme de tour l'une de l'autre.
            for (int remaining = 6; remaining != 0; remaining--)
            {
                short yaw = *(short*)(e + 0x32);

                *(int*)(e + 0x50) = (int)Winsys3d.GetSinTableEntry(yaw) << 4;
                *(int*)(e + 0x54) = 0x10000;              // et toutes vers le haut, a la meme vitesse
                *(int*)(e + 0x58) = Winsys3d.GetCosTableEntry(yaw) << 4;

                SpawnStatusEffectEntity_0047AC40(
                    e, here, Descriptors005519A0(), 0x2d, e[0x0b], -1);

                *(short*)(e + 0x32) += 0x2aa;
            }

            *(int*)(e + 0x20) -= height * 0x1000;         // la hauteur est rendue

            *(uint*)(e + 0x38) = 0x00b0b0b0;
            *(uint*)(e + 0x28) = 0x20002000;

            Aud.PlayPositionalSound(0x2f, 0x653, 0x3fff, here);
        }

        // UN GRAIN PAR IMAGE, celle-ci comprise.
        SpawnStatusEffectEntity_0047AC40(
            e, (int*)(e + 0x1c), Descriptors005519A0(), 0x2b, e[0x0b], -1);

        *(short*)(e + 0x32) += 0x400;
        *(short*)(e + 0x10) += 1;

        if (*(short*)(e + 0x10) > 0x17) *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_0047a7d0 @ 0x0047a7d0 — <b>le halo de l'herboristerie</b> : le sous-type
    /// <c>0x2c</c>, creneau 44 de <see cref="s_StaticEntityHandlers_00552230"/>.
    ///
    /// <para>
    /// <b>Il reste colle a la tete du lanceur</b> — il relit <c>+0x74</c> a chaque image et se pose
    /// une stature au-dessus de lui, donc il le suit s'il bouge. Sa vie tient en trois temps :
    /// <b>il s'ouvre</b> pendant douze images, son echelle suivant un quart de sinus
    /// (<c>sin(age &lt;&lt; 7) * 0x1200 &gt;&gt; 12</c>) sur la largeur et la hauteur mais
    /// <b>pas sur la profondeur</b> ; il tient ; puis <b>a partir de la trente-deuxieme il s'eteint</b>,
    /// sa teinte descendant de <c>0x20</c> par image et par composante jusqu'a la quarantieme, ou il
    /// s'efface.
    /// </para>
    /// <para>
    /// La teinte de l'extinction est batie a partir d'un seul octet — <c>0x4ff - age * 0x20</c> —
    /// recopie dans les trois composantes, avec un <c>0x200</c> force dans la composante du milieu.
    /// A la premiere image de l'extinction l'octet vaut <c>0xff</c> et le mot fait
    /// <c>0x02ffffff</c> ; a la trente-neuvieme, la derniere ou il vit encore, il vaut <c>0x1f</c> et le mot <c>0x021f1f1f</c>. C'est
    /// ecrit tel quel, decalages compris.
    /// </para>
    /// </summary>
    private static void TickHerbGlow_0047A7D0(byte* record)
    {
        byte* e = record;

        byte* caster = *(byte**)(e + 0x74);

        *(int*)(e + 0x1c) = *(int*)(caster + 0x1c);
        *(int*)(e + 0x20) = StatusBubbleHeight_00538BC0((uint*)caster) * 0x1000
                            + *(int*)(caster + 0x20);
        *(int*)(e + 0x24) = *(int*)(caster + 0x24);

        short age = *(short*)(e + 0x10);

        if (age == 0)
        {
            *(uint*)(e + 0x38) = 0x01ffffff;
            *(uint*)(e + 0x28) = 0;
            *(short*)(e + 0x2e) = -10;
        }

        if (age < 0xc)
        {
            // L'OUVERTURE : un quart de sinus sur douze images, largeur et profondeur seulement.
            short scale = (short)((int)Winsys3d.GetSinTableEntry(age << 7) * 0x1200 >> 0xc);

            *(short*)(e + 0x28) = scale;
            *(short*)(e + 0x2a) = scale;
        }

        age = *(short*)(e + 0x10);

        if (age >= 0x20)
        {
            // L'EXTINCTION : un seul octet, recopie dans les trois composantes.
            uint fade = (uint)(age * -0x20 + 0x4ff);
            *(uint*)(e + 0x38) = (((fade | 0x200) << 8 | fade) << 8) | fade;
        }

        if (age == 0x28) *(uint*)e = 0;

        *(short*)(e + 0x10) = (short)(age + 1);
    }

    /// <summary>
    /// Ghidra: FUN_0047a730 @ 0x0047a730 — <b>le grain de l'herboristerie</b> : le sous-type
    /// <c>0x2b</c>, creneau 43 de <see cref="s_StaticEntityHandlers_00552230"/>. Le sort en lache
    /// <b>un par image</b> pendant les vingt-quatre.
    ///
    /// <para>
    /// <b>Il tourne autour de la CIBLE</b>, pas du lanceur : il lit <c>+0x78</c>, le seul des trois
    /// enfants a le faire. Un cercle de <c>0x32</c> unites, le cap avancant de <c>0x100</c> par
    /// image, <b>et une hauteur qui redescend</b> — <c>sin(0x800 - age * 0x40) * 0xf0</c>, donc un
    /// arc qui part du haut et retombe. Son image d'atlas boucle sur trois.
    /// </para>
    /// <para>
    /// <b>Sa mort tient a un zero exact</b> : sa teinte perd <c>0x101010</c> par image et il ne
    /// s'efface que si le resultat vaut <b>exactement</b> zero. Ca tombe juste parce que le sort la
    /// lui donne a <c>0xb0b0b0</c>, soit onze fois le pas — il vit onze images. <b>La marge est
    /// nulle</b> : une teinte de depart qui ne serait pas un multiple exact ferait un grain
    /// immortel, qui continuerait a descendre dans les negatifs. Transcrit tel quel.
    /// </para>
    /// </summary>
    private static void TickHerbMote_0047A730(byte* record)
    {
        byte* e = record;

        byte* prey = *(byte**)(e + 0x78);
        short yaw = *(short*)(e + 0x32);

        *(int*)(e + 0x1c) = *(int*)(prey + 0x1c) + (int)Winsys3d.GetSinTableEntry(yaw) * 0x32;

        // L'ARC QUI RETOMBE : le sinus est pris a rebours de l'age.
        *(int*)(e + 0x20) = (int)Winsys3d.GetSinTableEntry(*(short*)(e + 0x10) * -0x40 + 0x800) * 0xf0
                            + *(int*)(prey + 0x20);

        *(int*)(e + 0x24) = *(int*)(prey + 0x24) + Winsys3d.GetCosTableEntry(yaw) * 0x32;

        *(short*)(e + 0x32) = (short)(yaw + 0x100);

        byte frame = (byte)(e[0x40] + 1);
        e[0x40] = frame;
        if (frame > 2) e[0x40] = 0;

        // LE ZERO EXACT, et rien d'autre, ne l'arrete.
        int tint = *(int*)(e + 0x38) - 0x101010;
        *(int*)(e + 0x38) = tint;
        if (tint == 0) *(uint*)e = 0;

        *(short*)(e + 0x10) += 1;
    }

    /// <summary>
    /// Ghidra: FUN_00476140 @ 0x00476140 — <b>le grain qui tourne autour d'une victime</b> : le
    /// sous-type <c>0x2e</c>, creneau <b>70</b> de <see cref="s_StaticEntityHandlers_00552230"/>.
    ///
    /// <para>
    /// <b>Corrige le 2026-09-01 : ce corps n'appartient pas a l'herboristerie.</b> Il etait ecrit
    /// et range sous le nom « TickHerbSeed », avec le sous-type <c>0x2d</c> et le creneau 45 — un
    /// decalage d'un cran dans la table, et une famille de rattachement fausse. Le sous-type
    /// <c>0x2d</c> est <see cref="EntityHandler_0047A880"/> ; le seul engendreur de <c>0x2e</c>
    /// dans <b>tout le binaire</b> est <see cref="TickStatusBurst_004760C0"/>, la gerbe de l'etat
    /// <c>0x80</c>, qui en seme <b>quatre</b> en croix. Le corps, lui, etait juste — et sa condition
    /// de survie le disait deja : elle lit le bit <c>0x80</c>, celui de l'effet 12, que jamais une
    /// herbe ne pose.
    /// </para>
    ///
    /// <para>
    /// <b>Ghidra a perdu deux valeurs sur ce corps</b> — il les rend en <c>unaff_EBX</c> et
    /// <c>unaff_retaddr</c>, la marque d'un parametre non reconstruit. Le desassemblage tranche, et
    /// la reponse est que <b>les deux sont la meme</b> : le rayon <c>(short)+0x12 &gt;&gt; 2</c>,
    /// calcule une fois en <c>0x00476155</c> et range sur la pile en <c>[esp+0x18]</c> avant les
    /// deux <c>push</c> qui decalent le cadre. Ghidra a lu les deux relectures comme deux entrees
    /// distinctes. Releve garde sous <c>Legacy/Raw/Blaze/FUN_00476140.asm</c>.
    /// </para>
    /// <para>
    /// <b>Elle tourne autour de la victime</b> (<c>+0x74</c>, que la gerbe a rempli pour elle) : un
    /// cercle du <b>quart</b> de <c>+0x12</c>, le cap avancant de <c>0x80</c> par image, a une
    /// hauteur fixe de <c>+0x12</c> unites au-dessus d'elle. Elle ne se sert donc <b>pas</b> de la
    /// vitesse heritee en <c>+0x50</c>..<c>+0x58</c> ni de la gravite <c>+0x9a</c>
    /// : ces champs sont poses, herites, et jamais lus par elle. Son image d'atlas boucle sur
    /// <c>+0x1a</c>.
    /// </para>
    /// <para>
    /// <b>Elle vit tant que la victime porte son etat</b> : elle relit le bloc de statistiques de
    /// la victime a chaque image et s'efface des que le bit <c>0x80</c> de <c>+0x40</c> tombe, ou
    /// des que le bit <c>0x40000000</c> se pose. Elle n'a pas de duree a elle — c'est sa mere qui
    /// cesse d'en semer.
    /// </para>
    /// </summary>
    private static void TickStatusMote_00476140(byte* record)
    {
        byte* e = record;

        short lift = *(short*)(e + 0x12);
        short yaw = *(short*)(e + 0x32);
        byte* anchor = *(byte**)(e + 0x74);

        // Ghidra: unaff_retaddr et unaff_EBX sont cette meme valeur, spillee en [esp+0x18].
        int radius = lift >> 2;

        *(int*)(e + 0x1c) = (int)Winsys3d.GetSinTableEntry(yaw) * radius + *(int*)(anchor + 0x1c);
        *(int*)(e + 0x20) = (lift << 0xc) + *(int*)(anchor + 0x20);
        *(int*)(e + 0x24) = Winsys3d.GetCosTableEntry(yaw) * radius + *(int*)(anchor + 0x24);

        *(short*)(e + 0x32) = (short)(yaw + 0x80);

        byte frame = (byte)(e[0x40] + 1);
        e[0x40] = frame;
        if (frame >= *(short*)(e + 0x1a)) e[0x40] = 0;

        uint state = *(uint*)(GetEntityStatBlock((uint*)anchor) + 0x40);

        if ((state & 0x80) == 0 || (state & 0x40000000) != 0) *(uint*)e = 0;
    }

    // =====================================================================
    // LES DEUX AURES D'ETAT — 0x46 et 0x47 de 0x00551c30, et leurs deux enfants
    //
    // Une entite d'aura par etat inflige, posee sur la VICTIME et non sur le lanceur. Les deux se
    // ressemblent assez pour se lire ensemble, et different sur un point qui compte :
    //
    //   0x004760C0   L'etat 0x80 (l'effet 12, FUN_0053b810). Une SEULE image : elle seme quatre
    //                enfants 0x2e en croix, puis s'eteint. L'aura ne dure pas ; les enfants si.
    //   0x004761D0   L'etat 0x40, LE SOMMEIL (l'effet 11, FUN_0053b730). Elle VIT : un enfant
    //                0x2f toutes les huit images, tant que la victime dort.
    //
    //   0x00476140   l'enfant de la premiere, sous-type 0x2e — deja ecrit.
    //   0x00476290   l'enfant de la seconde, sous-type 0x2f — ecrit ici.
    //
    // LES DEUX SUIVENT LA TETE DE LA VICTIME. Elles appellent StatusBubbleHeight_00538BC0 sur elle,
    // rangent la hauteur en +0x12 et s'en servent deux fois : pour poser l'enfant a cette hauteur
    // au-dessus d'elle, et pour l'echelle, `hauteur << n / 150`. Le decalage n differe — 0xd pour le
    // sommeil, 0xb pour l'autre —, donc les bulles du sommeil sont QUATRE FOIS plus grosses.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_004760c0 @ 0x004760c0 — <b>la gerbe de l'etat <c>0x80</c></b> : le sous-type
    /// <c>0x46</c>, creneau 70 de <see cref="s_StaticEntityHandlers_00551c30"/>. Vingt lignes.
    ///
    /// <para>
    /// <b>Elle ne vit qu'une image.</b> Elle se cale sur la victime (<c>+0x6c</c> recopie dans
    /// <c>+0x74</c>), prend sa hauteur de tete, seme <b>quatre</b> enfants <c>0x2e</c> en tournant
    /// le cap de <c>0x400</c> — un quart de tour — entre chacun, puis s'eteint. Ce sont les enfants
    /// qui portent la duree : ils vivent tant que la victime garde le bit <c>0x80</c>.
    /// </para>
    /// <para>
    /// Elle ne pose <b>pas</b> la position des enfants : <c>+0x1c</c>..<c>+0x24</c> partent tels que
    /// <see cref="SpawnStatusEffectEntity_0047AC40"/> les recopie, et
    /// <see cref="TickStatusMote_00476140"/> les recalcule des sa premiere image depuis
    /// <c>+0x74</c>. C'est ce qui la distingue de sa sœur du sommeil.
    /// </para>
    /// </summary>
    private static void TickStatusBurst_004760C0(byte* record)
    {
        byte* e = record;
        byte* victim = *(byte**)(e + 0x6c);

        *(byte**)(e + 0x74) = victim;

        int height = StatusBubbleHeight_00538BC0((uint*)victim);
        *(short*)(e + 0x12) = (short)height;

        uint scale = (uint)((height << 0xb) / 0x96);
        *(ushort*)(e + 0x1a) = 3;
        *(uint*)(e + 0x28) = scale << 0x10 | scale;

        for (int i = 0; i < 4; i++)
        {
            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), Descriptors005519A0(), 0x2e, e[0x0b], -1);

            *(short*)(e + 0x32) += 0x400;
        }

        *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_004761d0 @ 0x004761d0 — <b>l'aure du sommeil</b> : le sous-type <c>0x47</c>,
    /// creneau 71 de <see cref="s_StaticEntityHandlers_00551c30"/>. C'est l'entite que
    /// <see cref="ApplyStatusEffect_0053B730"/> — l'effet 11, bit <c>0x40</c> — fait naitre sur la
    /// victime en meme temps que la marque <c>0x29</c>.
    ///
    /// <para><b>Trois temps, et ils ne tombent pas ensemble :</b></para>
    /// <list type="bullet">
    /// <item><b>a la premiere image seulement</b> — elle prend la victime pour ancre, mesure sa
    /// hauteur de tete et en tire son echelle, <c>hauteur &lt;&lt; 13 / 150</c> dans les deux
    /// axes.</item>
    /// <item><b>une image sur huit</b> — un cap tire au hasard, la position reprise de la victime
    /// mais relevee de la hauteur de tete, et un enfant <c>0x2f</c> lache. Le test porte sur
    /// l'octet bas de <c>+0x10</c>, donc bien sur l'age et non sur un compteur separe.</item>
    /// <item><b>a chaque image</b> — elle relit le bloc de statistiques de la victime et s'efface
    /// des que celle-ci disparait, meurt, ou <b>se reveille</b> : le bit <c>0x40</c> de
    /// <c>+0x40</c> est la condition de sa survie.</item>
    /// </list>
    /// </summary>
    private static void TickSleepAura_004761D0(byte* record)
    {
        byte* e = record;
        byte* victim = *(byte**)(e + 0x6c);

        if (*(short*)(e + 0x10) == 0)
        {
            *(byte**)(e + 0x74) = victim;

            int height = StatusBubbleHeight_00538BC0((uint*)victim);
            *(short*)(e + 0x12) = (short)height;

            uint scale = (uint)((height << 0xd) / 0x96);
            *(uint*)(e + 0x28) = scale << 0x10 | scale;
        }

        // Ghidra lit l'octet bas de +0x10 : une image sur huit.
        if ((e[0x10] & 7) == 0)
        {
            *(short*)(e + 0x32) = (short)CrtRand();

            *(int*)(e + 0x1c) = *(int*)(victim + 0x1c);
            *(int*)(e + 0x20) = (*(short*)(e + 0x12) << 0xc) + *(int*)(victim + 0x20);
            *(int*)(e + 0x24) = *(int*)(victim + 0x24);

            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), Descriptors00551BA0() + 0x30, 0x2f, e[0x0b], -1);
        }

        uint state = *(uint*)(GetEntityStatBlock((uint*)victim) + 0x40);

        if ((*(uint*)victim & 0x80000000) == 0 || (state & 0x40000000) != 0 || (state & 0x40) == 0)
        {
            *(uint*)e = 0;
        }

        *(short*)(e + 0x10) += 1;
    }

    /// <summary>
    /// Ghidra: FUN_00476290 @ 0x00476290 — <b>la bulle du sommeil</b> : le sous-type <c>0x2f</c>,
    /// creneau 47 de <see cref="s_StaticEntityHandlers_00552230"/>. L'enfant que
    /// <see cref="TickSleepAura_004761D0"/> lache une image sur huit.
    ///
    /// <para>
    /// <b>Elle monte en ondulant.</b> Sa hauteur gagne <c>0x4000</c> par image — quatre unites — et
    /// sa derive horizontale est un balancement : l'amplitude est <c>sin(age &lt;&lt; 8) &gt;&gt;
    /// 10</c>, appliquee sur le cap <b>a angle droit</b> (<c>cap + 0x800</c>), et s'ajoute a une
    /// derive constante de quatre unites sur le cap lui-meme. Le cap ne bouge pas ; c'est
    /// l'amplitude qui change de signe, ce qui fait osciller la bulle de part et d'autre de sa
    /// trajectoire.
    /// </para>
    /// <para><b>Vingt images</b>, et elle s'eteint : elle n'a pas besoin de savoir si la victime
    /// dort encore, sa mere s'en charge et cesse d'en lacher.</para>
    /// </summary>
    private static void TickSleepBubble_00476290(byte* record)
    {
        byte* e = record;

        int heading = *(short*)(e + 0x32);
        int sway = (int)Winsys3d.GetSinTableEntry(*(short*)(e + 0x10) << 8);

        *(int*)(e + 0x1c) += (int)Winsys3d.GetSinTableEntry(heading + 0x800) * (sway >> 10)
                             + (int)Winsys3d.GetSinTableEntry(heading) * 4;
        *(int*)(e + 0x20) += 0x4000;

        int lateral = Winsys3d.GetCosTableEntry(heading + 0x800);
        int along = Winsys3d.GetCosTableEntry(heading);

        *(short*)(e + 0x10) += 1;

        *(int*)(e + 0x24) += lateral * (sway >> 10) + along * 4;

        if (*(short*)(e + 0x10) > 0x13) *(uint*)e = 0;
    }

    // =====================================================================
    // LES SORTS DE MONSTRE — familles 4 et 6, les deux seuls corps qui manquaient
    //
    //   0x004477D0   LE SORT DE LA FAMILLE 4. Sous-type 0x4b de 0x00551c30. 288 octets, ABSENT de
    //                Blaze.c ; releve sous Legacy/Raw/Blaze/FUN_004477D0.asm.
    //   0x004478F0   SON TRAIT, sous-type 0x51 de 0x00551f30. 415 octets, ABSENT de Blaze.c ;
    //                releve sous Legacy/Raw/Blaze/FUN_004478F0.asm.
    //   0x004769A0   LE SORT DE LA FAMILLE 6. Sous-type 0x4a de 0x00551c30. DECOMPILE, sept lignes.
    //   0x004769F0   SA BOULE, sous-type 0x28 de 0x00552230. 635 octets, ABSENTE de Blaze.c ;
    //                releve sous Legacy/Raw/Blaze/FUN_004769F0.asm.
    //
    // LA TABLE +0x9c PORTE HUIT FAMILLES, ET LES QUATRE DERNIERES NE SONT DESIGNEES PAR PERSONNE —
    // ni par une classe (0x00562ab8 n'en nomme que 0 a 3), ni par un script d'objet (l'opcode 14
    // n'emploie que 0, 1 et 2). Le seul appelant restant de CastSpell_0053A980 est le mot +0x06
    // d'une entite de scene : ce sont les sorts que les monstres lancent. Leurs noms sont restes
    // dans le jeu de caracteres d'origine, jamais traduits.
    //
    // ET SUR LES 43 FICHES RELEVEES, QUATRE SEULEMENT DESIGNENT UN VRAI CORPS. Les 39 autres
    // tombent sur DespawnEntity_0047ADC0, le bouche-trou. Des quatre, la famille 5 emploie
    // 0x0047a100 et la famille 7 emploie le corps de Meteores (0x00482370) — tous deux deja
    // ecrits. Restaient ces deux-ci. Le detail qui compte : leurs sous-types sont 0x49, 0x4a et
    // 0x4b, TROIS CRENEAUX CONSECUTIFS sur la PREMIERE fiche des familles 5, 6 et 4. Trois
    // emplacements voisins reserves a trois sorts de monstre ; tout le reste des 43 est du
    // remplissage, et l'etendue reelle de ces familles n'est toujours pas etablie.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_004477d0 @ 0x004477d0 — <b>le sort de la famille 4</b> : le sous-type
    /// <c>0x4b</c>, creneau 75 de <see cref="s_StaticEntityHandlers_00551c30"/>. 288 octets,
    /// <b>absent de <c>Blaze.c</c></b> ; le releve est garde sous
    /// <c>Legacy/Raw/Blaze/FUN_004477D0.asm</c>.
    ///
    /// <para>
    /// <b>C'est un depart de trait, et rien d'autre.</b> A sa premiere image il se fait haut et
    /// mince (<c>0x800</c> de large, <c>0x157c</c> de haut, <c>0xc00</c> de profond), se teinte de
    /// blanc plein, s'avance de <b>huit unites</b> dans son propre cap, se donne une vitesse de
    /// <b>neuf fois ce pas</b>, range le lanceur en <c>+0x78</c> et lache le trait
    /// <see cref="TickMonsterBolt_004478F0"/>. Puis il ne fait plus que <b>reprendre le meme eclat
    /// deux fois</b>, aux images 1 et 2, chaque fois plus sombre, et il s'eteint a la seizieme.
    /// </para>
    /// <para>
    /// <b>L'assombrissement se fait par debordement d'octet</b> : il ajoute <c>0xc0</c> aux trois
    /// composantes, donc <c>0xff</c> devient <c>0xbf</c> puis <c>0x7f</c>. C'est bien une addition
    /// dans le binaire, pas une soustraction, et le repli sur huit bits est ce qui la rend
    /// decroissante. Transcrit tel quel.
    /// </para>
    /// <para>
    /// <b>Il ne s'efface pas, il se desarme</b> : les deux sorties tombantes font
    /// <c>&amp;= 0x7fffffff</c> — elles enlevent le bit de vie et laissent le reste du mot debout —
    /// la ou la plupart des corps du depot ecrivent un zero franc. Son enfant fait de meme.
    /// </para>
    /// <para>
    /// Le bruit du depart n'est joue que si le bit <c>0x4000</c> de <c>+0x12</c> est absent.
    /// </para>
    /// </summary>
    private static void TickMonsterBoltCast_004477D0(byte* record)
    {
        byte* e = record;

        // Le porteur s'en va : on perd le bit de vie, et on continue quand meme cette image.
        if ((*(uint*)e & 0x40000000) != 0) *(uint*)e &= 0x7fffffff;

        short age = *(short*)(e + 0x10);

        if (age == 0)
        {
            e[0x36] |= 2;

            e[0x38] = 0xff;
            e[0x39] = 0xff;
            e[0x3a] = 0xff;

            *(uint*)e |= 0x682;

            *(ushort*)(e + 0x28) = 0x800;
            *(ushort*)(e + 0x2c) = 0xc00;
            *(ushort*)(e + 0x2a) = 0x157c;

            short yaw = *(short*)(e + 0x32);

            int stepX = (int)Winsys3d.GetSinTableEntry(yaw) << 3;
            int stepZ = Winsys3d.GetCosTableEntry(yaw) << 3;

            *(int*)(e + 0x1c) += stepX;
            *(int*)(e + 0x24) += stepZ;

            // Neuf fois le pas d'avance : le trait part vite.
            *(int*)(e + 0x50) = stepX * 9;
            *(int*)(e + 0x58) = stepZ * 9;

            e[0x04] = 0x1e;

            // Le lanceur, prete au trait par la voie longue : lui le lira en +0x6c de son pere.
            *(byte**)(e + 0x78) = *(byte**)(e + 0x6c);

            SpawnCastEntity_0047AAE0(e, 0x51, 0, 4);

            if ((*(ushort*)(e + 0x12) & 0x4000) == 0)
            {
                Aud.PlayPositionalSound(0x23, 0xca6, 0x1800, (int*)(e + 0x1c));
            }

            e[0x13] |= 0x40;
            return;
        }

        // Ghidra: LAB_0044789e — DEUX RAPPELS, aux images 1 et 2.
        if (age < 3)
        {
            // L'assombrissement par debordement : 0xff, 0xbf, 0x7f.
            e[0x38] += 0xc0;
            e[0x39] += 0xc0;
            e[0x3a] += 0xc0;

            *(uint*)e |= 0x2000;
            SpawnCastEntity_0047AAE0(e, 0x51, 0, 4);
            *(uint*)e &= 0xffffdfff;
        }

        // Ghidra: LAB_004478db
        *(short*)(e + 0x10) += 1;

        if (*(short*)(e + 0x10) >= 0x10) *(uint*)e &= 0x7fffffff;
    }

    /// <summary>
    /// Ghidra: FUN_004478f0 @ 0x004478f0 — <b>le trait de la famille 4</b> : le sous-type
    /// <c>0x51</c>, creneau 81 de <see cref="s_StaticEntityHandlers_00551f30"/>. 415 octets,
    /// <b>absent de <c>Blaze.c</c></b> ; le releve est garde sous
    /// <c>Legacy/Raw/Blaze/FUN_004478F0.asm</c>.
    ///
    /// <para>
    /// <b>Il vole huit images et frappe qui il touche.</b> Sa vitesse est amortie de <b>trois
    /// huitiemes</b> par image (un quart plus un huitieme, dans cet ordre) sur X et Z, jamais sur
    /// Y ; sa largeur perd <c>0x70</c> par image et sa profondeur <c>0xf0</c>, sa hauteur ne bouge
    /// pas ; sa teinte perd <c>0x0f</c> sur les trois composantes tant qu'elle le peut.
    /// </para>
    /// <para>
    /// <b>Il retrouve le lanceur par la voie longue</b> : son <c>+0x6c</c> est le <b>sort</b>, et
    /// c'est le <c>+0x6c</c> du sort qui porte le lanceur. Il le recopie en <c>+0x74</c> a chaque
    /// image, et c'est ce <c>+0x74</c> qu'il donnera comme assaillant au coup.
    /// </para>
    /// <para>
    /// <b>Le decor l'arrete</b> : une fois pose par <see cref="FinalizeEntityPlacement2"/>, si son
    /// etat <c>+0x90</c> porte <c>0x802</c>, ou s'il est descendu plus bas que le sol moins
    /// <c>0x32000</c>, ou si son porteur est marque, alors <b>le sort et lui prennent tous deux le
    /// bit <c>0x8000</c> de <c>+0x12</c></b> et sa vitesse tombe a zero. Sinon il se cale sur le
    /// sol. Ce bit est ce qui, a l'image suivante, lui fait sauter la pose : il est fiche en
    /// terre.
    /// </para>
    /// <para>
    /// <b>La recherche de cible change de camp selon le sien</b> : <c>0x600000</c> pose, il balaye
    /// le groupe (<see cref="SweepPartyForMeleeHit_00519C30"/>) ; sinon les entites de scene
    /// (<see cref="SweepSceneEntitiesForMeleeHit_00519AF0"/>). <b>Ce second appel ne passe que
    /// trois arguments la ou la fonction en lit quatre</b> — voir LB-029 dans
    /// <c>Documentation/Reference/legacy-bug.md</c>. Ce qui est touche prend un coup d'arme
    /// (<see cref="ResolveMeleeHit_00539B80"/>), le bit <c>0x40</c> et <c>0x14</c> en
    /// <c>+0x96</c>.
    /// </para>
    /// <para>
    /// <b>A la huitieme image il force l'age de son sort a 8</b> avant de se desarmer : c'est le
    /// seul moyen qu'il ait de dire au sort qu'il est fini, et le sort, qui meurt de toute facon a
    /// seize, s'en trouve avance.
    /// </para>
    /// </summary>
    private static void TickMonsterBolt_004478F0(byte* record)
    {
        byte* e = record;

        // La boite de detection, reconstruite sur la pile a chaque image.
        short* probe = stackalloc short[6] { 0, -50, 0x32, 0x82, 0, 0x64 };

        byte* spell = *(byte**)(e + 0x6c);

        // Le lanceur, retrouve par la voie longue : le +0x6c du sort.
        *(byte**)(e + 0x74) = *(byte**)(spell + 0x6c);

        if ((*(uint*)spell & 0x40000000) != 0) *(uint*)e &= 0x7fffffff;

        // Ghidra: LAB_0044793c
        if (*(short*)(e + 0x10) == 0) *(ushort*)(e + 0x12) &= 0x7fff;

        // Ghidra: LAB_00447948 — l'avance, puis l'amortissement de trois huitiemes.
        int velX = *(int*)(e + 0x50);
        int velZ = *(int*)(e + 0x58);

        *(int*)(e + 0x24) += velZ;
        *(int*)(e + 0x1c) += velX;

        *(ushort*)(e + 0x28) -= 0x70;
        *(ushort*)(e + 0x2c) -= 0xf0;

        *(int*)(e + 0x50) = velX - (velX >> 3) - (velX >> 2);
        *(int*)(e + 0x58) = velZ - (velZ >> 2) - (velZ >> 3);

        if (e[0x38] >= 0x0f)
        {
            e[0x38] -= 0x0f;
            e[0x39] += 0xf1;                              // = -0x0f, ecrit ainsi dans le binaire
            e[0x3a] += 0xf1;
        }

        // Ghidra: LAB_004479ab — fiche en terre, il ne se pose plus.
        if ((*(ushort*)(e + 0x12) & 0x8000) == 0)
        {
            FinalizeEntityPlacement2((uint*)e);

            uint state = *(uint*)(e + 0x90);
            int ground = *(int*)(e + 0x60);
            int y = *(int*)(e + 0x20);
            int floor = ground - 0x32000;

            if ((state & 0x802) != 0
                || y < floor
                || (*(uint*)e & 0x40000000) != 0
                || (*(ushort*)(spell + 0x12) & 0x8000) != 0)
            {
                // Ghidra: LAB_004479f5 — le sort et le trait se fichent ensemble.
                *(ushort*)(spell + 0x12) |= 0x8000;
                *(ushort*)(e + 0x12) |= 0x8000;
                *(int*)(e + 0x50) = 0;
                *(int*)(e + 0x58) = 0;
            }
            else if (y <= ground && y > floor)
            {
                *(int*)(e + 0x20) = ground;               // il se cale sur le sol
            }
        }

        // Ghidra: LAB_00447a0a — le bit 0x4000 lui interdit de frapper.
        if ((*(ushort*)(e + 0x12) & 0x4000) == 0)
        {
            byte* hit = (*(uint*)e & 0x600000) != 0
                ? SweepPartyForMeleeHit_00519C30(
                      *(byte**)(e + 0x74), (int*)(e + 0x1c), probe, 0)
                // LB-029 : le binaire n'empile ici que TROIS arguments. Le quatrieme que lit la
                // fonction est l'edi sauve par le prologue, donc une valeur quelconque.
                : SweepSceneEntitiesForMeleeHit_00519AF0(
                      *(byte**)(e + 0x74), (int*)(e + 0x1c), probe, 0);

            if (hit != null)
            {
                ResolveMeleeHit_00539B80(*(uint**)(e + 0x74), (uint*)hit);
                *(uint*)hit |= 0x40;
                *(ushort*)(hit + 0x96) = 0x14;
            }
        }

        // Ghidra: LAB_00447a6a — huit images, et il avance l'age de son sort en partant.
        *(short*)(e + 0x10) += 1;

        if (*(short*)(e + 0x10) >= 8)
        {
            *(ushort*)(spell + 0x10) = 8;
            *(uint*)e &= 0x7fffffff;
        }
    }

    /// <summary>
    /// Ghidra: FUN_004769a0 @ 0x004769a0 — <b>le sort de la famille 6</b> : le sous-type
    /// <c>0x4a</c>, creneau 74 de <see cref="s_StaticEntityHandlers_00551c30"/>. <b>Sept lignes</b>,
    /// et c'est le plus court corps de sort du depot.
    ///
    /// <para>
    /// <b>Il ne vit qu'une image</b> : il se donne une gravite de <c>-20</c>, lache la boule
    /// <see cref="TickMonsterOrb_004769F0"/> avec le huitieme descripteur de la plage
    /// <see cref="s_Descriptors_00551BA0"/>, joue son bruit et s'efface. Tout ce que fait le sort
    /// est dans son enfant.
    /// </para>
    /// </summary>
    private static void TickMonsterOrbCast_004769A0(byte* record)
    {
        byte* e = record;

        e[0x36] |= 2;
        *(short*)(e + 0x2e) = -20;

        SpawnStatusEffectEntity_0047AC40(
            e, (int*)(e + 0x1c), Descriptors00551BD8(), 0x28, 0, 2);

        Aud.PlayPositionalSound(0x23, 0x1e9c, 0xe00, (int*)(e + 0x1c));

        *(uint*)e = 0;
    }

    /// <summary>
    /// Ghidra: FUN_004769f0 @ 0x004769f0 — <b>la boule de la famille 6</b> : le sous-type
    /// <c>0x28</c>, creneau 40 de <see cref="s_StaticEntityHandlers_00552230"/>. 635 octets,
    /// <b>absente de <c>Blaze.c</c></b> ; le releve est garde sous
    /// <c>Legacy/Raw/Blaze/FUN_004769F0.asm</c>.
    ///
    /// <para>
    /// <b>Elle nait devant le lanceur, a mi-hauteur de sa tete</b> — le <c>(stature &amp; ~1) &lt;&lt;
    /// 11</c> qu'emploie aussi <see cref="TickSleepBubble_00476CF0"/> — et prend la vitesse du
    /// lanceur plus <b>quarante-huit unites</b> dans son propre cap. Ensuite elle ne fait plus que
    /// tomber : sa vitesse horizontale est amortie d'un quart par image, sa vitesse verticale est
    /// celle que le sort lui a donnee.
    /// </para>
    /// <para>
    /// <b>Sa teinte est son sablier</b> : elle perd <c>0x18</c> sur les trois composantes par
    /// image, et des qu'elle ne peut plus, elle <b>perd son bit de vie</b> — dix images, la teinte
    /// de depart <c>0xf0</c> etant exactement dix fois le pas. Et tant que cette teinte reste
    /// <b>au-dessus de <c>0x60</c></b>, elle seme a chaque image une etincelle <c>0xbe</c> dans une
    /// direction tiree au sort autour de son cap et de son tangage (<c>±0x100</c> sur l'un,
    /// <c>±0x100</c> autour de <c>0x900</c> sur l'autre) : <b>cinq images de trainee, puis plus
    /// rien</b>. Les six champs qu'elle emprunte pour engendrer — vitesse, echelle, teinte — lui
    /// sont rendus juste apres.
    /// </para>
    /// <para>
    /// <b>Trois fins, et deux seulement l'effacent.</b> Si son etat <c>+0x90</c> porte
    /// <c>0xa000</c>, ou si elle est encore en l'air, elle cherche un adversaire par
    /// <see cref="SweepOpposingSideForMeleeHit_00474C70"/> : ce qu'elle touche prend un coup d'arme
    /// et <b>la moitie de sa vitesse en poussee</b>, et elle disparait. Sinon elle a atteint le
    /// sol : elle s'y cale, y pose l'eclat <c>0xbd</c> et disparait. Et si elle ne touche rien en
    /// l'air, elle vieillit d'une image.
    /// </para>
    /// <para>
    /// <b>La perte du bit de vie ne l'arrete pas</b> : le corps continue jusqu'au bout de l'image,
    /// et peut encore frapper. C'est la passe de la table qui la retirera.
    /// </para>
    /// </summary>
    private static void TickMonsterOrb_004769F0(byte* record)
    {
        byte* e = record;

        short* probe = stackalloc short[6] { 0, -50, 0x32, 0x64, 0, 0x64 };

        if (*(short*)(e + 0x10) == 0)
        {
            byte* caster = *(byte**)(e + 0x74);

            *(ushort*)(e + 0x28) = 0xc00;
            *(ushort*)(e + 0x2a) = 0xc00;
            *(uint*)(e + 0x38) = 0x00f0f0f0;

            int height = StatusBubbleHeight_00538BC0((uint*)caster);

            // A MI-HAUTEUR DE TETE : la stature paire, decalee de onze et non de douze.
            *(int*)(e + 0x20) += (height & ~1) << 0xb;

            short yaw = *(short*)(e + 0x32);

            // La vitesse du lanceur, plus quarante-huit unites dans son propre cap.
            *(int*)(e + 0x50) = ((int)Winsys3d.GetSinTableEntry(yaw) * 3 << 4)
                                + *(int*)(caster + 0x50);
            *(int*)(e + 0x58) = (Winsys3d.GetCosTableEntry(yaw) * 3 << 4)
                                + *(int*)(caster + 0x58);
        }

        // Ghidra: LAB_00476a87 — LE SABLIER.
        if (e[0x38] >= 0x18)
        {
            e[0x38] -= 0x18;
            e[0x39] += 0xe8;                              // = -0x18, ecrit ainsi dans le binaire
            e[0x3a] += 0xe8;
        }
        else
        {
            // Ghidra: LAB_00476aa7 — elle perd son bit de vie et poursuit quand meme cette image.
            *(uint*)e &= 0x7fffffff;
        }

        // Ghidra: LAB_00476aad — LA TRAINEE, tant que la teinte est au-dessus de 0x60.
        if (e[0x38] > 0x60)
        {
            int savedVelX = *(int*)(e + 0x50);
            int savedVelY = *(int*)(e + 0x54);
            int savedVelZ = *(int*)(e + 0x58);
            int savedScale = *(int*)(e + 0x28);
            int savedDepth = *(int*)(e + 0x2c);
            int savedTint = *(int*)(e + 0x38);

            *(byte**)(e + 0x70) = null;

            int yaw = *(short*)(e + 0x32) - (CrtRand() & 0x1ff) + 0x100;
            int pitch = *(short*)(e + 0x34) - (CrtRand() & 0x1ff) + 0x900;

            // La direction de l'etincelle est ecrite PAR-DESSUS sa propre vitesse : c'est elle que
            // l'enfant heritera, et elle est rendue juste apres.
            SetVectorFromAngles_00532AD0((int*)(e + 0x50), yaw, pitch, 0x10);

            *(ushort*)(e + 0x12) = 3;
            *(uint*)(e + 0x28) = 0x06400640;
            *(ushort*)(e + 0x14) = 0x640;
            *(ushort*)(e + 0x16) = 0x1f;
            *(uint*)(e + 0x38) = 0x00808080;
            *(ushort*)(e + 0x1a) = 1;

            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), Descriptors00551BA8(), 0xbe, e[0x0b], -1);

            *(int*)(e + 0x54) = savedVelY;
            *(int*)(e + 0x58) = savedVelZ;
            *(int*)(e + 0x50) = savedVelX;
            *(int*)(e + 0x28) = savedScale;
            *(int*)(e + 0x2c) = savedDepth;
            *(int*)(e + 0x38) = savedTint;
        }

        // Ghidra: LAB_00476b8a — l'avance, et un quart d'amortissement horizontal.
        int velX = *(int*)(e + 0x50);
        int velZ = *(int*)(e + 0x58);

        *(int*)(e + 0x24) += velZ;
        *(int*)(e + 0x1c) += velX;

        *(int*)(e + 0x50) = velX - (velX >> 2);
        *(int*)(e + 0x58) = velZ - (velZ >> 2);

        // Y est mis de cote AVANT la pose et rendu apres : la pose le corrige, la boule non.
        int y = *(int*)(e + 0x20);

        FinalizeEntityPlacement2((uint*)e);

        uint state = *(uint*)(e + 0x90);
        *(int*)(e + 0x20) = y;

        int ground = *(int*)(e + 0x60);

        bool airborne = (state & 0xa000) != 0
                        || ((state & 0x802) == 0 && y > ground);

        if (!airborne)
        {
            // Ghidra: LAB_00476bdc — ELLE A TOUCHE LE SOL.
            if (y <= ground) *(int*)(e + 0x20) = ground;

            SpawnStatusEffectEntity_0047AC40(
                e, (int*)(e + 0x1c), Descriptors00551A08(), 0xbd, 0, 4);

            *(uint*)e = 0;
            return;
        }

        // Ghidra: LAB_00476c07 — ELLE CHERCHE QUELQU'UN.
        byte* hit = SweepOpposingSideForMeleeHit_00474C70(e, probe);

        if (hit != null)
        {
            ResolveMeleeHit_00539B80(*(uint**)(e + 0x74), (uint*)hit);

            // LA MOITIE DE SA VITESSE, PASSEE EN POUSSEE a ce qu'elle vient de frapper.
            *(int*)(hit + 0x50) += *(int*)(e + 0x50) >> 1;
            *(int*)(hit + 0x58) += *(int*)(e + 0x58) >> 1;

            *(uint*)hit |= 0x40;
            *(ushort*)(hit + 0x96) = 0x14;

            *(uint*)e = 0;
            return;
        }

        // Ghidra: LAB_00476c5f
        *(short*)(e + 0x10) += 1;
    }

    /// <summary>
    /// Ghidra: FUN_0051a5d0 @ 0x0051a5d0 — <b>la reconnaissance de la combinaison de boutons</b>
    /// saisie pendant l'incantation. Elle rend l'indice du sort dont la combinaison correspond, ou
    /// <c>-1</c>.
    ///
    /// <para>
    /// <b>C'est la table de sorts elle-meme qui porte les combinaisons.</b> Chaque fiche fait
    /// <c>0x30</c> octets ; <c>+0x1f</c> est la <b>longueur</b> de sa combinaison et <c>+0x20</c>
    /// ouvre la suite des coups attendus. La borne du balayage vient de
    /// <see cref="s_SpellCounts_00564600"/>, indexee par l'ecole <c>personnage[0x2b5]</c>.
    /// </para>
    /// <para>
    /// Cote joueur, <see cref="ApplyGroundMotion_0051A020"/> empile chaque bouton de face presse dans
    /// <c>entree[0x0c + n]</c> sous la forme <c>(manette[2..3] &gt;&gt; 8) &amp; 0xf0</c> et compte
    /// les coups dans <c>entree[0x0b]</c>, plafonne a <c>0x10</c>. <b>Les deux bornes se repondent
    /// exactement</b> : seize octets tiennent entre <c>+0x20</c> et la fin de la fiche, ce qui
    /// confirme les deux lectures l'une par l'autre.
    /// </para>
    /// <para>
    /// La comparaison est un <c>memcmp</c> que Ghidra a deroule ; il est reecrit en boucle. Le test
    /// <c>longueur != 0</c> est invariant de boucle dans le binaire — il est remonte avant, ce qui
    /// ne change rien : une combinaison vide ne correspond a rien et le balayage rendait
    /// <c>-1</c> apres l'avoir parcouru pour rien.
    /// </para>
    /// </summary>
    private static int PickCastTarget_0051A5D0(byte* entry, byte* perChar)
    {
        byte school = perChar[0x2b5];
        int count = s_SpellCounts_00564600[school];
        if (count == 0) return -1;

        byte length = entry[0x0b];
        if (length == 0) return -1;

        // La fiche de sort commence 0x20 octets plus tot ; on balaye directement les combinaisons.
        byte* combo = *(byte**)(*(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x9c)
                                + school * 4) + 0x20;

        for (int index = 0; index < count; index++, combo += 0x30)
        {
            if (length != combo[-1]) continue;          // la longueur, en +0x1f de la fiche

            int matched = 0;
            while (matched < length && entry[0x0c + matched] == combo[matched]) matched++;

            if (matched == length) return index;
        }

        return -1;
    }

    /// <summary>
    /// Ghidra: <c>(*(code *)(&amp;PTR_FUN_00562ce0)[bloc + 0x2b7])(…)</c> — quatre gestionnaires de
    /// commande, releves dans le binaire sous <see cref="s_InputHandlers_00562ce0"/>. Aucun n'est
    /// le corps vide.
    /// </summary>
    private static void DispatchInputHandler(byte index, uint* slot, byte* perChar, byte* pad)
    {
        uint target = index < s_InputHandlers_00562ce0.Length
            ? s_InputHandlers_00562ce0[index]
            : 0;

        switch (target)
        {
            case 0x0050E140: HandleDirectionalInput_0050E140(slot, perChar, pad); return;

            default:
                throw new NotImplementedException(
                    $"FUN_0050bf20 : le gestionnaire de commande d'indice {index} (table " +
                    $"0x00562ce0) vaut 0x{target:X6} et n'est pas transcrit. Les quatre entrees de " +
                    "la table sont relevees dans le binaire : 0x0050E140, 0x0050DE90 (toutes deux " +
                    "dans Blaze.c), 0x0050DD00 et 0x0050DFF0 (absentes, a desassembler). Il prend " +
                    "(entite, bloc par personnage, manette).");
        }
    }

    /// <summary>
    /// Ghidra: FUN_0050e140 @ 0x0050e140 — l'entree <b>0</b> de la table de commande
    /// <c>PTR_FUN_00562ce0</c> : <b>la marche a la croix directionnelle</b>. C'est le premier
    /// gestionnaire que la carte du monde atteint, et le seul chemin par lequel le joueur fait
    /// bouger son personnage.
    ///
    /// <para>
    /// Trois façons d'obtenir une direction, selon le bit 3 de <c>bloc + 0x140</c> : normalement
    /// la croix, lue a travers <see cref="s_PadDirection_00562dc8"/> ; quand le bit est pose — le
    /// personnage est desoriente — <b>une direction tiree au sort</b> des qu'une touche est
    /// enfoncee, et rien du tout sinon.
    /// </para>
    /// <para>
    /// La direction n'est convertie en cap qu'a la <b>transition</b> de la croix (bit 1 de
    /// <c>manette + 0xb</c>, consomme au passage), pas a chaque image : c'est ce qui empeche le
    /// personnage de tourner en continu tant qu'une direction est tenue. Le cap est relatif a la
    /// camera, arrondi au seizieme de tour (<c>(angle + 0x80) &amp; 0xf00</c>) — et la meme
    /// desorientation remplace cette reference par un tirage.
    /// </para>
    /// <para>
    /// La vitesse vient de <see cref="s_PostureSpeed_00562cc0"/>, sauf en mode de mise au point
    /// avec le modificateur tenu, ou elle passe a <c>0x3c000</c> — la marche rapide. Elle est
    /// ensuite mise a l'echelle par les memes trois drapeaux de <c>bloc + 0x140</c> que le membre
    /// suivi utilise pour sa distance d'arret.
    /// </para>
    /// </summary>
    private static void HandleDirectionalInput_0050E140(uint* slot, byte* perChar, byte* pad)
    {
        byte* s = (byte*)slot;
        int direction;

        if ((perChar[0x140] & 8) == 0)
        {
            direction = s_PadDirection_00562dc8[*pad >> 4];
        }
        else if ((*pad & 0xf0) == 0)
        {
            direction = 0;
        }
        else
        {
            direction = (CrtRand() & 7) + 1;
        }

        if (direction == 0)
        {
            if ((*slot & 0x47) == 0 && (*pad & 0xf0) == 0 && *(short*)(s + 0x18) != 0)
            {
                *(uint*)(s + 0x18) = 0;
                *slot |= 0x1000000;
            }

            return;
        }

        if ((*slot & 0x8000047) == 0 && *(short*)(s + 0x18) != 1)
        {
            *(uint*)(s + 0x18) = 1;
            *slot |= 0x1000000;
        }

        if ((pad[0x0b] & 2) != 0)
        {
            pad[0x0b] &= 0xfd;

            short reference = (perChar[0x140] & 8) == 0
                ? (short)((*(ushort*)(Mem.s_CameraVector_00604928 + 2) + 0x80u) & 0xf00)
                : (short)(((short)CrtRand() + 0x80u) & 0xf00);

            *(short*)(s + 0x32) = (short)((short)(direction * 0x200) - reference - 0x200);
        }

        *(short*)(s + 0x98) = *(short*)(s + 0x32);

        if (Mem.s_DebugModeLatch_005633a8 == 0)
        {
            *(int*)(s + 0x5c) = (pad[1] & 0x20) == 0
                ? s_PostureSpeed_00562cc0[perChar[0x150] & 7] << 0xc
                : 0x3c000;
        }
        else
        {
            *(int*)(s + 0x5c) = s_PostureSpeed_00562cc0[perChar[0x150] & 7] << 0xc;
        }

        uint posture = *(uint*)(perChar + 0x140);
        int scale = 0x1000;
        if ((posture & 0x4000) != 0) scale = 0x1333;
        if ((posture & 0x8000) != 0) scale = 0xccc;
        if ((posture & 4) != 0) scale = 0x800;

        *(int*)(s + 0x5c) = scale * *(int*)(s + 0x5c) >> 0xc;
    }

    /// <summary>
    /// Ghidra: <c>(*(code *)(&amp;PTR_FUN_00562ca0)[bloc + 0x150 &amp; 7])(…)</c> — huit gestionnaires
    /// de posture, releves sous <see cref="s_PostureHandlers_00562ca0"/>. <b>Quatre sont le corps
    /// vide <c>0x0040A600</c></b>, deja verifie au desassembleur : les postures 1, 2, 3 et 5 ne
    /// font rien.
    ///
    /// <para>
    /// <b>Les quatre autres sont maintenant ecrites</b> (2026-09-01). Le site d'appel empile cinq
    /// arguments — entite, entree d'emplacement, bloc par personnage, manette, animation courante —
    /// mais le desassemblage montre que trois des quatre corps ne lisent que le premier ; seule la
    /// posture 4 va chercher le troisieme. L'appel est en cdecl, donc les arguments non lus sont
    /// sans consequence.
    /// </para>
    /// </summary>
    private static void DispatchPostureHandler(
        byte posture, uint* slot, byte* entry, byte* perChar, byte* pad, byte* anim)
    {
        uint target = s_PostureHandlers_00562ca0[posture];

        switch (target)
        {
            case 0x0040A600: return;   // corps vide verifie au desassembleur
            case 0x0051A670: PostureHandler_0051A670(slot); return;
            case 0x0051A6B0: PostureHandler_0051A6B0(slot, perChar); return;
            case 0x0051A700: PostureHandler_0051A700(slot); return;
            case 0x0051A710: PostureHandler_0051A710(slot); return;

            default:
                throw new NotImplementedException(
                    $"FUN_0050bf20 : le gestionnaire de posture {posture} (table 0x00562ca0) vaut " +
                    $"0x{target:X6}, qui n'est aucune des cinq adresses relevees dans la table. " +
                    "La table est fausse, ou l'indice deborde.");
        }
    }

    /// <summary>
    /// Ghidra: FUN_0051a670 @ 0x0051a670 — la posture <b>0</b>, la marche : quatorze lignes.
    ///
    /// <para>
    /// Elle ne fait qu'une chose : a la <b>cinquieme image de l'etat 6</b>, elle fait naitre
    /// l'entite d'effet <c>0xba</c> — la trainee de l'arme, dont la table 0x005ff400 porte la
    /// duree de vie. Le test <c>param_1[6] == 0x50006</c> compare l'etat ET l'image en un seul
    /// dword, ce qui est la forme compacte de « etat 6, image 5 » : les deux <c>short</c> de
    /// <c>+0x18</c> et <c>+0x1a</c> lus ensemble.
    /// </para>
    /// <para>
    /// <b>Ghidra ne lui donne qu'un parametre</b> alors que le site d'appel en empile cinq. Ce
    /// n'est pas une signature manquee : le corps ne touche jamais aux quatre autres, et l'appel
    /// est en cdecl, donc sans consequence. Meme precedent que <c>FreezeAllEntities</c>.
    /// </para>
    /// </summary>
    private static void PostureHandler_0051A670(uint* slot)
    {
        byte* s = (byte*)slot;

        if ((*slot & 2) != 0 && *(uint*)(s + 0x18) == 0x50006)
        {
            SpawnEffectEntity(s, 0xba, 0, 0);
        }

        if ((*slot & 1) != 0) *slot &= 0xfffffffb;
    }

    // =====================================================================
    // LES TROIS DERNIERES POSTURES — 4, 6 et 7, absentes de `Blaze.c`, sorties du desassembleur
    // le 2026-09-01. Elles tiennent en 208 octets a elles trois.
    //
    // LES QUATRE GESTIONNAIRES DE POSTURE SONT LE MEME GESTE. Tous comparent le dword `+0x18` de
    // l'entite a une valeur exacte, et agissent a cette seule image. Ce dword est la paire
    // (etat d'animation, image) que `PostureHandler_0051A670` decrit : le `short` bas est l'etat,
    // le haut l'image. Les trois nouvelles visent toutes **l'etat 3**, celui du deplacement, a une
    // image precise du cycle — le moment ou le pied touche, ou l'aile bat.
    //
    // Et deux d'entre elles ne font pas naitre une entite d'effet : elles **lancent un sort**, par
    // le meme `CastSpell_0053A980` qu'une incantation. Les familles 5 et 6, indice 0 — deux des
    // quatre familles hors ecole, celles que `SortsAtteignables.md` compte a part.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_0051a6b0 @ 0x0051a6b0 — la posture <b>4</b>, 77 octets, <b>absente de
    /// <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// A une image precise de l'etat d'animation 3, elle leve le bit <c>0x800</c> de l'entite et
    /// lance la fiche de sort <b>famille 5, indice 0</b> (sous-type <c>0x49</c>). L'image visee
    /// depend du bit <c>8</c> de <c>+0x150</c> du bloc par personnage — <b>l'image 0x10 quand il
    /// est eteint, l'image 0x0c quand il est allume</b> : deux cycles de longueurs differentes pour
    /// la meme posture, et le meme effet pose au bon moment dans chacun.
    /// </para>
    /// <para>
    /// La cascade du binaire est ecrite « en losange » — le premier test retombe dans le second
    /// quand l'image est la bonne mais le bit aussi —, ce qui revient exactement aux deux
    /// conjonctions ci-dessous.
    /// </para>
    /// </summary>
    private static void PostureHandler_0051A6B0(uint* slot, byte* perChar)
    {
        if ((*slot & 2) == 0) return;

        uint frame = *(uint*)((byte*)slot + 0x18);
        bool alternate = (perChar[0x150] & 8) != 0;

        if ((frame == 0x100003 && !alternate) || (frame == 0x000c0003 && alternate))
        {
            // TODO(REVERSE): le bit 0x800 du mot d'etat de l'entite — pose ici et par la posture 7,
            // aucun lecteur identifie dans le transcrit. Voir REVERSE_STATUS.md, 2026-09-01.
            *slot |= 0x800;
            CastSpell_0053A980(slot, 5, 0, -1, -1);
        }
    }

    /// <summary>
    /// Ghidra: FUN_0051a700 @ 0x0051a700 — la posture <b>6</b>, <b>16 octets</b>, la plus courte du
    /// depot apres les corps vides, <b>absente de <c>Blaze.c</c></b>.
    ///
    /// <para>
    /// Elle est la <b>queue de <see cref="PostureHandler_0051A670"/></b>, seule : le compilateur a
    /// emis deux fois la meme fin. Cette posture ne fait donc que retomber le bit <c>0x04</c> quand
    /// le bit <c>0x01</c> est leve, sans rien engendrer.
    /// </para>
    /// </summary>
    private static void PostureHandler_0051A700(uint* slot)
    {
        if ((*slot & 1) != 0) *slot &= 0xfffffffb;
    }

    /// <summary>
    /// Ghidra: FUN_0051a710 @ 0x0051a710 — la posture <b>7</b>, 42 octets, <b>absente de
    /// <c>Blaze.c</c></b>. <b>C'est le vol</b> : la posture du Lutin, et celle qui plantait des
    /// l'entree en foret.
    ///
    /// <para>
    /// A l'image 3 de l'etat d'animation 3 — le battement d'aile —, elle leve le bit <c>0x800</c>
    /// et lance la fiche de sort <b>famille 6, indice 0</b> (sous-type <c>0x4a</c>, le gestionnaire
    /// <c>0x004769a0</c>). Rien d'autre : pas de queue en <c>0x04</c> comme les postures 0 et 6.
    /// </para>
    /// </summary>
    private static void PostureHandler_0051A710(uint* slot)
    {
        if ((*slot & 2) != 0 && *(uint*)((byte*)slot + 0x18) == 0x30003)
        {
            *slot |= 0x800;
            CastSpell_0053A980(slot, 6, 0, -1, -1);
        }
    }

    /// <summary>
    /// Ghidra: FUN_00474eb0 @ 0x00474eb0 — <b>cherche la cible la plus proche du camp d'en
    /// face</b>. Dix-neuf lignes d'aiguillage : selon le mode et le bit <c>0x800000</c> qui
    /// distingue un membre du groupe, elle balaie soit la table des entites de scene, soit celle
    /// du groupe.
    ///
    /// <para>
    /// Avec le mode <c>1</c> — le seul que la carte du monde emploie — un membre du groupe cherche
    /// parmi les entites de scene, et une entite de scene parmi les membres du groupe. C'est donc
    /// bien « l'adversaire le plus proche » et non un obstacle quelconque : le nom
    /// <c>FindNearbyObstacle</c> que ce depot lui donnait d'apres son seul site d'appel etait une
    /// supposition, corrigee ici.
    /// </para>
    /// <para>
    /// <b>Ghidra la declare <c>void</c></b> alors que son appelant lit son resultat. Ce n'est pas
    /// une signature manquee : les deux branches sont des appels <b>terminaux</b>, et le resultat
    /// de l'appelee traverse tel quel. Rendu explicitement ici.
    /// </para>
    /// </summary>
    private static byte* FindNearestOpponent_00474EB0(uint* entity, uint mask, int mode)
    {
        if (mode == 0)
        {
            if ((*entity & 0x800000) == 0) return FindNearestSceneEntity_00474DB0(entity, mask);
        }
        else if ((*entity & 0x800000) != 0)
        {
            return FindNearestSceneEntity_00474DB0(entity, mask);
        }

        return FindNearestPartyMember_00474CD0(entity);
    }

    /// <summary>
    /// Ghidra: FUN_00474db0 @ 0x00474db0 — la plus proche des 0x20 entites de scene
    /// (<c>DAT_005ecaa0</c>) dans un rayon de <b>600 unites</b>, en excluant la demanderesse
    /// elle-meme.
    ///
    /// <para>
    /// Quatre conditions filtrent les candidates : active (<c>0x80000000</c>), sans aucun des bits
    /// <c>0x50002040</c>, sans cible deja tenue a <c>+0x74</c>, et sans compte a rebours
    /// d'invulnerabilite a <c>+0x96</c>.
    /// </para>
    /// <para>
    /// Le <paramref name="mask"/> est teste par <c>(*bloc &amp; ~mask) == 0</c> contre le mot de
    /// <c>+0x14</c> du bloc de statistiques. <b>Le seul appelant passe -1</b>, ce qui rend
    /// <c>~mask</c> nul et la condition toujours vraie : le filtre existe mais dort.
    /// </para>
    /// </summary>
    private static byte* FindNearestSceneEntity_00474DB0(uint* entity, uint mask)
    {
        byte* self = (byte*)entity;
        int x = *(int*)(self + 0x1c);
        int y = *(int*)(self + 0x20);
        int z = *(int*)(self + 0x24);

        int best = 600;
        byte* found = null;

        byte* candidate = Mem.Entity(0x005ecaa0);
        byte* stats = s_EntityStatBlocks_005ea560 + 0x14;

        for (int i = 0x20; i != 0; i--, candidate += 0x9c, stats += 0x120)
        {
            if ((*(uint*)candidate & 0x80000000) != 0
                && (*(uint*)candidate & 0x50002040) == 0
                && (*(uint*)stats & ~mask) == 0
                && *(int*)(candidate + 0x74) == 0
                && *(short*)(candidate + 0x96) == 0)
            {
                int dx = (x - *(int*)(candidate + 0x1c)) >> 0xc;
                int dy = (y - *(int*)(candidate + 0x20)) >> 0xc;
                int dz = (z - *(int*)(candidate + 0x24)) >> 0xc;
                int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dy * dy + dz * dz));

                if (distance < best && self != candidate)
                {
                    best = distance;
                    found = candidate;
                }
            }
        }

        return found;
    }

    /// <summary>
    /// Ghidra: FUN_00474cd0 @ 0x00474cd0 — la jumelle de
    /// <see cref="FindNearestSceneEntity_00474DB0"/> sur la table du groupe
    /// (<c>DAT_005e93c0</c>), bornee a la taille reelle du groupe et sans le filtre de masque.
    /// Meme rayon de 600, memes quatre conditions, meme exclusion de soi.
    /// </summary>
    private static byte* FindNearestPartyMember_00474CD0(uint* entity)
    {
        byte* self = (byte*)entity;
        int best = 600;
        byte* found = null;

        int x = *(int*)(self + 0x1c);
        int y = *(int*)(self + 0x20);
        int z = *(int*)(self + 0x24);

        if (s_PartySize_005e9020 == 0) return null;

        byte* candidate = Inp.s_SlotFlags_005e93c0;

        for (int i = s_PartySize_005e9020; i != 0; i--, candidate += 0x9c)
        {
            if ((*(uint*)candidate & 0x80000000) != 0
                && (*(uint*)candidate & 0x50002040) == 0
                && *(int*)(candidate + 0x74) == 0
                && *(short*)(candidate + 0x96) == 0)
            {
                int dx = (x - *(int*)(candidate + 0x1c)) >> 0xc;
                int dy = (y - *(int*)(candidate + 0x20)) >> 0xc;
                int dz = (z - *(int*)(candidate + 0x24)) >> 0xc;
                int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dy * dy + dz * dz));

                if (distance < best && self != candidate)
                {
                    best = distance;
                    found = candidate;
                }
            }
        }

        return found;
    }

    /// <summary>Ghidra: FUN_00519df0 @ 0x00519df0 (51 l.) — applique la vitesse a la position et
    /// met a jour les drapeaux de collision de <c>+0x90</c>.</summary>
    /// <summary>
    /// Ghidra: FUN_00519df0 @ 0x00519df0 — <b>la collision contre le voisinage</b> : un balayage
    /// 3x3 des cellules de la <b>premiere</b> grille spatiale (celle de <c>0x1c4000</c>, que
    /// <see cref="TickEntityTable_005fa5e0"/> alimente) autour de l'entite, qui soumet chaque
    /// occupant a <c>FUN_00534330</c>.
    ///
    /// <para>
    /// La constante <c>0x3880</c> de la pseudo-C est la meme que celle de
    /// <see cref="LinkIntoWorldGrid"/> : <c>0x3880 * 0x20 * 4 = 0x1c4000</c>. Le pas de
    /// <c>0x80</c> entre deux cellules avance d'une rangee (0x20 cellules de quatre octets).
    /// </para>
    /// <para>
    /// <b>Ghidra reutilise <c>param_1</c> comme compteur de boucle</b> apres l'avoir sauve dans
    /// <c>puVar3</c> — d'ou un corps ou le meme nom designe tantot l'entite, tantot le nombre 3.
    /// Les deux ont ici des noms distincts.
    /// </para>
    /// <para>
    /// Le porteur de <c>+0x78</c> est <b>remis a zero avant le balayage</b> et relu apres : s'il a
    /// change, la position du nouveau porteur est recopiee dans l'entree d'emplacement. C'est ce
    /// qui permet a <see cref="ComputeCarrierOffset"/> de travailler au tour suivant.
    /// </para>
    /// </summary>
    private static void ApplyEntityMotion_00519DF0(uint* entity, byte* entry)
    {
        byte* e = (byte*)entity;
        byte* mainMem = GetMainMemPtr();

        uint previousCarrier = *(uint*)(e + 0x78);
        *(uint*)(e + 0x78) = 0;

        uint cellX = (uint)((((*(int*)(e + 0x1c) >> 0xc) + 0x2000) >> 9) - 1);
        *entity &= 0xffffffcf;
        uint cellZ = (uint)((((*(int*)(e + 0x24) >> 0xc) + 0x2000) >> 9) - 1);

        for (int column = 3; column != 0; column--)
        {
            int offset = (int)((cellZ + 0x3880) * 0x20 + cellX) * 4;
            uint row = cellZ;

            for (int step = 3; step != 0; step--)
            {
                if (cellX < 0x20 && row < 0x20)
                {
                    for (uint* occupant = *(uint**)(mainMem + offset);
                         occupant != null;
                         occupant = *(uint**)((byte*)occupant + 0x68))
                    {
                        if ((*occupant & 0x2000) == 0)
                        {
                            ResolveEntityContact_00534330(occupant, entity, entry);
                        }
                    }
                }

                offset += 0x80;
                row++;
            }

            cellZ = row - 3;
            cellX++;
        }

        uint carrier = *(uint*)(e + 0x78);
        if (carrier != 0 && carrier != previousCarrier)
        {
            byte* c = (byte*)(nuint)carrier;
            *(uint*)(entry + 0x28) = *(uint*)(c + 0x1c);
            *(uint*)(entry + 0x2c) = *(uint*)(c + 0x20);
            *(uint*)(entry + 0x30) = *(uint*)(c + 0x24);
        }
    }

    /// <summary>
    /// Ghidra: FUN_00534330 @ 0x00534330 — <b>le contact entre deux entites</b> : le personnage
    /// contre le maillage de collision d'un occupant voisin. Appelee par
    /// <see cref="ApplyEntityMotion_00519DF0"/> pour chaque occupant des neuf cellules de grille.
    /// C'est elle qui pose le porteur de <c>+0x78</c> et les bits de <c>+0x90</c>.
    ///
    /// <para>
    /// <b>2 464 octets</b> (0x00534330..0x00534cd0), 277 lignes de pseudo-C : une boucle sur les
    /// faces du maillage, avec par face un produit vectoriel dans les registres GTE emules puis
    /// jusqu'a trois <c>NormalClip</c> pour le test d'appartenance au triangle.
    /// </para>
    /// <para>
    /// <b>La pseudo-C ne peut pas etre transcrite telle quelle : elle confond les DEUX entites.</b>
    /// Ghidra declare <c>FUN_00534330(uint *param_1)</c> alors que le site d'appel en empile trois
    /// (<c>add esp,0Ch</c> en 0x00519e83), et il fait porter a un meme nom des acces qui visent des
    /// objets differents. La correspondance ci-dessous est <b>etablie au desassembleur</b> et
    /// suffit a rendre la pseudo-C utilisable :
    /// </para>
    /// <list type="table">
    /// <item><term><c>param_1</c>, <c>puStack_18</c></term><description>l'<b>argument 1</b>,
    /// l'occupant — <c>[esp+74h]</c> apres les quatre <c>push</c> du prologue. Les deux noms
    /// designent le meme objet : <c>puStack_18 = param_1</c> en tete de boucle et
    /// <c>param_1 = puStack_18</c> en queue.</description></item>
    /// <item><term><c>local_14</c> <i>vu comme une entite</i></term><description>l'<b>argument
    /// 2</b>, le personnage qui se deplace — <c>[esp+78h]</c>.</description></item>
    /// <item><term><c>local_14</c> <i>passe a FUN_0051c300 / FUN_005327b0 / Ordinal_366</i></term>
    /// <description>un <b>tampon local de neuf shorts</b> a <c>[esp+5Ch]</c>, la matrice de
    /// l'occupant. Rien a voir avec l'entite ci-dessus : Ghidra a fusionne deux emplacements de
    /// pile voisins.</description></item>
    /// <item><term><c>iStack_10</c></term><description>l'<b>argument 3</b>, l'entree
    /// d'emplacement — <c>[esp+7Ch]</c>. Elle recoit le vecteur de contact a <c>+0x1c</c> et la
    /// pose de l'occupant a <c>+0x28</c>..<c>+0x48</c>.</description></item>
    /// <item><term><c>puStack_54</c></term><description>le bloc de modele de l'occupant, mis de
    /// cote en tete et restaure a chaque tour de boucle.</description></item>
    /// </list>
    /// <para>
    /// <b>Le recoupement decisif est 0x00534778</b> : <c>mov [edi+78h],esi</c> puis
    /// <c>mov ecx,[esp+7Ch] ; mov [ecx+1Ch],edx</c> ou <c>edx = [edi+1Ch] - [esi+1Ch]</c>. EDI est
    /// l'argument 2 et ESI l'argument 1, donc <c>entite[0x78] = occupant</c> et
    /// <c>entree[0x1c] = entite.x - occupant.x</c> — ce que la pseudo-C rend en
    /// <c>local_14[0x1e] = puStack_18</c> et
    /// <c>*(uint *)(iStack_10 + 0x1c) = local_14[7] - puStack_18[7]</c>.
    /// </para>
    /// <para>
    /// <b>Le danger de cette fonction est le silence.</b> Intervertir les deux entites compile,
    /// tourne, et rend une collision qui pousse le decor au lieu du personnage. Aucun compteur de
    /// primitives ne le dirait. Verifier chaque acces contre la table ci-dessus avant de
    /// l'ecrire, et ne rien deduire du nom seul.
    /// </para>
    /// <para>
    /// Les six termes du <c>NormalClip</c> sont <b>inlines</b> ici et le depot en porte deja la
    /// version reconstruite (<c>FUN_0051c280</c>, <c>Platform/Winsys3d.cs</c>) : les recouper terme
    /// a terme avant d'appeler, Ghidra les emet dans un autre ordre — precedent deja paye sur
    /// <c>FinalizeEntityPlacement2</c>.
    /// </para>
    /// </summary>
    private static uint ResolveEntityContact_00534330(uint* occupantPtr, uint* entityPtr, byte* entry)
    {
        byte* occupant = (byte*)occupantPtr;
        byte* entity = (byte*)entityPtr;
        byte* mainMem = GetMainMemPtr();

        EnsureGteRegisters();

        // Le maillage de collision de l'occupant, choisi par son type et le decalage de zone.
        byte* model = *(byte**)(Mem.Entity(0x005f7bc0) + (occupant[4] + *Mem.Entity(0x00600838)) * 4);

        // La rangee de translation du registre MATRIX est mise a zero : on travaille en repere
        // local de l'occupant, la translation est faite a la main par les deltas ci-dessous.
        *(int*)(s_GteMatrix814 + 0x1c) = 0;
        *(int*)(s_GteMatrix814 + 0x18) = 0;
        *(int*)(s_GteMatrix814 + 0x14) = 0;

        short* matrix = stackalloc short[9];
        RotMatrix((short*)(occupant + 0x30), matrix);
        ScaleMatrix_005327B0(matrix, (ushort*)(occupant + 0x28));
        Winsys3d.Ordinal_366(matrix);

        // Les deux nappes de sommets transformes : les positions dans MainMem + 0x1b0000, les
        // normales dans + 0x1b8000. Le mot de tete du modele porte les deux comptes.
        uint counts = *(uint*)model;
        Winsys3d.Ordinal_792((short*)(model + 0x40), (short*)(mainMem + 0x1b0000), counts & 0xffff);
        Winsys3d.Ordinal_792(*(short**)(model + 0x24), (short*)(mainMem + 0x1b8000),
            (uint)((int)counts >> 0x10) & 0xffff);

        bool pushed = false;      // Ghidra: bVar6
        bool overFace = false;    // Ghidra: bVar5

        int occupantY = *(int*)(occupant + 0x20);
        int entityY = *(int*)(entity + 0x20);

        short* faceIndex = *(short**)(*(byte**)(model + 0x38) + 4);

        // **L'asymetrie de ces trois deltas est reelle**, verifiee au desassembleur
        // (0x005343ef..0x0053440a) : X et Z sont pris `entite - occupant`, mais Y
        // `occupant - entite`. Ce n'est pas un artefact de Ghidra, et ce n'est pas corrige.
        int deltaX = (*(int*)(entity + 0x1c) - *(int*)(occupant + 0x1c)) >> 0xc;
        int deltaZ = (*(int*)(entity + 0x24) - *(int*)(occupant + 0x24)) >> 0xc;

        *(uint*)s_GteSxy807 = ((uint)deltaZ << 0x10) | ((uint)deltaX & 0xffff);

        int* vec799 = (int*)s_GteVec799;
        int* vec800 = (int*)s_GteVec800;
        int* mac801 = (int*)s_GteMac801;
        short* ir813 = (short*)s_GteIr813;

        while (true)
        {
            short index = *faceIndex;

            if (index < 0)
            {
                if (!overFace) break;

                // L'entite repose sur une face de cet occupant sans le traverser.
                *(uint*)(occupant + 0x70) = (uint)(nuint)entity;
                if ((*entityPtr & 0x10000) == 0)
                {
                    *(uint*)(occupant + 0x6c) = (uint)(nuint)entity;
                    *occupantPtr |= 0x40;
                }

                if ((*entityPtr & 0x40012000) == 0)
                {
                    byte kind = (byte)(occupant[0x0d] & 0xf);
                    if (kind == 0 || (kind == 1 && (occupant[9] & 0xf) == 0))
                    {
                        RunEntityScript(s_Unknown_005e97cc, entity, *(ushort*)(occupant + 0x0e));
                    }
                }

                if (pushed)
                {
                    *(uint*)(entity + 0x90) |= 0x8000800;
                    *(int*)(occupant + 0x50) += *(int*)(entity + 0x50);
                    *(int*)(occupant + 0x58) += *(int*)(entity + 0x58);
                }

                occupant[9] |= (byte)(1 << (int)(*(uint*)(entity + 8) & 0x1f));
                return FinishContact(occupantPtr, entityPtr);
            }

            byte* face = *(byte**)(model + 0x28) + index * 0x10;
            uint corners = *(uint*)face;
            ushort attributes = *(ushort*)(face + 0x0c);
            uint* normal = (uint*)(mainMem + 0x1b8000 + face[4] * 8);

            byte* cache = mainMem + 0x1b0000;
            short* a = (short*)(cache + (corners & 0xff) * 8);
            short* b = (short*)(cache + ((corners >> 8) & 0xff) * 8);
            short* c = (short*)(cache + ((corners >> 0x10) & 0xff) * 8);

            // Le produit vectoriel des deux aretes de la face, depose dans MAC1..3 puis recopie
            // dans IR1..3 — la normale non normalisee.
            vec800[0] = b[0] - a[0];
            vec800[1] = b[1] - a[1];
            vec800[2] = b[2] - a[2];
            vec799[0] = c[0] - a[0];
            vec799[1] = c[1] - a[1];
            vec799[2] = c[2] - a[2];

            mac801[0] = vec799[2] * vec800[1] - vec799[1] * vec800[2];
            mac801[1] = vec800[2] * vec799[0] - vec799[2] * vec800[0];
            mac801[2] = vec799[1] * vec800[0] - vec800[1] * vec799[0];

            ir813[0] = (short)mac801[0];
            ir813[1] = (short)mac801[1];
            ir813[2] = (short)mac801[2];

            int normalY = mac801[1];
            int planar = (deltaZ - a[2]) * mac801[2] + (deltaX - a[0]) * mac801[0];
            int side = (((occupantY - entityY) >> 0xc) - a[1]) * normalY + planar;

            // De quel cote du plan de la face l'entite se trouve-t-elle ? Les faces marquees
            // 0x2000 sont a sens unique et laissent passer par en dessous.
            if ((normalY == 0 && side >= 0)
                || (normalY > 0 && side > 0)
                || (normalY < 0 && side > 0 && (attributes & 0x2000) != 0))
            {
                break;
            }

            if ((attributes & 0x2000) == 0)
            {
                // Le test d'appartenance, en projection sur le plan XZ : trois (ou quatre pour un
                // quad) NormalClip contre les aretes. Les six termes inlines par le compilateur
                // sont **terme a terme** ceux de Winsys3d.NormalClip, deja reconstruit — recoupes
                // avant d'appeler, comme FinalizeEntityPlacement2 l'a exige en aout.
                uint flatA = ((uint)a[2] << 0x10) | (ushort)a[0];
                uint flatB = ((uint)b[2] << 0x10) | (ushort)b[0];
                uint flatC = ((uint)c[2] << 0x10) | (ushort)c[0];

                *(uint*)s_GteSxy805 = flatA;
                *(uint*)s_GteSxy806 = flatB;

                if (NormalClip() >= 0)
                {
                    *(uint*)s_GteSxy805 = flatB;
                    *(uint*)s_GteSxy806 = flatC;

                    if (NormalClip() >= 0)
                    {
                        int last;

                        if ((attributes & 1) == 0)
                        {
                            *(uint*)s_GteSxy805 = flatC;
                            *(uint*)s_GteSxy806 = flatA;
                            last = NormalClip();
                        }
                        else
                        {
                            // Face a quatre sommets : le quatrieme est l'octet haut du mot de
                            // coins, et le test se fait en deux aretes de plus.
                            short* d = (short*)(cache + (corners >> 0x18) * 8);
                            uint flatD = ((uint)d[2] << 0x10) | (ushort)d[0];

                            *(uint*)s_GteSxy805 = flatC;
                            *(uint*)s_GteSxy806 = flatD;
                            if (NormalClip() < 0) goto nextFace;

                            *(uint*)s_GteSxy805 = flatD;
                            *(uint*)s_GteSxy806 = flatA;
                            last = NormalClip();
                        }

                        if (last >= 0)
                        {
                            // L'entite est au-dessus de cette face : on en deduit la hauteur du
                            // plan sous elle.
                            int height = normalY == 0
                                ? occupantY
                                : (planar / normalY - a[1]) * 0x1000 + occupantY;

                            int reach = -0x32000;
                            if (*(int*)(entity + 0x54) < 0) reach = *(int*)(entity + 0x54) - 0x32000;

                            if (height + reach <= entityY)
                            {
                                *occupantPtr |= 0x20;
                                *entityPtr |= 0x20;

                                if ((*(int*)(entity + 0x64) <= height && (attributes & 0x1000) == 0)
                                    || (*(uint*)(entity + 0x90) & 4) != 0)
                                {
                                    *(int*)(entity + 0x64) = height;
                                    *(uint*)(entity + 0x78) = (uint)(nuint)occupant;
                                    PublishContact(entry, entity, occupant, normal);
                                }

                                if (*(int*)(entity + 0x60) <= height
                                    || (*(uint*)(entity + 0x90) & 4) != 0)
                                {
                                    *(int*)(entity + 0x60) = height;
                                    *(uint*)(entity + 0x78) = (uint)(nuint)occupant;

                                    if ((*(uint*)(entity + 0x90) & 0x8800) == 0)
                                    {
                                        *(uint*)(entity + 0x90) = attributes;
                                    }

                                    if (entityY <= height)
                                    {
                                        // Contact franc : l'entite est posee dessus.
                                        (*(short*)(occupant + 0x96))++;
                                        *occupantPtr |= 0x10;
                                        *(int*)(entity + 0x54) = 0;
                                        *entityPtr |= 0x10;
                                        PublishContact(entry, entity, occupant, normal);

                                        uint slotIndex = *(uint*)(entity + 8);
                                        *(uint*)(occupant + 0x70) = (uint)(nuint)entity;
                                        occupant[9] |= (byte)((1 << (int)(slotIndex & 0x1f)) << 4);

                                        if ((*entityPtr & 0x10000) == 0)
                                        {
                                            *(uint*)(occupant + 0x6c) = (uint)(nuint)entity;
                                        }

                                        if ((*entityPtr & 0x40012000) == 0
                                            && (occupant[0x0d] & 0xf) == 4)
                                        {
                                            RunEntityScript(s_Unknown_005e97cc, entity,
                                                *(ushort*)(occupant + 0x0e));
                                        }

                                        return FinishContact(occupantPtr, entityPtr);
                                    }
                                }

                                return 0;
                            }

                            // Trop haut pour se poser : la hauteur est notee et l'entite sera
                            // poussee au tour suivant.
                            *(int*)(entry + 4) = height;
                            pushed = true;
                            overFace = true;
                        }
                    }
                }
            }
            else
            {
                overFace = true;
            }

        nextFace:
            faceIndex++;
        }

        // Ghidra: LAB_0053470b — aucune face ne porte l'entite.
        if ((*entityPtr & 0x40012000) == 0 && (occupant[0x0d] & 0xf) == 2)
        {
            RunEntityScript(s_Unknown_005e97cc, entity, *(ushort*)(occupant + 0x0e));
        }

        occupant[9] &= (byte)~(1 << (int)(*(uint*)(entity + 8) & 0x1f));
        return 0;
    }

    /// <summary>
    /// Ghidra: <c>LAB_005348d5</c> — les deux lignes communes aux deux sorties « contact » de
    /// <see cref="ResolveEntityContact_00534330"/>.
    /// </summary>
    private static uint FinishContact(uint* occupantPtr, uint* entityPtr)
    {
        if ((*occupantPtr & 0x10000000) == 0 && (*entityPtr & 0x10000) == 0)
        {
            *occupantPtr &= 0xbfffffff;
        }

        return 1;
    }

    /// <summary>
    /// Le bloc de treize ecritures que <see cref="ResolveEntityContact_00534330"/> repete
    /// <b>a l'identique</b> a ses deux points de contact : le vecteur qui separe les deux entites,
    /// la pose complete de l'occupant, et les deux mots de normale de la face touchee.
    /// Factorise parce que c'est une unite reellement independante — le meme bloc, deux fois.
    /// </summary>
    private static void PublishContact(byte* entry, byte* entity, byte* occupant, uint* normal)
    {
        *(uint*)(entry + 0x1c) = (uint)(*(int*)(entity + 0x1c) - *(int*)(occupant + 0x1c));
        *(uint*)(entry + 0x20) = (uint)(*(int*)(entity + 0x20) - *(int*)(occupant + 0x20));
        *(uint*)(entry + 0x24) = (uint)(*(int*)(entity + 0x24) - *(int*)(occupant + 0x24));

        *(uint*)(entry + 0x28) = *(uint*)(occupant + 0x1c);
        *(uint*)(entry + 0x2c) = *(uint*)(occupant + 0x20);
        *(uint*)(entry + 0x30) = *(uint*)(occupant + 0x24);
        *(uint*)(entry + 0x34) = *(uint*)(occupant + 0x28);
        *(uint*)(entry + 0x38) = *(uint*)(occupant + 0x2c);
        *(uint*)(entry + 0x3c) = *(uint*)(occupant + 0x30);
        *(uint*)(entry + 0x40) = *(uint*)(occupant + 0x34);

        *(uint*)(entry + 0x44) = normal[0];
        *(uint*)(entry + 0x48) = normal[1];
    }

    /// <summary>
    /// Ghidra: FUN_005327b0 @ 0x005327b0 — le <c>ScaleMatrix</c> du SDK : chaque <b>colonne</b> de
    /// la matrice 3x3 est multipliee par un facteur en 1.12 pris dans un triplet de
    /// <c>ushort</c>.
    ///
    /// <para>
    /// L'original passe par les registres GTE emules — le facteur dans 812, la colonne dans
    /// IR1..3 (813), le produit dans MAC1..3 (801) — et non par des variables. Transcrit tel quel :
    /// ces registres sont observables depuis le reste du moteur, et rien ne garantit qu'aucun
    /// lecteur ne les regarde entre deux appels.
    /// </para>
    /// <para>Ce sont bien les <b>colonnes</b> et non les rangees : la fonction touche les indices
    /// 0/3/6, puis 1/4/7, puis 2/5/8.</para>
    /// </summary>
    private static void ScaleMatrix_005327B0(short* matrix, ushort* scale)
    {
        EnsureGteRegisters();

        ushort* factor = (ushort*)s_GteScale812;
        short* ir = (short*)s_GteIr813;
        int* mac = (int*)s_GteMac801;

        for (int column = 0; column < 3; column++)
        {
            *factor = scale[column];
            ir[0] = matrix[column];
            ir[1] = matrix[column + 3];
            ir[2] = matrix[column + 6];

            mac[0] = (int)(*factor * ir[0]) >> 0xc;
            ir[0] = (short)mac[0];
            mac[1] = (int)(ir[1] * *factor) >> 0xc;
            ir[1] = (short)mac[1];
            mac[2] = (int)(ir[2] * *factor) >> 0xc;
            ir[2] = (short)mac[2];

            matrix[column] = ir[0];
            matrix[column + 3] = ir[1];
            matrix[column + 6] = ir[2];
        }
    }

    /// <summary>
    /// Ghidra: FUN_00519f50 @ 0x00519f50 — <b>la laisse</b> : l'entite est ramenee vers le point
    /// que suit la camera des qu'elle s'en eloigne de plus de 400 unites, proportionnellement a
    /// l'exces. En deca, elle se contente de poser le bit <c>0x100</c>.
    ///
    /// <para>
    /// <b>Ghidra a fondu les deux parametres en un.</b> Il declare
    /// <c>void FUN_00519f50(uint *param_1)</c> et rend l'ecriture de la distance comme
    /// <c>*(undefined2 *)param_1 = …</c>, c'est-a-dire dans la moitie basse du mot d'etat de
    /// l'entite — ce qui ecraserait seize drapeaux. Le desassemblage dit autre chose :
    /// <c>0x00519f9b</c> lit <c>[esp+18h]</c>, soit <b>le second argument</b> apres les quatre
    /// <c>push</c> du prologue, et ecrit la distance dans <c>[ecx]</c>. La distance va donc dans
    /// l'<b>entree d'emplacement</b>, pas dans l'entite.
    /// </para>
    /// <para>
    /// C'est le cinquieme parametre perdu de cet arbre d'appel, et le plus dangereux : les quatre
    /// autres se voyaient parce que la pseudo-C lisait une variable jamais ecrite. Celui-ci
    /// <b>compile et tourne</b>, en corrompant seize drapeaux a chaque image.
    /// </para>
    /// </summary>
    private static void PullEntityTowardCameraTarget_00519F50(uint* entity, byte* entry)
    {
        byte* e = (byte*)entity;

        *entity &= 0xfffffeff;
        if ((*(uint*)(e + 0x90) & 0x8000) != 0) return;

        int dx = (*Mem.Camera(0x005de098) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*Mem.Camera(0x005de0a0) - *(int*)(e + 0x24)) >> 0xc;
        *(ushort*)entry = (ushort)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));

        dz = (*Mem.Camera(0x005de070) - *(int*)(e + 0x24)) >> 0xc;
        dx = (*Mem.Camera(0x005de068) - *(int*)(e + 0x1c)) >> 0xc;

        int angle = Winsys3d.Ordinal_457(dx, dz);
        int excess = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz)) - 400;

        uint flags = *entity;
        if (excess < 1)
        {
            if ((flags & 0x4000) == 0) *entity = flags | 0x100;
        }
        else if ((flags & 0x40000000) == 0)
        {
            *(int*)(e + 0x50) += (int)Winsys3d.GetSinTableEntry(angle) * excess;
            *(int*)(e + 0x58) += Winsys3d.GetCosTableEntry(angle) * excess;
        }
    }

    /// <summary>
    /// Ghidra: FUN_00519ee0 @ 0x00519ee0 — <b>le clignotement d'invulnerabilite</b>. Le compte a
    /// rebours de <c>+0x96</c> descend, et sa parite alterne entre le rendu normal (mode 1, blanc)
    /// et le rendu teinte (mode 5, orange <c>0x4080ff</c>). A zero, le bit <c>0x40</c> tombe.
    ///
    /// <para>
    /// La garde du haut fait retomber trois etats de deplacement (0, 1 et 4) sur l'etat 2 des que
    /// <c>0x40</c> est pose : un personnage touche ne marche plus, il encaisse.
    /// </para>
    /// <para>
    /// Comme <see cref="PostureHandler_0051A670"/>, Ghidra ne lui donne qu'un parametre alors que
    /// le site d'appel en empile deux ; le corps ne lit pas le second.
    /// </para>
    /// </summary>
    private static void UpdateEntityShadow_00519EE0(uint* entity, byte* perChar)
    {
        byte* e = (byte*)entity;

        if ((*entity & 0x40) != 0)
        {
            short state = *(short*)(e + 0x18);
            if (state == 0 || state == 1 || state == 4)
            {
                *(uint*)(e + 0x18) = 2;
                *entity &= 0xfefffff9;
            }
        }

        if (*(short*)(e + 0x96) != 0)
        {
            ushort remaining = (ushort)(*(short*)(e + 0x96) - 1);
            *(ushort*)(e + 0x96) = remaining;

            if ((remaining & 1) == 0)
            {
                *(ushort*)(e + 0x36) = 1;
                *(uint*)(e + 0x38) = 0xffffff;
            }
            else
            {
                *(ushort*)(e + 0x36) = 5;
                *(uint*)(e + 0x38) = 0x4080ff;
            }

            if (remaining == 0) *entity &= 0xffffffbf;
        }
    }

    /// <summary>Ghidra: FUN_005335e0 @ 0x005335e0 (78 l.) — l'angle de la pente sous une
    /// position.</summary>
    private static int GroundSlopeAngle_005335E0(uint* entity, int* position)
        => throw new NotImplementedException(
            "FUN_005335e0 (0x005335e0) : non transcrite. 78 lignes dans Blaze.c — l'angle de la " +
            "face du terrain sous une position, dont la sonde se sert pour recaler le cap contre " +
            "un mur.");

    /// <summary>
    /// Ghidra: <c>LAB_0050caf3</c>, 0x0050caf3..0x0050dc0d — <b>la queue commune</b> de
    /// <see cref="TickPartyMember"/> : tous les chemins y aboutissent. Environ 500 lignes de
    /// pseudo-C.
    /// </summary>
    private static void TickPartyMemberTail(
        int member, byte* s, uint* slot, byte* entry, byte* pad, byte* perChar, byte* mainMem)
    {
        // ---------------------------------------------- (A) la restitution d'etat
        uint held = *slot;
        uint attributes = *(uint*)(s + 0x90);

        if (((held & 0x40000001) != 0 || (attributes & 0xad40) != 0)
            && (s[0x90] & 2) == 0 && (held & 0x20000000) != 0)
        {
            if ((held & 0x4000) == 0) *slot = held | 0x4000;

            // Le membre reprend l'etat d'un camarade valide ; a defaut, celui que la sous-zone a
            // mis de cote en entrant. La boucle s'arrete AUSSI sur le premier camarade qui porte
            // 0x4001 sans le bit 0x8000 — auquel cas rien n'est restitue du tout.
            bool restored = false;
            int index = 0;
            uint* donor = (uint*)Inp.s_SlotFlags_005e93c0;

            while (index < s_PartySize_005e9020)
            {
                if (donor != slot && (*donor & 0x50000000) == 0)
                {
                    byte* d = (byte*)donor;
                    if ((*donor & 0x4001) == 0)
                    {
                        Mem.CopyDwords((uint*)(d + 0x7c), (uint*)(s + 0x7c), 7);
                        Mem.CopyDwords((uint*)(d + 0x1c), (uint*)(s + 0x1c), 3);
                        Mem.CopyDwords((uint*)(d + 0x60), (uint*)(s + 0x60), 2);
                        Mem.CopyDwords(
                            (uint*)(Inp.s_SlotArea_005e9180 + index * 0x4c + 0x1c),
                            (uint*)(entry + 0x1c), 0xc);

                        *(int*)(s + 0x78) = *(int*)(d + 0x78);
                        *slot = (*donor & 0xc2dedf77) | (*slot & 0x49212000);
                        *(uint*)(s + 0x90) = *(uint*)(d + 0x90) & 0xffff7eff;
                        restored = true;
                        break;
                    }

                    if ((*(uint*)(d + 0x90) & 0x8000) == 0) break;
                }

                index++;
                donor = (uint*)((byte*)donor + 0x9c);
            }

            if (!restored && index == s_PartySize_005e9020)
            {
                *Mem.Camera(0x005de068) = *(int*)Mem.Arena(0x005e9a30);
                *Mem.Camera(0x005de06c) = *(int*)Mem.Arena(0x005e9a34);
                *Mem.Camera(0x005de070) = *(int*)Mem.Arena(0x005e9a38);

                *(uint*)(s + 0x80) = *(uint*)Mem.Entity(0x005f7d70);
                *(uint*)(s + 0x84) = *(uint*)Mem.Entity(0x005f7d74);
                *(uint*)(s + 0x88) = *(uint*)Mem.Entity(0x005f7d78);
                *(uint*)(s + 0x8c) = *(uint*)Mem.Entity(0x005f7d7c);

                *(int*)(s + 0x1c) = *(int*)Mem.Arena(0x005e9a30);
                int savedY = *(int*)Mem.Arena(0x005e9a34);
                *(int*)(s + 0x20) = savedY;
                *(int*)(s + 0x24) = *(int*)Mem.Arena(0x005e9a38);

                // Ghidra pose la MEME valeur dans +0x60 et +0x64 : le sol et le plafond partent
                // tous deux de la hauteur mise de cote. Transcrit tel quel.
                *(int*)(s + 0x60) = savedY;
                *(int*)(s + 0x64) = savedY;

                *slot = (*(uint*)Mem.Entity(0x005ff3e4) & 0xc2dedf77) | (*slot & 0x49212000);
                *(uint*)(s + 0x90) = *(ushort*)Mem.Arena(0x005e9b38) & 0xffff7effu;
                *(uint*)(s + 0x7c) = *(uint*)Mem.Entity(0x005f7b48);
                restored = true;
            }

            if (restored)
            {
                held = *slot;
                *slot = held & 0xdfffbff8;
                *(uint*)(s + 0x90) &= 0xffff7eff;

                if ((held & 0x40000000) == 0)
                {
                    *(short*)(s + 0x96) = 0;
                    ApplyPercentDamage_005397B0(slot, 2, 0);
                    *(short*)(s + 0x96) = 0x10;
                    *(short*)(s + 0x14) = 0;
                    *(uint*)(s + 0x5c) = 0;
                    *(int*)(s + 0x50) = 0;
                    *(int*)(s + 0x54) = 0;
                    *(int*)(s + 0x58) = 0;
                    s[9] = 0;
                    *(uint*)(s + 0x18) = 0;
                }
            }
        }

        // ---------------------------------------------- (B) la publication vers les globales
        Mem.CopyDwords((uint*)(s + 0x1c), (uint*)Mem.Entity(0x005fa4e0), 10);
        *(uint*)Mem.Arena(0x005e9b4c) = *(uint*)(s + 0x80);
        *(uint*)Mem.Arena(0x005e9b50) = *(uint*)(s + 0x84);
        *(uint*)Mem.Arena(0x005e9b44) = *(uint*)(s + 0x88);
        *(uint*)Mem.Arena(0x005e9b48) = *(uint*)(s + 0x8c);
        *(int*)Mem.Entity(0x005f7cc4) = *(int*)(s + 0x78);

        // Ghidra: `_DAT_005ff3e8 = *puVar3;`. L'adresse LUE plus haut est 0x005ff3e4 et celle
        // ECRITE ici est 0x005ff3e8 — deux cases voisines et distinctes, verifie au
        // desassembleur (`mov [5FF3E8h],eax` en 0x0050cd43).
        *(uint*)Mem.Entity(0x005ff3e8) = *slot;
        *(ushort*)Mem.Entity(0x0060083c) = *(ushort*)(s + 0x90);

        // ---------------------------------------------- (C) l'integration de la vitesse
        //
        // **Le triplet est (sinus, 0, cosinus), verifie au desassembleur** (0x0050cd63..0x0050cd7e)
        // et non deduit de la pseudo-C, qui attache les deux noms aux mauvais emplacements et rend
        // la mise a zero de Y comme un `iStack_10 = 0` mort.
        int facing = *(short*)(s + 0x98);
        int* heading = stackalloc int[3];
        heading[0] = (int)Winsys3d.GetSinTableEntry(facing);
        heading[1] = 0;
        heading[2] = Winsys3d.GetCosTableEntry(facing);

        int* carried = stackalloc int[3];

        if ((*slot & 1) == 0)
        {
            if ((*slot & 0x10) == 0)
            {
                // Le cap est bascule sur la pente : on sonde le sol un seizieme d'unite devant,
                // et Ordinal_439 normalise le vecteur qui joint les deux points.
                int* slope = stackalloc int[3];
                slope[0] = heading[0] * 0x10 + *(int*)(s + 0x1c);
                slope[2] = heading[2] * 0x10 + *(int*)(s + 0x24);

                // Ghidra appelle GroundHeightOnFace AVANT d'ecrire slope[1] : la hauteur passee est
                // celle laissee par le tour precedent. Conserve — la fonction ne lit que X et Z.
                int groundAhead = GroundHeightOnFace(*(uint**)(s + 0x7c), slope);

                slope[1] = ((groundAhead - *(int*)(s + 0x20)) >> 0xc) - 5;
                slope[0] = (heading[0] << 4) >> 0xc;
                slope[2] = (heading[2] << 4) >> 0xc;
                Winsys3d.Ordinal_439(slope, heading);
            }

            int speed = *(int*)(s + 0x5c);
            if ((*(uint*)(s + 0x90) & 0x100) == 0)
            {
                carried[0] = *(int*)(s + 0x50);
                carried[2] = *(int*)(s + 0x58);
                heading[0] = heading[0] * speed >> 0xc;
                heading[1] = heading[1] * speed >> 0xc;
                carried[1] = *(int*)(s + 0x54);
                heading[2] = heading[2] * speed >> 0xc;
            }
            else
            {
                // Le regime « monte » : cinq bits de plus a l'amortissement, et le vecteur de
                // l'entree d'emplacement s'ajoute au cap.
                heading[0] = heading[0] * speed >> 0x11;
                heading[1] = heading[1] * speed >> 0x11;
                heading[2] = heading[2] * speed >> 0x11;

                if ((*slot & 0x10) == 0)
                {
                    heading[0] += *(short*)(entry + 0x44) * 4;
                    heading[1] += *(short*)(entry + 0x46) * 4;
                    heading[2] += *(short*)(entry + 0x48) * 4;
                }

                carried[0] = *(int*)(s + 0x50) >> 5;
                carried[1] = *(int*)(s + 0x54) >> 5;
                carried[2] = *(int*)(s + 0x58) >> 5;
            }
        }
        else
        {
            heading[0] = heading[0] * *(int*)(s + 0x5c) >> 0x10;
            heading[2] = heading[2] * *(int*)(s + 0x5c) >> 0x10;
            carried[0] = *(int*)(s + 0x50) >> 4;
            carried[2] = *(int*)(s + 0x58) >> 4;
            carried[1] = 0;
        }

        // ---------------------------------------------- (D) le porteur
        int* push = stackalloc int[3];
        push[0] = 0;
        push[1] = 0;
        push[2] = 0;

        byte* carrier = *(byte**)(s + 0x78);
        if (carrier != null)
        {
            if ((carrier[7] & 0x40) != 0)
            {
                *(short*)(s + 0x32) += (short)(*(short*)(carrier + 0x32) - *(short*)(entry + 0x3e));
                ComputeCarrierOffset(entry, carrier, push);

                if (((*(ushort*)(carrier + 0x34) | *(ushort*)(entry + 0x40)) & 0xfff) != 0)
                {
                    push[0] = -push[0];
                    push[1] = -0xa000 - push[1];
                    push[2] = -push[2];
                }
            }

            if ((carrier[7] & 0x20) != 0)
            {
                push[0] += *(int*)(carrier + 0x1c) - *(int*)(entry + 0x28);
                push[1] += *(int*)(carrier + 0x20) - *(int*)(entry + 0x2c);
                push[2] += *(int*)(carrier + 0x24) - *(int*)(entry + 0x30);
            }

            if ((carrier[7] & 0x10) != 0)
            {
                push[0] += *(int*)(carrier + 0x50);
                push[1] += *(int*)(carrier + 0x54);
                push[2] += *(int*)(carrier + 0x58);
            }

            if ((*slot & 1) == 0 && (*slot & 0x10) != 0)
            {
                *(int*)(s + 0x50) += push[0];
                *(int*)(s + 0x54) += push[1];
                *(int*)(s + 0x58) += push[2];
            }
        }

        // ---------------------------------------------- (E) deux demi-pas de placement
        *(int*)(s + 0x50) += heading[0] - carried[0];
        *(int*)(s + 0x54) += heading[1] - carried[1];
        *(int*)(s + 0x58) += heading[2] - carried[2];

        PullEntityTowardCameraTarget_00519F50(slot, entry);

        uint gathered = 0;
        *slot &= 0xdfffffff;

        // Deux demi-pas plutot qu'un pas entier : le placement rattrape une marche que le pas
        // entier aurait traversee. Le premier tour efface les trois bits de face du resultat.
        for (int half = 2; half != 0; half--)
        {
            *(int*)(s + 0x1c) += *(int*)(s + 0x50) >> 1;
            *(int*)(s + 0x20) += *(int*)(s + 0x54) >> 1;
            *(int*)(s + 0x24) += *(int*)(s + 0x58) >> 1;

            FinalizeEntityPlacement2(slot);
            gathered |= *(uint*)(s + 0x90);
            if (half == 2) gathered &= 0xfffff8ff;
        }

        *(uint*)(s + 0x90) = gathered;
        ApplyEntityMotion_00519DF0(slot, entry);

        // L'entree dans une zone marquee : le script d'ambiance part une fois.
        if ((*(ushort*)Mem.Entity(0x0060083c) & 0x8000) == 0
            && (*(uint*)(s + 0x90) & 0x8000) != 0
            && *(sbyte*)(s_Unknown_005f2ce0 + 0x11) != -1)
        {
            RunEntityScript(s_Unknown_005e97cc, s, (uint)*(sbyte*)(s_Unknown_005f2ce0 + 0x11));
        }

        // ---------------------------------------------- (F) l'amortissement et le rebond
        short gravity = *(short*)(s + 0x9a);
        int vx = *(int*)(s + 0x50) - (*(int*)(s + 0x50) >> 8);
        *(int*)(s + 0x50) = vx;

        int vy = *(int*)(s + 0x54) + (((gravity >> 8) - (*(int*)(s + 0x54) >> 8)) - gravity);
        int vz = *(int*)(s + 0x58) - (*(int*)(s + 0x58) >> 8);
        *(int*)(s + 0x54) = vy;
        *(int*)(s + 0x58) = vz;

        if (vy < 1) *(short*)(s + 0x9a) = 0x6000;

        attributes = *(uint*)(s + 0x90);
        if ((attributes & 0x800) != 0)
        {
            // Le placement a refuse : on revient a la position d'avant, publiee en (B).
            *(int*)(s + 0x1c) = *(int*)Mem.Entity(0x005fa4e0);
            *(int*)(s + 0x24) = *(int*)Mem.Entity(0x005fa4e8);

            uint after = *slot;
            if ((after & 1) == 0) *(int*)(s + 0x20) = *(int*)Mem.Entity(0x005fa4e4);

            *(uint*)(s + 0x80) = *(uint*)Mem.Arena(0x005e9b4c);
            *(uint*)(s + 0x84) = *(uint*)Mem.Arena(0x005e9b50);
            *(uint*)(s + 0x88) = *(uint*)Mem.Arena(0x005e9b44);
            *(uint*)(s + 0x8c) = *(uint*)Mem.Arena(0x005e9b48);
            *(int*)(s + 0x78) = *(int*)Mem.Entity(0x005f7cc4);

            if ((perChar[0x150] & 7) == 2)
            {
                if ((after & 4) == 0)
                {
                    *(int*)(s + 0x50) = 0;
                    *(int*)(s + 0x58) = 0;
                }
                else
                {
                    // Le rebond contre un mur en pleine course : la vitesse s'inverse de moitie et
                    // le personnage est relance vers le haut.
                    *(short*)(s + 0x9a) = 0x6000;
                    *(uint*)(s + 0x18) = 4;
                    *slot = (after & 0xfefffffb) | 1;
                    *(int*)(s + 0x50) = -(vx >> 1);
                    *(int*)(s + 0x54) = 0xe000;
                    *(int*)(s + 0x20) += 0xe000;
                    *(int*)(s + 0x58) = -(vz >> 1);
                    entry[0x0a] = 0;
                }
            }
            else
            {
                *(int*)(s + 0x50) = 0;
                *(int*)(s + 0x58) = 0;
            }

            if ((*(uint*)(s + 0x90) & 0x10000000) == 0)
            {
                byte* holder = *(byte**)Mem.Entity(0x005f7cc4);
                if (holder != null)
                {
                    *(int*)(s + 0x1c) += push[0];
                    *(int*)(s + 0x24) += push[2];

                    if ((*slot & 1) == 0)
                    {
                        if ((*slot & 0x20) != 0)
                        {
                            int lifted = push[1] + *(int*)(s + 0x20);
                            *(int*)(s + 0x20) = Math.Max(lifted, *(int*)(s + 0x60));
                        }
                    }
                    else
                    {
                        *(int*)(s + 0x50) = push[0];
                        *(int*)(s + 0x58) = push[2];

                        int drop = *(int*)(holder + 0x20) - *(int*)(s + 0x20);
                        if (drop < -0xc7fff)
                        {
                            *(int*)(s + 0x54) = drop >> 4;
                            *(int*)(s + 0x20) += drop >> 4;
                        }
                    }
                }
            }
            else if ((*(uint*)(s + 0x90) & 0x40000000) != 0 && (*slot & 1) == 0)
            {
                *(int*)(s + 0x54) = 0;
            }

            FinalizeEntityPlacement2(slot);
            ApplyEntityMotion_00519DF0(slot, entry);

            attributes = *(uint*)(s + 0x90);
            if ((attributes & 0x800) != 0)
            {
                if ((attributes & 0x10000000) == 0)
                {
                    byte* target = *(byte**)(s + 0x78);
                    if (target != null)
                    {
                        // Toujours refuse : on glisse d'un seizieme vers le porteur plutot que de
                        // rester bloque.
                        int slideX = *(int*)(target + 0x1c) - *(int*)(s + 0x1c);
                        int slideZ = *(int*)(target + 0x24) - *(int*)(s + 0x24);
                        *(int*)(s + 0x1c) += slideX >> 4;
                        *(int*)(s + 0x24) += slideZ >> 4;

                        if ((*slot & 1) == 0)
                        {
                            if ((*slot & 0x20) != 0) *(int*)(s + 0x20) = *(int*)(s + 0x60);
                        }
                        else
                        {
                            *(int*)(s + 0x50) += slideX >> 4;
                            *(int*)(s + 0x58) += slideZ >> 4;
                        }
                    }
                }
                else if ((attributes & 0x40000000) != 0 && (*slot & 1) == 0)
                {
                    *(int*)(s + 0x54) = 0;
                }
            }
        }

        // ---------------------------------------------- (G) le sol et le plafond
        if (*(int*)(s + 0x64) < *(int*)(s + 0x20) || (attributes & 0xa000) != 0)
        {
            uint after = *slot;
            if ((after & 1) == 0)
            {
                *(short*)(s + 0x9a) = 0x6000;
                *slot = (after & 0xfffffffb) | 1;
                if ((after & 0x40000002) == 0)
                {
                    *(uint*)(s + 0x18) = 4;
                    *slot = (after & 0xfefffffb) | 1;
                }
            }
        }
        else
        {
            // Pose au sol : la matiere de la face devient celle des pas, et le contact peut
            // declencher un son et une pose.
            byte* material = Mem.Entity(0x005fa508) + *(ushort*)(*(byte**)(s + 0x7c) + 8) * 8;
            *(uint*)(entry + 0x44) = *(uint*)material;
            *(uint*)(entry + 0x48) = *(uint*)(material + 4);

            int ground = *(int*)(s + 0x64);
            if (*(int*)(s + 0x20) + 0xa000 < ground) *(int*)(s + 0x54) = 0;
            *(int*)(s + 0x20) = ground;

            DispatchEntityHandler(
                Res.ResolveEntityHandler(0x0056afc8, 32), s,
                $"FUN_0050bf20, membre {member} : le crochet de contact au sol PTR_FUN_0056b048");

            if ((*(uint*)(s + 0x90) & 0x400) != 0
                && *(short*)(s + 0x96) == 0
                && (perChar[0x150] & 7) != 7
                && (*(uint*)(perChar + 0x140) & 0x40400000) == 0)
            {
                Aud.PlayPositionalSound(5, 0xa00, 0x1800, (int*)(s + 0x1c));
                ApplyPercentDamage_005397B0(slot, 2, 0);
                pad[0x0c] = 0;
                *(short*)(s + 0x96) = 0x10;
            }

            if ((*slot & 1) != 0)
            {
                if (*(int*)(s + 0x54) < -0x18000)
                {
                    Aud.PlayPositionalSound(1, 0x400, 0x1800, (int*)(s + 0x1c));
                }

                uint landing = *slot;
                if ((landing & 0x40000042) == 0)
                {
                    *(uint*)(s + 0x18) = 0;
                    *slot = landing | 0x1000000;
                }

                *slot &= 0xfffffffe;
            }

            entry[0x0a] = 2;
        }

        // ---------------------------------------------- (H) la cascade de fin
        held = *slot;
        if ((held & 0x40000000) != 0)
        {
            *(short*)(s + 0x96) = 0;
            return;
        }

        // L'instantane que la sous-zone relira si ce membre doit etre restitue.
        if ((held & 0x40000001) == 0
            && ((*(uint*)(s + 0x90) & 0xad40) == 0 || (*(uint*)(s + 0x90) & 2) != 0)
            && (*(int*)(s + 0x78) == 0 || (held & 0x20) == 0))
        {
            *(uint*)Mem.Entity(0x005f7d70) = *(uint*)(s + 0x80);
            *(uint*)Mem.Entity(0x005f7d74) = *(uint*)(s + 0x84);
            *(uint*)Mem.Entity(0x005f7d78) = *(uint*)(s + 0x88);
            *(uint*)Mem.Entity(0x005f7d7c) = *(uint*)(s + 0x8c);
            *(int*)Mem.Arena(0x005e9a30) = *(int*)(s + 0x1c);
            *(int*)Mem.Arena(0x005e9a34) = *(int*)(s + 0x20);
            *(int*)Mem.Arena(0x005e9a38) = *(int*)(s + 0x24);
            *(uint*)Mem.Entity(0x005ff3e4) = *slot;
            *(short*)Mem.Arena(0x005e9b38) = *(short*)(s + 0x90);
            *(uint*)Mem.Entity(0x005f7b48) = *(uint*)(s + 0x7c);
        }

        // Le coup recu : l'entite que la collision a designee, si elle est armee.
        byte* hit = CollectEntityHit_005197D0(slot);
        if (hit != null && (*(uint*)hit & 0x80080000) == 0x80080000)
        {
            uint kind = *(uint*)hit;
            if ((kind & 0x8000) == 0)
            {
                if ((kind & 0x10000000) == 0)
                {
                    // EXPERIENCE repartie sur tout le groupe encore debout — et non « degats »,
                    // comme ce commentaire le disait jusqu'au 2026-08-29 : la part s'ajoute a
                    // +0x158, la jauge que CheckLevelUp_00539190 examine juste apres.
                    int index = 0;
                    int offset = 0;
                    uint* victim = (uint*)Inp.s_SlotFlags_005e93c0;
                    while (index < s_PartySize_005e9020)
                    {
                        if ((*victim & 0x80000000) != 0 && (*victim & 0x50000000) == 0)
                        {
                            int share = (int)(*(uint*)((byte*)hit + 0x5c)
                                              - *(ushort*)(mainMem + 0xf0144 + offset)) >> 1;
                            share += (int)*(uint*)((byte*)hit + 0x5c) >> 1;
                            if (share < 0) share = 0;

                            share += (int)(*(uint*)((byte*)hit + 0x5c) + 0xf) >> 4;
                            *(int*)(mainMem + 0xf0158 + offset) += share;

                            CheckLevelUp_00539190((byte*)victim, mainMem + 0xf0000 + offset);
                        }

                        index++;
                        offset += 0x2000;
                        victim = (uint*)((byte*)victim + 0x9c);
                    }
                }
                else
                {
                    uint purse = (uint)(*(int*)(perChar + 0x26c) + (int)(*(uint*)((byte*)hit + 0x5c) + 9) / 10);
                    *(uint*)(perChar + 0x26c) = purse;
                    if (purse > 99999) *(uint*)(perChar + 0x26c) = 99999;
                }

                *(uint*)hit &= 0x7fffffff;
                FreeEntitySlot(Mem.Entity(0x005f7b60), ((byte*)hit)[8]);
                Aud.PlayPositionalSound(7, 0x800, 0x1000, (int*)(s + 0x1c));
            }
            else if ((*slot & 0x10000) == 0)
            {
                if (((byte*)hit)[6] == 0)
                {
                    *(byte**)(s + 0x6c) = hit;
                    GrantChestContents_00530F20(slot, ((byte*)hit)[7], 0x005312d0);
                    Aud.PlayPositionalSound(0x21, 0x800, 0x1800, (int*)(s + 0x1c));
                }
                else
                {
                    byte* labels = *(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x70);
                    if ((perChar[0x150] & 7) == 2)
                    {
                        BindMenuLabels(*(byte**)(labels + 0x5a0), (uint)(nuint)slot,
                            s_WorldMapDescriptor_005633b0, 0);
                    }
                    else
                    {
                        BindMenuLabels(*(byte**)(labels + 0x550), (uint)(nuint)slot,
                            s_WorldMapDescriptor_005633b0, 0);
                        SpawnEffectEntity(s, ((byte*)hit)[6], 0, 0);
                    }

                    ((byte*)hit)[6] = 0;
                    if (*(short*)((byte*)hit + 0x10) < 0x32) *(short*)((byte*)hit + 0x10) = 0x32;
                }
            }
        }

        // LE COUP, sur la derniere image du geste — et non « le pas sonore », comme ce commentaire
        // le disait jusqu'au 2026-08-29 : voir SweepSceneEntitiesForMeleeHit_00519940. Les deux
        // postures ecartees (4 et 7, modulo 8) sont exactement celles dont le gabarit de portee est
        // entierement nul dans la table de 0x00562cf0.
        if ((*slot & 2) != 0)
        {
            byte posture = perChar[0x150];
            if ((posture & 7) != 4 && (posture & 7) != 7)
            {
                byte* animSet = *(byte**)(Mem.Arena(0x005e9680) + s[4] * 4);
                byte* anim = *(byte**)(animSet + *(short*)(s + 0x18) * 4);

                if ((uint)(*(short*)(s + 0x1a) + 1) == *(ushort*)(anim + 0x16))
                {
                    uint row = posture;
                    if ((posture & 7) == 0 && *(short*)(s + 0x18) == 6) row = (row >> 3) + 0x10;

                    SweepSceneEntitiesForMeleeHit_00519940((byte*)slot, (int*)(s + 0x1c), MeleeProbeForPosture(row));
                }
            }
        }

        UpdateEntityShadow_00519EE0(slot, perChar);

        if ((*(uint*)(s + 0x90) & 0x8000) == 0) TestTriggerVolumes_00534CD0(slot);

        // Le changement de sous-zone : la face foulee porte l'identifiant de la zone voisine.
        byte destination = (*(byte**)(s + 0x7c))[0x0f];
        if (destination != 0
            && (uint)*Mem.Camera(0x005de058) != destination - 1u
            && (*(uint*)(s + 0x90) & 0x2000) == 0)
        {
            uint before = *slot;
            *(short*)(s + 0x98) = *(short*)(s + 0x32);
            *slot = (before & 0xf7fffdff) | 0x2000;
            (*(ushort*)(s + 0x12))++;

            Res.s_Unknown_005de528 = s_Unknown_00566c84;
            s_Unknown_005de52c = s_Unknown_00566c88;
            s_Unknown_005de53c = s[8];
            *(byte*)Mem.Camera(0x005de038) = (byte)(destination - 1);
            s_WorldMapStep_005645f8 = 1;
        }

        // L'immobilite : deux comptes a rebours descendent tant que rien ne bouge, et repartent au
        // maximum des qu'une touche ou une vitesse apparait.
        if (*(short*)(s + 0x32) == *(short*)Mem.Entity(0x005fa4f6)
            && *(int*)(s + 0x5c) == 0
            && *(short*)(s + 0x96) == 0
            && (*slot & 6) == 0
            && (*pad & 0xf0) == 0)
        {
            if (perChar[0x206] != 0) perChar[0x206]--;

            if (s[8] == (byte)Mem.s_Unknown_005de538 && *(ushort*)Mem.Arena(0x005e9ae6) != 0)
            {
                (*(ushort*)Mem.Arena(0x005e9ae6))--;
            }
        }
        else
        {
            perChar[0x206] = 100;
            if (s[8] == (byte)Mem.s_Unknown_005de538) *(ushort*)Mem.Arena(0x005e9ae6) = 300;
        }

        if (s_Unknown_00566c84 != 0 && *(ushort*)(s + 0x12) == 0)
        {
            AdvanceSceneEntityAnimation_0053aa10(s);
        }

        *slot |= 0xe00;
    }

    /// <summary>
    /// Ghidra: 0x0050cfb1..0x0050d290 — <b>l'offset impose par le porteur</b>, quand un membre du
    /// groupe est transporte par une autre entite.
    ///
    /// <para>
    /// Deux produits matrice-vecteur en 64 bits, decalage <c>&gt;&gt; 12</c> chacun. La premiere matrice
    /// est la <b>transposee</b> de celle du repere de l'emplacement : le code la construit avec
    /// <c>RotMatrix</c> puis la retourne a la main dans l'ordre 0,3,6 / 1,4,7 / 2,5,8. La seconde
    /// est celle du porteur. Autrement dit : exprimer la position dans le repere local de
    /// l'emplacement, puis la re-exprimer dans celui de ce qui le porte — un attachement
    /// pere-fils. Le resultat est la difference entre la position ainsi transportee et la position
    /// d'origine.
    /// </para>
    /// <para>
    /// <b>Ghidra brouille l'ordre des operandes dans chaque triplet</b>, ce qui donne l'illusion
    /// que les composantes sont permutees entre les deux passes. Elles ne le sont pas : la somme
    /// est commutative, et ce qui compte est quel coefficient va avec quel emplacement de pile. En
    /// suivant les <c>[esp+N]</c> a travers les <c>push</c>, les deux passes sont le meme
    /// <c>ligne_i = (m[3i]*x + m[3i+1]*y + m[3i+2]*z) &gt;&gt; 12</c>.
    /// </para>
    /// </summary>
    private static void ComputeCarrierOffset(byte* entry, byte* carrier, int* offset)
    {
        EnsureGteRegisters();

        short* work = (short*)Mem.Arena(0x005e9b20);
        short* transposed = (short*)Mem.Arena(0x005e9b00);

        RotMatrix((short*)(entry + 0x3c), work);

        transposed[0] = work[0]; transposed[1] = work[3]; transposed[2] = work[6];
        transposed[3] = work[1]; transposed[4] = work[4]; transposed[5] = work[7];
        transposed[6] = work[2]; transposed[7] = work[5]; transposed[8] = work[8];

        RotMatrix((short*)(carrier + 0x30), work);

        int* local = stackalloc int[3];
        int* world = stackalloc int[3];

        Winsys3d.Ordinal_366(transposed);
        ApplyGteMatrix((int*)(entry + 0x1c), local);

        Winsys3d.Ordinal_366(work);
        ApplyGteMatrix(local, world);

        offset[0] = world[0] - *(int*)(entry + 0x1c);
        offset[1] = world[1] - *(int*)(entry + 0x20);
        offset[2] = world[2] - *(int*)(entry + 0x24);
    }

    /// <summary>
    /// Le produit matrice-vecteur que le binaire ecrit en <c>__allmul</c>/<c>__allshr</c> : neuf
    /// multiplications 64 bits et un decalage de 12. La matrice est celle que le dernier
    /// <c>Ordinal_366</c> a chargee dans le registre MATRIX de la DLL (export 814).
    /// </summary>
    private static void ApplyGteMatrix(int* vector, int* result)
    {
        short* m = (short*)s_GteMatrix814;

        for (int row = 0; row < 3; row++)
        {
            long sum = (long)m[row * 3] * vector[0]
                     + (long)m[row * 3 + 1] * vector[1]
                     + (long)m[row * 3 + 2] * vector[2];
            result[row] = (int)(sum >> 12);
        }
    }

    /// <summary>
    /// Ghidra: FUN_005397b0 @ 0x005397b0 — <b>applique des degats en pourcentage des points de vie
    /// maximaux</b>, avec le verrou d'invulnerabilite qui va avec. Le corps est dans
    /// <c>Blaze.c</c> ; il etait stube ici sous le nom <c>SetEntityPose_005397B0</c>, qui <b>etait
    /// faux</b> : il n'y a aucune pose la-dedans.
    ///
    /// <para>
    /// Ce que la lecture du corps donne, et que l'adresse seule ne donnait pas : <c>+0x96</c> est un
    /// <b>verrou d'invulnerabilite</b>. Non nul, le coup ne passe pas du tout ; la fonction le pose
    /// a <c>0x10</c> des qu'elle frappe. Les deux appelants deja transcrits le confirment — ils le
    /// mettent a zero juste avant l'appel et le remettent a <c>0x10</c> juste apres, pour forcer un
    /// coup a travers.
    /// </para>
    /// <para>
    /// Les degats sont <c>PV_max * pourcentage / 100</c>, avec un <b>plancher a 1</b> : un
    /// pourcentage trop petit pour valoir un point en vaut quand meme un. A zero point de vie, le
    /// bit <c>0x40000000</c> part <b>a la fois</b> sur le bloc du personnage et sur son entite.
    /// </para>
    /// <para>
    /// <b>Deux champs sont sauves et rendus</b> autour de la naissance de l'effet <c>0x50</c> :
    /// <c>+0x18</c> et <c>+0x0a</c>. L'effet herite d'une copie de l'entite
    /// (<see cref="SpawnEffectEntity"/>), donc le binaire y glisse <c>100</c> et
    /// <paramref name="effectParam"/> le temps de l'appel, puis remet les valeurs d'origine. Sans
    /// cette restitution, une entite frappee garderait la teinte de son propre effet de degats.
    /// </para>
    /// </summary>
    private static void ApplyPercentDamage_005397B0(uint* entity, int percent, ushort effectParam)
    {
        byte* e = (byte*)entity;

        if (*(short*)(e + 0x96) != 0) return;
        *(short*)(e + 0x96) = 0x10;

        // Ghidra: `((byte)param_1[2] + 0x78) * 0x2000 + MainMem` — l'octet +0x8 est l'index de
        // membre, et 0x78 * 0x2000 vaut 0xf0000, le meme decalage de bloc de personnage que
        // AreaVerb_0053DEA0 ecrit `membre * 0x2000 + 0xf02bc`.
        byte* character = GetMainMemPtr() + (e[8] + 0x78) * 0x2000;

        int damage = *(short*)(character + 0x148) * percent / 100;
        if (damage == 0) damage = 1;

        *(short*)(character + 0x14c) -= (short)damage;
        if (*(short*)(character + 0x14c) < 1)
        {
            *(ushort*)(character + 0x14c) = 0;
            *(uint*)(character + 0x140) |= 0x40000000;
            *(uint*)e |= 0x40000000;
        }

        *(ushort*)(character + 0x196) = 0;
        *(uint*)(character + 0x140) &= 0xffffffbf;

        SpawnParticle_0050F070((uint*)(e + 0x1c), (uint)damage, 0);

        uint savedTint = *(uint*)(e + 0x18);
        ushort savedFacing = *(ushort*)(e + 0x0a);
        *(ushort*)(e + 0x18) = 100;
        *(ushort*)(e + 0x1a) = effectParam;

        SpawnEffectEntity(e, 0x50, 0, 0);                 // Ghidra: FUN_0047a9d0

        *(uint*)(e + 0x18) = savedTint;
        *(ushort*)(e + 0x0a) = savedFacing;
    }


    /// <summary>
    /// Ghidra: FUN_005197d0 @ 0x005197d0 — <b>la collecte du coup recu</b> : un balayage 3x3 des
    /// cellules de la seconde grille spatiale autour du personnage, qui rend la premiere entite
    /// armee (bit <c>0x80000</c>) assez proche pour toucher, ou zero.
    ///
    /// <para>
    /// « Assez proche » se lit en deux temps : moins de 0x28 unites au sol, et une difference de
    /// hauteur dans une bande de <c>±0x50</c> — le test <c>(dy + 0x50) &lt; 0xa0</c> en <b>non
    /// signe</b>, qui rejette les deux debordements d'un coup.
    /// </para>
    /// <para>
    /// <b>Chaque entite ne touche qu'une fois.</b> L'octet <c>+0x09</c> de la candidate porte un
    /// bit par emplacement de personnage : il est pose au moment du coup et n'est efface que
    /// lorsque la distance repasse au-dessus du seuil. Une entite qui reste collee ne blesse donc
    /// pas a chaque image.
    /// </para>
    /// <para>
    /// <b>La constante de grille est <c>0x389f</c> et non <c>0x38a0</c></b> : le <c>-1</c> du
    /// balayage est replie dedans, la ou <see cref="ApplyEntityMotion_00519DF0"/> l'ecrit a part.
    /// La consequence est reelle et conservee : pour un personnage dans la rangee 0, la premiere
    /// des trois rangees balayees est <c>0x389f</c>, c'est-a-dire <b>la derniere rangee de l'autre
    /// grille</b> — les deux pages etant adjacentes (0x1c4000 et 0x1c5000). Le garde
    /// <c>row &lt; 0x71800</c> ne borne que le haut.
    /// </para>
    /// </summary>
    private static byte* CollectEntityHit_005197D0(uint* entityPtr)
    {
        byte* entity = (byte*)entityPtr;
        byte* mainMem = GetMainMemPtr();

        int y = *(int*)(entity + 0x20);
        int x = *(int*)(entity + 0x1c);
        int z = *(int*)(entity + 0x24);

        uint cellX = (uint)(((((x >> 0xc) + 0x2000) >> 9) - 1));
        uint row = (uint)((((z >> 0xc) + 0x2000) >> 9) + 0x389f) * 0x20;

        byte mask = (byte)(1 << (entity[8] & 0x1f));

        for (int outer = 3; outer != 0; outer--)
        {
            uint column = cellX;

            for (int inner = 3; inner != 0; inner--)
            {
                if (column < 0x20 && row < 0x71800)
                {
                    for (byte* candidate = *(byte**)(mainMem + (column + row) * 4);
                         candidate != null;
                         candidate = *(byte**)(candidate + 0x68))
                    {
                        int candidateY = *(int*)(candidate + 0x20);
                        int dx = (x - *(int*)(candidate + 0x1c)) >> 0xc;
                        int dz = (z - *(int*)(candidate + 0x24)) >> 0xc;
                        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));

                        if ((*(uint*)candidate & 0x80000) == 0) continue;

                        if (distance < 0x28 && (uint)(((y - candidateY) >> 0xc) + 0x50) < 0xa0)
                        {
                            if ((candidate[9] & mask) == 0)
                            {
                                candidate[9] |= mask;
                                *Mem.Camera(0x005de0b8) = 1;
                                return candidate;
                            }
                        }
                        else
                        {
                            candidate[9] &= (byte)~mask;
                        }
                    }
                }

                column++;
            }

            cellX = column - 3;
            row += 0x20;
        }

        // Ghidra: `DAT_005de0b8 = local_14;` — le compteur de boucle, nul a la sortie.
        *Mem.Camera(0x005de0b8) = 0;
        return null;
    }

    /// <summary>
    /// Ghidra: FUN_00539190 @ 0x00539190 — <b>la verification de palier apres un gain
    /// d'experience</b>, en basculant l'allocateur de la DLL sur le tampon de travail le temps du
    /// calcul. Exactement la meme enveloppe que <see cref="RunEntityScript"/> autour de
    /// <c>RunScript</c> : <c>Ordinal_46</c> rend l'etat courant de l'allocateur, negatif voulant
    /// dire « rien a preserver ».
    ///
    /// <para>
    /// <b>Elle s'appelait <c>ApplyDamageToMember_00539190</c> et ce nom etait faux</b> — elle
    /// n'applique aucun degat. Le site d'appel le montre : <c>+0x158</c> vient de recevoir
    /// l'experience du coup, et c'est cela qu'elle examine. Troisieme nom invente tombe le
    /// 2026-08-29, tous les trois sur le chemin « taper sur un monstre ».
    /// </para>
    /// <para>
    /// <b>Ghidra rend le second appel comme <c>FUN_005391f0(unaff_retaddr, param_1)</c></b>, ce qui
    /// n'a pas de sens. Le desassemblage tranche : les deux branches font
    /// <c>push [esp+8] ; push [esp+4] ; call</c>, donc les deux passent <c>(param_1, param_2)</c>.
    /// L'artefact vient de ce que Ghidra a perdu le niveau de pile apres l'appel <b>stdcall</b> a
    /// <c>Ordinal_45</c>, qui depile lui-meme son argument.
    /// </para>
    /// </summary>
    private static void CheckLevelUp_00539190(byte* member, byte* character)
    {
        if (Winsys3d.Ordinal_46() < 0)
        {
            LevelUpCharacter_005391F0(member, character);
            return;
        }

        *(int*)Mem.Arena(0x005e9318) = Winsys3d.Ordinal_46();
        Winsys3d.Ordinal_45(GetMainMemPtr() + 0x1c0000);
        LevelUpCharacter_005391F0(member, character);
        Winsys3d.Ordinal_45((void*)(nint)(*(int*)Mem.Arena(0x005e9318)));
    }

