            if (*(ushort*)(e + 0x10) == 1) *(ushort*)(e + 0x10) = 2;
        }
        else if (*(ushort*)(e + 0x10) == 1)
        {
            *(ushort*)(e + 0x10) = 3;
        }

        if (*(ushort*)(e + 0x10) == 2)
        {
            if (*(ushort*)(e + 0x98) == 0)
            {
                byte* sounds = *(byte**)(*(byte**)(s_Unknown_005e97cc + 0xa8));
                TryPlaySoundNearEntity(entity, sounds[0x12], 0x400, 0x1000, 0, 0);
                *(ushort*)(e + 0x98) = 1;
