        if (*(ushort*)(e + 0x10) == 3)
        {
            *(int*)(e + 0x20) = *(short*)(e + 0x12) << 0xc;
            *(ushort*)(e + 0x98) = 0;
            *(ushort*)(e + 0x10) = 1;
        }
    }

